                                </span>
                                <span className="text-[11px] font-semibold text-slate-600 bg-[#F1F3F5] px-2 py-0.5 rounded-[6px] w-fit mt-1.5 capitalize">
                                  {order.itemType}
                                </span>
                              </div>
                            </div>
                          </td>

                          {/* Order Date */}
                          <td className="py-4 px-3 align-middle text-xs sm:text-sm font-medium text-slate-700 whitespace-nowrap">
                            {order.orderDate}
                          </td>

                          {/* Due Date */}
                          <td className="py-4 px-3 align-middle text-xs sm:text-sm font-medium text-slate-700 whitespace-nowrap">
                            {order.dueDate}
                          </td>

                          {/* Total */}
                          <td className="py-4 px-3 align-middle text-xs sm:text-sm font-bold text-slate-900 whitespace-nowrap">
                            {order.price.toLocaleString("en-US", { style: "currency", currency: "USD" })}
                          </td>

                          {/* Status */}
                          <td className="py-4 px-3 align-middle whitespace-nowrap">
                            {order.status === "revision" ? (
                              <span className="bg-[#F5F0FF] text-[#8B5CF6] border border-[#DDD6FE] text-xs font-semibold px-3 py-1 rounded-full text-center inline-block">
                                Revision
                              </span>
                            ) : order.status === "delivered" ? (
                              <span className="bg-[#E6FFFA] text-[#0D9488] border border-[#99F6E4] text-xs font-semibold px-3 py-1 rounded-full text-center inline-block">
                                Delivered
                              </span>
                            ) : order.status === "completed" ? (
                              <span className="bg-[#ECFDF5] text-[#10B981] border border-[#A7F3D0] text-xs font-semibold px-3 py-1 rounded-full text-center inline-block">
                                Completed
                              </span>
                            ) : order.status === "late" ? (
                              <span className="bg-[#FEE2E2] text-[#DC2626] border border-[#FECACA] text-xs font-semibold px-3 py-1 rounded-full text-center inline-block">
                                Late
                              </span>
                            ) : order.status === "disputed" ? (
                              <span className="bg-[#FEF3C7] text-[#B45309] border border-[#FDE68A] text-xs font-semibold px-3 py-1 rounded-full text-center inline-block">
                                Disputed
                              </span>
                            ) : (
                              <span className="bg-[#EEF2FF] text-[#6366F1] border border-[#C7D2FE] text-xs font-semibold px-3 py-1 rounded-full text-center inline-block">
                                Inprogress
                              </span>
                            )}
                          </td>
                        </tr>
                      );
                    })
                  )}
                </tbody>
              </table>
            </div>
          )}

          {/* See more orders button */}
          {normalizedOrders.length > 5 && (
            <div className="flex justify-center mt-6">
              <Button
                type="button"
                onClick={() => setShowAllOrders(!showAllOrders)}
                variant="outline"
                size="sm"
                radius="fiverr"
                rightIcon={
                  <FiChevronDown
                    className={`transition-transform duration-200 ${showAllOrders ? "rotate-180" : ""}`}
                  />
                }
              >
                {showAllOrders ? "Show less orders" : "See more orders"}
              </Button>
            </div>
          )}

        </div>

      </div>
    </div>
  );
}

"use client";

import React, { useEffect, Suspense } from 'react';
import { toast } from "@/utils/toast";
import { useRouter, useParams, useSearchParams } from "next/navigation";
import { axiosFetch } from "@/utils";
import { Loader } from "@/components";

// Module-level deduplication set to persist across React 18/19 Suspense remounts
const activePaymentIntents = new Set<string>();

const PayContent: React.FC = () => {
  const params = useParams();
  const id = typeof params?.id === 'string' ? params.id : Array.isArray(params?.id) ? params.id[0] : undefined;
  const searchParams = useSearchParams();
  const packageType = searchParams.get('tier') || 'basic';
  const navigate = useRouter();

  useEffect(() => {
    if (!id) return;
    const requestKey = `${id}-${packageType}`;

    // Prevent duplicate concurrent requests across Suspense hydration & StrictMode
    if (activePaymentIntents.has(requestKey)) return;
    activePaymentIntents.add(requestKey);

    (async () => {
      try {
        const { data } = await axiosFetch.post(`/orders/create-payment-intent/${id}`, { packageType });
        if (data?.url) {
          window.location.href = data.url;
        } else if (data?.error) {
          toast.error(data.message || 'Payment creation failed.');
          setTimeout(() => {
            activePaymentIntents.delete(requestKey);
            navigate.push('/packages?category=ai-services');
          }, 2000);
        }
      } catch (error: any) {
        console.error('Redirect to checkout failed:', error);
        toast.error(error.response?.data?.message || 'Package not found or payment failed.');
        setTimeout(() => {
          activePaymentIntents.delete(requestKey);
          navigate.push('/packages?category=ai-services');
        }, 2000);
      }
    })();
    window.scrollTo(0, 0);
  }, [id, navigate, packageType]);

  return (
    <div className="w-[90%] min-[901px]:w-[600px] h-[400px] mx-auto flex flex-col items-center justify-center gap-5" style={{ height: '55vh' }}>
      <Loader size={45} />
      <h2 className="my-[20px] mb-[40px] text-[#1e293b] font-medium" style={{ color: '#1e293b', fontWeight: 500 }}>Redirecting to secure payment checkout...</h2>
    </div>
  );
};

export default function Pay() {
  return (
    <Suspense fallback={<div className="flex justify-center items-center h-screen"><Loader size={45} /></div>}>
      <PayContent />
    </Suspense>
  );
}

"use client";

import React, { useEffect, Suspense } from "react";
import { useRouter, useSearchParams } from "next/navigation";
import { axiosFetch } from "@/utils";
import { useUserStore } from "@/store/userStore";
import { Loader } from "@/components";
import { CheckCircle2 } from "lucide-react";

const Success: React.FC = () => {
  const searchParams = useSearchParams();
  const navigate = useRouter();
  const payment_intent = searchParams.get("payment_intent");
  const user = useUserStore((state) => state.user);

  useEffect(() => {
    (async () => {
      try {
        await axiosFetch.patch("/orders", { payment_intent });
        setTimeout(() => {
          navigate.push("/orders");
        }, 5000);
      } catch (err: any) {
        console.log(err?.response?.data?.message || err?.message);
      }
    })();
  }, [navigate, payment_intent]);

  return (
    <div className="w-[90%] max-w-lg mx-auto text-center min-h-[450px] flex flex-col items-center justify-center gap-4 p-8">
      <div className="w-16 h-16 rounded-full bg-emerald-50 text-emerald-600 flex items-center justify-center mb-2 animate-bounce">
        <CheckCircle2 size={36} />
      </div>
      <h2 className="text-2xl font-bold text-slate-800">Payment Successful!</h2>
      <p className="text-slate-600 text-base max-w-md">
        You are being redirected to your orders page. Please do not close this page...
      </p>
      <div className="mt-4">
        <Loader size={30} />
      </div>
    </div>
  );
};

export default function SuccessPage() {
  return (
    <Suspense fallback={<div className="w-full min-h-[400px] flex items-center justify-center"><Loader size={45} /></div>}>
      <Success />
    </Suspense>
  );
}

"use client";

