              <button
                type="button"
                onClick={() => setSelectedPost(featured)}
                className="px-6 h-10 inline-flex items-center justify-center rounded-[6px] bg-white hover:bg-gray-100 text-[#0f172a] font-semibold text-xs sm:text-sm transition shadow-xs cursor-pointer"
              >
                Read Featured Story
              </button>
            </div>
          </div>
        </section>
      </div>

      {/* Featured Article Card */}
      <section className="pt-10 sm:pt-14">
        <div className="container mx-auto px-4 md:px-6">
          <div className="max-w-4xl mx-auto">
            <div
              onClick={() => setSelectedPost(featured)}
              className="bg-white border border-gray-200 rounded-[6px] p-8 sm:p-10 shadow-xs hover:border-[#327C73] hover:shadow-md transition-all duration-300 cursor-pointer space-y-4"
            >
              <div className="flex flex-wrap items-center gap-3 text-xs">
                <span className="px-3 py-1 rounded-full font-bold bg-[#10b981]/10 text-[#327C73]">
                  Featured • {featured.category}
                </span>
                <span className="text-gray-400">•</span>
                <span className="text-gray-500">{featured.date}</span>
                <span className="text-gray-400">•</span>
                <span className="text-gray-500">{featured.readTime}</span>
              </div>

              <h2 className="text-2xl sm:text-3xl font-bold text-[#0f172a] hover:text-[#327C73] transition-colors leading-tight">
                {featured.title}
              </h2>

              <p className="text-sm sm:text-base text-gray-600 leading-relaxed font-normal">
                {featured.summary}
              </p>

              <div className="flex items-center justify-between pt-4 border-t border-gray-100">
                <div className="text-xs">
                  <span className="font-bold text-[#0f172a] block">{featured.author}</span>
                  <span className="text-gray-400">{featured.authorRole}</span>
                </div>
                <span className="text-xs font-bold text-[#327C73] inline-flex items-center gap-1">
                  <span>Read Article</span>
                  <ArrowRight className="w-3.5 h-3.5" />
                </span>
              </div>
            </div>
          </div>
        </div>
      </section>

      {/* Main Blog Grid */}
      <section id="articles" className="py-16 bg-white">
        <div className="container mx-auto px-4 md:px-6">
          {/* Controls: Search & Categories */}
          <div className="flex flex-col sm:flex-row items-center justify-between gap-4 mb-12">
            <div className="flex items-center gap-2 overflow-x-auto pb-2 sm:pb-0 w-full sm:w-auto scrollbar-none">
              {categories.map((cat) => (
                <Button
                  key={cat}
                  type="button"
                  variant={selectedCat === cat ? "brand" : "soft"}
                  size="xs"
                  radius="xl"
                  onClick={() => setSelectedCat(cat)}
                  className={`px-4 py-2 whitespace-nowrap ${selectedCat === cat
                    ? "bg-[#327C73] hover:bg-[#2b6b63] text-white shadow-xs"
                    : "bg-[#f1f5f9] text-gray-600 hover:bg-gray-200"
                    }`}
                >
                  {cat}
                </Button>
              ))}
            </div>

            <div className="relative w-full sm:w-72">
              <Search className="w-4 h-4 text-gray-400 absolute left-3.5 top-1/2 -translate-y-1/2" />
              <input
                type="text"
                placeholder="Search articles..."
                value={searchQuery}
                onChange={(e) => setSearchQuery(e.target.value)}
                className="w-full pl-10 pr-4 py-2 rounded-[6px] border border-gray-200 text-xs focus:border-[#327C73] outline-none"
              />
            </div>
          </div>

          {/* Posts Grid */}
          <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-8">
            {filteredPosts.map((post) => (
              <article
                key={post.id}
                onClick={() => setSelectedPost(post)}
                className="bg-[#f8fafc] border border-gray-200/90 rounded-[6px] p-7 hover:bg-white hover:border-[#327C73] hover:shadow-md transition-all duration-300 cursor-pointer flex flex-col justify-between space-y-6"
              >
                <div className="space-y-3">
                  <div className="flex items-center gap-2 text-[11px]">
