                    </span>
                    <span className="text-gray-400">•</span>
                    <span className="text-gray-400">{post.readTime}</span>
                  </div>

                  <h3 className="text-lg font-bold text-[#0f172a] hover:text-[#327C73] transition-colors leading-snug">
                    {post.title}
                  </h3>

                  <p className="text-xs text-gray-600 leading-relaxed font-normal line-clamp-3">
                    {post.summary}
                  </p>
                </div>

                <div className="flex items-center justify-between pt-4 border-t border-gray-200/60 text-xs">
                  <div>
                    <span className="font-semibold text-gray-800 block">{post.author}</span>
                    <span className="text-[11px] text-gray-400">{post.date}</span>
                  </div>
                  <ArrowRight className="w-4 h-4 text-[#327C73]" />
                </div>
              </article>
            ))}
          </div>

          {/* Newsletter Box */}
          <div className="mt-20 bg-[#0f172a] text-white rounded-[6px] p-8 sm:p-12 text-center max-w-3xl mx-auto space-y-5">
            <h3 className="text-2xl sm:text-3xl font-bold">Stay Ahead in the Creator Economy</h3>
            <p className="text-xs sm:text-sm text-gray-300 max-w-lg mx-auto">
              Get our weekly digest of top freelance playbooks, marketplace trends, and exclusive interviews delivered to your inbox.
            </p>
            <form onSubmit={handleSubscribe} className="flex flex-col sm:flex-row gap-3 max-w-md mx-auto">
              <input
                type="email"
                required
                value={subscribeEmail}
                onChange={(e) => setSubscribeEmail(e.target.value)}
                placeholder="Enter your work email"
                className="w-full px-4 py-3 rounded-[6px] bg-white/10 border border-white/20 text-xs text-white placeholder-gray-400 focus:outline-none focus:border-[#10b981]"
              />
              <Button
                type="submit"
                variant="brand"
                size="md"
                radius="xl"
                className="px-6 py-3 font-semibold text-xs transition active:scale-95 shrink-0"
              >
                Subscribe
              </Button>
            </form>
          </div>
        </div>
      </section>

      {/* Article Reader Modal */}
      {selectedPost && (
        <div className="fixed inset-0 z-50 bg-black/60 backdrop-blur-xs flex items-center justify-center p-4 overflow-y-auto">
          <div className="bg-white rounded-[6px] max-w-2xl w-full p-6 sm:p-10 shadow-2xl relative border border-gray-100 my-8">
            <Button
              type="button"
              variant="soft"
              size="icon"
              radius="full"
              onClick={() => setSelectedPost(null)}
              className="absolute top-5 right-5 w-8 h-8 bg-gray-100 hover:bg-gray-200 text-gray-600 p-0"
              aria-label="Close article"
            >
              <X className="w-4 h-4" />
            </Button>

            <div className="space-y-3 mb-6">
              <span className="px-2.5 py-1 rounded-[6px] text-xs font-bold bg-[#10b981]/10 text-[#327C73]">
                {selectedPost.category}
              </span>
              <h2 className="text-2xl sm:text-3xl font-bold text-[#0f172a] leading-snug">
                {selectedPost.title}
              </h2>
              <div className="text-xs text-gray-500">
                By {selectedPost.author} ({selectedPost.authorRole}) • {selectedPost.date} • {selectedPost.readTime}
              </div>
            </div>

            <div className="border-t border-gray-100 pt-6 space-y-4 text-xs sm:text-sm text-gray-700 leading-relaxed whitespace-pre-line">
              {selectedPost.content}
            </div>

            <div className="mt-8 pt-6 border-t border-gray-100 flex items-center justify-between">
              <span className="text-xs text-gray-400">Workvence Insights Editorial</span>
              <Button
                type="button"
                variant="soft"
                size="md"
                radius="xl"
                leftIcon={<Share2 className="w-3.5 h-3.5" />}
                onClick={() => {
                  navigator.clipboard?.writeText(window.location.href);
                  toast.success("Article link copied!");
                }}
                className="bg-gray-100 hover:bg-gray-200 font-semibold text-gray-700"
              >
                Share
              </Button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
}

"use client";

import React, { useState } from "react";
import Link from "next/link";
import {
  Building2,
  Users,
  ShieldCheck,
  CreditCard,
  Sparkles,
  ArrowRight,
  CheckCircle2,
  Briefcase,
  FileCheck,
  Headphones,
  Lock,
  Send,
  X
} from "lucide-react";
import { Button } from "@/components";
import { CustomSelect, CustomSelectOption } from "@/components/ui";
import { toast } from "@/utils/toast";

const COMPANY_SIZE_OPTIONS: CustomSelectOption[] = [
  { value: "1-20 employees", label: "1-20 employees" },
  { value: "20-50 employees", label: "20-50 employees" },
  { value: "50-250 employees", label: "50-250 employees" },
  { value: "250+ employees", label: "250+ employees" },
];

const enterpriseFeatures = [
  {
    icon: Users,
    title: "Multi-Seat Team Workspace",
    desc: "Invite your entire department. Set granular spending limits, assign project permissions, and collaborate across teams seamlessly."
  },
  {
    icon: CreditCard,
    title: "Consolidated Monthly Invoicing",
    desc: "Streamline accounts payable with a single monthly invoice, Net-30 payment terms, and automated corporate expense categorization."
  },
  {
    icon: Headphones,
    title: "Dedicated Account Concierge",
    desc: "Your dedicated talent specialist matches custom project briefs with pre-vetted specialists within 2 business hours."
  },
  {
    icon: Lock,
    title: "Custom NDAs & IP Protection",
    desc: "Ensure enterprise legal compliance with custom Master Services Agreements (MSA), strict confidentiality clauses, and automated IP transfer."
  }
];

export default function BusinessSolutionsPage() {
  const [isDemoOpen, setIsDemoOpen] = useState(false);
  const [demoForm, setDemoForm] = useState({
    name: "",
    company: "",
    workEmail: "",
    teamSize: "20-50 employees",
    projectScope: ""
  });

  const handleDemoSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (!demoForm.name || !demoForm.workEmail || !demoForm.company) {
      toast.error("Please fill in the required fields.");
      return;
    }
    toast.success("Demo request received! An enterprise account executive will contact you to schedule a consultation.");
    setIsDemoOpen(false);
    setDemoForm({ name: "", company: "", workEmail: "", teamSize: "20-50 employees", projectScope: "" });
  };

  return (
    <div className="min-h-screen bg-white text-[#112131] font-sans">
      {/* Hero Section */}
      <section className="bg-gradient-to-b from-[#f2fbf6] via-[#f7fdf9] to-white border-b border-[rgba(0,0,0,0.10)] py-20 lg:py-28">
        <div className="container mx-auto px-4 md:px-6">
          <div className="max-w-3xl mx-auto text-center space-y-6">
            <div className="inline-flex items-center gap-2 px-3 py-1.5 rounded-full bg-white border border-[rgba(0,0,0,0.10)] text-[#0D6D5F] text-xs font-semibold">
              <Building2 className="w-3.5 h-3.5 text-[#0D6D5F]" />
              <span>Workvence Enterprise & Business</span>
            </div>
            <h1 className="text-3xl sm:text-5xl md:text-6xl font-normal tracking-tight text-[#0f172a] leading-tight">
              Enterprise Talent Solutions for <br className="hidden sm:inline" />
              <span className="text-[#0D6D5F]">Scaling Modern Teams</span>
            </h1>
            <p className="text-xs sm:text-sm md:text-base text-gray-600 max-w-2xl mx-auto font-normal leading-relaxed">
              Empower your team with vetted freelancers, centralized corporate billing, custom Master Service Agreements, and dedicated talent curation.
            </p>
            <div className="flex flex-wrap items-center justify-center gap-4 pt-3">
              <Button
                onClick={() => setIsDemoOpen(true)}
                variant="brand"
                size="md"
                radius="fiverr"
                rightIcon={<ArrowRight className="w-4 h-4" />}
                className="font-semibold text-xs sm:text-sm shadow-xs"
              >
                Book an Enterprise Demo
              </Button>
              <Link
                href="/pro"
                className="px-6 h-10 inline-flex items-center justify-center rounded-[6px] bg-white border border-[rgba(0,0,0,0.10)] hover:bg-gray-50 text-[#0f172a] font-semibold text-xs sm:text-sm transition cursor-pointer"
              >
                Explore Pro Talent
              </Link>
            </div>
          </div>
        </div>
      </section>

      {/* Features Grid */}
      <section className="pt-20 pb-[80px] min-[1400px]:pb-[100px] bg-[#f8fafc]">
        <div className="container mx-auto px-4 md:px-6">
          <div className="text-center max-w-2xl mx-auto mb-16 space-y-2">
            <span className="text-xs font-bold uppercase tracking-wider text-[#0D6D5F]">Enterprise Capabilities</span>
            <h2 className="text-2xl sm:text-3xl md:text-4xl font-bold text-[#0f172a] tracking-tight">
              Built for Scale, Security & Control
            </h2>
            <p className="text-xs sm:text-sm text-gray-500">
              Scale your freelance workforce with enterprise governance and dedicated support.
            </p>
          </div>

          <div className="grid grid-cols-1 md:grid-cols-2 gap-8">
            {enterpriseFeatures.map((f, idx) => {
              const Icon = f.icon;
              return (
                <div
                  key={idx}
                  className="bg-white border border-[rgba(0,0,0,0.10)] rounded-[6px] p-7 sm:p-8 space-y-4 shadow-xs hover:border-[#0D6D5F]/40 transition duration-200"
                >
                  <div className="w-12 h-12 rounded-[6px] bg-[#fff] border border-[rgba(0,0,0,0.10)] text-[#0D6D5F] flex items-center justify-center shrink-0">
                    <Icon className="w-6 h-6 text-[#0D6D5F]" />
                  </div>
                  <h3 className="text-base sm:text-lg font-bold text-[#0f172a]">{f.title}</h3>
                  <p className="text-xs sm:text-[13px] text-gray-600 leading-relaxed font-normal">{f.desc}</p>
                </div>
              );
            })}
          </div>
        </div>
      </section>

      {/* Demo Booking Modal */}
      {isDemoOpen && (
        <div className="fixed inset-0 z-50 bg-black/60 backdrop-blur-xs flex items-center justify-center p-4 overflow-y-auto">
          <div className="bg-white rounded-[6px] max-w-lg w-full p-6 sm:p-8 shadow-2xl relative border border-[rgba(0,0,0,0.10)] my-8">
            <Button
              onClick={() => setIsDemoOpen(false)}
              variant="soft"
              size="icon"
              radius="full"
              className="absolute top-5 right-5 w-8 h-8 text-gray-600 hover:text-black cursor-pointer"
