                    value={demoForm.name}
                    onChange={(e) => setDemoForm({ ...demoForm, name: e.target.value })}
                    placeholder="e.g. Rachel Adams"
                    className="w-full px-3 py-2 rounded-[6px] border border-gray-300 text-xs focus:border-[#0D6D5F] outline-none"
                  />
                </div>
                <div>
                  <label className="block text-xs font-semibold text-gray-700 mb-1">Company Name *</label>
                  <input
                    type="text"
                    required
                    value={demoForm.company}
                    onChange={(e) => setDemoForm({ ...demoForm, company: e.target.value })}
                    placeholder="e.g. Acme Corp"
                    className="w-full px-3 py-2 rounded-[6px] border border-gray-300 text-xs focus:border-[#0D6D5F] outline-none"
                  />
                </div>
              </div>

              <div className="grid grid-cols-1 sm:grid-cols-2 gap-3">
                <div>
                  <label className="block text-xs font-semibold text-gray-700 mb-1">Work Email *</label>
                  <input
                    type="email"
                    required
                    value={demoForm.workEmail}
                    onChange={(e) => setDemoForm({ ...demoForm, workEmail: e.target.value })}
                    placeholder="rachel@acmecorp.com"
                    className="w-full px-3 py-2 rounded-[6px] border border-gray-300 text-xs focus:border-[#0D6D5F] outline-none"
                  />
                </div>
                <div>
                  <label className="block text-xs font-semibold text-gray-700 mb-1">Company Size</label>
                  <CustomSelect
                    value={demoForm.teamSize}
                    onChange={(val) => setDemoForm((prev) => ({ ...prev, teamSize: val }))}
                    options={COMPANY_SIZE_OPTIONS}
