                Request Content Strategy Call
              </Button>
              <Link
                href="/packages?category=writing-and-translation"
                className="px-6 h-10 inline-flex items-center justify-center rounded-[6px] bg-white border border-[rgba(0,0,0,0.10)] hover:bg-gray-50 text-[#0f172a] font-semibold text-xs sm:text-sm transition cursor-pointer"
              >
                Explore Copywriting Packages
              </Link>
            </div>
          </div>
        </div>
      </section>

      {/* Solutions Grid */}
      <section className="pt-20 pb-[80px] min-[1400px]:pb-[100px] bg-[#f8fafc]">
        <div className="container mx-auto px-4 md:px-6">
          <div className="text-center max-w-2xl mx-auto mb-16 space-y-2">
            <span className="text-xs font-bold uppercase tracking-wider text-[#0D6D5F]">Editorial Capabilities</span>
            <h2 className="text-2xl sm:text-3xl md:text-4xl font-bold text-[#0f172a] tracking-tight">
              End-to-End Managed Editorial Pipelines
            </h2>
            <p className="text-xs sm:text-sm text-gray-500">
              Scale your brand content with dedicated freelance editors and domain writers.
            </p>
          </div>

          <div className="grid grid-cols-1 md:grid-cols-3 gap-8">
            {contentSolutions.map((sol, idx) => {
              const Icon = sol.icon;
              return (
                <div
                  key={idx}
                  className="bg-white border border-[rgba(0,0,0,0.10)] rounded-[6px] p-7 sm:p-8 space-y-4 shadow-xs hover:border-[#0D6D5F]/40 transition duration-200"
                >
                  <div className="w-12 h-12 rounded-[6px] bg-[#fff] border border-[rgba(0,0,0,0.10)] text-[#0D6D5F] flex items-center justify-center shrink-0">
                    <Icon className="w-6 h-6 text-[#0D6D5F]" />
                  </div>
                  <h3 className="text-base sm:text-lg font-bold text-[#0f172a]">{sol.title}</h3>
                  <p className="text-xs sm:text-[13px] text-gray-600 leading-relaxed font-normal">{sol.desc}</p>
                </div>
              );
            })}
          </div>
        </div>
      </section>

      {/* Request Modal */}
      {isRequestOpen && (
        <div className="fixed inset-0 z-50 bg-black/60 backdrop-blur-xs flex items-center justify-center p-4 overflow-y-auto">
          <div className="bg-white rounded-[6px] max-w-lg w-full p-6 sm:p-8 shadow-2xl relative border border-[rgba(0,0,0,0.10)] my-8">
            <Button
              onClick={() => setIsRequestOpen(false)}
              variant="soft"
              size="icon"
              radius="full"
              className="absolute top-5 right-5 w-8 h-8 text-gray-600 hover:text-black cursor-pointer"
              aria-label="Close modal"
            >
              <X className="w-4 h-4" />
            </Button>

            <div className="space-y-1 mb-5">
              <span className="text-xs font-bold text-[#0D6D5F] uppercase tracking-wider">Content Strategy</span>
              <h3 className="text-lg sm:text-xl font-bold text-[#0f172a]">Request Content Strategy</h3>
              <p className="text-xs text-gray-500">Plan your managed editorial schedule.</p>
            </div>

            <form onSubmit={handleContentSubmit} className="space-y-4">
              <div>
                <label className="block text-xs font-semibold text-gray-700 mb-1">Your Name *</label>
                <input
                  type="text"
                  required
                  value={contentForm.name}
                  onChange={(e) => setContentForm({ ...contentForm, name: e.target.value })}
                  placeholder="e.g. Sarah Connor"
                  className="w-full px-3.5 py-2.5 rounded-[6px] border border-gray-300 text-xs focus:border-[#0D6D5F] outline-none"
                />
              </div>

              <div>
                <label className="block text-xs font-semibold text-gray-700 mb-1">Work Email *</label>
                <input
                  type="email"
                  required
                  value={contentForm.email}
                  onChange={(e) => setContentForm({ ...contentForm, email: e.target.value })}
                  placeholder="sarah@company.com"
                  className="w-full px-3.5 py-2.5 rounded-[6px] border border-gray-300 text-xs focus:border-[#0D6D5F] outline-none"
                />
              </div>

              <div>
                <label className="block text-xs font-semibold text-gray-700 mb-1">Expected Monthly Volume</label>
                <CustomSelect
                  value={contentForm.volume}
                  onChange={(val) => setContentForm((prev) => ({ ...prev, volume: val }))}
                  options={VOLUME_OPTIONS}
                  size="md"
                />
              </div>

              <Button
                type="submit"
                variant="brand"
                size="md"
                radius="fiverr"
                fullWidth
                leftIcon={<Send className="w-4 h-4" />}
                className="font-semibold shadow-xs mt-2"
              >
                Submit Strategy Request
              </Button>
            </form>
          </div>
        </div>
      )}
    </div>
  );
}

"use client";

import React, { useState } from "react";
import Link from "next/link";
import { useParams } from "next/navigation";
import { useQuery } from "@tanstack/react-query";
import { Breadcrumb } from "@/components";
import {
  EventJoinActionCard,
  EventVideoPlayer,
  EventGallery,
  EventDetailSkeleton,
} from "@/features/events/components";
import { eventService } from "@/features/events/services/eventService";
import {
  Calendar,
  Clock,
  Video,
  MapPin,
  ArrowLeft,
  Sparkles,
  Tag,
  AlertCircle,
} from "lucide-react";

export default function SingleEventDetailPage() {
  const params = useParams();
  const slug = params?.slug as string;
  const [bannerError, setBannerError] = useState(false);

  const {
    data: event,
    isLoading,
    isError,
  } = useQuery({
    queryKey: ["event-detail", slug],
    queryFn: () => eventService.getEventBySlug(slug),
    enabled: Boolean(slug),
    staleTime: 1000 * 60 * 3,
    retry: 1,
  });

  if (isLoading) {
    return <EventDetailSkeleton />;
  }

  if (isError || !event) {
    return (
      <div className="min-h-[70vh] flex flex-col items-center justify-center p-6 text-center bg-white">
        <div className="w-14 h-14 rounded-full bg-red-50 text-red-500 flex items-center justify-center mb-4">
          <AlertCircle className="w-7 h-7" />
        </div>
        <h1 className="font-sf-pro font-semibold text-2xl text-[#112131] mb-2">
          Event Not Found
        </h1>
        <p className="font-inter text-sm text-[#64748b] max-w-md mb-6">
          The event you are looking for does not exist, has been removed, or is still in draft mode.
        </p>
        <Link
          href="/events"
          className="inline-flex items-center gap-2 px-5 py-2.5 rounded-[6px] bg-[#0D6D5F] hover:bg-[#0b5c50] text-white text-xs sm:text-[13px] font-medium transition-colors shadow-2xs"
        >
          <ArrowLeft className="w-4 h-4" />
          <span>Back to All Events</span>
        </Link>
      </div>
    );
  }

  const formattedDate = (() => {
    try {
      const d = new Date(event.startDate);
      if (isNaN(d.getTime())) return event.startDate;
      return d.toLocaleDateString("en-US", {
        weekday: "long",
        month: "long",
        day: "numeric",
        year: "numeric",
      });
    } catch {
      return event.startDate;
    }
  })();

  const formattedTime = (() => {
    try {
      const d = new Date(event.startDate);
      if (isNaN(d.getTime())) return "";
      return d.toLocaleTimeString("en-US", {
        hour: "numeric",
        minute: "2-digit",
        hour12: true,
      });
    } catch {
      return "";
    }
  })();

  const hasBanner = event.banner && !bannerError && !event.banner.startsWith("blob:");

  return (
    <div className="min-h-screen bg-white text-[#171717] font-sans antialiased pb-24">
      {/* 1. Top Breadcrumb & Navigation */}
      <div className="w-full container mx-auto px-4 sm:px-6 md:px-8 pt-6 sm:pt-8 pb-4">
        <Breadcrumb
          items={[
            { label: "Home", href: "/" },
            { label: "Events", href: "/events" },
            { label: event.title, isLast: true },
          ]}
        />
      </div>

      {/* 2. Cover Banner */}
      <div className="w-full container mx-auto px-4 sm:px-6 md:px-8">
        <div className="w-full aspect-[16/7] sm:aspect-[21/9] md:aspect-[24/9] rounded-[10px] overflow-hidden bg-slate-900 border border-black/[0.06] shadow-xs relative">
          {hasBanner ? (
            <img
              src={event.banner}
              alt={event.title}
              onError={() => setBannerError(true)}
              className="w-full h-full object-cover select-none"
            />
          ) : (
            <div className="w-full h-full bg-gradient-to-br from-[#0D6D5F] via-[#0b4d43] to-[#112131] flex flex-col items-center justify-center p-8 text-white text-center">
              <Sparkles className="w-12 h-12 text-[#6AD724] mb-3 opacity-90" />
              <span className="font-sf-pro font-semibold text-lg sm:text-xl text-white/90">
                {event.category || "Workvence Marketplace Event"}
              </span>
            </div>
          )}

          {/* Floating Pill on Banner */}
          <div className="absolute top-4 left-4 flex flex-wrap items-center gap-2">
            {event.category && (
              <span className="px-3 py-1 rounded-[4px] bg-black/60 backdrop-blur-xs text-white text-xs font-medium uppercase tracking-wider">
                {event.category}
              </span>
            )}
            {event.eventType === "virtual" ? (
              <span className="inline-flex items-center gap-1.5 px-3 py-1 rounded-[4px] bg-[#0D6D5F]/95 backdrop-blur-xs text-white text-xs font-medium">
                <Video className="w-3.5 h-3.5" />
                Virtual Event
              </span>
            ) : (
              <span className="inline-flex items-center gap-1.5 px-3 py-1 rounded-[4px] bg-slate-800/95 backdrop-blur-xs text-white text-xs font-medium">
                <MapPin className="w-3.5 h-3.5" />
                In-Person
              </span>
            )}
          </div>
        </div>
      </div>

      {/* 3. Main Detail Grid */}
      <div className="w-full container mx-auto px-4 sm:px-6 md:px-8 mt-8 sm:mt-10">
        <div className="grid grid-cols-1 lg:grid-cols-12 gap-8 lg:gap-12 items-start">
          {/* Left Column: Details, Description, Videos, Gallery */}
          <main className="lg:col-span-8 space-y-8">
            {/* Header Titles */}
            <div className="space-y-3 pb-6 border-b border-gray-100">
              <div className="flex flex-wrap items-center gap-3 text-xs sm:text-[13px] text-[#64748b] font-inter">
                <div className="inline-flex items-center gap-1.5 font-medium text-[#112131]">
                  <Calendar className="w-4 h-4 text-[#0D6D5F]" />
                  <span>{formattedDate}</span>
                </div>
                {formattedTime && (
                  <div className="inline-flex items-center gap-1.5">
                    <Clock className="w-4 h-4 text-gray-400" />
                    <span>
                      {formattedTime} {event.timezone ? `(${event.timezone})` : ""}
                    </span>
                  </div>
                )}
              </div>

              <h1 className="font-sf-pro font-semibold text-2xl sm:text-3xl md:text-4xl text-[#112131] leading-tight tracking-tight">
                {event.title}
              </h1>

              {event.summary && (
                <p className="font-inter text-sm sm:text-base text-[#475569] leading-relaxed">
                  {event.summary}
                </p>
              )}
            </div>

            {/* Promo Video (if present) */}
            {event.videoUrl && (
              <EventVideoPlayer
                url={event.videoUrl}
                title={`${event.title} Preview`}
                isReplay={false}
              />
            )}

            {/* Description Section */}
            <div className="space-y-3">
              <h2 className="font-sf-pro font-semibold text-xl text-[#112131]">
                About This Event
              </h2>

              <div
                className="font-inter text-[14px] sm:text-[14.5px] text-[#334155] leading-relaxed space-y-4
                  [&_p]:mb-3.5 [&_p]:leading-relaxed
                  [&_h3]:text-[17px] [&_h3]:font-semibold [&_h3]:text-[#112131] [&_h3]:mt-6 [&_h3]:mb-2.5 [&_h3]:font-sf-pro
                  [&_h4]:text-[15px] [&_h4]:font-semibold [&_h4]:text-[#112131] [&_h4]:mt-4 [&_h4]:mb-2
                  [&_ul]:list-disc [&_ul]:pl-5 [&_ul]:space-y-2 [&_ul]:mb-4 [&_ul]:marker:text-slate-400
                  [&_li]:pl-1
                  [&_strong]:font-semibold [&_strong]:text-[#112131]
                  [&_a]:text-[#0D6D5F] [&_a]:underline hover:[&_a]:text-[#0b5c50]"
                dangerouslySetInnerHTML={{ __html: event.description }}
              />
            </div>

            {/* Session Recording / Replay (if present) */}
            {event.recordingUrl && (
              <div className="pt-6 border-t border-gray-100">
                <EventVideoPlayer
                  url={event.recordingUrl}
                  title={`${event.title} Recording Replay`}
                  isReplay={true}
                />
              </div>
            )}

            {/* Photo Gallery (if present) */}
            {event.images && event.images.length > 0 && (
              <EventGallery images={event.images} title={event.title} />
            )}

            {/* Tags */}
            {event.tags && event.tags.length > 0 && (
              <div className="pt-6 border-t border-gray-100 space-y-2">
                <div className="flex items-center gap-1.5 text-xs text-[#64748b] font-medium">
                  <Tag className="w-3.5 h-3.5" />
                  <span>Related Topics &amp; Tags:</span>
                </div>
                <div className="flex flex-wrap gap-2">
                  {event.tags.map((tag, tIdx) => (
                    <span
                      key={tIdx}
                      className="px-3 py-1 rounded-[6px] bg-[#F4F5F7] border border-gray-200/60 text-xs text-[#475569] font-inter"
                    >
                      #{tag}
                    </span>
                  ))}
                </div>
              </div>
            )}
          </main>

          {/* Right Column: Sticky Action Card */}
          <div className="lg:col-span-4">
            <EventJoinActionCard event={event} />
          </div>
        </div>
      </div>
    </div>
  );
}

"use client";

import React, { useState } from "react";
import Link from "next/link";
import { useQuery } from "@tanstack/react-query";
import { Breadcrumb } from "@/components";
import {
  EventHeroSpotlight,
  EventFiltersBar,
  EventCard,
  EventGridSkeleton,
} from "@/features/events/components";
import { eventService } from "@/features/events/services/eventService";
import { EventTimeline } from "@/types";
import { Calendar, ChevronLeft, ChevronRight, Sparkles, Inbox } from "lucide-react";

export default function EventsPage() {
  const [timeline, setTimeline] = useState<EventTimeline>("upcoming");
  const [selectedCategory, setSelectedCategory] = useState<string>("All");
  const [searchQuery, setSearchQuery] = useState<string>("");
  const [page, setPage] = useState<number>(1);
  const limit = 9;

  // 1. Fetch Featured Event for Hero Spotlight
  const { data: featuredData } = useQuery({
    queryKey: ["featured-event"],
    queryFn: () => eventService.getEvents({ featured: true, limit: 1 }),
    staleTime: 1000 * 60 * 5,
  });

  const featuredEvent = featuredData?.events?.[0] || null;

  // 2. Fetch Events for Listing Grid
  const {
    data: eventsData,
    isLoading,
    isFetching,
    isError,
  } = useQuery({
    queryKey: ["events", { timeline, selectedCategory, searchQuery, page, limit }],
    queryFn: () =>
      eventService.getEvents({
        timeline,
        category: selectedCategory,
        search: searchQuery,
        page,
        limit,
      }),
    staleTime: 1000 * 60 * 2,
  });

  const events = eventsData?.events || [];
  const total = eventsData?.total || 0;
  const totalPages = eventsData?.totalPages || 0;

  // Handler for timeline change (resets page)
  const handleTimelineChange = (newTimeline: EventTimeline) => {
    setTimeline(newTimeline);
    setPage(1);
  };

  // Handler for category change (resets page)
  const handleCategoryChange = (newCategory: string) => {
    setSelectedCategory(newCategory);
    setPage(1);
  };

  // Handler for search change (resets page)
  const handleSearchChange = (newSearch: string) => {
    setSearchQuery(newSearch);
    setPage(1);
  };

  return (
    <div className="min-h-screen bg-white text-[#171717] font-sans antialiased">
      <div className="w-full container mx-auto px-4 sm:px-6 md:px-8 py-6 sm:py-8 md:py-12 pb-24">
        {/* Breadcrumb */}
        <div className="mb-4">
          <Breadcrumb
            items={[
              { label: "Home", href: "/" },
              { label: "Community", href: "/community" },
              { label: "Events", isLast: true },
            ]}
          />
        </div>

        {/* Hero Spotlight Section */}
        {/* <EventHeroSpotlight featuredEvent={featuredEvent} /> */}

        {/* Events Directory & Filter Section */}
        <section className="mt-12 sm:mt-16 md:mt-20 space-y-8">
          {/* Filter Bar with Tabs, Categories and Search */}
          <EventFiltersBar
            timeline={timeline}
            onTimelineChange={handleTimelineChange}
            selectedCategory={selectedCategory}
            onCategoryChange={handleCategoryChange}
            searchQuery={searchQuery}
            onSearchChange={handleSearchChange}
            totalCount={total}
          />

          {/* Events Grid or States */}
          {isLoading ? (
            <EventGridSkeleton count={6} />
          ) : isError ? (
            <div className="rounded-[8px] border border-red-200 bg-red-50/50 p-8 text-center text-red-600 space-y-2">
              <p className="font-semibold text-sm">Failed to load events.</p>
              <p className="text-xs text-red-500">
                Please check your network connection or try refreshing the page.
              </p>
            </div>
          ) : events.length === 0 ? (
            <div className="rounded-[10px] border border-dashed border-gray-300 bg-[#FBFBFB] p-12 sm:p-16 text-center flex flex-col items-center justify-center space-y-3">
              <div className="w-12 h-12 rounded-full bg-gray-100 flex items-center justify-center text-gray-400">
                <Inbox className="w-6 h-6" />
              </div>
              <h3 className="font-sf-pro font-semibold text-lg text-[#112131]">
                {timeline === "upcoming"
                  ? "No upcoming events scheduled right now"
                  : "No past event recordings found"}
              </h3>
              <p className="font-inter text-xs sm:text-sm text-[#64748b] max-w-md">
                {timeline === "upcoming"
                  ? "We are preparing exciting webinars, workshops, and meetups. In the meantime, explore past sessions and recordings."
                  : "We couldn't find any recorded events matching your current filters. Try changing categories or search terms."}
              </p>
              {timeline === "upcoming" && (
                <button
                  type="button"
                  onClick={() => handleTimelineChange("past")}
                  className="mt-2 inline-flex items-center gap-2 px-4 py-2 rounded-[6px] bg-[#0D6D5F] hover:bg-[#0b5c50] text-white text-xs font-medium transition-colors shadow-2xs"
                >
                  <Calendar className="w-3.5 h-3.5" />
                  <span>Browse Past Recordings</span>
                </button>
              )}
            </div>
          ) : (
            <div className="space-y-10">
              <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6 sm:gap-8">
                {events.map((event) => (
                  <EventCard
                    key={event.id}
                    event={event}
                    isPast={timeline === "past"}
                  />
                ))}
              </div>

              {/* Pagination Controls */}
              {totalPages > 1 && (
                <div className="pt-6 border-t border-gray-100 flex items-center justify-between">
                  <button
                    type="button"
                    disabled={page <= 1 || isFetching}
                    onClick={() => setPage((p) => Math.max(1, p - 1))}
                    className="inline-flex items-center gap-1.5 px-3.5 py-2 rounded-[6px] border border-gray-200 text-xs font-medium text-[#112131] hover:bg-gray-50 disabled:opacity-50 disabled:pointer-events-none transition-colors"
                  >
                    <ChevronLeft className="w-4 h-4" />
                    <span>Previous</span>
                  </button>

                  <span className="text-xs text-[#64748b] font-inter">
                    Page <span className="font-semibold text-[#112131]">{page}</span> of{" "}
                    <span className="font-semibold text-[#112131]">{totalPages}</span>
                  </span>

                  <button
                    type="button"
                    disabled={page >= totalPages || isFetching}
                    onClick={() => setPage((p) => Math.min(totalPages, p + 1))}
                    className="inline-flex items-center gap-1.5 px-3.5 py-2 rounded-[6px] border border-gray-200 text-xs font-medium text-[#112131] hover:bg-gray-50 disabled:opacity-50 disabled:pointer-events-none transition-colors"
                  >
                    <span>Next</span>
                    <ChevronRight className="w-4 h-4" />
                  </button>
                </div>
              )}
            </div>
          )}
        </section>
      </div>
    </div>
  );
}

