    title: "Discussion: Tips for setting up Next.js 16 App Router with Supabase & Stripe webhooks",
    category: "Web & Tech",
    author: "Kenji Sato",
    authorBadge: "Pro Seller",
    timeAgo: "2 days ago",
    replies: 35,
    upvotes: 112,
    views: 1800,
    tags: ["Next.js", "TypeScript", "Stripe"]
  },
  {
    id: "t-5",
    title: "Feature Request: Automatic multi-milestone invoice generator for repeat clients",
    category: "Platform Feedback",
    author: "Rachel Green",
    timeAgo: "3 days ago",
    replies: 51,
    upvotes: 215,
    views: 2400,
    tags: ["Invoicing", "Workspace"]
  }
];

const categories = [
  "All Categories",
  "Tips for Sellers",
  "Client Communication",
  "Web & Tech",
  "Design Showcase",
  "Platform Feedback"
];

export default function ForumPage() {
  const [threads, setThreads] = useState<Thread[]>(initialThreads);
  const [selectedCat, setSelectedCat] = useState("All Categories");
  const [searchQuery, setSearchQuery] = useState("");
  const [isCreatingPost, setIsCreatingPost] = useState(false);
  const [newPost, setNewPost] = useState({
    title: "",
    category: "Tips for Sellers",
    content: "",
    tags: ""
  });

  const filteredThreads = threads.filter((t) => {
    const matchesCat = selectedCat === "All Categories" || t.category === selectedCat;
    const matchesSearch =
      !searchQuery ||
      t.title.toLowerCase().includes(searchQuery.toLowerCase()) ||
      t.tags.some((tag) => tag.toLowerCase().includes(searchQuery.toLowerCase()));
    return matchesCat && matchesSearch;
  });

  const handleUpvote = (id: string) => {
    setThreads((prev) =>
      prev.map((t) => (t.id === id ? { ...t, upvotes: t.upvotes + 1 } : t))
    );
    toast.success("Upvoted!");
  };

  const handleCreatePost = (e: React.FormEvent) => {
    e.preventDefault();
    if (!newPost.title || !newPost.content) {
      toast.error("Please fill in title and discussion content.");
      return;
    }
    const created: Thread = {
      id: "t-" + Date.now(),
      title: newPost.title,
      category: newPost.category,
      author: "You (Community Member)",
      authorBadge: "Member",
      timeAgo: "Just now",
      replies: 0,
      upvotes: 1,
      views: 1,
      tags: newPost.tags ? newPost.tags.split(",").map((s) => s.trim()) : ["Community"]
    };
    setThreads([created, ...threads]);
    setIsCreatingPost(false);
    setNewPost({ title: "", category: "Tips for Sellers", content: "", tags: "" });
    toast.success("Discussion posted to community forum!");
  };

  return (
    <div className="min-h-screen bg-[#f8fafc] text-[#112131] font-sans pb-[80px] min-[1400px]:pb-[100px]">
      {/* 1. Hero Banner Card */}
      <div className="w-full container mx-auto px-4 md:px-6 pt-6 sm:pt-8 md:pt-10">
        <section
          aria-label="Workvence Community Forum Banner"
          className="relative w-full rounded-[6px] py-12 sm:py-14 md:py-16 px-6 sm:px-10 text-center flex flex-col items-center justify-center shadow-xs overflow-hidden bg-[#013571] bg-cover bg-center bg-no-repeat"
          style={{ backgroundImage: "url('/media/BecomeASeller.png')" }}
        >
          {/* Subtle dark overlay for optimal text contrast */}
          <div className="absolute inset-0 bg-[#011e40]/30 backdrop-blur-[0.5px]" />

          <div className="relative z-10 max-w-3xl mx-auto text-center flex flex-col items-center">
            {/* Breadcrumb Navigation */}
            <Breadcrumb
              variant="inverted"
              className="mb-3 sm:mb-4 select-none [&>ol]:justify-center"
              items={[
                {
                  name: "Forum",
                  isLast: true,
                },
              ]}
            />

            <h1 className="text-3xl sm:text-5xl md:text-6xl lg:text-[64px] font-normal italic tracking-tight text-[#fff] leading-[1.12] sm:leading-[1.08] select-none">
              Discussions, Knowledge &amp; <br className="hidden sm:inline" />
              <span className="text-[#6AD724]">Ideas</span>
            </h1>

            <p className="mt-3 sm:mt-4 text-xs sm:text-[13px] md:text-sm text-[#fff]/60 max-w-xl leading-relaxed">
              Ask questions, share workflows, get feedback from peers, and collaborate with creators and digital entrepreneurs worldwide.
            </p>

            <div className="flex flex-wrap items-center justify-center gap-4 pt-4 sm:pt-6">
              <button
                type="button"
                onClick={() => setIsCreatingPost(true)}
                className="px-6 h-10 inline-flex items-center justify-center rounded-[6px] bg-[#0D6D5F] hover:bg-[#0b5c50] text-white font-semibold text-xs sm:text-sm transition shadow-xs gap-2 cursor-pointer"
              >
                <PlusCircle className="w-4 h-4" />
                <span>Start New Discussion</span>
              </button>
              <a
                href="#discussions"
                className="px-6 h-10 inline-flex items-center justify-center rounded-[6px] bg-white hover:bg-gray-100 text-[#0f172a] font-semibold text-xs sm:text-sm transition shadow-xs cursor-pointer"
              >
                Browse Topics
              </a>
            </div>
          </div>
        </section>
      </div>

      {/* Main Container */}
      <div id="discussions" className="container mx-auto px-4 md:px-6 pt-10 sm:pt-14">
        <div className="grid grid-cols-1 lg:grid-cols-12 gap-8">

          {/* Left Sidebar: Categories & Stats (3 cols) */}
          <div className="lg:col-span-3 space-y-6">
            <div className="bg-white p-5 rounded-[6px] border border-gray-200/90 shadow-xs space-y-3">
              <h3 className="text-xs font-bold text-gray-400 uppercase tracking-wider">Categories</h3>
              <div className="space-y-1">
                {categories.map((cat) => (
                  <Button
                    key={cat}
                    onClick={() => setSelectedCat(cat)}
                    variant={selectedCat === cat ? "brand" : "ghost"}
                    size="sm"
                    radius="xl"
                    fullWidth
                    rightIcon={<ChevronRight className="w-3.5 h-3.5 opacity-60" />}
                    className={`justify-between text-left font-medium ${selectedCat === cat
                      ? "font-semibold"
                      : "text-gray-600 hover:bg-gray-100"
                      }`}
                  >
                    <span>{cat}</span>
                  </Button>
                ))}
              </div>
            </div>

            <div className="bg-white p-5 rounded-[6px] border border-gray-200/90 shadow-xs space-y-3 text-xs text-gray-600">
              <h3 className="text-xs font-bold text-gray-400 uppercase tracking-wider">Forum Rules</h3>
              <p>• Be constructive and respectful.</p>
              <p>• No spamming or self-promotion outside showcase.</p>
              <p>• Protect client confidentiality & private contracts.</p>
            </div>
          </div>

          {/* Right Column: Search + Discussion Threads (9 cols) */}
          <div className="lg:col-span-9 space-y-4">

            {/* Search Input Bar */}
            <div className="bg-white p-3 rounded-[6px] border border-gray-200/90 shadow-xs flex items-center gap-3">
              <Search className="w-4 h-4 text-gray-400 ml-2" />
              <input
                type="text"
                placeholder="Search topics, questions, tags..."
                value={searchQuery}
                onChange={(e) => setSearchQuery(e.target.value)}
                className="w-full text-xs text-gray-800 bg-transparent outline-none"
              />
            </div>

            {/* Threads List */}
            <div className="space-y-3">
              {filteredThreads.map((thread) => (
                <div
                  key={thread.id}
                  className="bg-white border border-gray-200 rounded-[6px] p-5 hover:border-[#327C73] hover:shadow-sm transition duration-200 flex flex-col sm:flex-row sm:items-center justify-between gap-4"
                >
                  <div className="space-y-2 max-w-2xl">
                    <div className="flex flex-wrap items-center gap-2 text-[11px]">
                      {thread.isPinned && (
                        <span className="px-2 py-0.5 rounded-[6px] font-bold bg-amber-50 text-amber-700 border border-amber-200">
                          Pinned
                        </span>
                      )}
                      <span className="px-2 py-0.5 rounded-[6px] font-semibold bg-gray-100 text-gray-600">
                        {thread.category}
                      </span>
                      <span className="text-gray-400">•</span>
                      <span className="text-gray-500 font-medium">{thread.author}</span>
                      {thread.authorBadge && (
                        <span className="px-1.5 py-0.2 rounded text-[10px] bg-[#10b981]/10 text-[#327C73] font-semibold">
                          {thread.authorBadge}
                        </span>
                      )}
                      <span className="text-gray-400">•</span>
                      <span className="text-gray-400">{thread.timeAgo}</span>
                    </div>

                    <h3 className="text-base font-bold text-[#0f172a] hover:text-[#327C73] transition cursor-pointer">
                      {thread.title}
                    </h3>

                    <div className="flex flex-wrap items-center gap-1.5 pt-1">
                      {thread.tags.map((tag) => (
                        <span
                          key={tag}
                          className="px-2 py-0.5 rounded-[6px] text-[10px] bg-[#f1f5f9] text-gray-500"
                        >
                          #{tag}
                        </span>
                      ))}
                    </div>
                  </div>

                  {/* Upvotes & Replies Counters */}
                  <div className="flex items-center gap-3 shrink-0 pt-2 sm:pt-0 border-t sm:border-t-0 border-gray-100">
                    <Button
                      onClick={() => handleUpvote(thread.id)}
                      variant="outline"
                      size="xs"
                      radius="xl"
                      leftIcon={<ThumbsUp className="w-3.5 h-3.5" />}
                      className="bg-gray-50 hover:bg-emerald-50 text-gray-600 hover:text-[#327C73] border-gray-200 font-semibold"
                    >
                      {thread.upvotes}
                    </Button>

                    <div className="flex items-center gap-3 text-xs text-gray-400">
                      <span className="flex items-center gap-1">
                        <MessageCircle className="w-3.5 h-3.5" />
                        {thread.replies}
                      </span>
                      <span className="flex items-center gap-1">
                        <Eye className="w-3.5 h-3.5" />
                        {thread.views}
                      </span>
                    </div>
                  </div>
                </div>
              ))}
            </div>

          </div>

        </div>
      </div>

      {/* Start Discussion Modal */}
      {isCreatingPost && (
        <div className="fixed inset-0 z-50 bg-black/60 backdrop-blur-xs flex items-center justify-center p-4 overflow-y-auto">
          <div className="bg-white rounded-[6px] max-w-lg w-full p-6 sm:p-8 shadow-2xl relative border border-gray-100 my-8">
            <Button
              onClick={() => setIsCreatingPost(false)}
              variant="soft"
              size="icon"
              radius="full"
              className="absolute top-5 right-5 w-8 h-8 text-gray-600 hover:text-black"
              aria-label="Close modal"
            >
              <X className="w-4 h-4" />
            </Button>

            <div className="space-y-1 mb-5">
              <h3 className="text-xl font-bold text-[#0f172a]">Start a Discussion</h3>
              <p className="text-xs text-gray-500">Share with the global Workvence community.</p>
            </div>

            <form onSubmit={handleCreatePost} className="space-y-4">
              <div>
                <label className="block text-xs font-semibold text-gray-700 mb-1">Category *</label>
                <CustomSelect
                  size="md"
                  options={categories
                    .filter((c) => c !== "All Categories")
                    .map((c) => ({ value: c, label: c }))}
                  value={newPost.category}
                  onChange={(val) => setNewPost({ ...newPost, category: String(val) })}
                  placeholder="Select Category"
                  ariaLabel="Discussion Category"
                />
              </div>

              <div>
                <label className="block text-xs font-semibold text-gray-700 mb-1">Title *</label>
                <input
                  type="text"
                  required
                  value={newPost.title}
                  onChange={(e) => setNewPost({ ...newPost, title: e.target.value })}
                  placeholder="e.g. What are your tips for increasing conversion on gig thumbnails?"
                  className="w-full px-3.5 py-2.5 rounded-[6px] border border-gray-300 text-xs focus:border-[#327C73] outline-none"
                />
              </div>

              <div>
                <label className="block text-xs font-semibold text-gray-700 mb-1">Content / Details *</label>
                <textarea
                  rows={4}
                  required
                  value={newPost.content}
                  onChange={(e) => setNewPost({ ...newPost, content: e.target.value })}
                  placeholder="Provide context, examples, or your specific questions..."
                  className="w-full px-3.5 py-2.5 rounded-[6px] border border-gray-300 text-xs focus:border-[#327C73] outline-none resize-none"
                />
              </div>

              <div>
                <label className="block text-xs font-semibold text-gray-700 mb-1">Tags (Comma separated)</label>
                <input
                  type="text"
                  value={newPost.tags}
                  onChange={(e) => setNewPost({ ...newPost, tags: e.target.value })}
                  placeholder="e.g. Design, Packages, Conversions"
                  className="w-full px-3.5 py-2.5 rounded-[6px] border border-gray-300 text-xs focus:border-[#327C73] outline-none"
                />
              </div>

              <Button
                type="submit"
                variant="brand"
                size="md"
                radius="xl"
                fullWidth
                leftIcon={<Send className="w-4 h-4" />}
                className="font-semibold shadow-md mt-2"
              >
                Publish Discussion
              </Button>
            </form>
          </div>
        </div>
      )}
    </div>
  );
}

