                  >
                    <span>Hire Creator</span>
                    <ArrowRight className="w-3.5 h-3.5" />
                  </Link>
                </div>
              </div>
            );
          })}
        </div>
      </div>

      {/* Project Detail Modal */}
      {selectedProject && (
        <div className="fixed inset-0 z-50 bg-black/70 backdrop-blur-xs flex items-center justify-center p-4 overflow-y-auto">
          <div className="bg-white rounded-[6px] max-w-2xl w-full p-6 sm:p-8 shadow-2xl relative border border-gray-100 my-8">
            <Button
              onClick={() => setSelectedProject(null)}
              variant="soft"
              size="icon"
              radius="full"
              className="absolute top-5 right-5 w-8 h-8 text-gray-600 hover:text-black z-20"
              aria-label="Close modal"
            >
              <X className="w-4 h-4" />
            </Button>

            {/* High-Res Hero Image Preview */}
            <div className="relative h-72 sm:h-80 w-full rounded-[6px] overflow-hidden mb-6 bg-gray-100">
              <img
                src={selectedProject.imageUrl}
                alt={selectedProject.title}
                className="w-full h-full object-cover"
              />
              <div className="absolute top-4 left-4 z-10">
                <span className="px-3 py-1 rounded-full text-xs font-bold bg-black/60 text-white backdrop-blur-md">
                  {selectedProject.category}
                </span>
              </div>
            </div>

            <div className="space-y-4">
              <div className="flex flex-col sm:flex-row sm:items-center justify-between gap-4 border-b border-gray-100 pb-4">
                <div className="space-y-1">
                  <h2 className="text-2xl font-bold text-[#0f172a]">{selectedProject.title}</h2>
                  <div className="flex items-center gap-2 text-xs text-gray-500">
                    <span>By {selectedProject.creator} ({selectedProject.creatorRole})</span>
                    <span>•</span>
                    <span className="text-emerald-700 font-medium">{selectedProject.turnaround}</span>
                  </div>
                </div>

                <div className="flex items-center gap-2">
                  <Button
                    onClick={() => {
                      navigator.clipboard?.writeText(window.location.href);
                      toast.success("Project link copied!");
                    }}
                    variant="soft"
                    size="icon"
                    radius="xl"
                    className="p-2.5 text-gray-700 hover:bg-gray-200"
                    aria-label="Share project"
                  >
                    <Share2 className="w-4 h-4" />
                  </Button>
                </div>
              </div>

              <div className="space-y-2">
                <h4 className="text-xs font-bold uppercase tracking-wider text-gray-400">About the Project:</h4>
                <p className="text-xs sm:text-sm text-gray-700 leading-relaxed font-normal">
