            <div className="space-y-2 text-center">
              <h3 className="text-xl font-bold text-[#0f172a]">Your Unique Referral Link</h3>
              <p className="text-xs text-gray-500">Share this link anywhere online to automatically track your bonuses.</p>
            </div>

            {/* Link Copy Input */}
            <div className="flex items-center h-10 bg-[#F0F0F0] border border-[rgba(0,0,0,0.10)] focus-within:border-gray-300 focus-within:bg-white rounded-[6px] pl-3.5 pr-1.5 shadow-2xs">
              <input
                type="text"
                readOnly
                value={referralLink}
                className="w-full text-xs sm:text-sm font-mono text-gray-900 bg-transparent outline-none"
              />
              <Button
                onClick={handleCopy}
                variant="brand"
                size="xs"
                radius="fiverr"
                leftIcon={copied ? <Check className="w-3.5 h-3.5" /> : <Copy className="w-3.5 h-3.5" />}
                className="shrink-0 font-semibold"
              >
                {copied ? "Copied!" : "Copy Link"}
              </Button>
            </div>

            {/* 1-Click Social Sharing */}
            <div className="space-y-3 text-center pt-2">
              <span className="text-xs sm:text-[13px] font-medium text-gray-700 block">
                Or share instantly via:
              </span>
              <div className="flex flex-wrap items-center justify-center gap-3">
                <Button
