                  size="sm"
                  radius="xl"
                  className="bg-[#0077b5]/10 hover:bg-[#0077b5]/20 text-[#0077b5] border-[#0077b5]/20 text-xs font-semibold"
                >
                  LinkedIn
                </Button>
              </div>
            </div>

            {/* Direct Email Invites Form */}
            <div className="border-t border-gray-200/80 pt-6 space-y-4">
              <h4 className="text-sm font-bold text-[#0f172a]">Invite by Email</h4>
              <form onSubmit={handleSendInvites} className="space-y-3">
                <div>
                  <label className="block text-xs sm:text-[13px] font-medium text-gray-700 mb-1.5">
                    Enter Email Addresses (Separated by commas)
