export default function PartnershipsClient() {
  const [isApplying, setIsApplying] = useState(false);
  const [selectedTrack, setSelectedTrack] = useState("Agency & Solutions Partners");
  const [partnerForm, setPartnerForm] = useState({
    companyName: "",
    contactName: "",
    email: "",
    website: "",
    track: "Agency & Solutions Partners",
    message: ""
  });

  const handlePartnerSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (!partnerForm.companyName || !partnerForm.email || !partnerForm.contactName) {
      toast.error("Please fill in the required partner details.");
      return;
    }
    toast.success("Partnership application submitted! Our partner director will connect within 2 business days.");
    setIsApplying(false);
    setPartnerForm({
      companyName: "",
      contactName: "",
      email: "",
      website: "",
      track: "Agency & Solutions Partners",
      message: ""
    });
  };

  return (
    <div className="min-h-screen bg-white text-[#112131] font-sans antialiased">
      {/* 1. Hero Banner */}
      <div className="w-full container mx-auto px-4 md:px-6 pt-6 sm:pt-8 md:pt-10">
        <section
          aria-label="Partnerships Hero Banner"
          className="relative w-full rounded-[6px] py-12 sm:py-14 md:py-16 px-6 sm:px-10 text-center flex flex-col items-center justify-center shadow-xs overflow-hidden bg-[#102322] bg-cover bg-center bg-no-repeat"
          style={{ backgroundImage: "url('/media/WorkwithBG.png')" }}
        >
          {/* Subtle dark overlay for optimal text contrast */}
          <div className="absolute inset-0 bg-[#011e40]/30 backdrop-blur-[0.5px]" />

          <div className="relative z-10 max-w-3xl mx-auto text-center flex flex-col items-center">
            {/* Breadcrumb Navigation */}
            <Breadcrumb
              variant="inverted"
              className="mb-3 sm:mb-4 select-none [&>ol]:justify-center"
              items={[
                {
                  name: "Partnerships",
                  isLast: true,
                },
              ]}
            />

            <h1 className="text-3xl sm:text-5xl md:text-6xl lg:text-[64px] font-normal italic tracking-tight text-[#fff] leading-[1.12] sm:leading-[1.08] select-none">
              Grow Together with the <br className="hidden sm:inline" />
              <span className="text-[#6AD724]">World&apos;s Top Talent</span>
            </h1>

            <p className="mt-3 sm:mt-4 text-xs sm:text-[13px] md:text-sm text-[#fff]/60 max-w-xl leading-relaxed">
              Whether you are an agency, technology provider, educational bootcamp, or enterprise consultancy, partnering with Workvence unlocks unprecedented scale and revenue.
            </p>

            <div className="flex flex-wrap items-center justify-center gap-4 pt-4 sm:pt-6">
              <button
                type="button"
                onClick={() => setIsApplying(true)}
                className="px-6 h-10 inline-flex items-center justify-center rounded-[6px] bg-[#0D6D5F] hover:bg-[#0b5c50] text-white font-semibold text-xs sm:text-sm transition shadow-xs gap-2 cursor-pointer"
              >
                <span>Become a Partner</span>
                <ArrowRight className="w-4 h-4" />
              </button>
              <a
                href="#tracks"
                className="px-6 h-10 inline-flex items-center justify-center rounded-[6px] bg-white hover:bg-gray-100 text-[#0f172a] font-semibold text-xs sm:text-sm transition shadow-xs cursor-pointer"
              >
                Explore Partner Tracks
              </a>
            </div>
          </div>
        </section>
      </div>

      {/* Partner Tracks Grid */}
      <section id="tracks" className="py-16 sm:py-20 bg-[#f8fafc]">
        <div className="container mx-auto px-4 md:px-6">
          <div className="text-center max-w-2xl mx-auto mb-12 sm:mb-16 space-y-2">
            <span className="text-xs font-bold uppercase tracking-wider text-[#0D6D5F]">Partnership Tracks</span>
            <h2 className="text-2xl sm:text-3xl md:text-4xl font-bold text-[#0f172a] tracking-tight">
              Tailored Programs for Every Model
            </h2>
            <p className="text-xs sm:text-sm text-gray-500">
              Select the track aligned with your business goals and start building with our platform.
            </p>
          </div>

          <div className="grid grid-cols-1 md:grid-cols-2 gap-6 sm:gap-8">
            {partnerTracks.map((track, idx) => {
              const Icon = track.icon;
              return (
                <div
                  key={idx}
                  className="bg-white rounded-[6px] p-6 sm:p-8 border border-[rgba(0,0,0,0.10)] shadow-xs hover:border-[#0D6D5F]/40 hover:shadow-xs transition duration-200 space-y-6 flex flex-col justify-between"
                >
                  <div className="space-y-4">
                    <div className="w-12 h-12 rounded-[6px] bg-[#fff] border border-[rgba(0,0,0,0.10)] text-[#0D6D5F] flex items-center justify-center shrink-0">
                      <Icon className="w-6 h-6 text-[#0D6D5F]" />
                    </div>
                    <h3 className="text-lg sm:text-xl font-bold text-[#0f172a]">{track.title}</h3>
                    <p className="text-xs sm:text-[13px] text-gray-600 leading-relaxed font-normal">{track.desc}</p>

                    <div className="pt-2 space-y-2 border-t border-gray-100">
                      <span className="text-xs font-bold text-gray-900 uppercase tracking-wider block">
                        Key Benefits
                      </span>
                      {track.benefits.map((b, i) => (
                        <div key={i} className="flex items-start gap-2 text-xs text-gray-700">
                          <CheckCircle2 className="w-4 h-4 text-[#0D6D5F] shrink-0 mt-0.5" />
                          <span>{b}</span>
                        </div>
                      ))}
                    </div>
                  </div>

                  <Button
                    onClick={() => {
                      setSelectedTrack(track.title);
                      setPartnerForm((prev) => ({ ...prev, track: track.title }));
                      setIsApplying(true);
                    }}
                    variant="outline"
                    size="md"
                    radius="fiverr"
                    fullWidth
                    rightIcon={<ArrowRight className="w-3.5 h-3.5" />}
                    className="bg-gray-50 hover:bg-[#0D6D5F] hover:text-white text-[#0f172a] font-semibold text-xs border border-[rgba(0,0,0,0.10)]"
                  >
                    Apply for this Track
                  </Button>
                </div>
              );
            })}
          </div>
        </div>
      </section>

      {/* Ecosystem Section */}
      <section className="py-16 sm:py-20 bg-white border-t border-gray-100">
        <div className="container mx-auto px-4 md:px-6">
          <div className="text-center max-w-xl mx-auto mb-12 sm:mb-16 space-y-2">
            <span className="text-xs font-bold text-[#0D6D5F] uppercase tracking-wider">Integrated Ecosystem</span>
            <h2 className="text-2xl sm:text-3xl md:text-4xl font-bold text-[#0f172a] tracking-tight">Trusted by Leading Platforms</h2>
            <p className="text-xs sm:text-sm text-gray-500">
              Workvence integrates seamlessly with world-class tools and infrastructure.
            </p>
          </div>

          <div className="grid grid-cols-2 sm:grid-cols-3 lg:grid-cols-6 gap-4">
            {ecosystemLogos.map((item, idx) => {
              const Icon = item.icon;
              return (
                <div
                  key={idx}
                  className="group bg-[#f8fafc] hover:bg-white border border-[rgba(0,0,0,0.10)] hover:border-[#0D6D5F]/40 hover:shadow-xs rounded-[6px] p-5 text-center flex flex-col items-center justify-center transition-all duration-200"
                >
                  <div className="w-12 h-12 mb-3 rounded-[6px] bg-[#fff] border border-[rgba(0,0,0,0.10)] flex items-center justify-center group-hover:scale-110 transition-transform duration-200 shadow-2xs">
                    <Icon className="w-6 h-6" style={{ color: item.brandColor }} />
                  </div>
                  <div className="font-semibold text-sm text-[#0f172a]">{item.name}</div>
                  <div className="text-[11px] text-gray-500 mt-0.5">{item.category}</div>
                </div>
              );
            })}
          </div>
        </div>
      </section>

      {/* Bottom CTA Banner */}
      <CTA
        title="Ready to Partner with Workvence?"
        description="Join leading tech companies, agencies, and institutions expanding their reach with our talent network."
        buttonText="Become a Partner"
        onButtonClick={() => setIsApplying(true)}
      />

      {/* Partner Application Modal */}
      {isApplying && (
        <div className="fixed inset-0 z-50 bg-black/60 backdrop-blur-xs flex items-center justify-center p-4 overflow-y-auto">
          <div className="bg-white rounded-[6px] max-w-lg w-full p-6 sm:p-8 shadow-2xl relative border border-gray-100 my-8">
            <Button
              onClick={() => setIsApplying(false)}
              variant="soft"
              size="icon"
              radius="full"
              className="absolute top-5 right-5 w-8 h-8 text-gray-600 hover:text-black"
              aria-label="Close modal"
            >
              <X className="w-4 h-4" />
            </Button>

            <div className="space-y-2 mb-6">
              <span className="text-xs font-bold text-[#327C73] uppercase tracking-wider">
                Partnership Inquiry
              </span>
              <h3 className="text-xl font-bold text-[#0f172a]">Join the Partner Program</h3>
              <p className="text-xs text-gray-500">
                Tell us about your organization and how we can collaborate.
              </p>
            </div>

            <form onSubmit={handlePartnerSubmit} className="space-y-4">
              <div>
                <label className="block text-xs font-semibold text-gray-700 mb-1">
                  Partnership Track *
                </label>
                <CustomSelect
                  value={partnerForm.track}
                  onChange={(val) => setPartnerForm((prev) => ({ ...prev, track: val }))}
                  options={PARTNER_TRACK_OPTIONS}
                  size="md"
                />
              </div>

              <div className="grid grid-cols-1 sm:grid-cols-2 gap-3">
                <div>
                  <label className="block text-xs font-semibold text-gray-700 mb-1">
                    Company Name *
                  </label>
                  <input
                    type="text"
                    required
                    value={partnerForm.companyName}
                    onChange={(e) => setPartnerForm({ ...partnerForm, companyName: e.target.value })}
                    placeholder="Acme Corp"
                    className="w-full px-3.5 py-2.5 rounded-[6px] border border-[rgba(0,0,0,0.10)] bg-[#F0F0F0] text-xs placeholder:text-[#868686] placeholder:font-normal focus:bg-white focus:border-[#0D6D5F] outline-none"
                  />
                </div>
                <div>
                  <label className="block text-xs font-semibold text-gray-700 mb-1">
                    Contact Name *
                  </label>
                  <input
                    type="text"
                    required
                    value={partnerForm.contactName}
                    onChange={(e) => setPartnerForm({ ...partnerForm, contactName: e.target.value })}
                    placeholder="e.g. Sarah Jenkins"
                    className="w-full px-3.5 py-2.5 rounded-[6px] border border-[rgba(0,0,0,0.10)] bg-[#F0F0F0] text-xs placeholder:text-[#868686] placeholder:font-normal focus:bg-white focus:border-[#0D6D5F] outline-none"
                  />
                </div>
              </div>

              <div className="grid grid-cols-1 sm:grid-cols-2 gap-3">
                <div>
                  <label className="block text-xs font-semibold text-gray-700 mb-1">
                    Business Email *
                  </label>
                  <input
                    type="email"
                    required
                    value={partnerForm.email}
                    onChange={(e) => setPartnerForm({ ...partnerForm, email: e.target.value })}
                    placeholder="sarah@acme.com"
                    className="w-full px-3.5 py-2.5 rounded-[6px] border border-[rgba(0,0,0,0.10)] bg-[#F0F0F0] text-xs placeholder:text-[#868686] placeholder:font-normal focus:bg-white focus:border-[#0D6D5F] outline-none"
                  />
                </div>
                <div>
                  <label className="block text-xs font-semibold text-gray-700 mb-1">
                    Company Website
                  </label>
                  <input
                    type="url"
                    value={partnerForm.website}
                    onChange={(e) => setPartnerForm({ ...partnerForm, website: e.target.value })}
                    placeholder="https://acme.com"
                    className="w-full px-3.5 py-2.5 rounded-[6px] border border-[rgba(0,0,0,0.10)] bg-[#F0F0F0] text-xs placeholder:text-[#868686] placeholder:font-normal focus:bg-white focus:border-[#0D6D5F] outline-none"
                  />
                </div>
              </div>

              <div>
                <label className="block text-xs font-semibold text-gray-700 mb-1">
                  Collaboration Vision / Notes
                </label>
                <textarea
                  rows={3}
                  value={partnerForm.message}
                  onChange={(e) => setPartnerForm({ ...partnerForm, message: e.target.value })}
                  placeholder="How can we work together? (e.g. integrations, agency volume, graduate placement)"
                  className="w-full px-3.5 py-2.5 rounded-[6px] border border-[rgba(0,0,0,0.10)] bg-[#F0F0F0] text-xs placeholder:text-[#868686] placeholder:font-normal focus:bg-white focus:border-[#0D6D5F] outline-none resize-none"
                />
              </div>

              <Button
                type="submit"
                variant="brand"
                size="md"
                radius="xl"
                fullWidth
                leftIcon={<Send className="w-4 h-4" />}
                className="font-semibold shadow-md mt-2"
              >
                Submit Partner Application
              </Button>
            </form>
          </div>
        </div>
      )}
    </div>
  );
}

"use client";

import React, { useState } from "react";
import Link from "next/link";
import {
  Mic,
  Play,
  Pause,
  Volume2,
  Calendar,
  Clock,
  Sparkles,
  ArrowRight,
  Share2,
  Headphones,
  Radio,
  ExternalLink
} from "lucide-react";
import { toast } from "@/utils/toast";
import { Button } from "@/components";

interface Episode {
  id: string;
  number: number;
  title: string;
  guest: string;
  guestRole: string;
  duration: string;
  date: string;
  summary: string;
  timestamps: string[];
}

const episodes: Episode[] = [
  {
    id: "ep-1",
    number: 34,
    title: "How to Build a $500k Boutique Creative Agency on Workvence",
    guest: "Elena Rostova",
    guestRole: "Founder of Studio 3D & Level 2 Seller",
    duration: "48 min",
    date: "August 24, 2026",
    summary: "Elena breaks down her journey from a solo 3D modeler to managing a 4-person design studio. We discuss pricing psychology, delegating milestones, and retaining enterprise clients.",
    timestamps: [
      "04:15 - Leaving corporate design for marketplace freelancing",
      "14:30 - The 3-tier package strategy that doubled average order value",
      "28:10 - Delegating production work while preserving quality",
      "41:00 - Elena's advice for new sellers in 2026"
    ]
  },
  {
    id: "ep-2",
    number: 33,
    title: "AI & The Next Decade of Independent Software Engineering",
    guest: "Kenji Sato",
    guestRole: "Principal AI Infrastructure Architect",
    duration: "54 min",
    date: "August 10, 2026",
    summary: "Kenji shares how he integrates LLM coding assistants and semantic search pipelines into full-stack client deliverables, delivering enterprise apps 3x faster.",
    timestamps: [
      "06:20 - Why prompt engineering is evolving into systems engineering",
      "19:45 - The real-time marketplace tech stack of Workvence",
      "35:10 - How senior contractors charge for speed rather than hours"
    ]
  },
  {
    id: "ep-3",
    number: 32,
    title: "Escrow Systems, KYC & Why Trust is the Marketplace Moat",
    guest: "Marcus Vance",
    guestRole: "VP of Marketplace Trust & Risk",
    duration: "42 min",
    date: "July 22, 2026",
    summary: "An inside look at how Workvence protects buyer funds, verifies freelancer identity, and mediates high-stakes international contracts.",
    timestamps: [
      "05:00 - The mathematics behind zero-latency escrow release",
      "18:20 - Preventing buyer fraud and chargebacks",
      "31:40 - The future of global multi-currency settlements"
    ]
  }
];

export default function PodcastPage() {
  const [playingId, setPlayingId] = useState<string | null>("ep-1");
  const [isPlaying, setIsPlaying] = useState(false);
  const [progress, setProgress] = useState(32);

  const activeEpisode = episodes.find((e) => e.id === playingId) || episodes[0];

  const togglePlay = (id: string) => {
    if (playingId === id) {
      setIsPlaying(!isPlaying);
    } else {
      setPlayingId(id);
      setIsPlaying(true);
      setProgress(0);
      toast.success(`Now playing: Episode #${episodes.find(e => e.id === id)?.number}`);
    }
  };

  return (
    <div className="min-h-screen bg-white text-[#112131] font-sans">
      {/* Hero Section */}
      <section className="bg-gradient-to-b from-[#f2fbf6] via-[#f7fdf9] to-white border-b border-[rgba(0,0,0,0.10)] py-20 lg:py-28">
        <div className="container mx-auto px-4 md:px-6">
          <div className="max-w-3xl mx-auto text-center space-y-6">
            <div className="inline-flex items-center gap-2 px-3 py-1.5 rounded-full bg-white border border-[rgba(0,0,0,0.10)] text-[#0D6D5F] text-xs font-semibold">
              <Mic className="w-3.5 h-3.5 text-[#0D6D5F]" />
              <span>The Official Workvence Podcast</span>
            </div>
            <h1 className="text-3xl sm:text-5xl md:text-6xl font-normal tracking-tight text-[#0f172a] leading-tight">
              The Future of Independent <br className="hidden sm:inline" />
              <span className="text-[#0D6D5F]">Work & Creativity</span>
            </h1>
            <p className="text-xs sm:text-sm md:text-base text-gray-600 max-w-2xl mx-auto font-normal leading-relaxed">
              Candid conversations with the world's highest-earning freelancers, agency founders, engineers, and tech visionaries.
            </p>

            {/* Listening Platforms Badges */}
            <div className="flex flex-wrap items-center justify-center gap-3 pt-3">
              <Button
                type="button"
                variant="dark"
                size="sm"
                radius="fiverr"
                onClick={() => toast.success("Opening Spotify channel...")}
                rightIcon={<ExternalLink className="w-3 h-3 text-gray-400" />}
                className="px-4 py-2 font-semibold text-xs"
              >
                <span>Listen on Spotify</span>
              </Button>
              <Button
                type="button"
                variant="soft"
                size="sm"
                radius="fiverr"
                onClick={() => toast.success("Opening Apple Podcasts...")}
                rightIcon={<ExternalLink className="w-3 h-3 text-gray-400" />}
                className="px-4 py-2 bg-[#f1f5f9] text-gray-800 hover:bg-gray-200 font-semibold text-xs"
              >
                <span>Apple Podcasts</span>
              </Button>
              <Button
                type="button"
                variant="outline"
                size="sm"
                radius="fiverr"
                onClick={() => toast.success("Opening YouTube...")}
                rightIcon={<ExternalLink className="w-3 h-3 text-red-500" />}
                className="px-4 py-2 bg-red-50 text-red-700 border-red-200 hover:bg-red-100 font-semibold text-xs"
              >
                <span>YouTube Watch</span>
              </Button>
            </div>
          </div>
        </div>
      </section>

      {/* Featured / Active Episode Player Banner */}
      <section className="py-12 bg-white">
        <div className="container mx-auto px-4 md:px-6 max-w-4xl">
          <div className="bg-[#0f172a] text-white rounded-[6px] p-8 sm:p-10 shadow-xl space-y-6 border border-[rgba(0,0,0,0.10)]">
            <div className="flex items-center justify-between">
              <span className="px-3 py-1 rounded-full text-xs font-bold bg-[#0D6D5F]/20 text-[#0D6D5F] border border-[#0D6D5F]/30">
                Episode #{activeEpisode.number} • Featured
              </span>
              <span className="text-xs text-gray-400 flex items-center gap-1">
                <Clock className="w-3.5 h-3.5" />
                {activeEpisode.duration}
              </span>
            </div>

            <div className="space-y-2">
              <h2 className="text-2xl sm:text-3xl font-bold leading-tight">{activeEpisode.title}</h2>
              <p className="text-xs sm:text-sm text-gray-300">
                Guest: <span className="text-[#0D6D5F] font-semibold">{activeEpisode.guest}</span> ({activeEpisode.guestRole})
              </p>
            </div>

            {/* Audio Wave / Scrubber Bar */}
            <div className="space-y-2 pt-2">
              <div
                className="w-full bg-white/20 h-2 rounded-full cursor-pointer relative overflow-hidden"
                onClick={(e) => {
                  const rect = e.currentTarget.getBoundingClientRect();
                  const pct = ((e.clientX - rect.left) / rect.width) * 100;
                  setProgress(Math.round(pct));
                }}
              >
                <div
                  className="bg-[#0D6D5F] h-full rounded-full transition-all duration-100"
                  style={{ width: `${progress}%` }}
                />
              </div>
              <div className="flex justify-between text-[11px] text-gray-400">
                <span>{Math.floor((progress / 100) * 48)}:12</span>
                <span>{activeEpisode.duration}</span>
              </div>
            </div>

            {/* Controls Bar */}
            <div className="flex items-center justify-between pt-2">
              <div className="flex items-center gap-4">
                <Button
                  type="button"
                  variant="brand"
                  size="icon"
                  radius="fiverr"
                  onClick={() => togglePlay(activeEpisode.id)}
                  className="w-10 h-10 shadow-xs active:scale-95 p-0 bg-[#0D6D5F] hover:bg-[#0b5c50] text-white"
                  aria-label={isPlaying && playingId === activeEpisode.id ? "Pause" : "Play"}
                >
                  {isPlaying && playingId === activeEpisode.id ? (
                    <Pause className="w-5 h-5" />
                  ) : (
                    <Play className="w-5 h-5 ml-0.5" />
                  )}
                </Button>
                <span className="text-xs font-semibold text-gray-300">
                  {isPlaying ? "Playing Now" : "Click to Play Episode"}
                </span>
              </div>

              <div className="flex items-center gap-2">
                <Button
                  type="button"
                  variant="soft"
                  size="icon"
                  radius="fiverr"
                  onClick={() => {
                    navigator.clipboard?.writeText(window.location.href);
                    toast.success("Episode link copied!");
                  }}
                  className="p-2.5 bg-white/10 hover:bg-white/20 text-gray-300 cursor-pointer"
                  aria-label="Share episode"
                >
                  <Share2 className="w-4 h-4" />
                </Button>
              </div>
            </div>
          </div>
        </div>
      </section>

      {/* Episode Archive List */}
      <section className="pt-12 pb-[80px] min-[1400px]:pb-[100px] bg-white">
        <div className="container mx-auto px-4 md:px-6 max-w-4xl space-y-6">
          <div className="flex items-center justify-between border-b border-[rgba(0,0,0,0.10)] pb-4">
            <h3 className="text-2xl sm:text-3xl font-bold text-[#0f172a] tracking-tight">All Episodes</h3>
            <span className="text-xs text-gray-500 font-medium">34 Available</span>
          </div>

          <div className="space-y-6">
            {episodes.map((ep) => (
              <div
                key={ep.id}
                className="bg-white border border-[rgba(0,0,0,0.10)] rounded-[6px] p-7 hover:border-[#0D6D5F]/40 shadow-xs transition duration-200 space-y-4"
              >
                <div className="flex items-start justify-between gap-4">
                  <div className="space-y-1">
                    <span className="text-xs font-bold uppercase tracking-wider text-[#0D6D5F]">Episode #{ep.number}</span>
                    <h4 className="text-base sm:text-lg font-bold text-[#0f172a]">{ep.title}</h4>
                    <p className="text-xs text-gray-500">
                      With {ep.guest} • {ep.date} • {ep.duration}
                    </p>
                  </div>

                  <button
                    type="button"
                    onClick={() => togglePlay(ep.id)}
                    className="w-10 h-10 shrink-0 rounded-[6px] bg-[#fff] border border-[rgba(0,0,0,0.10)] text-[#0D6D5F] hover:bg-[#0D6D5F] hover:text-white flex items-center justify-center transition duration-150 cursor-pointer"
                    aria-label={isPlaying && playingId === ep.id ? "Pause" : "Play"}
                  >
                    {isPlaying && playingId === ep.id ? (
                      <Pause className="w-4 h-4" />
                    ) : (
                      <Play className="w-4 h-4 ml-0.5" />
                    )}
                  </button>
                </div>

                <p className="text-xs sm:text-[13px] text-gray-600 leading-relaxed font-normal">
                  {ep.summary}
                </p>

                {/* Show Notes / Timestamps */}
                <div className="pt-3 border-t border-[rgba(0,0,0,0.06)] space-y-1.5">
                  <span className="text-[11px] font-bold text-gray-400 uppercase tracking-wider block">
                    Episode Timestamps:
                  </span>
                  <div className="grid grid-cols-1 sm:grid-cols-2 gap-1.5 text-xs text-gray-600">
                    {ep.timestamps.map((t, i) => (
                      <div key={i} className="flex items-center gap-1.5">
                        <span className="w-1.5 h-1.5 rounded-full bg-[#0D6D5F]" />
                        <span>{t}</span>
                      </div>
                    ))}
                  </div>
                </div>
              </div>
            ))}
          </div>
        </div>
      </section>
    </div>
  );
}

"use client";

import { useEffect, useState } from "react";
import Link from "next/link";
import { Star, MapPin, Briefcase } from "lucide-react";
import { axiosFetch } from "@/utils";
import { toast } from "@/utils/toast";

const RecommendedSellers = () => {
  const [sellers, setSellers] = useState<any[]>([]);
  const [isLoading, setIsLoading] = useState(true);

  useEffect(() => {
    const fetchSellers = async () => {
      try {
        const { data } = await axiosFetch.get("/users/random-sellers?limit=20");
        if (!data.error) {
          setSellers(data.sellers || []);
        } else {
          toast.error(data.message || "Failed to fetch recommended sellers");
        }
      } catch (err: any) {
        toast.error(err.message || "An error occurred while fetching sellers");
      } finally {
        setIsLoading(false);
      }
    };

    fetchSellers();
  }, []);

  return (
    <div className="w-full min-h-[80vh] bg-gray-50 pt-16 pb-[80px] min-[1400px]:pb-[100px]">
      <div className="container mx-auto px-4 md:px-8">
        <div className="mb-12 text-center md:text-left space-y-2">
