"use client";

import { useState, useMemo, useEffect } from "react";
import { useQuery, useMutation, useQueryClient } from "@tanstack/react-query";
import { useRouter } from "next/navigation";
import Link from "next/link";
import moment from "moment";
import { toast } from "@/utils/toast";
import {
  FiMoreVertical,
  FiPlus,
  FiEye,
  FiUsers,
  FiXCircle,
  FiArrowRight,
  FiSearch,
  FiX,
  FiChevronDown,
  FiEdit3,
  FiRotateCcw,
  FiTrash2,
} from "react-icons/fi";

import { axiosFetch } from "@/utils";
import { useUserStore } from "@/store/userStore";
import { Button, AiGradientButton } from "@/components";
import { CustomSelect, CustomSelectOption, BriefsListSkeleton, ConfirmModal } from "@/components/ui";
import { EditBriefModal } from "@/features/buyer";
import { HugeiconsIcon } from "@hugeicons/react";
import { FolderKanbanIcon } from "@hugeicons/core-free-icons";

const DEFAULT_AVATARS = [
  "https://images.unsplash.com/photo-1534528741775-53994a69daeb?w=100&auto=format&fit=crop&q=80",
  "https://images.unsplash.com/photo-1507003211169-0a1dd7228f2d?w=100&auto=format&fit=crop&q=80",
  "https://images.unsplash.com/photo-1500648767791-00dcc994a43e?w=100&auto=format&fit=crop&q=80",
];

const BRIEF_SORT_OPTIONS: CustomSelectOption[] = [
  { value: "newest", label: "Sort: Newest" },
  { value: "proposals", label: "Sort: Most Proposals" },
  { value: "budget", label: "Sort: Budget" },
];

const getBriefTags = (brief: any): string[] => {
  if (Array.isArray(brief.skills) && brief.skills.length > 0) {
    return brief.skills.slice(0, 3);
  }
  if (Array.isArray(brief.tags) && brief.tags.length > 0) {
    return brief.tags.slice(0, 3);
  }
  // Contextual smart fallback based on category & title
  const cat = (brief.category || "").toLowerCase();
  const title = (brief.title || "").toLowerCase();

  if (cat.includes("data") || title.includes("data") || title.includes("analys")) {
    return ["Detail-oriented", "Data Scientist", "Data Analyst"];
  }
  if (cat.includes("design") || cat.includes("illustrat") || title.includes("graphic") || title.includes("logo")) {
    return ["Imaginative", "Graphic Artist", "Illustrator"];
  }
  if (cat.includes("mobile") || cat.includes("app") || title.includes("mobile") || title.includes("flutter") || title.includes("react native")) {
    return ["Creative thinker", "Mobile Developer", "App Engineer"];
  }
  if (cat.includes("security") || cat.includes("cyber") || title.includes("security")) {
    return ["Analytical", "Security Analyst", "Network Security Engineer"];
  }
  if (cat.includes("content") || cat.includes("writ") || title.includes("writing") || title.includes("seo")) {
    return ["Communicative", "Content Writer", "Copywriter"];
  }
  if (cat.includes("management") || title.includes("project") || title.includes("manage") || title.includes("lead")) {
    return ["Organized", "Project Manager", "Scrum Master"];
  }
  if (cat.includes("web") || title.includes("web") || title.includes("full stack") || title.includes("developer")) {
    return ["Frontend", "Full Stack", "Web Developer"];
  }
  return [brief.category || "Professional", "Expert", "Reliable"];
};

const getWorkType = (brief: any, index: number): string => {
  if (brief.workType) return brief.workType;
  if (brief.location) return brief.location;
  if (brief.deliveryTime) return `${brief.deliveryTime} Days`;
  const types = ["On-site", "Remote", "Hybrid", "On-site", "Remote", "Hybrid"];
  return types[index % types.length];
};

const getRateBadge = (brief: any): string => {
  if (brief.hoursPerWeek) return `${brief.hoursPerWeek} hrs/week`;
  if (brief.budget) return typeof brief.budget === "number" ? `$${brief.budget}` : String(brief.budget);
  if (brief.deliveryTime) return `${brief.deliveryTime} Days`;
  return "40 hrs/week";
};

type BriefFilter = "all" | "new_proposals" | "new_projects" | "open" | "closed";

const isProjectNew = (brief: any): boolean => {
  if (!brief?.createdAt) return false;
  return moment().diff(moment(brief.createdAt), "days") <= 14;
};

const MyBriefs = () => {
  const router = useRouter();
  const user = useUserStore((state) => state.user);
  const queryClient = useQueryClient();
  const [filter, setFilter] = useState<BriefFilter>("all");
  const [searchQuery, setSearchQuery] = useState("");
  const [sortBy, setSortBy] = useState<"newest" | "proposals" | "budget">("newest");
  const [openMenuId, setOpenMenuId] = useState<string | null>(null);
  const [editingBrief, setEditingBrief] = useState<any | null>(null);
  const [deletingBriefId, setDeletingBriefId] = useState<string | null>(null);

  useEffect(() => {
    window.scrollTo(0, 0);
    const handleClickOutside = () => setOpenMenuId(null);
    window.addEventListener("click", handleClickOutside);
    return () => window.removeEventListener("click", handleClickOutside);
  }, []);

  // Real backend query
  const { isLoading, data: briefs = [] } = useQuery({
    queryKey: ["my-briefs"],
    queryFn: () =>
      axiosFetch
        .get("/briefs/my-briefs")
        .then(({ data }) => {
          if (Array.isArray(data)) return data;
          if (Array.isArray(data?.briefs)) return data.briefs;
          if (Array.isArray(data?.data)) return data.data;
          return [];
        })
        .catch(() => []),
  });

  const closeMutation = useMutation({
    mutationFn: (briefId: string) =>
      axiosFetch.patch(`/briefs/${briefId}/close`).then(({ data }) => data),
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ["my-briefs"] });
      toast.success("Project closed successfully");
    },
    onError: (err: any) => {
      toast.error(err?.response?.data?.message || "Failed to close project");
    },
  });

  const reopenMutation = useMutation({
    mutationFn: (briefId: string) =>
      axiosFetch.patch(`/briefs/${briefId}/reopen`).then(({ data }) => data),
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ["my-briefs"] });
      toast.success("Project reopened successfully");
    },
    onError: (err: any) => {
      toast.error(err?.response?.data?.message || "Failed to reopen project");
    },
  });

  const deleteMutation = useMutation({
    mutationFn: (briefId: string) =>
      axiosFetch.delete(`/briefs/${briefId}`).then(({ data }) => data),
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ["my-briefs"] });
      setDeletingBriefId(null);
      toast.success("Project deleted successfully");
    },
    onError: (err: any) => {
      toast.error(err?.response?.data?.message || "Failed to delete project");
    },
  });

  const briefsArray = Array.isArray(briefs) ? briefs : [];

  // Count stats for filter pills
  const counts = useMemo(() => {
    let newProposalsCount = 0;
    let newProjectsCount = 0;
    let openCount = 0;
    let closedCount = 0;

    briefsArray.forEach((b: any) => {
      const isClosed = b.isClosed || b.status === "closed";
      const pCount =
        b.proposalCount ??
        b.proposalsCount ??
        (Array.isArray(b.proposals) ? b.proposals.length : 0);

      if (pCount > 0 && !isClosed) newProposalsCount++;
      if (isProjectNew(b) && !isClosed) newProjectsCount++;
      if (!isClosed) openCount++;
      if (isClosed) closedCount++;
    });

    return {
      all: briefsArray.length,
      new_proposals: newProposalsCount,
      new_projects: newProjectsCount,
      open: openCount,
      closed: closedCount,
    };
  }, [briefsArray]);

  const filtered = useMemo(() => {
    let list = [...briefsArray];

    // 1. Status / Pill Filter
    if (filter === "open") {
      list = list.filter((b) => !b.isClosed && b.status !== "closed");
    } else if (filter === "closed") {
      list = list.filter((b) => b.isClosed || b.status === "closed");
    } else if (filter === "new_proposals") {
      list = list.filter((b) => {
        const isClosed = b.isClosed || b.status === "closed";
        const pCount =
          b.proposalCount ??
          b.proposalsCount ??
          (Array.isArray(b.proposals) ? b.proposals.length : 0);
        return pCount > 0 && !isClosed;
      });
    } else if (filter === "new_projects") {
      list = list.filter((b) => isProjectNew(b) && !b.isClosed && b.status !== "closed");
    }

    // 2. Keyword Search
    const q = searchQuery.trim().toLowerCase();
    if (q) {
      list = list.filter((b) => {
        const title = (b.title || "").toLowerCase();
        const description = (b.description || "").toLowerCase();
        const category = (b.category || "").toLowerCase();
        const skills = Array.isArray(b.skills)
          ? b.skills.join(" ").toLowerCase()
          : Array.isArray(b.requiredSkills)
            ? b.requiredSkills.join(" ").toLowerCase()
            : "";
        return (
          title.includes(q) ||
          description.includes(q) ||
          category.includes(q) ||
          skills.includes(q)
        );
      });
    }

    // 3. Sorting
    list.sort((a, b) => {
      if (sortBy === "proposals") {
        const pA = a.proposalCount ?? a.proposalsCount ?? (Array.isArray(a.proposals) ? a.proposals.length : 0);
        const pB = b.proposalCount ?? b.proposalsCount ?? (Array.isArray(b.proposals) ? b.proposals.length : 0);
        return pB - pA;
      }
      if (sortBy === "budget") {
        const bA = typeof a.budget === "number" ? a.budget : parseFloat(a.budget) || 0;
        const bB = typeof b.budget === "number" ? b.budget : parseFloat(b.budget) || 0;
        return bB - bA;
      }
      // Default: newest first
      return new Date(b.createdAt || 0).getTime() - new Date(a.createdAt || 0).getTime();
    });

    return list;
  }, [briefsArray, filter, searchQuery, sortBy]);

  const emptyState = useMemo(() => {
    if (searchQuery) {
      return {
        title: "No matching projects found",
        description: `We couldn't find any projects matching "${searchQuery}". Try adjusting your keywords.`,
      };
    }
    switch (filter) {
      case "new_proposals":
        return {
          title: "No projects with new proposals",
          description: "None of your active projects have received candidate proposals yet.",
        };
      case "new_projects":
        return {
          title: "No new projects",
          description: "Projects posted within the last 14 days will appear here.",
        };
      case "open":
        return {
          title: "No open projects",
          description: "You don't have any open projects at the moment.",
        };
      case "closed":
        return {
          title: "No closed projects",
          description: "Completed or archived projects will appear here.",
        };
      default:
        return {
          title: "No projects posted yet",
          description: "Post your project specifications to receive detailed proposals from vetted freelancers.",
        };
    }
  }, [filter, searchQuery]);

  if (!user) {
    return (
      <div className="min-h-screen bg-[#F5F5F5] pt-6 sm:pt-10 pb-[80px] font-sans">
        <div className="container mx-auto px-4 md:px-6">
          <BriefsListSkeleton />
        </div>
      </div>
    );
  }

  return (
    <div className="min-h-screen bg-[#F5F5F5] pt-6 sm:pt-10 pb-[80px] min-[1400px]:pb-[100px] font-sans">
      <div className="container mx-auto px-4 md:px-6">

        {/* Title Header */}
        <div className="flex flex-col sm:flex-row sm:items-center justify-between gap-4 mb-6">
          <div>
            <h1 className="text-xl sm:text-[34px] font-bold text-slate-900 tracking-tight">
              My Projects
            </h1>
            <p className="text-slate-500 text-xs sm:text-sm mt-1.5">
              Keep track of your projects, progress, milestones, and updates all in one place.
            </p>
          </div>
          {!user?.isSeller && (
            <AiGradientButton
              href="/briefs/create?ai=true"
              text="Post a Project with AI"
              icon={
                <svg xmlns="http://www.w3.org/2000/svg" width="17" height="17" viewBox="0 0 17 17" fill="none">
                  <path d="M0.75 7.60886C3.56875 4.84296 10.19 -0.808996 12.025 1.15511C14.3438 3.63702 2.15937 9.91366 4.03854 12.6791C6.0234 15.6001 12.9646 5.30336 15.3135 7.14726C17.6625 8.99126 9.676 13.1401 11.5552 15.4451C12.3069 16.367 14.3739 14.9841 15.3135 14.0621" stroke="#292929" strokeWidth="1.5" strokeLinecap="round" strokeLinejoin="round" />
                </svg>
              }
              px="px-3.5 sm:px-4.5"
              py="py-2 sm:py-2.5"
              className="h-[40px] rounded-[6px] text-[16px] font-semibold text-[#112131] shadow-none shrink-0 whitespace-nowrap self-start sm:self-center"
            />
          )}
        </div>

        {/* Filter Pills & Search / Sort Toolbar */}
        <div className="flex flex-col xl:flex-row xl:items-center justify-between gap-3.5 sm:gap-4 mb-6 sm:mb-8 w-full min-w-0 max-w-full">
          {/* Filter Pills (Scrollable with edge bleed on mobile, smooth track on larger screens) */}
          <div className="w-full xl:w-auto min-w-0 max-w-full overflow-x-auto [-ms-overflow-style:none] [scrollbar-width:none] [&::-webkit-scrollbar]:hidden py-1 -mx-4 px-4 sm:mx-0 sm:px-0">
            <div className="flex items-center gap-1.5 sm:gap-2 min-w-max">
              <Button
                type="button"
                variant={filter === "all" ? "dark" : "outline"}
                size="sm"
                radius="full"
                onClick={() => setFilter("all")}
                className="px-3 sm:px-3.5 py-1.5 font-semibold text-xs sm:text-[13px] !inline-flex !items-center !flex-nowrap !whitespace-nowrap shrink-0"
              >
                <span className="whitespace-nowrap shrink-0">All Projects</span>
                <span className={`inline-flex items-center justify-center min-w-[20px] h-5 px-1.5 rounded-full text-[11px] font-bold leading-none shrink-0 whitespace-nowrap ${filter === "all" ? "bg-white/20 text-white" : "bg-slate-100 text-slate-600"
                  }`}>
                  {counts.all}
                </span>
              </Button>

              <Button
                type="button"
                variant={filter === "new_proposals" ? "dark" : "outline"}
                size="sm"
                radius="full"
                onClick={() => setFilter("new_proposals")}
                className={`px-3 sm:px-3.5 py-1.5 font-semibold text-xs sm:text-[13px] !inline-flex !items-center !flex-nowrap !whitespace-nowrap shrink-0 ${filter === "new_proposals" ? "!bg-[#0D6D5F] hover:!bg-[#0B403F] text-white border-transparent" : ""
                  }`}
              >
                <span className="whitespace-nowrap shrink-0">New Proposals</span>
                <span className={`inline-flex items-center justify-center min-w-[20px] h-5 px-1.5 rounded-full text-[11px] font-bold leading-none shrink-0 whitespace-nowrap ${filter === "new_proposals" ? "bg-white/20 text-white" : "bg-emerald-50 text-emerald-700"
                  }`}>
                  {counts.new_proposals}
                </span>
              </Button>

              <Button
                type="button"
                variant={filter === "new_projects" ? "dark" : "outline"}
                size="sm"
                radius="full"
                onClick={() => setFilter("new_projects")}
                className={`px-3 sm:px-3.5 py-1.5 font-semibold text-xs sm:text-[13px] !inline-flex !items-center !flex-nowrap !whitespace-nowrap shrink-0 ${filter === "new_projects" ? "!bg-[#0D6D5F] hover:!bg-[#0B403F] text-white border-transparent" : ""
                  }`}
              >
                <span className="whitespace-nowrap shrink-0">New Projects</span>
                <span className={`inline-flex items-center justify-center min-w-[20px] h-5 px-1.5 rounded-full text-[11px] font-bold leading-none shrink-0 whitespace-nowrap ${filter === "new_projects" ? "bg-white/20 text-white" : "bg-blue-50 text-blue-700"
                  }`}>
                  {counts.new_projects}
                </span>
              </Button>

              <Button
                type="button"
                variant={filter === "open" ? "dark" : "outline"}
                size="sm"
                radius="full"
                onClick={() => setFilter("open")}
                className="px-3 sm:px-3.5 py-1.5 font-semibold text-xs sm:text-[13px] !inline-flex !items-center !flex-nowrap !whitespace-nowrap shrink-0"
              >
                <span className="whitespace-nowrap shrink-0">Open</span>
                <span className={`inline-flex items-center justify-center min-w-[20px] h-5 px-1.5 rounded-full text-[11px] font-bold leading-none shrink-0 whitespace-nowrap ${filter === "open" ? "bg-white/20 text-white" : "bg-slate-100 text-slate-600"
                  }`}>
                  {counts.open}
                </span>
              </Button>

              <Button
                type="button"
                variant={filter === "closed" ? "dark" : "outline"}
                size="sm"
                radius="full"
                onClick={() => setFilter("closed")}
                className="px-3 sm:px-3.5 py-1.5 font-semibold text-xs sm:text-[13px] !inline-flex !items-center !flex-nowrap !whitespace-nowrap shrink-0"
              >
                <span className="whitespace-nowrap shrink-0">Closed</span>
                <span className={`inline-flex items-center justify-center min-w-[20px] h-5 px-1.5 rounded-full text-[11px] font-bold leading-none shrink-0 whitespace-nowrap ${filter === "closed" ? "bg-white/20 text-white" : "bg-slate-100 text-slate-600"
                  }`}>
                  {counts.closed}
                </span>
              </Button>
            </div>
          </div>

          {/* Search and Sort Toolbar */}
          <div className="flex flex-col sm:flex-row items-stretch sm:items-center gap-2.5 w-full xl:w-auto shrink-0">
            {/* Search Input */}
            <div className="relative flex items-center flex-1 sm:w-64 min-w-0">
              <FiSearch className="absolute left-3 text-slate-400 text-xs sm:text-sm pointer-events-none" />
              <input
                type="text"
                placeholder="Search projects..."
                value={searchQuery}
                onChange={(e) => setSearchQuery(e.target.value)}
                className="w-full pl-8 sm:pl-9 pr-7 py-2 bg-white border border-slate-200 focus:border-[#0D6D5F] focus:ring-1 focus:ring-[#0D6D5F] rounded-[6px] text-xs sm:text-[13px] text-slate-800 placeholder:text-slate-400 outline-none transition-all shadow-2xs h-[38px]"
              />
              {searchQuery && (
                <button
                  type="button"
                  onClick={() => setSearchQuery("")}
                  className="absolute right-2 text-slate-400 hover:text-slate-600 p-1"
                  aria-label="Clear search"
                >
                  <FiX className="text-xs" />
                </button>
              )}
            </div>

            {/* Sort Select */}
            <div className="w-full sm:w-[195px] shrink-0">
              <CustomSelect
                size="sm"
                options={BRIEF_SORT_OPTIONS}
                value={sortBy}
                onChange={(val) => setSortBy(val as any)}
                placeholder="Sort: Newest"
                ariaLabel="Sort briefs"
              />
            </div>
          </div>
        </div>

        {/* Content Section */}
        {isLoading ? (
          <BriefsListSkeleton />
        ) : filtered.length === 0 ? (
          <div className="text-center py-16 px-6 bg-white rounded-[6px] border border-slate-200/90 shadow-[0_1px_3px_rgba(0,0,0,0.02)] flex flex-col items-center">
            <div className="w-10 h-10 rounded-[6px] bg-white border border-[rgba(0,0,0,0.10)] flex items-center justify-center text-2xl mb-4 text-slate-400">
              <HugeiconsIcon icon={FolderKanbanIcon} size={20} color="#292929" />
            </div>
            <h3 className="text-lg font-bold text-slate-900 mb-1.5">
              {emptyState.title}
            </h3>
            <p className="text-slate-500 text-xs sm:text-sm max-w-md mb-6">
              {emptyState.description}
            </p>
            {filter === "all" && !searchQuery && !user?.isSeller ? (
              <Link
                href="/briefs/create"
                className="px-5 py-2.5 rounded-[6px] font-semibold text-xs sm:text-sm bg-[#0B0F19] hover:bg-black text-white transition-colors cursor-pointer shadow-xs"
              >
                Post Your First Project
              </Link>
            ) : (
              <Button
                type="button"
                variant="soft"
                size="md"
                radius="xl"
                onClick={() => {
                  setFilter("all");
                  setSearchQuery("");
                }}
                className="px-5 py-2.5 font-semibold text-xs sm:text-sm bg-slate-100 hover:bg-slate-200 text-slate-800"
              >
                Show All Projects
              </Button>
            )}
          </div>
        ) : (
          <div className="grid grid-cols-1 lg:grid-cols-2 gap-6">
            {filtered.map((brief: any, index: number) => {
              const isClosed = brief.isClosed || brief.status === "closed";
              const isNew = isProjectNew(brief);
              const proposalCount =
                brief.proposalCount ??
                brief.proposalsCount ??
                (Array.isArray(brief.proposals) ? brief.proposals.length : 0);
              const tags = getBriefTags(brief);
              const workType = getWorkType(brief, index);
              const rateBadge = getRateBadge(brief);
              const isMenuOpen = openMenuId === brief._id;

              return (
                <div
                  key={brief._id}
                  onClick={() => router.push(`/briefs/${brief._id}`)}
                  className={`relative bg-white rounded-[6px] border border-slate-200/90 hover:border-[var(--purple-200,#B78AF7)] hover:rounded-[6px] shadow-[0_1px_3px_rgba(0,0,0,0.02)] hover:shadow-md p-5 sm:p-6 sm:p-7 flex flex-col justify-between transition-all duration-300 group cursor-pointer ${isMenuOpen ? "z-30 overflow-visible" : "overflow-hidden"
                    }`}
                >
                  {/* Ambient Purple Glow (contained in clipped layer so it never overflows) */}
                  <div className="absolute inset-0 overflow-hidden rounded-[6px] pointer-events-none z-0">
                    <div
                      className="absolute opacity-0 group-hover:opacity-100 transition-opacity duration-500 ease-out"
                      style={{
                        position: "absolute",
                        right: "-210px",
                        top: "-407px",
                        width: "555px",
                        height: "513px",
                        borderRadius: "555px",
                        transform: "rotate(-180deg)",
                        background: "var(--purple-100, #CEB0FA)",
                        filter: "blur(150px)",
                      }}
                      aria-hidden="true"
                    />
                  </div>

                  {/* Top Header Row */}
                  <div className={`relative ${isMenuOpen ? "z-40" : "z-10"}`}>
                    <div className="flex items-start justify-between gap-3">
                      <div className="min-w-0 flex-1">
                        <div className="relative group/title max-w-full inline-block">
                          <h2 className="text-base sm:text-[19px] font-bold text-slate-900 tracking-tight group-hover:text-slate-950 truncate">
                            {brief.title}
                          </h2>

                          {/* Custom Floating Tooltip */}
                          <div className="pointer-events-none absolute left-0 top-full mt-1.5 hidden group-hover/title:flex items-center z-50 animate-in fade-in zoom-in-95 duration-150">
                            <div className="relative bg-slate-900 text-white text-xs font-medium px-3 py-1.5 rounded-[6px] shadow-xl max-w-xs sm:max-w-sm whitespace-normal leading-snug border border-slate-800">
                              {brief.title}
                              <div className="absolute -top-1 left-4 w-2 h-2 bg-slate-900 rotate-45 border-l border-t border-slate-800" />
                            </div>
                          </div>
                        </div>
                        <div className="flex flex-wrap items-center gap-1.5 text-xs text-slate-400 mt-1">
                          <span>Posted {moment(brief.createdAt).fromNow()}</span>
                          {/* <span>{workType}</span> */}


                          {isClosed && (
                            <>
                              <span>•</span>
                              <span className="text-rose-600 font-semibold bg-rose-50 border border-rose-200/80 text-[11px] px-2 py-0.5 rounded-full">
                                Inactive
                              </span>
                            </>
                          )}
                        </div>
                      </div>

                      {/* Right Badges & Menu */}
                      <div className="flex items-center gap-2 shrink-0">
                        {/* Purple Rate Pill */}
                        <span className="bg-[#F3E8FF] text-[#7E22CE] border border-[#E9D5FF] text-xs font-bold px-3 py-1 rounded-full whitespace-nowrap">
                          {rateBadge}
                        </span>

                        {/* Category Pill */}
                        <span className="bg-slate-50 border border-slate-200 text-slate-800 text-xs font-semibold px-3 py-1 rounded-full max-w-[150px] truncate hidden sm:inline-block">
                          {brief.category || "General"}
                        </span>

                        {/* More Action Menu Button */}
                        <div
                          className={`relative ${isMenuOpen ? "z-50" : ""}`}
                          onClick={(e) => {
                            e.stopPropagation();
                            setOpenMenuId(isMenuOpen ? null : brief._id);
                          }}
                        >
                          <Button
                            type="button"
                            variant="ghost"
                            size="icon"
                            radius="full"
                            className="w-8 h-8 !p-0 aspect-square text-[#292929] hover:text-slate-700 hover:bg-slate-100 border-none shadow-none shrink-0"
                            title="Options"
                          >
                            <FiMoreVertical className="w-4 h-4 text-[#292929]" />
                          </Button>

                          {/* Dropdown Menu */}
                          {isMenuOpen && (
                            <div
                              onClick={(e) => e.stopPropagation()}
                              className="absolute right-0 top-9 w-44 bg-white border border-gray-100 rounded-[6px] shadow-2xl py-1.5 z-50 overflow-hidden animate-in fade-in slide-in-from-top-2 duration-150"
                            >


                              {!isClosed && (
                                <Button
                                  type="button"
                                  variant="ghost"
                                  size="sm"
                                  radius="none"
                                  fullWidth
                                  onClick={() => {
                                    setOpenMenuId(null);
                                    setEditingBrief(brief);
                                  }}
                                  leftIcon={<FiEdit3 className="text-[#292929] group-hover:text-teal-700" />}
                                  className="group !justify-start text-left px-3.5 py-2 text-xs font-medium text-[#292929] hover:bg-teal-50/70 hover:text-teal-800 border-none shadow-none h-auto min-h-0 transition-colors"
                                >
                                  Edit
                                </Button>
                              )}

                              {!isClosed && (
                                <Button
                                  type="button"
                                  variant="ghost"
                                  size="sm"
                                  radius="none"
                                  fullWidth
                                  onClick={() => {
                                    setOpenMenuId(null);
                                    closeMutation.mutate(brief._id || brief.id);
                                  }}
                                  leftIcon={<FiXCircle className="text-[#292929]" />}
                                  className="!justify-start text-left px-3.5 py-2 text-xs font-medium text-[#292929] hover:bg-amber-50 border-none shadow-none h-auto min-h-0 transition-colors"
                                >
                                  Inactive
                                </Button>
                              )}

                              {isClosed && (
                                <Button
                                  type="button"
                                  variant="ghost"
                                  size="sm"
                                  radius="none"
                                  fullWidth
                                  onClick={() => {
                                    setOpenMenuId(null);
                                    reopenMutation.mutate(brief._id || brief.id);
                                  }}
                                  leftIcon={<FiRotateCcw className="text-teal-600" />}
                                  className="!justify-start text-left px-3.5 py-2 text-xs font-medium text-teal-700 hover:bg-teal-50 border-none shadow-none h-auto min-h-0 transition-colors"
                                >
                                  Active
                                </Button>
                              )}

                              <Button
                                type="button"
                                variant="ghost"
                                size="sm"
                                radius="none"
                                fullWidth
                                onClick={() => {
                                  setOpenMenuId(null);
                                  setDeletingBriefId(brief._id || brief.id);
                                }}
                                leftIcon={<FiTrash2 className="text-rose-500" />}
                                className="!justify-start text-left px-3.5 py-2 text-xs font-medium text-rose-600 hover:bg-rose-50 border-none shadow-none h-auto min-h-0 transition-colors"
                              >
                                Delete
                              </Button>
                            </div>
                          )}
                        </div>
                      </div>
                    </div>

                    {/* Description */}
                    <p className="text-sm text-slate-600 line-clamp-2 my-4 leading-relaxed font-normal">
                      {brief.description}
                    </p>

                    {/* Skill Tags */}
                    <div className="flex flex-wrap gap-2 mb-6">
                      {tags.map((tag, tIdx) => (
                        <span
                          key={tIdx}
                          className="bg-[#F1F3F5] text-slate-700 text-xs font-medium px-3 py-1 rounded-[6px] border border-slate-200/60"
                        >
                          {tag}
                        </span>
                      ))}
                    </div>
                  </div>

                  {/* Divider & Footer */}
                  <div className="relative z-0 border-t border-slate-100 pt-4 flex items-center justify-between mt-auto">
                    {/* Left: Avatar Stack and Proposal Count */}
                    <div className="flex items-center">
                      {proposalCount > 0 ? (
                        <>
                          <div className="flex items-center -space-x-2 mr-2.5">
                            {DEFAULT_AVATARS.slice(0, Math.min(3, proposalCount)).map((imgSrc, aIdx) => (
                              <img
                                key={aIdx}
                                src={imgSrc}
                                alt="Applicant"
                                className="w-7 h-7 rounded-full border-2 border-white object-cover shadow-2xs"
                              />
                            ))}
                            <div className="w-7 h-7 rounded-full bg-slate-100 border-2 border-white text-[10px] font-bold text-slate-700 flex items-center justify-center shadow-2xs">
                              {proposalCount > 3 ? `${proposalCount - 2}+` : `${proposalCount}+`}
                            </div>
                          </div>
                          <span className="text-xs font-semibold text-slate-800">
                            {proposalCount} {proposalCount === 1 ? "proposal" : "proposals"}
                          </span>
                        </>
                      ) : (
                        <span className="text-xs text-slate-400 font-medium">
                          0 proposals
                        </span>
                      )}
                    </div>

                    {/* Right: View Details Link */}
                    <div className="flex items-center gap-1 text-xs sm:text-sm font-bold text-[#0D9488] ">
                      <span>View Details</span>
                      <FiArrowRight className="text-sm group-hover:translate-x-0.5 transition-transform" />
                    </div>
                  </div>
                </div>
              );
            })}
          </div>
        )}
      </div>

      {/* Edit Brief Modal */}
      <EditBriefModal
        isOpen={Boolean(editingBrief)}
        brief={editingBrief}
        onClose={() => setEditingBrief(null)}
      />

      {/* Confirm Delete Modal */}
      <ConfirmModal
        isOpen={Boolean(deletingBriefId)}
        title="Delete Project"
        message="Are you sure you want to delete this project? If proposals exist, the project will be safely archived; otherwise, it will be permanently removed."
        confirmText="Delete"
        variant="danger"
        isLoading={deleteMutation.isPending}
        onConfirm={() => deletingBriefId && deleteMutation.mutate(deletingBriefId)}
        onClose={() => setDeletingBriefId(null)}
      />
    </div>
  );
};

const MyProposals = () => {
  const router = useRouter();
  const { isLoading, data: proposals = [] } = useQuery({
    queryKey: ["my-proposals"],
    queryFn: () =>
      axiosFetch
        .get("/briefs/my-proposals")
        .then(({ data }) => {
          if (Array.isArray(data)) return data;
          if (Array.isArray(data?.proposals)) return data.proposals;
          if (Array.isArray(data?.data)) return data.data;
          return [];
        })
        .catch(() => []),
  });

  const proposalsArray = Array.isArray(proposals) ? proposals : [];

  return (
    <div className="min-h-screen bg-[#F5F5F5] pt-6 sm:pt-10 pb-[80px] min-[1400px]:pb-[100px] font-sans">
      <div className="container mx-auto px-4 md:px-6">

        {/* Title Header */}
        <div className="flex flex-col sm:flex-row sm:items-center justify-between gap-4 mb-8">
          <div>
            <h1 className="text-3xl sm:text-[34px] font-bold text-slate-900 tracking-tight">
              My Proposals
            </h1>
            <p className="text-slate-500 text-xs sm:text-sm mt-1.5">
              Track your submitted proposals, client responses, and bidding status.
            </p>
          </div>
          <Link
            href="/briefs"
            className="inline-flex items-center justify-center gap-2 px-4.5 py-2.5 rounded-[6px] bg-[#0B0F19] hover:bg-black text-white text-xs sm:text-sm font-semibold transition-colors shadow-xs shrink-0 self-start sm:self-center"
          >
            <span>Browse Open Projects</span>
          </Link>
        </div>

        {/* Content Section */}
        {isLoading ? (
          <BriefsListSkeleton />
        ) : proposalsArray.length === 0 ? (
          <div className="text-center py-16 px-6 bg-white rounded-[6px] border border-slate-200/90 shadow-[0_1px_3px_rgba(0,0,0,0.02)] flex flex-col items-center">
            <div className="w-14 h-14 rounded-[6px] bg-slate-50 border border-slate-200 flex items-center justify-center text-2xl mb-4 text-slate-400">
              📝
            </div>
            <h3 className="text-lg font-bold text-slate-900 mb-1.5">No proposals submitted</h3>
            <p className="text-slate-500 text-xs sm:text-sm max-w-md mb-6">
              You haven&apos;t submitted any proposals yet. Browse open client projects and start pitching!
            </p>
            <Link
              href="/briefs"
              className="px-5 py-2.5 rounded-[6px] font-semibold text-xs sm:text-sm bg-[#0B0F19] hover:bg-black text-white transition-colors cursor-pointer shadow-xs"
            >
              Browse Open Projects
            </Link>
          </div>
        ) : (
          <div className="grid grid-cols-1 lg:grid-cols-2 gap-6">
            {proposalsArray.map((proposal: any) => {
              const brief = proposal.briefID || {};
              const briefId = brief._id || proposal.briefID;

              return (
                <div
                  key={proposal._id}
                  onClick={() => router.push(`/briefs/${briefId}`)}
                  className="relative overflow-hidden bg-white rounded-[6px] border border-slate-200/90 hover:border-[var(--purple-200,#B78AF7)] hover:rounded-[6px] shadow-[0_1px_3px_rgba(0,0,0,0.02)] hover:shadow-md p-6 sm:p-7 flex flex-col justify-between transition-all duration-300 group cursor-pointer"
                >
                  {/* Ambient Purple Glow (appears on card hover) */}
                  <div
                    className="absolute pointer-events-none opacity-0 group-hover:opacity-100 transition-opacity duration-500 ease-out z-0"
                    style={{
                      position: "absolute",
                      right: "-210px",
                      top: "-407px",
                      width: "555px",
                      height: "513px",
                      borderRadius: "555px",
                      transform: "rotate(-180deg)",
                      background: "var(--purple-100, #CEB0FA)",
                      filter: "blur(150px)",
                    }}
                    aria-hidden="true"
                  />

                  <div className="relative z-10">
                    <div className="flex items-start justify-between gap-3">
                      <div className="min-w-0 flex-1">
                        <h2 className="text-lg sm:text-[19px] font-bold text-slate-900 tracking-tight group-hover:text-slate-950 truncate">
                          {brief.title || "Project Proposal"}
                        </h2>
                        <div className="flex items-center gap-1.5 text-xs text-slate-400 mt-1">
                          <span>Submitted {moment(proposal.createdAt).fromNow()}</span>
                          {proposal.status && (
                            <>
                              <span>•</span>
                              <span
                                className={`font-semibold capitalize ${proposal.status === "accepted"
                                  ? "text-emerald-600"
                                  : proposal.status === "rejected"
                                    ? "text-rose-600"
                                    : "text-amber-600"
                                  }`}
                              >
                                {proposal.status}
                              </span>
                            </>
                          )}
                        </div>
                      </div>

                      <div className="flex items-center gap-2 shrink-0">
                        {proposal.price && (
                          <span className="bg-[#F3E8FF] text-[#7E22CE] border border-[#E9D5FF] text-xs font-bold px-3 py-1 rounded-full whitespace-nowrap">
                            ${proposal.price}
                          </span>
                        )}
                        {proposal.deliveryTime && (
                          <span className="bg-slate-50 border border-slate-200 text-slate-800 text-xs font-semibold px-3 py-1 rounded-full whitespace-nowrap">
                            {proposal.deliveryTime} Days
                          </span>
                        )}
                      </div>
                    </div>

                    {proposal.coverLetter && (
                      <p className="text-sm text-slate-600 line-clamp-3 my-4 leading-relaxed font-normal">
                        {proposal.coverLetter}
                      </p>
                    )}
                  </div>

                  <div className="relative z-10 border-t border-slate-100 pt-4 flex items-center justify-between mt-auto">
                    <span className="text-xs text-slate-400 font-medium">
                      Status:{" "}
                      <strong className="text-slate-700 capitalize">
                        {proposal.status || "Pending"}
                      </strong>
                    </span>
                    <div className="flex items-center gap-1 text-xs sm:text-sm font-bold text-[#0D9488] group-hover:underline">
                      <span>View Project</span>
                      <FiArrowRight className="text-sm group-hover:translate-x-0.5 transition-transform" />
                    </div>
                  </div>
                </div>
              );
            })}
          </div>
        )}
      </div>
    </div>
  );
};

export default function MyBriefsPage() {
  const user = useUserStore((state) => state.user);
  const router = useRouter();

  useEffect(() => {
    if (user?.isSeller) {
      router.replace("/briefs/my-proposals");
    }
  }, [user?.isSeller, router]);

  return user?.isSeller ? <MyProposals /> : <MyBriefs />;
}

"use client";

import { useState, useMemo, useEffect } from "react";
import { useQuery } from "@tanstack/react-query";
import { useRouter } from "next/navigation";
import Link from "next/link";
import moment from "moment";
import {
  FiArrowRight,
  FiSearch,
  FiX,
  FiClock,
  FiCheckCircle,
  FiXCircle,
  FiAlertCircle,
  FiPaperclip,
  FiExternalLink,
  FiFileText,
  FiDollarSign,
  FiCalendar,
} from "react-icons/fi";

import { axiosFetch } from "@/utils";
import { useUserStore } from "@/store/userStore";
import { Button } from "@/components";
import { Breadcrumb, BriefsListSkeleton } from "@/components/ui";
import { Home } from "lucide-react";

type StatusFilter = "all" | "open" | "closed";

export default function MyProposalsPage() {
  const router = useRouter();
  const user = useUserStore((state) => state.user);

  const [statusFilter, setStatusFilter] = useState<StatusFilter>("all");
  const [searchQuery, setSearchQuery] = useState("");
  const [selectedProposal, setSelectedProposal] = useState<any | null>(null);

  useEffect(() => {
    window.scrollTo(0, 0);
  }, []);

  // Helper to determine if proposal is active/open (pending review, project not closed)
  const isProposalOpen = (p: any) => {
    const s = (p.status || "pending").toLowerCase();
    const brief = typeof p.briefID === "object" && p.briefID !== null ? p.briefID : {};
    const isBriefClosed = brief.isClosed || brief.status === "closed";
    if (isBriefClosed || s === "closed" || s === "rejected" || s === "accepted") {
      return false;
    }
    return s === "pending" || s === "open";
  };

  const isProposalClosed = (p: any) => {
    return !isProposalOpen(p);
  };

  // Fetch submitted proposals from backend endpoint
  const { isLoading, data: rawData = [] } = useQuery({
    queryKey: ["my-proposals"],
    queryFn: () =>
      axiosFetch
        .get("/briefs/my-proposals")
        .then(({ data }) => {
          if (Array.isArray(data)) return data;
          if (Array.isArray(data?.proposals)) return data.proposals;
          if (Array.isArray(data?.data)) return data.data;
          return [];
        })
        .catch(() => []),
  });

  const proposals: any[] = useMemo(() => {
    return Array.isArray(rawData) ? rawData : [];
  }, [rawData]);

  // Dynamic counts for 3 status filters: All, Open (pending), Closed
  const counts = useMemo(() => {
    let open = 0;
    let closed = 0;
    proposals.forEach((p) => {
      if (isProposalOpen(p)) open += 1;
      else closed += 1;
    });
    return { all: proposals.length, open, closed };
  }, [proposals]);

  // Filtered & searched proposals list
  const filteredProposals = useMemo(() => {
    return proposals.filter((p) => {
      if (statusFilter === "open" && !isProposalOpen(p)) return false;
      if (statusFilter === "closed" && !isProposalClosed(p)) return false;

      if (searchQuery.trim()) {
        const query = searchQuery.toLowerCase().trim();
        const brief = typeof p.briefID === "object" && p.briefID !== null ? p.briefID : {};
        const title = (brief.title || p.title || "").toLowerCase();
        const letter = (p.coverLetter || "").toLowerCase();
        const category = (brief.category || "").toLowerCase();
        if (!title.includes(query) && !letter.includes(query) && !category.includes(query)) {
          return false;
        }
      }

      return true;
    });
  }, [proposals, statusFilter, searchQuery]);

  const getStatusBadge = (status: string, brief?: any) => {
    const s = (status || "pending").toLowerCase();
    const isBriefClosed = brief?.isClosed || brief?.status === "closed";

    if (s === "accepted") {
      return (
        <span className="inline-flex items-center gap-1.5 px-2.5 py-1 rounded-full text-xs font-semibold bg-emerald-50 text-emerald-700 border border-emerald-200">
          <FiCheckCircle className="w-3.5 h-3.5" />
          <span>Accepted</span>
        </span>
      );
    }
    if (s === "rejected") {
      return (
        <span className="inline-flex items-center gap-1.5 px-2.5 py-1 rounded-full text-xs font-semibold bg-rose-50 text-rose-700 border border-rose-200">
          <FiXCircle className="w-3.5 h-3.5" />
          <span>Rejected</span>
        </span>
      );
    }
    if (isBriefClosed || s === "closed") {
      return (
        <span className="inline-flex items-center gap-1.5 px-2.5 py-1 rounded-full text-xs font-semibold bg-slate-100 text-slate-700 border border-slate-200">
          <FiXCircle className="w-3.5 h-3.5" />
          <span>Closed</span>
        </span>
      );
    }
    return (
      <span className="inline-flex items-center gap-1.5 px-2.5 py-1 rounded-full text-xs font-semibold bg-amber-50 text-amber-700 border border-amber-200">
        <FiClock className="w-3.5 h-3.5" />
        <span>Open</span>
      </span>
    );
  };

  return (
    <div className="min-h-screen bg-[#f5f5f5] pt-6 sm:pt-10 pb-20 font-sans">
      <div className="container mx-auto px-4 md:px-6 space-y-7">

        {/* 1. Breadcrumb */}
        <Breadcrumb
          homeHref="/dashboard/seller"
          homeTitle="Home"
          items={[
            {
              name: "My Proposals",
              isLast: true,
            },
          ]}
        />
        {/* Header section */}
        <div className="flex flex-col sm:flex-row sm:items-center justify-between gap-4 mb-8">
          <div>
            <h1 className="text-2xl sm:text-[28px] font-medium text-gray-950 tracking-tight font-sf-pro">
              My Submitted Proposals
            </h1>
            <p className="text-xs sm:text-[13px] text-gray-500 mt-1 max-w-2xl leading-relaxed">
              Keep track of your bids, client responses, and proposal status for open client projects.
            </p>
          </div>

          <div className="flex items-center gap-3 shrink-0 self-start sm:self-center">
            <Button
              href="/briefs?view=feed"
              variant="brand"
              size="sm"
              radius="fiverr"
              rightIcon={<FiArrowRight className="w-4 h-4" />}
            >
              Explore Projects
            </Button>
          </div>
        </div>

        {/* Controls: Status Filters & Search Bar */}
        <div className="bg-white rounded-[6px] border border-gray-200/80 shadow-[0_1px_6px_rgba(0,0,0,0.02)] p-4 sm:p-5 mb-6 flex flex-col md:flex-row md:items-center justify-between gap-4">
          {/* Status Tabs: 3 tabs (All Proposals, Open, Closed) */}
          <div className="flex items-center gap-1.5 overflow-x-auto pb-2 md:pb-0 scrollbar-none">
            {(
              [
                { id: "all", label: "All Proposals", count: counts.all },
                { id: "open", label: "Open", count: counts.open },
                { id: "closed", label: "Closed", count: counts.closed },
              ] as const
            ).map((tab) => {
              const active = statusFilter === tab.id;
              return (
                <Button
                  key={tab.id}
                  onClick={() => setStatusFilter(tab.id)}
                  type="button"
                  variant={active ? "brand" : "ghost"}
                  size="sm"
                  radius="fiverr"
                  className={`px-3.5 py-2 font-semibold text-xs sm:text-[13px] whitespace-nowrap shrink-0 ${active
                    ? "!bg-[#0D6D5F] text-white shadow-2xs"
                    : "!bg-gray-50 !text-gray-600 hover:!bg-gray-100 hover:!text-gray-900 border border-transparent"
                    }`}
                >
                  <span className="whitespace-nowrap shrink-0">{tab.label}</span>
                  <span
                    className={`inline-flex items-center justify-center min-w-[20px] h-5 px-1.5 rounded-full text-[11px] font-bold leading-none shrink-0 ${active
                      ? "bg-white/20 text-white"
                      : "bg-gray-200/80 text-gray-700"
                      }`}
                  >
                    {tab.count}
                  </span>
                </Button>
              );
            })}
          </div>

          {/* Search Box */}
          <div className="relative w-full md:w-72 shrink-0">
            <FiSearch className="absolute left-3.5 top-1/2 -translate-y-1/2 text-gray-400 w-4 h-4 pointer-events-none" />
            <input
              type="text"
              placeholder="Search by project or keywords..."
              value={searchQuery}
              onChange={(e) => setSearchQuery(e.target.value)}
              className="w-full h-10 pl-10 pr-8 bg-[#F0F0F0] border border-[rgba(0,0,0,0.10)] focus:border-gray-300 focus:bg-white rounded-[6px] transition-colors outline-none text-sm text-gray-900 placeholder:text-[#868686] placeholder:font-normal"
            />
            {searchQuery && (
              <button
                type="button"
                onClick={() => setSearchQuery("")}
                className="absolute right-2.5 top-1/2 -translate-y-1/2 text-gray-400 hover:text-gray-600"
              >
                <FiX className="w-3.5 h-3.5" />
              </button>
            )}
          </div>
        </div>

        {/* Content Section */}
        {isLoading ? (
          <BriefsListSkeleton />
        ) : filteredProposals.length === 0 ? (
          <div className="text-center py-16 px-6 bg-white rounded-[6px] border border-gray-200/80 shadow-[0_1px_6px_rgba(0,0,0,0.02)] flex flex-col items-center">
            <div className="w-14 h-14 rounded-full bg-teal-50 border border-teal-100 flex items-center justify-center text-teal-700 mb-4">
              <FiFileText className="w-6 h-6" />
            </div>
            <h3 className="text-lg font-bold text-gray-950 mb-1.5 font-sf-pro">
              {searchQuery || statusFilter !== "all"
                ? "No matching proposals found"
                : "No proposals submitted yet"}
            </h3>
            <p className="text-gray-500 text-xs sm:text-[13px] max-w-md mb-6 leading-relaxed">
              {searchQuery || statusFilter !== "all"
                ? "Try clearing your search query or selecting a different status filter."
                : "You haven't submitted any proposals yet. Browse open client projects to find work that matches your skills and pitch to clients!"}
            </p>
            {searchQuery || statusFilter !== "all" ? (
              <Button
                type="button"
                variant="outline"
                size="sm"
                radius="fiverr"
                onClick={() => {
                  setStatusFilter("all");
                  setSearchQuery("");
                }}
              >
                Reset Filters
              </Button>
            ) : (
              <Link
                href="/briefs?view=feed"
                className="px-5 py-2.5 rounded-[6px] font-semibold text-xs sm:text-[13px] bg-[#0D6D5F] hover:bg-[#0B5C50] text-white transition-colors cursor-pointer shadow-2xs"
              >
                Browse Open Projects
              </Link>
            )}
          </div>
        ) : (
          <div className="grid grid-cols-1 lg:grid-cols-2 gap-5">
            {filteredProposals.map((proposal) => {
              const brief =
                typeof proposal.briefID === "object" && proposal.briefID !== null
                  ? proposal.briefID
                  : typeof proposal.brief === "object" && proposal.brief !== null
                    ? proposal.brief
                    : {};
              const briefId =
                brief._id ||
                brief.id ||
                (typeof proposal.briefID === "string" ? proposal.briefID : proposal.briefId);

              const projectTitle = brief.title || proposal.title || "Project Proposal";
              const briefBudget = brief.budget;
              const hasAttachments =
                Array.isArray(proposal.attachments) && proposal.attachments.length > 0;

              return (
                <div
                  key={proposal._id || proposal.id}
                  onClick={() => setSelectedProposal(proposal)}
                  className="relative overflow-hidden bg-white rounded-[6px] border border-slate-200/90 hover:border-[var(--purple-200,#B78AF7)] hover:rounded-[6px] shadow-[0_1px_3px_rgba(0,0,0,0.02)] hover:shadow-md p-5 sm:p-6 sm:p-7 flex flex-col justify-between transition-all duration-300 group cursor-pointer"
                >
                  {/* Ambient Purple Glow (appears on card hover) */}
                  <div
                    className="absolute pointer-events-none opacity-0 group-hover:opacity-100 transition-opacity duration-500 ease-out z-0"
                    style={{
                      position: "absolute",
                      right: "-210px",
                      top: "-407px",
                      width: "555px",
                      height: "513px",
                      borderRadius: "555px",
                      transform: "rotate(-180deg)",
                      background: "var(--purple-100, #CEB0FA)",
                      filter: "blur(150px)",
                    }}
                    aria-hidden="true"
                  />

                  <div className="relative z-10 flex flex-col justify-between h-full">
                    <div>
                      {/* Top Row: Title, Date, and Status Badge */}
                      <div className="flex items-start justify-between gap-3 mb-3">
                        <div className="min-w-0 flex-1">
                          <div className="flex items-center gap-2 mb-1">
                            {brief.category && (
                              <span className="text-[11px] font-semibold text-gray-500 bg-gray-100 px-2 py-0.5 rounded">
                                {brief.category}
                              </span>
                            )}
                            <span className="text-[11px] text-gray-400 flex items-center gap-1">
                              <FiCalendar className="w-3 h-3" />
                              <span>Submitted {moment(proposal.createdAt).fromNow()}</span>
                            </span>
                          </div>
                          <h2 className="text-base sm:text-[19px] font-bold text-slate-900 tracking-tight line-clamp-2 group-hover:text-slate-950 transition-colors font-sf-pro">
                            {projectTitle}
                          </h2>
                        </div>
                        <div className="shrink-0">{getStatusBadge(proposal.status, brief)}</div>
                      </div>

                      {/* Price & Delivery duration tags */}
                      <div className="flex flex-wrap items-center gap-2.5 mb-3.5 pt-1">
                        <div className="inline-flex items-center gap-1.5 px-3 py-1 rounded-[6px] bg-white text-black border border-gray-200/60 text-xs font-bold">
                          <FiDollarSign className="w-3.5 h-3.5 text-black" />
                          <span>Your Bid: ${proposal.price}</span>
                        </div>
                        {proposal.deliveryTime && (
                          <div className="inline-flex items-center gap-1.5 px-3 py-1 rounded-[6px] bg-gray-100 text-gray-700 border border-gray-200/60 text-xs font-semibold">
                            <FiClock className="w-3.5 h-3.5 text-gray-500" />
                            <span>{proposal.deliveryTime} Days Delivery</span>
                          </div>
                        )}
                        {briefBudget && (
                          <div className="text-[11px] text-gray-400 font-medium ml-auto">
                            Client Budget:{" "}
                            <strong className="text-gray-600">
                              {typeof briefBudget === "number" ? `$${briefBudget}` : briefBudget}
                            </strong>
                          </div>
                        )}
                      </div>

                      {/* Cover Letter Excerpt */}
                      {proposal.coverLetter && (
                        <p className="text-xs sm:text-[13px] text-[#4A4A4A] my-6 line-clamp-3 leading-relaxed mb-4 font-normal">
                          {proposal.coverLetter.slice(0, 100) + "..."}
                        </p>
                      )}

                      {/* Attachment preview indicator */}
                      {hasAttachments && (
                        <div className="flex items-center gap-1 text-[11px] text-gray-500 mb-3 font-medium">
                          <FiPaperclip className="w-3.5 h-3.5 text-gray-400" />
                          <span>{proposal.attachments.length} attachment(s) included</span>
                        </div>
                      )}
                    </div>

                    {/* Card Footer Actions */}
                    <div className="pt-3.5 border-t border-gray-100 flex items-center justify-between gap-3 mt-auto">
                      <Button
                        type="button"
                        variant="ghost"
                        size="sm"
                        radius="fiverr"
                        onClick={(e) => {
                          e.stopPropagation();
                          setSelectedProposal(proposal);
                        }}
                        className="text-xs sm:text-[13px] font-semibold text-gray-700 hover:text-gray-900 hover:bg-gray-100 p-0 h-auto"
                      >
                        View Full Proposal
                      </Button>

                      {briefId && (
                        <Link
                          href={`/briefs/${briefId}`}
                          onClick={(e) => e.stopPropagation()}
                          className="inline-flex items-center gap-1.5 text-xs sm:text-[13px] font-bold text-[#0D6D5F] hover:text-[#0B5C50] group-hover:underline transition-colors"
                        >
                          <span>View Project</span>
                          <FiExternalLink className="w-3.5 h-3.5" />
                        </Link>
                      )}
                    </div>
                  </div>
                </div>
              );
            })}
          </div>
        )}
      </div>

      {/* Slide-out Drawer for Full Proposal Details */}
      <div
        className={`fixed inset-0 z-[1000] transition-all duration-300 ${selectedProposal ? "visible pointer-events-auto" : "invisible pointer-events-none delay-300"
          }`}
      >
        {/* Backdrop Overlay */}
        <div
          className={`fixed inset-0 bg-black/50 backdrop-blur-xs transition-opacity duration-300 ease-out ${selectedProposal ? "opacity-100" : "opacity-0"
            }`}
          onClick={() => setSelectedProposal(null)}
          aria-hidden="true"
        />

        {/* Drawer Panel from Right */}
        <aside
          className={`fixed inset-y-0 right-0 z-[1001] w-full max-w-xl bg-white shadow-2xl flex flex-col h-full overflow-hidden transform transition-transform duration-300 ease-out ${selectedProposal ? "translate-x-0" : "translate-x-full"
            }`}
          role="dialog"
          aria-modal="true"
          aria-label="Proposal Details"
          onClick={(e) => e.stopPropagation()}
        >
          {/* Drawer Header */}
          <div className="flex justify-between pt-2 items-center px-6 py-4.5 border-b border-gray-100 bg-white shrink-0">
            <div>
              <div className="flex items-center gap-2 mb-0.5">
                <span className="text-[11px] font-semibold uppercase tracking-wider text-gray-500">
                  Proposal Details
                </span>
                {selectedProposal && getStatusBadge(selectedProposal.status, selectedProposal.briefID)}
              </div>
              <h2 className="text-lg font-bold text-gray-950 font-sf-pro truncate max-w-md">
                {(() => {
                  const brief =
                    typeof selectedProposal?.briefID === "object" && selectedProposal?.briefID !== null
                      ? selectedProposal.briefID
                      : {};
                  return brief.title || selectedProposal?.title || "Submitted Proposal";
                })()}
              </h2>
            </div>
            <Button
              type="button"
              variant="ghost"
              size="icon"
              radius="full"
              onClick={() => setSelectedProposal(null)}
              className="w-8 h-8 text-gray-400 hover:text-gray-700 hover:bg-gray-100 border-none shadow-none"
              title="Close"
            >
              <FiX className="w-4 h-4" />
            </Button>
          </div>

          {/* Drawer Body Content */}
          <div className="p-6 flex flex-col gap-5 overflow-y-auto scrollbar-hide flex-1 text-xs sm:text-[13px]">
            {/* Price & Delivery Highlights */}
            <div className="grid grid-cols-2 gap-4 bg-gray-50 p-4 rounded-[6px] border border-gray-100">
              <div>
                <span className="text-[11px] font-bold text-gray-400 uppercase tracking-wider block mb-1">
                  Offered Price
                </span>
                <span className="text-xl sm:text-2xl font-black text-emerald-600 font-sf-pro">
                  ${selectedProposal?.price}
                </span>
              </div>
              <div>
                <span className="text-[11px] font-bold text-gray-400 uppercase tracking-wider block mb-1">
                  Delivery Time
                </span>
                <span className="text-xl sm:text-2xl font-bold text-gray-900 font-sf-pro">
                  {selectedProposal?.deliveryTime} Days
                </span>
              </div>
            </div>

            {/* Submission Timing */}
            <div className="text-xs text-gray-500 flex items-center gap-1.5">
              <FiCalendar className="w-3.5 h-3.5 text-gray-400" />
              <span>
                Submitted on{" "}
                <strong className="text-gray-700">
                  {moment(selectedProposal?.createdAt).format("MMMM D, YYYY [at] h:mm A")}
                </strong>{" "}
                ({moment(selectedProposal?.createdAt).fromNow()})
              </span>
            </div>

            {/* Full Cover Letter */}
            <div>
              <h3 className="text-xs font-bold text-gray-900 uppercase tracking-wider mb-2">
                Cover Letter
              </h3>
              <div className="text-xs sm:text-[13px] text-gray-700 whitespace-pre-wrap leading-relaxed bg-white p-4 rounded-[6px] border border-gray-200">
                {selectedProposal?.coverLetter || "No cover letter provided."}
              </div>
            </div>

            {/* Attachments if available */}
            {Array.isArray(selectedProposal?.attachments) &&
              selectedProposal.attachments.length > 0 && (
                <div>
                  <h3 className="text-xs font-bold text-gray-900 uppercase tracking-wider mb-2">
                    Attachments ({selectedProposal.attachments.length})
                  </h3>
                  <div className="space-y-2">
                    {selectedProposal.attachments.map((fileUrl: string, idx: number) => (
                      <a
                        key={idx}
                        href={fileUrl}
                        target="_blank"
                        rel="noreferrer"
                        className="flex items-center justify-between p-3 rounded-[6px] border border-gray-200 bg-gray-50 hover:bg-gray-100 text-gray-700 transition-colors"
                      >
                        <div className="flex items-center gap-2 truncate pr-2">
                          <FiPaperclip className="w-4 h-4 text-gray-500 shrink-0" />
                          <span className="truncate text-xs font-medium">
                            Attachment {idx + 1}
                          </span>
                        </div>
                        <FiExternalLink className="w-3.5 h-3.5 text-gray-400 shrink-0" />
                      </a>
                    ))}
                  </div>
                </div>
              )}

            {/* Brief/Project Details Overview */}
            {(() => {
              const brief =
                typeof selectedProposal?.briefID === "object" && selectedProposal?.briefID !== null
                  ? selectedProposal.briefID
                  : {};
              const briefId =
                brief._id ||
                brief.id ||
                (typeof selectedProposal?.briefID === "string" ? selectedProposal.briefID : null);

              if (!brief.title && !brief.description) return null;

              return (
                <div className="mt-2 pt-4 border-t border-gray-100">
                  <h3 className="text-xs font-bold text-gray-900 uppercase tracking-wider mb-2">
                    Associated Project Brief
                  </h3>
                  <div className="p-4 bg-gray-50 rounded-[6px] border border-gray-200/80 space-y-2">
                    <div className="font-bold text-gray-900 text-sm">{brief.title}</div>
                    {brief.budget && (
                      <div className="text-xs text-gray-500">
                        Client Budget:{" "}
                        <span className="font-semibold text-gray-800">
                          {typeof brief.budget === "number" ? `$${brief.budget}` : brief.budget}
                        </span>
                      </div>
                    )}
                    {brief.description && (
                      <p className="text-xs text-gray-600 line-clamp-4 leading-relaxed">
                        {brief.description}
                      </p>
                    )}
                    {briefId && (
                      <div className="pt-2">
                        <Link
                          href={`/briefs/${briefId}`}
                          className="inline-flex items-center gap-1.5 text-xs font-bold text-[#0D6D5F] hover:underline"
                        >
                          <span>Open Full Project Page</span>
                          <FiArrowRight className="w-3.5 h-3.5" />
                        </Link>
                      </div>
                    )}
                  </div>
                </div>
              );
            })()}
          </div>

          {/* Drawer Footer */}
          <div className="p-4 border-t border-gray-100 bg-white flex items-center justify-end gap-3 shrink-0">
            <Button
              type="button"
              variant="outline"
              size="sm"
              radius="fiverr"
              onClick={() => setSelectedProposal(null)}
            >
              Close
            </Button>
            {(() => {
              const brief =
                typeof selectedProposal?.briefID === "object" && selectedProposal?.briefID !== null
                  ? selectedProposal.briefID
                  : {};
              const briefId =
                brief._id ||
                brief.id ||
                (typeof selectedProposal?.briefID === "string" ? selectedProposal.briefID : null);
              if (!briefId) return null;
              return (
                <Link
                  href={`/briefs/${briefId}`}
                  className="px-4 h-10 inline-flex items-center justify-center rounded-[6px] bg-[#0D6D5F] hover:bg-[#0B5C50] text-white text-xs font-semibold transition-colors"
                >
                  View Project
                </Link>
              );
            })()}
          </div>
        </aside>
      </div>
    </div>
  );
}

