"use client";

import React, { useEffect, useMemo, useRef } from "react";
import Link from "next/link";
import { useParams } from "next/navigation";
import { useQuery, useQueryClient } from "@tanstack/react-query";
import { toast } from "@/utils/toast";
import moment from "moment";
import { axiosFetch } from "@/utils";
import { socket } from "@/utils/socket";
import { useUserStore } from "@/store/userStore";
import { OrderSkeleton } from "@/components/ui";
import { BuyerOrderView, SellerOrderView, NormalizedOrder, ExtensionRequestData } from "@/features/orders";

export default function OrderDetailPage() {
  const { id } = useParams();
  const queryClient = useQueryClient();
  const user = useUserStore((state: any) => state.user);

  // Persistent reference to preserve order data during background refetches or transient errors
  const lastValidOrderRef = useRef<any>(null);

  useEffect(() => {
    window.scrollTo(0, 0);
  }, []);

  // Fetch real order from backend API
  const { data: rawOrder, isLoading, error, refetch } = useQuery({
    queryKey: ["order", id],
    queryFn: async () => {
      try {
        const { data } = await axiosFetch.get(`/orders/${id}`);
        const orderData = data?.order || data?.data || data;
        if (orderData) {
          lastValidOrderRef.current = orderData;
        }
        return orderData;
      } catch (err: any) {
        if (err?.response?.status === 429) {
          toast.error("Too many requests. Please wait a moment and try again.", {
            id: "order-429-toast",
          });
          // If we already have previous valid data, keep it intact
          if (lastValidOrderRef.current) {
            return lastValidOrderRef.current;
          }
        }
        throw err;
      }
    },
    staleTime: 30000,
    retry: (failureCount, err: any) => {
      // Do not auto-retry on 429, 404, or 403
      if (err?.response?.status === 429 || err?.response?.status === 404 || err?.response?.status === 403) {
        return false;
      }
      return failureCount < 1;
    },
  });

  // Query for linked dispute or escalated support ticket
  const { data: linkedTicket } = useQuery({
    queryKey: ["order-dispute-ticket", id],
    queryFn: async () => {
      try {
        const res = await axiosFetch.get(`/support/tickets?orderID=${id}`).catch(() => null) ||
                    await axiosFetch.get(`/admin/support/tickets?orderID=${id}`).catch(() => null);
        const data = res?.data;
        const list = Array.isArray(data) ? data : data?.tickets || data?.data || [];
        const found = list.find((t: any) =>
          (String(t.orderID || t.orderId || t.order?._id || t.order?.id) === String(id)) &&
          (t.status === 'escalated_to_dispute' || t.disputeID || t.disputeId)
        );
        return found || null;
      } catch {
        return null;
      }
    },
    staleTime: 10000,
  });

  const activeRawOrder = rawOrder || lastValidOrderRef.current;

  // Real-time socket sync
  useEffect(() => {
    if (!id) return;

    if (!socket.connected) {
      socket.connect();
    }

    const joinRoom = () => {
      socket.emit("join_order", id);
      socket.emit("join_room", `order_${id}`);
    };

    joinRoom();
    socket.on("connect", joinRoom);

    let debounceTimer: NodeJS.Timeout | null = null;

    const handleOrderUpdate = (data: any) => {
      const incomingId = String(
        data?.orderID ||
        data?.orderId ||
        data?.order?._id ||
        data?.order?.id ||
        data?.metadata?.orderID ||
        data?.metadata?.orderId ||
        data?._id ||
        ""
      ).trim();

      const isLinkMatch =
        typeof data?.link === "string" && data.link.includes(String(id));

      const hasOrderKeywords =
        Boolean(
          data?.title &&
          /order|delivery|extension|revision/i.test(String(data.title))
        ) ||
        Boolean(
          data?.message &&
          /order|delivery extension|revision/i.test(String(data.message))
        );

      const isReviewReplied =
        data?.event === "review_replied" ||
        /review|reply/i.test(String(data?.title || data?.message || ""));

      if (
        (incomingId && incomingId === String(id)) ||
        isLinkMatch ||
        isReviewReplied ||
        (!incomingId && hasOrderKeywords)
      ) {
        if (debounceTimer) clearTimeout(debounceTimer);
        debounceTimer = setTimeout(() => {
          queryClient.invalidateQueries({ queryKey: ["order", id] });
          queryClient.invalidateQueries({ queryKey: ["reviews"] });
        }, 600);
      }
    };

    socket.on("order_updated", handleOrderUpdate);
    socket.on("order_status_changed", handleOrderUpdate);
    socket.on("new_notification", handleOrderUpdate);
    socket.on("notification", handleOrderUpdate);

    return () => {
      if (debounceTimer) clearTimeout(debounceTimer);
      socket.emit("leave_order", id);
      socket.emit("leave_room", `order_${id}`);
      socket.off("connect", joinRoom);
      socket.off("order_updated", handleOrderUpdate);
      socket.off("order_status_changed", handleOrderUpdate);
      socket.off("new_notification", handleOrderUpdate);
      socket.off("notification", handleOrderUpdate);
    };
  }, [id, queryClient]);

  // Normalized order data
  const normalizedOrder: NormalizedOrder | null = useMemo(() => {
    if (!activeRawOrder) return null;
    const o = activeRawOrder;

    const orderId = String(o._id || id || "");
    const orderCode = o.orderCode || (orderId ? `FO_${orderId.slice(-8).toUpperCase()}` : "-");
    const orderNumber = typeof o.orderNumber === "number" ? o.orderNumber : Number(orderId.slice(-4)) || 1001;
    const title = o.title || o.gigID?.title || o.packageID?.title || "Deliverable Project";
    const packageTitle = o.packageTitle || o.title || o.gigID?.title || o.packageID?.title || "Standard Package";
    const coverImage = o.image || o.cover || o.packageID?.cover || o.packageID?.image || o.gigID?.cover || "/images/dashboard/orders/order_1.jpg";
    const price = typeof o.price === "number" ? o.price : 0;
    const rawStatus = (o.status || "inprogress").toLowerCase();
    const isCompleted = rawStatus === "completed" || rawStatus === "complete" || Boolean(o.isCompleted);
    const isCancelled = rawStatus === "cancelled" || rawStatus === "canceled" || rawStatus === "failed";
    const isDisputed = !isCompleted && !isCancelled && Boolean(
      (rawStatus === "disputed" || rawStatus === "escalated_to_dispute") ||
      (o.escrowStatus && String(o.escrowStatus).toLowerCase() === "disputed") ||
      (linkedTicket && (linkedTicket.status === 'escalated_to_dispute' || linkedTicket.disputeID))
    );

    const status = isDisputed ? "disputed" : rawStatus;
    const paymentStatus = o.isPaid || o.status === "paid" || o.status === "delivered" || o.status === "completed"
      ? "Paid"
      : (o.paymentStatus || "Unpaid");

    // Started date
    let startedOn = "-";
    if (o.createdAt) {
      const d = new Date(o.createdAt);
      if (!isNaN(d.getTime())) startedOn = moment(d).format("MMM D, YYYY");
    }

    // Delivery date & late days calculation
    let deliveryTime = "-";
    let lateDays = 0;
    let isLate = false;
    let deadline = o.deadline;

    if (!deadline && o.createdAt && o.deliveryTime) {
      const days = Number(o.deliveryTime);
      if (!isNaN(days)) {
        const est = new Date(o.createdAt).getTime() + days * 86400000;
        deadline = new Date(est).toISOString();
      }
    }

    let overdueMs = 0;
    if (deadline) {
      const targetTime = new Date(deadline).getTime();
      if (!isNaN(targetTime)) {
        deliveryTime = moment(targetTime).format("MMM D, YYYY");
        const diff = targetTime - Date.now();
        if (diff < 0) {
          overdueMs = Math.abs(diff);
          lateDays = Math.max(1, Math.abs(Math.floor(diff / (1000 * 60 * 60 * 24))));
        }
      }
    }

    const isTerminal = ["completed", "complete", "cancelled", "canceled", "failed"].includes(status);
    const isDelivered = status === "delivered";
    const isRevision = status === "revision" || status === "in_revision";

    // Active order after deadline provided it's not completed, delivered, cancelled, or in revision
    if (!isTerminal && !isDelivered && !isRevision && overdueMs > 0) {
      isLate = true;
    }

    // Delivered late detection
    const deliveredAt = o.deliveredAt || o.deliveredOn;
    const deadlineTime = deadline ? new Date(deadline).getTime() : 0;
    const deliveredTime = deliveredAt ? new Date(deliveredAt).getTime() : 0;
    const wasLateDelivered = Boolean(
      isDelivered && (
        o.wasLateDelivered ||
        (deliveredTime && deadlineTime && deliveredTime > deadlineTime)
      )
    );

    let displayStatus = status;
    if (isRevision) {
      displayStatus = "in_revision";
    } else if (isLate) {
      displayStatus = "late";
    } else if (isDelivered && wasLateDelivered) {
      displayStatus = "delivered_late";
    }

    // Seller normalization
    const sObj = typeof o.sellerID === "object" && o.sellerID !== null ? o.sellerID : {};
    const sellerRating = Number(
      sObj.rating ??
      sObj.starRating ??
      (sObj.starNumber && sObj.totalStars ? sObj.totalStars / sObj.starNumber : undefined) ??
      0
    );
    const sellerReviewCount = Number(
      sObj.reviewCount ??
      sObj.starNumber ??
      sObj.totalReviews ??
      0
    );
    const seller = {
      id: String(sObj._id || sObj.id || (typeof o.sellerID === "string" ? o.sellerID : "")),
      name: sObj.username || sObj.name || "Seller",
      username: sObj.username || sObj.name,
      avatar: sObj.image || sObj.avatar || "/media/noavatar.png",
      role: sObj.title || sObj.shortTitle || sObj.role || "--",
      badge: sObj.badge,
      rating: sellerRating,
      reviewCount: sellerReviewCount,
      country: sObj.country || sObj.location
    };

    // Buyer normalization
    const bObj = typeof o.buyerID === "object" && o.buyerID !== null ? o.buyerID : {};
    const buyer = {
      id: String(bObj._id || bObj.id || (typeof o.buyerID === "string" ? o.buyerID : "")),
      name: bObj.username || bObj.name || "Client",
      avatar: bObj.image || bObj.avatar || "/media/noavatar.png",
      country: bObj.country || bObj.location,
      joinedDate: bObj.createdAt ? moment(bObj.createdAt).format("MMM YYYY") : undefined,
    };

    // User role check
    const isUserSeller = Boolean(
      user?._id && (
        String(sObj._id || o.sellerID) === String(user._id) ||
        (user.isSeller && String(bObj._id || o.buyerID) !== String(user._id))
      )
    );
    const isUserBuyer = !isUserSeller;

    // Delivery files
    const rawFiles = o.deliveryFiles || o.deliverables || [];
    const deliveryFiles = Array.isArray(rawFiles)
      ? rawFiles.map((f: any, idx: number) => ({
        name: typeof f === "string" ? f.split("/").pop() || `Deliverable_${idx + 1}` : f.name || `Deliverable_${idx + 1}`,
        size: typeof f === "object" && f.size ? f.size : "-",
        url: typeof f === "string" ? f : f.url || "#",
      }))
      : [];

    // Requirements
    const reqs = o.requirements || o.projectRequirements || {};
    const requirements = {
      q1: reqs.q1 || "",
      q2: reqs.q2 || "",
      q3: reqs.q3 || "",
      submitted: Boolean(reqs.submitted || o.requirementsSubmitted || reqs.q1),
      submittedAt: reqs.submittedAt,
    };

    // Extension request
    const extReq = o.extensionRequest || o.extension;
    const extStatus = String(extReq?.status || "").toLowerCase().trim();
    const extensionRequest: ExtensionRequestData | null = extReq
      ? {
        days: extReq.days || extReq.extraDays || 1,
        reason: extReq.reason || "Time extension requested.",
        status: extStatus || "pending",
        rejectionReason: extReq.rejectionReason || o.rejectionReason || "",
        rejectedAt: extReq.rejectedAt || o.rejectedAt || "",
        extraDays: extReq.extraDays || extReq.days,
        requestedBy: extReq.requestedBy,
        createdAt: extReq.createdAt,
      }
      : null;

    return {
      id: orderId,
      orderCode,
      orderNumber,
      title,
      packageTitle,
      coverImage,
      price,
      status,
      paymentStatus,
      startedOn,
      deliveryTime,
      deadline,
      lateDays,
      isLate,
      wasLateDelivered,
      deliveredAt,
      overdueMs,
      displayStatus,
      seller,
      buyer,
      requirements,
      deliveryFiles,
      deliveryMessage: o.deliveryMessage || o.deliveryText,
      deliveryText: o.deliveryText || o.deliveryMessage,
      extensionRequest,
      revisionReason: o.revisionReason || o.revision?.reason,
      disputeSummary: o.disputeSummary || o.raw?.disputeSummary || o.dispute?.summary,
      disputeDetails:
        o.disputeDetails ||
        o.raw?.disputeDetails ||
        o.dispute?.details ||
        o.dispute?.decisionReason ||
        o.raw?.dispute?.decisionReason,
      hasReviewed: Boolean(o.hasReviewed || o.isReviewed || o.review || o.reviewID),
      reviewDeadline: o.reviewDeadline || o.review_deadline || o.raw?.reviewDeadline,
      replyDeadline: o.replyDeadline || o.reply_deadline || o.raw?.replyDeadline,
      isUserSeller,
      isUserBuyer,
      raw: {
        ...o,
        supportTicketID: o.supportTicketID || o.supportTicketId || linkedTicket?.id || linkedTicket?._id,
      },
    };
  }, [activeRawOrder, id, user]);

  // 1. Initial loading state (only while first fetch is pending and no cached data exists)
  if (isLoading && !activeRawOrder) {
    return <OrderSkeleton />;
  }

  // 2. Scenario 2: First visit gets 429 (Rate Limit on initial load, no data yet)
  if (!activeRawOrder && (error as any)?.response?.status === 429) {
    return (
      <div className="min-h-screen bg-[#F8FAFC] py-24 flex flex-col items-center justify-center font-sans px-4">
        <h2 className="text-xl font-bold text-slate-800 mb-2">Too Many Requests</h2>
        <p className="text-sm text-slate-500 mb-6 text-center max-w-sm">
          You have made too many requests in a short period. Please wait a moment and try again.
        </p>
        <button
          onClick={() => refetch()}
          className="px-5 py-2.5 rounded-[6px] bg-[#0D6D5F] hover:bg-[#0b5c50] text-white text-xs sm:text-sm font-semibold transition-colors cursor-pointer"
        >
          Try Again
        </button>
      </div>
    );
  }

  // 3. Scenario 3: Genuine 404 or missing order
  if (!normalizedOrder) {
    return (
      <div className="min-h-screen bg-[#F8FAFC] py-24 flex flex-col items-center justify-center font-sans px-4">
        <h2 className="text-xl font-bold text-slate-800 mb-2">Order Not Found</h2>
        <p className="text-sm text-slate-500 mb-6 text-center max-w-sm">
          The order you are trying to view does not exist or you do not have permission to view it.
        </p>
        <Link
          href={user?.isSeller ? "/manage-orders" : "/orders"}
          className="px-5 py-2.5 rounded-[6px] bg-slate-900 text-white text-xs sm:text-sm font-semibold hover:bg-slate-800 transition-colors"
        >
          Back to Orders
        </Link>
      </div>
    );
  }

  // Render role-specific view (Fiverr style)
  if (normalizedOrder.isUserSeller) {
    return <SellerOrderView order={normalizedOrder} refetch={refetch} />;
  }

  return <BuyerOrderView order={normalizedOrder} refetch={refetch} />;
}

"use client";

import React, { useState, useMemo, useEffect } from "react";
import { useParams, useRouter } from "next/navigation";
import { FiArrowLeft, FiFileText } from "react-icons/fi";
import { RiSearchLine } from "react-icons/ri";
import { useQuery } from "@tanstack/react-query";
import { axiosFetch } from "@/utils";
import { useUserStore } from "@/store/userStore";
import { Loader, Button } from "@/components";
import { Breadcrumb, Tag, Modal } from "@/components/ui";

type FilterTab = "priority" | "active" | "late" | "delivered" | "completed" | "cancelled" | "starred";

export default function ContactOrdersPage() {
  const router = useRouter();
  const params = useParams();
  const contactId = params?.id ? String(params.id) : "";

  const user = useUserStore((state) => state.user);
  const isSeller = Boolean(user?.isSeller);

  // Filter and search state
  const [activeTab, setActiveTab] = useState<FilterTab>("priority");
  const [searchQuery, setSearchQuery] = useState("");

  // Notes Modal state (for viewing instructions/notes)
  const [activeNotesOrder, setActiveNotesOrder] = useState<any | null>(null);

  useEffect(() => {
    window.scrollTo(0, 0);
  }, []);

  // 1. Fetch Contact User Profile (username, avatar, title, etc.)
  const { data: contactUser, isLoading: isUserLoading } = useQuery({
    queryKey: ["user-profile", contactId],
    queryFn: async () => {
      try {
        const { data } = await axiosFetch.get(`/users/${contactId}`);
        return data?.user || data?.data || data;
      } catch {
        return null;
      }
    },
    enabled: Boolean(contactId),
    staleTime: 60000,
  });

  // 2. Fetch All User Orders
  const { data: apiOrders = [], isLoading: isOrdersLoading } = useQuery({
    queryKey: ["orders"],
    queryFn: async () => {
      try {
        const { data } = await axiosFetch.get("/orders");
        return Array.isArray(data) ? data : data?.orders || [];
      } catch {
        return [];
      }
    },
    staleTime: 60000,
  });

  // 3. Filter orders to strictly mutual orders between current user and target contact
  const mutualOrders = useMemo(() => {
    if (!Array.isArray(apiOrders) || !user?._id || !contactId) return [];
    const currentUid = String(user._id || user.id);
    const targetUid = String(contactId);

    return apiOrders.filter((order: any) => {
      const sId = String(order.sellerID?._id || order.sellerID || "");
      const bId = String(order.buyerID?._id || order.buyerID || "");

      // If current user is a seller, the contact is the buyer
      if (isSeller) {
        return (sId === currentUid || !order.sellerID) && (bId === targetUid || !order.buyerID);
      }
      // If current user is a buyer, the contact is the seller
      return (bId === currentUid || !order.buyerID) && (sId === targetUid || !order.sellerID);
    });
  }, [apiOrders, user, contactId, isSeller]);

  // Status badge helper for seller view
  const getSellerStatusBadge = (status?: string, isCompleted?: boolean) => {
    if (isCompleted || status === "completed") {
      return { label: "Completed", style: "bg-[#D1FAE5] text-[#059669]" };
    }
    const st = (status || "inprogress").toLowerCase();
    if (st === "delivered") return { label: "Delivered", style: "bg-[#D1FAE5] text-[#059669]" };
    if (st === "revision" || st === "in_revision") return { label: "Revision", style: "bg-[#F3E8FF] text-[#9333EA]" };
    if (st === "late") return { label: "Late", style: "bg-[#FEE2E2] text-[#DC2626]" };
    if (st === "failed" || st === "cancelled") return { label: "Failed", style: "bg-[#FEE2E2] text-[#EF4444]" };
    if (st === "pending") return { label: "Pending", style: "bg-[#FEF3C7] text-[#D97706]" };
    return { label: "Inprogress", style: "bg-[#E0F2FE] text-[#0284C7]" };
  };

  // Status pill helper for buyer view
  const renderBuyerStatusPill = (status?: string, isCompleted?: boolean) => {
    if (isCompleted || status === "completed") {
      return <span className="bg-[#ECFDF5] text-[#10B981] text-xs font-semibold px-4 py-1.5 rounded-full inline-block">Completed</span>;
    }
    const st = (status || "inprogress").toLowerCase();
    if (st === "delivered") {
      return <span className="bg-[#E6FFFA] text-[#0D9488] text-xs font-semibold px-4 py-1.5 rounded-full inline-block">Delivered</span>;
    }
    if (st === "revision" || st === "in_revision") {
      return <span className="bg-[#F5F0FF] text-[#8B5CF6] text-xs font-semibold px-4 py-1.5 rounded-full inline-block">Revision</span>;
    }
    if (st === "late") {
      return <span className="bg-[#FEE2E2] text-[#DC2626] text-xs font-semibold px-4 py-1.5 rounded-full inline-block">Late</span>;
    }
    if (st === "failed") {
      return <span className="bg-[#FEE2E2] text-[#EF4444] text-xs font-semibold px-4 py-1.5 rounded-full inline-block">Failed</span>;
    }
    if (st === "cancelled") {
      return <span className="bg-slate-100 text-slate-600 text-xs font-semibold px-4 py-1.5 rounded-full inline-block">Cancelled</span>;
    }
    if (st === "pending") {
      return <span className="bg-[#FEF9C3] text-[#CA8A04] text-xs font-semibold px-4 py-1.5 rounded-full inline-block">Pending</span>;
    }
    return <span className="bg-[#EEF2FF] text-[#6366F1] text-xs font-semibold px-4 py-1.5 rounded-full inline-block">Inprogress</span>;
  };

  const renderBadge = (badge?: "Expert" | "Pro" | "Legend") => {
    if (!badge) return null;
    if (badge === "Expert") {
      return (
        <span className="bg-[#5c4928] text-[#FDE68A] text-[10px] font-bold px-2 py-0.5 rounded-[6px] tracking-wider">
          Expert
        </span>
      );
    }
    if (badge === "Pro") {
      return (
        <span className="bg-[#4C1D95] text-white text-[10px] font-bold px-2 py-0.5 rounded-[6px] tracking-wider">
          Pro
        </span>
      );
    }
    if (badge === "Legend") {
      return (
        <span className="bg-[#EA580C] text-white text-[10px] font-bold px-2 py-0.5 rounded-[6px] tracking-wider">
          Legend
        </span>
      );
    }
    return null;
  };

  // Filter orders by active tab and search query
  const filteredOrders = useMemo(() => {
    return mutualOrders.filter((order: any) => {
      const isCompleted = order.status === "completed" || order.isCompleted === true;
      const st = (order.status || "inprogress").toLowerCase();

      // Search matching
      if (searchQuery.trim()) {
        const q = searchQuery.toLowerCase().trim();
        const title = (order.title || order.projectTitle || order.gigID?.title || "").toLowerCase();
        const desc = (order.description || order.projectDescription || "").toLowerCase();
        const code = String(order._id || order.id || "").toLowerCase();
        if (!title.includes(q) && !desc.includes(q) && !code.includes(q)) {
          return false;
        }
      }

      // Tab filtering
      if (activeTab === "priority") return true;
      if (activeTab === "active") {
        if (isCompleted) return false;
        if (st === "cancelled" || st === "failed") return false;
        return (
          order.isCompleted === false ||
          st === "paid" ||
          st === "in_progress" ||
          st === "inprogress" ||
          st === "delivered" ||
          st === "in_revision" ||
          st === "revision" ||
          st === "pending" ||
          st === "late" ||
          !order.status
        );
      }
      if (activeTab === "late") return st === "late";
      if (activeTab === "delivered") return st === "delivered";
      if (activeTab === "completed") return isCompleted;
      if (activeTab === "cancelled") return st === "cancelled" || st === "failed";
      if (activeTab === "starred") return Boolean(order.starred);
      return true;
    });
  }, [mutualOrders, activeTab, searchQuery]);

  const tabs: { id: FilterTab; label: string }[] = [
    { id: "priority", label: "Priority" },
    { id: "active", label: "Active" },
    { id: "late", label: "Late" },
    { id: "delivered", label: "Delivered" },
    { id: "completed", label: "Completed" },
    { id: "cancelled", label: "Cancelled" },
    { id: "starred", label: "Starred" },
  ];

  const contactDisplayName =
    contactUser?.name || contactUser?.username || "Contact";
  const contactAvatar =
    contactUser?.image ||
    contactUser?.avatar ||
    contactUser?.img ||
    `https://ui-avatars.com/api/?name=${encodeURIComponent(contactDisplayName)}&background=0D9488&color=fff&bold=true`;

  const contactRole =
    contactUser?.shortTitle ||
    contactUser?.occupation ||
    contactUser?.title ||
    (isSeller ? "Buyer" : "Seller");

  const isLoading = isOrdersLoading || isUserLoading;

  return (
    <div className="min-h-screen bg-[#F8F8F8] pt-8 sm:pt-10 md:pt-12 pb-[80px] min-[1400px]:pb-[100px]">
      <div className="container mx-auto px-4 md:px-6 space-y-6">
        {/* Breadcrumb Navigation */}
        <div className="flex items-center justify-between flex-wrap gap-2">
          <Breadcrumb
            homeHref={isSeller ? "/dashboard/seller" : "/dashboard/buyer"}
            homeTitle="Dashboard"
            items={[
              {
                name: isSeller ? "Manage Orders" : "Orders",
                href: isSeller ? "/manage-orders" : "/orders",
              },
              {
                name: isSeller
                  ? `Orders from @${contactUser?.username || contactDisplayName}`
                  : `Orders with @${contactUser?.username || contactDisplayName}`,
                isLast: true,
              },
            ]}
          />

          <Button
            type="button"
            variant="ghost"
            size="sm"
            radius="fiverr"
            onClick={() => router.back()}
            leftIcon={<FiArrowLeft className="text-sm" />}
            className="text-slate-600 hover:text-slate-900 font-medium text-xs sm:text-sm"
          >
            Back to Chat
          </Button>
        </div>

        {/* Page Heading with Contact Overview */}
        <div className="flex flex-col sm:flex-row sm:items-center justify-between gap-4 bg-white rounded-[6px] border border-slate-200/80 p-5 sm:p-6 shadow-2xs">
          <div className="flex items-center gap-3.5">
            <img
              src={contactAvatar}
              alt={contactDisplayName}
              className="w-12 h-12 sm:w-14 sm:h-14 rounded-full object-cover border border-slate-200 shrink-0"
            />
            <div>
              <div className="flex items-center gap-2 flex-wrap">
                <h1 className="text-xl sm:text-2xl font-bold font-inter text-[#292929]">
                  {isSeller ? `Orders from ${contactDisplayName}` : `Orders with ${contactDisplayName}`}
                </h1>
                {contactUser?.username && (
                  <span className="text-xs text-slate-500 font-medium">@{contactUser.username}</span>
                )}
                <span className="bg-[#0D6D5F]/10 text-[#0D6D5F] text-[11px] font-bold px-2 py-0.5 rounded-full">
                  {mutualOrders.length} {mutualOrders.length === 1 ? "Order" : "Orders"}
                </span>
              </div>
              <p className="text-xs sm:text-[13px] text-slate-500 mt-1 leading-relaxed">
                {isSeller
                  ? `Track and manage all orders received from this buyer.`
                  : `Track and manage all orders placed with this seller.`}
              </p>
            </div>
          </div>


        </div>

        {/* Main Orders Table Card */}
        <div className="bg-white rounded-[6px] border border-slate-200/80 shadow-[0_1px_4px_rgba(0,0,0,0.02)] p-6 sm:p-8 space-y-6">
          {/* Controls Bar: Tabs + Calendar + Search Input */}
          <div className="flex flex-col lg:flex-row lg:items-center justify-between gap-4 pb-6 border-b border-slate-100">
            {/* Pill Tabs */}
            <div className="bg-[#F4F4F6] p-[4px] rounded-[6px] border border-gray-200/50 inline-flex items-center h-[46px] overflow-x-auto scrollbar-none max-w-full">
              {tabs.map((tab) => {
                const isActive = activeTab === tab.id;
                return (
                  <Button
                    key={tab.id}
                    type="button"
                    variant={isActive ? "brand" : "ghost"}
                    size="sm"
                    radius="fiverr"
                    onClick={() => setActiveTab(tab.id)}
                    className={`h-full font-sf-pro font-medium text-[14px] sm:text-[15px] px-3 sm:px-4 whitespace-nowrap transition-all cursor-pointer ${isActive
                      ? "bg-[#0B403F] hover:bg-[#0B403F] text-white shadow-sm"
                      : "bg-transparent hover:bg-transparent text-[#6E6E6E] hover:text-[#222427]"
                      }`}
                  >
                    {tab.label}
                  </Button>
                );
              })}
            </div>

            {/* Right Tools: Calendar button + Search box */}
            <div className="flex items-center gap-3">


              <div className="relative flex items-center w-full sm:w-64">
                <RiSearchLine className="absolute left-3.5 text-slate-400 text-sm pointer-events-none" />
                <input
                  type="text"
                  placeholder="Search project or ID"
                  value={searchQuery}
                  onChange={(e) => setSearchQuery(e.target.value)}
                  className="w-full pl-9 pr-4 py-2 text-xs sm:text-sm rounded-[6px] border border-slate-200 bg-white placeholder:text-slate-400 focus:outline-none focus:border-[#0D3B34] transition-colors"
                />
              </div>
            </div>
          </div>

          {/* Table Area */}
          {isLoading ? (
            <div className="py-24 flex justify-center items-center">
              <Loader size={45} />
            </div>
          ) : isSeller ? (
            /* ══════════════════════════════════════════════════════════
               SELLER VIEW: Manage Orders Style (Buyer, Project, Due on, Price, Status)
               ══════════════════════════════════════════════════════════ */
            <div className="w-full overflow-x-auto">
              <table className="w-full min-w-[820px] border-collapse text-left">
                <thead>
                  <tr className="border-b border-slate-100 text-xs sm:text-[13px] font-bold text-gray-900 tracking-tight">
                    <th className="py-3.5 px-4 font-bold">BUYER</th>
                    <th className="py-3.5 px-4 font-bold">PROJECT</th>
                    <th className="py-3.5 px-4 font-bold whitespace-nowrap">DUE ON</th>
                    <th className="py-3.5 px-4 font-bold whitespace-nowrap">TOTAL</th>
                    <th className="py-3.5 px-4 font-bold whitespace-nowrap">STATUS</th>
                  </tr>
                </thead>
                <tbody className="divide-y divide-slate-100">
                  {filteredOrders.length === 0 ? (
                    <tr>
                      <td colSpan={5} className="py-20 text-center text-slate-400 text-sm font-medium">
                        No orders found with this buyer in this view.
                      </td>
                    </tr>
                  ) : (
                    filteredOrders.map((order: any) => {
                      const buyerObj = typeof order.buyerID === "object" && order.buyerID !== null ? order.buyerID : {};
                      const buyerName = buyerObj.username || buyerObj.name || contactDisplayName;
                      const buyerAvatarUrl = buyerObj.image || buyerObj.avatar || contactAvatar;

                      const projectTitle =
                        order.title ||
                        order.projectTitle ||
                        order.gigID?.title ||
                        order.packageID?.title ||
                        "Custom Deliverable";
                      const projectDescription =
                        order.projectDescription ||
                        order.gigID?.desc ||
                        order.description ||
                        order.instructions ||
                        "";

                      let dueDateDisplay = "-";
                      if (order.deadline) {
                        const d = new Date(order.deadline);
                        if (!isNaN(d.getTime())) {
                          dueDateDisplay = d.toLocaleDateString("en-US", { month: "short", day: "numeric" });
                        }
                      } else if (order.createdAt) {
                        const d = new Date(order.createdAt);
                        if (!isNaN(d.getTime())) {
                          dueDateDisplay = d.toLocaleDateString("en-US", { month: "short", day: "numeric" });
                        }
                      }

                      const statusBadge = getSellerStatusBadge(order.status, order.isCompleted);

                      return (
                        <tr
                          key={order._id || order.id}
                          onClick={() => router.push(`/orders/${order._id || order.id}`)}
                          className="hover:bg-slate-50/70 cursor-pointer transition-colors group"
                        >
                          {/* Buyer Column */}
                          <td className="py-4 px-4 align-middle whitespace-nowrap">
                            <div className="flex items-center gap-3">
                              <img
                                src={buyerAvatarUrl}
                                alt={buyerName}
                                className="w-10 h-10 rounded-full object-cover border border-gray-200 shrink-0"
                              />
                              <div className="flex flex-col">
                                <span className="text-xs sm:text-[13px] font-semibold text-gray-950 group-hover:text-[#0D3B34] transition-colors">
                                  {buyerName}
                                </span>
                                <span className="text-[11px] text-gray-500 mt-0.5">
                                  {contactRole}
                                </span>
                              </div>
                            </div>
                          </td>

                          {/* Project Column */}
                          <td className="py-4 px-4 align-middle max-w-[340px]">
                            <div className="flex items-center justify-between gap-2">
                              <div className="flex flex-col min-w-0">
                                <span
                                  className="text-[13px] font-semibold text-gray-900 line-clamp-1 leading-snug group-hover:text-[#0D3B34] transition-colors"
                                  title={projectTitle}
                                >
                                  {projectTitle}
                                </span>
                                {projectDescription && (
                                  <span
                                    className="text-[11px] text-gray-500 mt-0.5 line-clamp-1 leading-normal"
                                    title={projectDescription}
                                  >
                                    {projectDescription}
                                  </span>
                                )}
                              </div>

                              {(order.notes || order.instructions) && (
                                <Button
                                  type="button"
                                  variant="outline"
                                  size="icon"
                                  radius="lg"
                                  onClick={(e) => {
                                    e.stopPropagation();
                                    setActiveNotesOrder({
                                      projectTitle,
                                      sellerOrBuyerName: buyerName,
                                      notes: order.notes || order.instructions,
                                    });
                                  }}
                                  className="shrink-0 p-1.5 w-8 h-8 text-slate-500 hover:text-slate-800 border-slate-200"
                                  title="View order notes"
                                >
                                  <FiFileText className="text-sm" />
                                </Button>
                              )}
                            </div>
                          </td>

                          {/* Due Date Column */}
                          <td className="py-4 px-4 align-middle text-xs sm:text-[13px] text-gray-700 font-normal whitespace-nowrap">
                            {dueDateDisplay}
                          </td>

                          {/* Price Column */}
                          <td className="py-4 px-4 align-middle text-xs sm:text-[13.5px] font-bold text-gray-950 whitespace-nowrap">
                            {(Number(order.price) || 0).toLocaleString("en-US", {
                              style: "currency",
                              currency: "USD",
                            })}
                          </td>

                          {/* Status Column */}
                          <td className="py-4 px-4 align-middle whitespace-nowrap">
                            <Tag variant={order.status || statusBadge.label}>
                              {statusBadge.label}
                            </Tag>
                          </td>
                        </tr>
                      );
                    })
                  )}
                </tbody>
              </table>
            </div>
          ) : (
            /* ══════════════════════════════════════════════════════════
               BUYER VIEW: Manage Orders Style (Seller, Project, Due on, Price, Status)
               ══════════════════════════════════════════════════════════ */
            <div className="w-full overflow-x-auto">
              <table className="w-full min-w-[820px] border-collapse text-left">
                <thead>
                  <tr className="border-b border-slate-100 text-xs sm:text-sm font-bold text-slate-800">
                    <th className="py-4 px-4 font-bold">Seller</th>
                    <th className="py-4 px-4 font-bold">Project</th>
                    <th className="py-4 px-4 font-bold whitespace-nowrap">Due on</th>
                    <th className="py-4 px-4 font-bold whitespace-nowrap">Price</th>
                    <th className="py-4 px-4 font-bold whitespace-nowrap">Status</th>
                  </tr>
                </thead>
                <tbody className="divide-y divide-slate-100">
                  {filteredOrders.length === 0 ? (
                    <tr>
                      <td colSpan={5} className="py-20 text-center text-slate-400 text-sm font-medium">
                        No orders found with this seller in this view.
                      </td>
                    </tr>
                  ) : (
                    filteredOrders.map((order: any) => {
                      const sellerObj = typeof order.sellerID === "object" && order.sellerID !== null ? order.sellerID : {};
                      const sellerName = sellerObj.username || sellerObj.name || contactDisplayName;
                      const sellerAvatarUrl = sellerObj.image || sellerObj.avatar || contactAvatar;
                      const sellerRole = sellerObj.title || sellerObj.shortTitle || contactRole;
                      const sellerBadge = sellerObj.badge || contactUser?.badge;

                      const projectTitle =
                        order.title ||
                        order.projectTitle ||
                        order.gigID?.title ||
                        order.packageID?.title ||
                        "Custom Deliverable";
                      const projectDescription =
                        order.description ||
                        order.projectDescription ||
                        order.gigID?.description ||
                        order.instructions ||
                        "";

                      let dueDate = "-";
                      if (order.deadline) {
                        const d = new Date(order.deadline);
                        if (!isNaN(d.getTime())) {
                          dueDate = d.toLocaleDateString("en-US", { month: "short", day: "numeric" });
                        }
                      } else if (order.createdAt) {
                        const d = new Date(order.createdAt);
                        if (!isNaN(d.getTime())) {
                          dueDate = d.toLocaleDateString("en-US", { month: "short", day: "numeric" });
                        }
                      }

                      return (
                        <tr
                          key={order._id || order.id}
                          onClick={() => router.push(`/orders/${order._id || order.id}`)}
                          className="hover:bg-slate-50/70 cursor-pointer transition-colors group"
                        >
                          {/* Seller info */}
                          <td className="py-5 px-4 align-middle whitespace-nowrap">
                            <div className="flex items-center gap-3">
                              <img
                                src={sellerAvatarUrl}
                                alt={sellerName}
                                className="w-10 h-10 rounded-full object-cover border border-slate-200 shrink-0 bg-slate-100"
                              />
                              <div className="flex flex-col">
                                <div className="flex items-center gap-1.5">
                                  <span className="text-sm font-bold text-slate-900 group-hover:text-[#0D3B34] transition-colors">
                                    {sellerName}
                                  </span>
                                  {renderBadge(sellerBadge)}
                                </div>
                                <span className="text-xs text-slate-500 font-normal">
                                  {sellerRole}
                                </span>
                              </div>
                            </div>
                          </td>

                          {/* Project info + Notes button */}
                          <td className="py-5 px-4 align-middle max-w-[340px]">
                            <div className="flex items-center justify-between gap-3">
                              <div className="flex flex-col min-w-0">
                                <span
                                  className="text-sm font-bold text-slate-900 line-clamp-1 group-hover:text-[#0D3B34] transition-colors"
                                  title={projectTitle}
                                >
                                  {projectTitle}
                                </span>
                                {projectDescription && (
                                  <span
                                    className="text-xs text-slate-500 line-clamp-1 mt-0.5"
                                    title={projectDescription}
                                  >
                                    {projectDescription}
                                  </span>
                                )}
                              </div>

                              {(order.notes || order.instructions) && (
                                <Button
                                  type="button"
                                  variant="outline"
                                  size="icon"
                                  radius="lg"
                                  onClick={(e) => {
                                    e.stopPropagation();
                                    setActiveNotesOrder({
                                      projectTitle,
                                      sellerOrBuyerName: sellerName,
                                      notes: order.notes || order.instructions,
                                    });
                                  }}
                                  className="shrink-0 p-1.5 w-8 h-8 text-slate-500 hover:text-slate-800 border-slate-200"
                                  title="View requirement notes"
                                >
                                  <FiFileText className="text-sm" />
                                </Button>
                              )}
                            </div>
                          </td>

                          {/* Due date */}
                          <td className="py-5 px-4 align-middle text-xs sm:text-sm font-medium text-slate-700 whitespace-nowrap">
                            {dueDate}
                          </td>

                          {/* Price */}
                          <td className="py-5 px-4 align-middle text-xs sm:text-sm font-bold text-slate-900 whitespace-nowrap">
                            {(Number(order.price) || 0).toLocaleString("en-US", {
                              style: "currency",
                              currency: "USD",
                            })}
                          </td>

                          {/* Status pill */}
                          <td className="py-5 px-4 align-middle whitespace-nowrap">
                            {renderBuyerStatusPill(order.status, order.isCompleted)}
                          </td>
                        </tr>
                      );
                    })
                  )}
                </tbody>
              </table>
            </div>
          )}
        </div>
      </div>

      {/* Notes Modal Popup */}
      <Modal
        isOpen={Boolean(activeNotesOrder)}
        onClose={() => setActiveNotesOrder(null)}
        title="Order Requirements & Notes"
        footer={
          <Button
            type="button"
            onClick={() => setActiveNotesOrder(null)}
            variant="soft"
            size="md"
            radius="fiverr"
          >
            Close
          </Button>
        }
      >
        {activeNotesOrder && (
          <div className="space-y-4 text-left">
            <div>
              <p className="text-xs font-semibold text-slate-400 uppercase tracking-wider mb-1">Project</p>
              <p className="text-sm font-medium text-slate-800">{activeNotesOrder.projectTitle}</p>
            </div>

            <div>
              <p className="text-xs font-semibold text-slate-400 uppercase tracking-wider mb-1">
                {isSeller ? "Buyer" : "Seller"}
              </p>
              <p className="text-sm text-slate-700">{activeNotesOrder.sellerOrBuyerName}</p>
            </div>

            <div>
              <p className="text-xs font-semibold text-slate-400 uppercase tracking-wider mb-1">Note / Instructions</p>
              <div className="p-3.5 bg-slate-50 rounded-[6px] border border-slate-100 text-xs sm:text-sm text-slate-700 leading-relaxed max-h-56 overflow-y-auto whitespace-pre-wrap">
                {activeNotesOrder.notes}
              </div>
            </div>
          </div>
        )}
      </Modal>
    </div>
  );
}

