"use client";

import React, { useEffect, useState, useMemo, useRef } from "react";
import { useRouter } from "next/navigation";
import Link from "next/link";
import { toast } from "@/utils/toast";
import {
  FiCamera,
  FiEdit2,
  FiPlus,
  FiTrash2,
  FiChevronDown,
  FiCheck,
  FiX,
  FiExternalLink,
  FiEye,
  FiSearch,
} from "react-icons/fi";
import {
  Briefcase,
  GraduationCap,
  FolderDot,
  ShieldCheck,
  User as UserIcon,
  UploadCloud,
  Folder,
  ArrowLeft,
  Image as ImageIcon,
  CheckCircle2,
} from "lucide-react";

import { useUserStore } from "@/store/userStore";
import { axiosFetch, countriesFlags, getCountryShortName } from "@/utils";
import supportService from "@/utils/supportService";
import { Loader, KycVerificationForm, Button } from "@/components";
import { CustomSelect, CustomSelectOption, AccountStandingCard } from "@/components/ui";
import { calculateProfileCompletion } from "@/features/dashboard";
import useAdminCategories from "@/hooks/useAdminCategories";

const FALLBACK_CATEGORIES = [
  "Graphics & Design",
  "Programming & Tech",
  "Digital Marketing",
  "Video & Animation",
  "Writing & Translation",
  "Music & Audio",
  "Business & Consulting",
  "AI Services & Development",
  "Data & Analytics",
  "Photography & Media",
  "UI/UX & Web Design",
  "Mobile App Development",
];

const LANGUAGE_LEVEL_OPTIONS: CustomSelectOption[] = [
  { value: "Basic", label: "Basic" },
  { value: "Conversational", label: "Conversational" },
  { value: "Fluent", label: "Fluent" },
  { value: "Native", label: "Native" },
];

const COUNTRY_OPTIONS: CustomSelectOption[] = Object.keys(countriesFlags)
  .sort((a, b) => a.localeCompare(b))
  .map((c) => ({
    value: getCountryShortName(c),
    label: c,
  }));

export default function ProfilePage() {
  const router = useRouter();
  const user = useUserStore((state) => state.user);
  const setUser = useUserStore((state) => state.setUser);
  const isSeller = Boolean(user?.isSeller || user?.role === "seller");

  // Active section tab for navigation
  const [activeSection, setActiveSection] = useState<
    "personal" | "professional" | "experience" | "portfolio" | "verification"
  >("personal");

  // Form states - Personal & Professional
  const [phone, setPhone] = useState(user?.phone || "");
  const [country, setCountry] = useState(user?.country || "");
  const [shortTitle, setShortTitle] = useState(user?.shortTitle || user?.title || "");
  const [description, setDescription] = useState(user?.description || user?.desc || user?.bio || "");

  // Multi-Category state (for seller profile)
  const { parentCategories } = useAdminCategories();
  const [selectedCategories, setSelectedCategories] = useState<string[]>(() => {
    if (Array.isArray(user?.categories)) return user.categories;
    if (typeof user?.category === "string" && user.category) return [user.category];
    return [];
  });
  const [isCategoryDropdownOpen, setIsCategoryDropdownOpen] = useState(false);
  const [categorySearch, setCategorySearch] = useState("");
  const categoryDropdownRef = useRef<HTMLDivElement>(null);

  // Available categories list
  const allCategoryNames = useMemo(() => {
    const list: string[] = [];
    if (Array.isArray(parentCategories) && parentCategories.length > 0) {
      parentCategories.forEach((cat) => {
        const name = typeof cat === "string" ? cat : cat.name || cat.title;
        if (name && !list.includes(name)) list.push(name);
      });
    }
    FALLBACK_CATEGORIES.forEach((name) => {
      if (!list.includes(name)) list.push(name);
    });
    return list;
  }, [parentCategories]);

  // Filtered categories for search
  const filteredCategories = useMemo(() => {
    if (!categorySearch.trim()) return allCategoryNames;
    const q = categorySearch.toLowerCase().trim();
    return allCategoryNames.filter((cat) => cat.toLowerCase().includes(q));
  }, [allCategoryNames, categorySearch]);

  const toggleCategory = (catName: string) => {
    setSelectedCategories((prev) => {
      if (prev.includes(catName)) {
        return prev.filter((c) => c !== catName);
      } else {
        if (prev.length >= 5) {
          toast.error("You can select up to 5 categories");
          return prev;
        }
        return [...prev, catName];
      }
    });
  };

  const removeCategory = (catName: string) => {
    setSelectedCategories((prev) => prev.filter((c) => c !== catName));
  };

  // Close category dropdown on outside click
  useEffect(() => {
    const handleClickOutside = (event: MouseEvent) => {
      if (
        categoryDropdownRef.current &&
        !categoryDropdownRef.current.contains(event.target as Node)
      ) {
        setIsCategoryDropdownOpen(false);
      }
    };
    if (isCategoryDropdownOpen) {
      document.addEventListener("mousedown", handleClickOutside);
    }
    return () => {
      document.removeEventListener("mousedown", handleClickOutside);
    };
  }, [isCategoryDropdownOpen]);

  // Clear search query when dropdown closes
  useEffect(() => {
    if (!isCategoryDropdownOpen) {
      setCategorySearch("");
    }
  }, [isCategoryDropdownOpen]);

  // Dedicated Username update states & handler (PATCH /api/users/username)
  const [isEditingUsername, setIsEditingUsername] = useState(false);
  const [newUsername, setNewUsername] = useState(user?.username || "");
  const [isSubmittingUsername, setIsSubmittingUsername] = useState(false);
  const [usernameError, setUsernameError] = useState<string | null>(null);

  const handleUpdateUsername = async (e?: React.FormEvent) => {
    if (e) e.preventDefault();
    const cleanUsername = newUsername.trim();

    if (!cleanUsername) {
      setUsernameError("Username cannot be empty");
      return;
    }

    if (cleanUsername.length < 3) {
      setUsernameError("Username must be at least 3 characters");
      return;
    }

    if (cleanUsername.length > 30) {
      setUsernameError("Username cannot exceed 30 characters");
      return;
    }

    if (!/^[a-zA-Z0-9_-]+$/.test(cleanUsername)) {
      setUsernameError("Username can only contain letters, numbers, underscores (_), and hyphens (-)");
      return;
    }

    if (cleanUsername.toLowerCase() === (user?.username || "").toLowerCase()) {
      setUsernameError("New username cannot be the same as your current username");
      return;
    }

    setIsSubmittingUsername(true);
    setUsernameError(null);

    try {
      const { data } = await axiosFetch.patch("/users/username", {
        username: cleanUsername,
      });

      const updatedUsername =
        data?.user?.username || data?.username || data?.data?.username || cleanUsername;

      const updatedUser = {
        ...user,
        ...(data?.user || data?.data || {}),
        username: updatedUsername,
      };

      setUser(updatedUser);
      toast.success(data?.message || "Username updated successfully!");
      setIsEditingUsername(false);
    } catch (err: any) {
      const errorMsg =
        err.response?.data?.message ||
        err.response?.data?.error ||
        err.message ||
        "Failed to update username";
      const displayMsg = Array.isArray(errorMsg) ? errorMsg[0] : errorMsg;
      setUsernameError(displayMsg);
      toast.error(displayMsg);
    } finally {
      setIsSubmittingUsername(false);
    }
  };

  // Skills as an array - only real user skills, no dummy fallbacks
  const [skillsList, setSkillsList] = useState<string[]>(() => {
    if (Array.isArray(user?.skills)) return user.skills;
    if (typeof user?.skills === "string") {
      return (user.skills as string)
        .split(",")
        .map((s) => s.trim())
        .filter(Boolean);
    }
    return [];
  });
  const [newSkillInput, setNewSkillInput] = useState("");
  const [isAddingSkill, setIsAddingSkill] = useState(false);

  // Languages state
  const [languages, setLanguages] = useState<any[]>(user?.languages || []);
  const [isAddingLanguage, setIsAddingLanguage] = useState(false);
  const [newLangName, setNewLangName] = useState("");
  const [newLangLevel, setNewLangLevel] = useState("Fluent");

  // Experience & Education states
  const [experience, setExperience] = useState<any[]>(user?.experience || []);
  const [isAddingExperience, setIsAddingExperience] = useState(false);
  const [newExp, setNewExp] = useState({
    title: "",
    company: "",
    startDate: "",
    endDate: "",
    description: "",
  });

  const [education, setEducation] = useState<any[]>(user?.education || []);
  const [isAddingEducation, setIsAddingEducation] = useState(false);
  const [newEd, setNewEd] = useState({
    degree: "",
    university: "",
    year: "",
    country: "",
  });

  // Portfolio (for sellers)
  const [portfolio, setPortfolio] = useState<any[]>(user?.portfolio || []);
  const [editingProjectIdx, setEditingProjectIdx] = useState<number | null>(null);
  const [uploadingPortfolioIdx, setUploadingPortfolioIdx] = useState<number | null>(null);

  // Image upload states
  const [imageFile, setImageFile] = useState<File | null>(null);
  const initialAvatar = user?.image || user?.img || user?.avatar || user?.pp;
  const [previewUrl, setPreviewUrl] = useState(initialAvatar || "/media/noavatar.png");
  const [coverImageUrl, setCoverImageUrl] = useState(
    user?.coverImage ||
    (typeof window !== "undefined" ? localStorage.getItem("user_cover_image") : null) ||
    "https://images.unsplash.com/photo-1618005182384-a83a8bd57fbe?w=1200&auto=format&fit=crop&q=80"
  );
  const [isUpdating, setIsUpdating] = useState(false);
  const fileInputRef = useRef<HTMLInputElement>(null);
  const coverInputRef = useRef<HTMLInputElement>(null);

  useEffect(() => {
    window.scrollTo(0, 0);
  }, []);

  // Sync user state on load
  useEffect(() => {
    if (user) {
      if (user.phone !== undefined) setPhone(user.phone || "");
      if (user.country !== undefined) setCountry(user.country || "");
      const titleVal = user.shortTitle || user.title || "";
      setShortTitle(titleVal);
      const descVal = user.description || user.desc || user.bio || "";
      setDescription(descVal);

      const avatar = user.image || user.img || user.avatar || user.pp;
      if (avatar) setPreviewUrl(avatar);

      if (user.coverImage) {
        setCoverImageUrl(user.coverImage);
      } else if (typeof window !== "undefined") {
        const savedCover = localStorage.getItem("user_cover_image");
        if (savedCover) setCoverImageUrl(savedCover);
      }
      if (Array.isArray(user.languages)) setLanguages(user.languages);
      if (Array.isArray(user.experience)) setExperience(user.experience);
      if (Array.isArray(user.education)) setEducation(user.education);
      if (Array.isArray(user.portfolio)) setPortfolio(user.portfolio);
      if (Array.isArray(user.skills)) setSkillsList(user.skills);
      if (Array.isArray(user.categories)) {
        setSelectedCategories(user.categories);
      } else if (typeof user.category === "string" && user.category) {
        setSelectedCategories([user.category]);
      }
      if (user.username && !isEditingUsername) setNewUsername(user.username);
    }
  }, [user, isEditingUsername]);

  // Handle avatar upload
  const handleImageChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      setImageFile(file);
      setPreviewUrl(URL.createObjectURL(file));
      toast.success("Profile image selected. Click 'Save Changes' to update.");
    }
  };

  // Handle cover image upload
  const handleCoverChange = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      try {
        toast.loading("Uploading cover image...", { id: "cover-upload" });
        const uploaded = await supportService.uploadFileToCloudinary(file, "profile_covers");
        const cdnUrl = uploaded?.secure_url || uploaded?.url;
        if (cdnUrl) {
          // Immediately update backend with cover photo
          await axiosFetch.patch("/users", { coverPhotoUrl: cdnUrl }).catch(() => null);

          setCoverImageUrl(cdnUrl);
          if (typeof window !== "undefined") {
            localStorage.setItem("user_cover_image", cdnUrl);
            
            // Also update the cached user
            const updatedUser = { ...user, coverPhotoUrl: cdnUrl, coverImage: cdnUrl };
            setUser(updatedUser);
            localStorage.setItem("user", JSON.stringify(updatedUser));
          }
          toast.dismiss("cover-upload");
        }
      } catch (err: any) {
        toast.error(err?.response?.data?.message || err.message || "Failed to upload cover image", { id: "cover-upload" });
      }
    }
  };

  // Skill handlers
  const handleAddSkill = () => {
    if (!newSkillInput.trim()) return;
    if (!skillsList.includes(newSkillInput.trim())) {
      setSkillsList([...skillsList, newSkillInput.trim()]);
    }
    setNewSkillInput("");
    setIsAddingSkill(false);
  };

  const handleRemoveSkill = (skillToRemove: string) => {
    setSkillsList(skillsList.filter((s) => s !== skillToRemove));
  };

  // Language handlers
  const handleAddLanguageItem = () => {
    if (!newLangName.trim()) return;
    setLanguages([...languages, { language: newLangName.trim(), level: newLangLevel }]);
    setNewLangName("");
    setIsAddingLanguage(false);
  };

  const handleRemoveLanguage = (idx: number) => {
    setLanguages(languages.filter((_, i) => i !== idx));
  };

  // Experience handlers
  const handleAddExperienceItem = () => {
    if (!newExp.title.trim() || !newExp.company.trim()) {
      toast.error("Please enter position title and company name");
      return;
    }
    setExperience([...experience, { ...newExp }]);
    setNewExp({ title: "", company: "", startDate: "", endDate: "", description: "" });
    setIsAddingExperience(false);
    toast.success("Experience added!");
  };

  const handleRemoveExperience = (idx: number) => {
    setExperience(experience.filter((_, i) => i !== idx));
  };

  // Education handlers
  const handleAddEducationItem = () => {
    if (!newEd.degree.trim() || !newEd.university.trim()) {
      toast.error("Please enter degree and university/college");
      return;
    }
    setEducation([...education, { ...newEd }]);
    setNewEd({ degree: "", university: "", year: "", country: "" });
    setIsAddingEducation(false);
    toast.success("Education added!");
  };

  const handleRemoveEducation = (idx: number) => {
    setEducation(education.filter((_, i) => i !== idx));
  };

  // Portfolio handlers
  const handleAddPortfolio = () => {
    const newPort = [...portfolio, { title: "", description: "", image: "", link: "" }];
    setPortfolio(newPort);
    setEditingProjectIdx(newPort.length - 1);
  };

  const handleUpdatePortfolio = (index: number, field: string, value: string) => {
    const newPort = [...portfolio];
    if (newPort[index]) {
      newPort[index] = { ...newPort[index], [field]: value };
      setPortfolio(newPort);
    }
  };

  const handleRemovePortfolio = (index: number) => {
    setPortfolio(portfolio.filter((_, i) => i !== index));
    if (editingProjectIdx === index) {
      setEditingProjectIdx(null);
    } else if (editingProjectIdx !== null && editingProjectIdx > index) {
      setEditingProjectIdx(editingProjectIdx - 1);
    }
    toast.success("Project removed from list");
  };

  const handleSaveProject = (index: number) => {
    const item = portfolio[index];
    if (!item || !item.title || !item.title.trim()) {
      toast.error("Please enter a project title");
      return;
    }
    if (!item.image || !item.image.trim()) {
      toast.error("Please upload a project cover image");
      return;
    }
    setEditingProjectIdx(null);
    toast.success("Project saved! Click 'Save Changes' to update your profile.");
  };

  const handleCancelEditProject = (index: number) => {
    const item = portfolio[index];
    if (!item?.title?.trim() && !item?.image?.trim() && !item?.description?.trim()) {
      setPortfolio(portfolio.filter((_, i) => i !== index));
    }
    setEditingProjectIdx(null);
  };

  const handlePortfolioImageUpload = async (
    index: number,
    e: React.ChangeEvent<HTMLInputElement>
  ) => {
    const file = e.target.files?.[0];
    if (!file) return;

    setUploadingPortfolioIdx(index);
    try {
      toast.loading("Uploading portfolio image...", { id: `port-up-${index}` });
      const uploaded = await supportService.uploadFileToCloudinary(file, "portfolio_images");
      const cdnUrl = uploaded?.secure_url || uploaded?.url;
      if (cdnUrl) {
        handleUpdatePortfolio(index, "image", cdnUrl);
        toast.dismiss(`port-up-${index}`);
      } else {
        throw new Error("Upload succeeded but no URL returned");
      }
    } catch (err: any) {
      toast.error(err?.message || "Portfolio image upload failed", { id: `port-up-${index}` });
    } finally {
      setUploadingPortfolioIdx(null);
      e.target.value = "";
    }
  };

  // Profile completion calculation based on role-specific necessary fields
  const profileCompletion = useMemo(() => {
    const realAvatar = (previewUrl && !previewUrl.includes("noavatar"))
      ? previewUrl
      : (user?.image || user?.img || user?.avatar || user?.pp || "");
    return calculateProfileCompletion({
      ...user,
      image: realAvatar,
      phone,
      country,
      shortTitle,
      description,
      skills: skillsList,
      categories: selectedCategories,
      languages,
      experience,
      education,
      portfolio,
    });
  }, [
    user,
    previewUrl,
    phone,
    country,
    shortTitle,
    description,
    skillsList,
    selectedCategories,
    languages,
    experience,
    education,
    portfolio,
  ]);

  // Submit profile updates to real backend API
  const handleSubmit = async (e?: React.FormEvent) => {
    if (e) e.preventDefault();
    setIsUpdating(true);
    let payload: any = {};

    try {
      let imageUrl = user?.image;

      if (imageFile) {
        try {
          const uploaded = await supportService.uploadFileToCloudinary(imageFile, "avatars");
          if (uploaded.secure_url || uploaded.url) {
            imageUrl = uploaded.secure_url || uploaded.url;
          }
        } catch {
          // Fallback to imgbb if cloudinary has issue
          const formData = new FormData();
          formData.append("image", imageFile);
          const uploadRes = await fetch(
            "https://api.imgbb.com/1/upload?key=6857715a54c637cd1d21c558202e7c9c",
            {
              method: "POST",
              body: formData,
            }
          );
          const uploadData = await uploadRes.json();
          if (uploadData.success) {
            imageUrl = uploadData.data.url;
          }
        }
      }

      const validPortfolio = portfolio.filter(
        (p: any) => p && p.title && p.title.trim() !== "" && p.image && p.image.trim() !== ""
      );

      payload = {
        image: imageUrl,
        phone,
        country: getCountryShortName(country),
        shortTitle,
        description,
        skills: skillsList,
        languages,
        education,
        experience,
        portfolio: validPortfolio,
      };

      if (isSeller) {
        if (selectedCategories.length > 5) {
          toast.error("You can select a maximum of 5 categories");
          setIsUpdating(false);
          return;
        }
        payload.categories = selectedCategories;
      }

      const { data } = await axiosFetch.patch("/users", payload);

      if (isSeller) {
        // Also sync seller categories via auth/me endpoint to guarantee persistence
        axiosFetch.patch("/auth/me", { categories: selectedCategories }).catch(() => null);
      }

      if (!data.error) {
        const updatedUser = {
          ...user,
          ...data.user,
          ...(isSeller ? { categories: selectedCategories } : {}),
          coverImage: coverImageUrl,
        };
        setUser(updatedUser);
        if (typeof window !== "undefined") {
          localStorage.setItem("user", JSON.stringify(updatedUser));
          if (coverImageUrl) {
            localStorage.setItem("user_cover_image", coverImageUrl);
          }
        }
        toast.success("Profile updated successfully!");
      } else {
        toast.error(data.message || "Failed to update profile");
      }
    } catch (err: any) {
      const errMsg = String(err?.response?.data?.message || "");
      if (
        isSeller &&
        (errMsg.includes("categories should not exist") ||
          errMsg.includes("property categories should not exist"))
      ) {
        try {
          delete payload.categories;
          const { data } = await axiosFetch.patch("/users", payload);
          await axiosFetch.patch("/auth/me", { categories: selectedCategories }).catch(() => null);
          const updatedUser = {
            ...user,
            ...data.user,
            categories: selectedCategories,
            coverImage: coverImageUrl,
          };
          setUser(updatedUser);
          if (typeof window !== "undefined") {
            localStorage.setItem("user", JSON.stringify(updatedUser));
            if (coverImageUrl) {
              localStorage.setItem("user_cover_image", coverImageUrl);
            }
          }
          toast.success("Profile updated successfully!");
          return;
        } catch (innerErr: any) {
          toast.error(
            innerErr.response?.data?.message || innerErr.message || "Failed to update profile"
          );
          return;
        }
      }
      toast.error(err.response?.data?.message || err.message || "Failed to update profile");
    } finally {
      setIsUpdating(false);
    }
  };

  // Scroll to section with sticky header offset
  const scrollToSection = (sectionId: string) => {
    const el = document.getElementById(sectionId);
    if (el) {
      const navHeight = typeof window !== "undefined"
        ? parseInt(getComputedStyle(document.documentElement).getPropertyValue('--navbar-height') || '80', 10)
        : 80;
      const stickyTabsHeight = 65;
      const totalOffset = (isNaN(navHeight) ? 80 : navHeight) + stickyTabsHeight;
      const elementPosition = el.getBoundingClientRect().top + window.scrollY;
      window.scrollTo({
        top: Math.max(0, elementPosition - totalOffset),
        behavior: "smooth",
      });
    }
  };

  // Sync active section based on scroll position
  useEffect(() => {
    const sectionIds = [
      "section-personal",
      "section-professional",
      "section-experience",
      ...(isSeller ? ["section-portfolio", "section-verification"] : []),
    ];

    const handleScroll = () => {
      const navHeight = parseInt(
        getComputedStyle(document.documentElement).getPropertyValue("--navbar-height") || "80",
        10
      );
      const offset = (isNaN(navHeight) ? 80 : navHeight) + 90;
      const scrollPos = window.scrollY + offset;

      for (let i = sectionIds.length - 1; i >= 0; i--) {
        const id = sectionIds[i];
        const el = document.getElementById(id);
        if (el && el.offsetTop <= scrollPos) {
          const rawSec = id.replace("section-", "") as
            | "personal"
            | "professional"
            | "experience"
            | "portfolio"
            | "verification";
          setActiveSection(rawSec);
          break;
        }
      }
    };

    window.addEventListener("scroll", handleScroll, { passive: true });
    return () => window.removeEventListener("scroll", handleScroll);
  }, [isSeller]);

  return (
    <div className="min-h-screen bg-[#F8FAFC] pt-6 sm:pt-10 pb-[80px] min-[1400px]:pb-[100px] font-sans">
      <div className="container mx-auto px-4 md:px-6">

        {/* Page Title & Navigation Tabs (Sticky) */}
        <div
          style={{
            top: `calc(var(--navbar-height, ${isSeller ? "82px" : "136px"}) + 0px)`,
          }}
          className={`sticky z-30 py-2.5 sm:py-3.5 -my-1 bg-[#F8FAFC]/95 backdrop-blur-md transition-[top] duration-200 mb-6 flex flex-col md:flex-row md:items-center justify-between gap-4 ${isSeller ? "top-[74px] md:top-[88px]" : "top-[128px] md:top-[142px]"
            }`}
        >
          <div>
            <h1 className="text-2xl sm:text-[28px] font-medium font-inter text-[#292929]">
              Edit Profile Settings
            </h1>
            <p className="text-slate-500 text-xs sm:text-sm mt-1">
              Update your personal information, professional details, and portfolio.
            </p>
          </div>

          {/* Section Pill Tabs */}
          <div className="bg-white border border-slate-200/80 rounded-[6px] p-1 flex items-center gap-1 self-start md:self-auto overflow-x-auto max-w-full scrollbar-none shadow-xs shrink-0">
            <Button
              type="button"
              size="sm"
              radius="fiverr"
              onClick={() => {
                setActiveSection("personal");
                scrollToSection("section-personal");
              }}
              className={`px-4 py-2 font-semibold whitespace-nowrap transition-colors ${activeSection === "personal"
                ? "bg-[#0D3B34] text-white shadow-2xs hover:bg-[#0D3B34]"
                : "bg-transparent text-slate-600 hover:text-slate-900 hover:bg-slate-50"
                }`}
            >
              Personal Info
            </Button>
            <Button
              type="button"
              size="sm"
              radius="fiverr"
              onClick={() => {
                setActiveSection("professional");
                scrollToSection("section-professional");
              }}
              className={`px-4 py-2 font-semibold whitespace-nowrap transition-colors ${activeSection === "professional"
                ? "bg-[#0D3B34] text-white shadow-2xs hover:bg-[#0D3B34]"
                : "bg-transparent text-slate-600 hover:text-slate-900 hover:bg-slate-50"
                }`}
            >
              Professional Details
            </Button>
            <Button
              type="button"
              size="sm"
              radius="fiverr"
              onClick={() => {
                setActiveSection("experience");
                scrollToSection("section-experience");
              }}
              className={`px-4 py-2 font-semibold whitespace-nowrap transition-colors ${activeSection === "experience"
                ? "bg-[#0D3B34] text-white shadow-2xs hover:bg-[#0D3B34]"
                : "bg-transparent text-slate-600 hover:text-slate-900 hover:bg-slate-50"
                }`}
            >
              Experience &amp; Education
            </Button>
            {isSeller && (
              <Button
                type="button"
                size="sm"
                radius="fiverr"
                onClick={() => {
                  setActiveSection("portfolio");
                  scrollToSection("section-portfolio");
                }}
                className={`px-4 py-2 font-semibold whitespace-nowrap transition-colors ${activeSection === "portfolio"
                  ? "bg-[#0D3B34] text-white shadow-2xs hover:bg-[#0D3B34]"
                  : "bg-transparent text-slate-600 hover:text-slate-900 hover:bg-slate-50"
                  }`}
              >
                Portfolio
              </Button>
            )}
            {isSeller && (
              <Button
                type="button"
                size="sm"
                radius="fiverr"
                onClick={() => {
                  setActiveSection("verification");
                  scrollToSection("section-verification");
                }}
                className={`px-4 py-2 font-semibold whitespace-nowrap transition-colors ${activeSection === "verification"
                  ? "bg-[#0D3B34] text-white shadow-2xs hover:bg-[#0D3B34]"
                  : "bg-transparent text-slate-600 hover:text-slate-900 hover:bg-slate-50"
                  }`}
              >
                Verification
              </Button>
            )}
          </div>
        </div>

        {/* Account Standing Status Card (only renders if warning or suspended) */}
        <AccountStandingCard className="mb-6" />

        {/* HERO BANNER CARD */}
        <div className="bg-white rounded-[6px] border border-slate-200/90 shadow-[0_1px_3px_rgba(0,0,0,0.02)] p-4 sm:p-5 mb-7">
          {/* Cover image banner */}
          <div
            className="h-36 sm:h-44 md:h-48 rounded-[6px] overflow-hidden relative bg-slate-900 bg-cover bg-center"
            style={{ backgroundImage: `url(${coverImageUrl})` }}
          >
            {/* Top Right Banner Controls */}
            <div className="absolute top-3 right-3 sm:top-4 sm:right-4 flex items-center gap-2">
              <Button
                type="button"
                variant="ghost"
                size="xs"
                radius="full"
                onClick={() => {
                  const targetUser = user?.username || user?._id || user?.id;
                  if (targetUser) {
                    router.push(`/seller/${encodeURIComponent(targetUser)}?preview=true`);
                  } else {
                    toast.error("User profile unavailable");
                  }
                }}
                className="bg-white/95 hover:bg-white text-slate-800 font-bold px-4 py-1.5 shadow-md flex items-center gap-1.5"
              >
                <span>See Public View</span>
              </Button>
              <Button
                type="button"
                variant="ghost"
                size="icon"
                radius="full"
                onClick={() => coverInputRef.current?.click()}
                className="w-8 h-8 rounded-full bg-white/95 hover:bg-white text-slate-700 shadow-md flex items-center justify-center p-0"
                title="Change Cover Image"
              >
                <FiEdit2 className="text-xs" />
              </Button>
              <input
                ref={coverInputRef}
                type="file"
                accept="image/*"
                onChange={handleCoverChange}
                className="hidden"
              />
            </div>
          </div>

          {/* Profile Meta Row: Avatar + Name + Completion */}
          <div className="px-2 sm:px-4 pt-3 sm:pt-4 flex flex-col sm:flex-row sm:items-end justify-between gap-4">
            <div className="flex items-end gap-3.5 -mt-12 sm:-mt-14">
              {/* Avatar with Camera upload trigger */}
              <div className="relative group shrink-0">
                <img
                  src={previewUrl}
                  alt={user?.username || "Avatar"}
                  className="w-20 h-20 sm:w-22 sm:h-22 rounded-full object-cover border-4 border-white shadow-md bg-slate-100"
                />
                <Button
                  type="button"
                  variant="ghost"
                  size="icon"
                  radius="full"
                  onClick={() => fileInputRef.current?.click()}
                  className="absolute inset-0 w-full h-full rounded-full bg-black/40 text-white opacity-0 group-hover:opacity-100 transition-opacity flex items-center justify-center p-0 hover:bg-black/50"
                  title="Upload profile picture"
                >
                  <FiCamera className="text-lg" />
                </Button>
                <input
                  ref={fileInputRef}
                  type="file"
                  accept="image/*"
                  onChange={handleImageChange}
                  className="hidden"
                />
              </div>

              {/* Name + Badge + Title */}
              <div className="mb-1">
                <div className="flex items-center gap-2">
                  <h2 className="font-bold text-base sm:text-lg text-slate-900 leading-tight">
                    {user?.name || user?.username || "User"}
                  </h2>
                  <span className="bg-[#4C1D95] text-white text-[10px] font-bold px-2 py-0.5 rounded-[6px] tracking-wider">
                    {user?.badge || (isSeller ? "Pro" : "Client")}
                  </span>
                </div>
                <p className="text-xs text-slate-500 mt-0.5">
                  {shortTitle || user?.shortTitle}
                </p>
              </div>
            </div>

            {/* Profile Completion Progress Bar */}
            <div className="sm:text-right pb-1">
              {profileCompletion >= 100 ? (
                <div className="flex flex-col sm:items-end gap-1.5">
                  <div className="flex items-center sm:justify-end gap-1.5 text-xs font-semibold text-emerald-700">
                    <CheckCircle2 className="w-4 h-4 text-emerald-600 shrink-0" />
                    <span>Profile 100% Completed</span>
                  </div>
                  <div className="w-full sm:w-44 h-1.5 bg-emerald-100 rounded-full overflow-hidden">
                    <div className="h-full bg-emerald-500 rounded-full transition-all duration-500 w-full" />
                  </div>
                </div>
              ) : (
                <>
                  <div className="flex items-center sm:justify-end gap-2 text-xs mb-1.5">
                    <span className="font-semibold text-slate-800 ">
                      Complete your profile
                    </span>
                    <span className="font-bold text-slate-900">{profileCompletion}%</span>
                  </div>
                  <div className="w-full sm:w-44 h-1.5 bg-slate-100 rounded-full overflow-hidden">
                    <div
                      className="h-full bg-gradient-to-r from-teal-400 to-emerald-500 rounded-full transition-all duration-500"
                      style={{ width: `${profileCompletion}%` }}
                    />
                  </div>
                </>
              )}
            </div>
          </div>
        </div>

        {/* SECTION 1: PERSONAL INFO */}
        <div
          id="section-personal"
          className="bg-white rounded-[6px] border border-slate-200/90 shadow-[0_1px_3px_rgba(0,0,0,0.02)] p-6 sm:p-7 mb-6 scroll-mt-32 sm:scroll-mt-36"
        >
          <div className="flex items-center justify-between pb-5 border-b border-slate-100 mb-6">
            <h2 className="text-base sm:text-lg font-bold text-slate-900">Personal Info</h2>
            <Button
              type="button"
              variant="ghost"
              size="icon"
              radius="fiverr"
              onClick={() => scrollToSection("section-personal")}
              className="text-slate-400 hover:text-slate-700 w-7 h-7 p-1 hover:bg-slate-100"
            >
              <FiEdit2 className="text-sm" />
            </Button>
          </div>

          <div className="grid grid-cols-1 sm:grid-cols-2 gap-5">
            {/* Account Username */}
            <div className="relative">
              <div className="flex items-center justify-between mb-1.5">
                <label className="text-xs font-bold text-slate-700">
                  Account username
                </label>
                {!isEditingUsername && (
                  <button
                    type="button"
                    onClick={() => {
                      setIsEditingUsername(true);
                      setNewUsername(user?.username || "");
                      setUsernameError(null);
                    }}
                    className="inline-flex items-center gap-1 text-[11px] font-semibold text-[#0D6D5F] hover:text-[#0b5c50] transition-colors cursor-pointer"
                  >
                    <FiEdit2 className="w-3 h-3" />
                    Change username
                  </button>
                )}
              </div>

              {!isEditingUsername ? (
                <div>
                  <div className="flex items-center w-full px-3.5 py-2.5 bg-slate-50/70 border border-slate-200 rounded-[6px] text-xs sm:text-sm text-slate-800">
                    <span className="text-slate-400 font-medium mr-1">@</span>
                    <span className="font-semibold text-slate-900 truncate">
                      {user?.username || "Not set"}
                    </span>
                  </div>
                  <p className="text-[11px] text-slate-400 mt-1">
                    Your unique public handle and profile identifier.
                  </p>
                </div>
              ) : (
                <div className="bg-slate-50 border border-[#0D6D5F]/30 rounded-[6px] p-3 space-y-2.5">
                  <div className="relative">
                    <span className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-400 text-xs font-semibold">
                      @
                    </span>
                    <input
                      type="text"
                      autoFocus
                      value={newUsername}
                      onChange={(e) => {
                        setNewUsername(e.target.value.toLowerCase().replace(/[^a-zA-Z0-9_-]/g, ""));
                        if (usernameError) setUsernameError(null);
                      }}
                      onKeyDown={(e) => {
                        if (e.key === "Enter") {
                          e.preventDefault();
                          handleUpdateUsername();
                        } else if (e.key === "Escape") {
                          setIsEditingUsername(false);
                          setUsernameError(null);
                        }
                      }}
                      placeholder="new_username"
                      disabled={isSubmittingUsername}
                      className="w-full pl-7 pr-3 py-2 bg-white border border-slate-300 focus:border-[#0D6D5F] focus:ring-1 focus:ring-[#0D6D5F]/20 rounded-[6px] text-xs sm:text-sm text-slate-900 outline-none transition disabled:opacity-50"
                    />
                  </div>

                  {usernameError && (
                    <p className="text-[11px] text-red-500 font-medium leading-tight">
                      {usernameError}
                    </p>
                  )}

                  <p className="text-[11px] text-slate-500 leading-relaxed">
                    Changing your username updates your public profile URL (e.g. <span className="font-mono text-slate-600">/seller/{newUsername || user?.username || "username"}</span>).
                  </p>

                  <div className="flex items-center gap-2 pt-1">
                    <Button
                      type="button"
                      variant="brand"
                      size="sm"
                      radius="fiverr"
                      onClick={() => handleUpdateUsername()}
                      disabled={isSubmittingUsername}
                      className="h-8 text-xs font-semibold px-3"
                    >
                      {isSubmittingUsername ? (
                        <div className="flex items-center gap-1.5">
                          <span className="w-3 h-3 border-2 border-white/30 border-t-white rounded-full animate-spin" />
                          <span>Saving...</span>
                        </div>
                      ) : (
                        "Save Username"
                      )}
                    </Button>
                    <Button
                      type="button"
                      variant="outline"
                      size="sm"
                      radius="fiverr"
                      onClick={() => {
                        setIsEditingUsername(false);
                        setNewUsername(user?.username || "");
                        setUsernameError(null);
                      }}
                      disabled={isSubmittingUsername}
                      className="h-8 text-xs font-medium px-3 text-slate-600 hover:text-slate-900"
                    >
                      Cancel
                    </Button>
                  </div>
                </div>
              )}
            </div>

            {/* Email Address */}
            <div>
              <label className="text-xs sm:text-[13px] font-medium text-gray-700 block mb-1.5">
                Email Address
              </label>
              <input
                type="email"
                value={user?.email || ""}
                disabled
                className="w-full h-10 px-3.5 bg-slate-50/70 border border-slate-200 rounded-[6px] text-sm text-slate-600 cursor-not-allowed"
              />
            </div>

            {/* Phone Number */}
            <div>
              <label className="text-xs sm:text-[13px] font-medium text-gray-700 block mb-1.5">
                Phone Number
              </label>
              <input
                type="text"
                value={phone}
                onChange={(e) => setPhone(e.target.value)}
                placeholder="+1 555-0199"
                className="w-full h-10 px-3.5 bg-[#F0F0F0] border border-[rgba(0,0,0,0.10)] focus:border-gray-300 focus:bg-white rounded-[6px] text-sm text-gray-900 placeholder:text-[#868686] placeholder:font-normal outline-none transition-colors"
              />
            </div>

            {/* Country */}
            <div>
              <label className="text-xs sm:text-[13px] font-medium text-gray-700 block mb-1.5">
                Country
              </label>
              <CustomSelect
                options={COUNTRY_OPTIONS}
                value={country}
                onChange={(val) => setCountry(String(val))}
                placeholder="Select country"
                variant="filled"
                searchable
                ariaLabel="Country"
              />
            </div>
          </div>
        </div>

        {/* SECTION 2: PROFESSIONAL DETAILS */}
        <div
          id="section-professional"
          className="bg-white rounded-[6px] border border-slate-200/90 shadow-[0_1px_3px_rgba(0,0,0,0.02)] p-6 sm:p-7 mb-7 scroll-mt-32 sm:scroll-mt-36"
        >
          <div className="flex items-center justify-between pb-5 border-b border-slate-100 mb-6">
            <h2 className="text-base sm:text-lg font-bold text-slate-900">
              Professional Details
            </h2>
            <Button
              type="button"
              variant="ghost"
              size="icon"
              radius="fiverr"
              onClick={() => scrollToSection("section-professional")}
              className="text-slate-400 hover:text-slate-700 w-7 h-7 p-1 hover:bg-slate-100"
            >
              <FiEdit2 className="text-sm" />
            </Button>
          </div>

          {/* Professional Title & Categories (Categories for Sellers only) */}
          <div className={`grid grid-cols-1 ${isSeller ? "sm:grid-cols-2" : ""} gap-5 mb-5`}>
            <div>
              <label className="text-xs sm:text-[13px] font-medium text-gray-700 block mb-1.5">
                Professional Title
              </label>
              <input
                type="text"
                value={shortTitle}
                onChange={(e) => setShortTitle(e.target.value)}
                placeholder="e.g Expert Digital Marketer & Specialist"
                className="w-full h-10 px-3.5 bg-[#F0F0F0] border border-[rgba(0,0,0,0.10)] focus:border-gray-300 focus:bg-white rounded-[6px] text-sm text-gray-900 placeholder:text-[#868686] placeholder:font-normal outline-none transition-colors"
              />
            </div>

            {isSeller && (
              <div className="relative" ref={categoryDropdownRef}>
                <label className="text-xs sm:text-[13px] font-medium text-gray-700 block mb-1.5">
                  Categories <span className="text-slate-400 font-normal text-[11px]">(Max 5)</span>
                </label>

                {/* Multi-Select Dropdown Trigger */}
                <button
                  type="button"
                  onClick={() => setIsCategoryDropdownOpen((prev) => !prev)}
                  className="w-full h-10 px-3.5 bg-[#F0F0F0] border border-[rgba(0,0,0,0.10)] hover:border-gray-300 focus:border-[#0D6D5F] focus:bg-white rounded-[6px] text-sm text-gray-900 flex items-center justify-between outline-none transition-colors cursor-pointer"
                >
                  <span className={selectedCategories.length === 0 ? "text-[#868686]" : "text-gray-900 font-medium truncate pr-2"}>
                    {selectedCategories.length === 0
                      ? "Select categories (max 5)..."
                      : `${selectedCategories.length} / 5 categories selected`}
                  </span>
                  <FiChevronDown
                    className={`w-4 h-4 text-gray-500 shrink-0 transition-transform duration-200 ${isCategoryDropdownOpen ? "rotate-180" : ""
                      }`}
                  />
                </button>

                {/* Dropdown Menu */}
                {isCategoryDropdownOpen && (
                  <div className="absolute left-0 right-0 top-full mt-1.5 bg-white border border-slate-200 rounded-[6px] shadow-lg z-50 p-2 max-h-60 overflow-y-auto">
                    <div className="relative mb-2">
                      <FiSearch className="absolute left-2.5 top-1/2 -translate-y-1/2 text-slate-400 text-xs" />
                      <input
                        type="text"
                        value={categorySearch}
                        onChange={(e) => setCategorySearch(e.target.value)}
                        placeholder="Search category..."
                        className="w-full pl-7 pr-2.5 py-1.5 text-xs bg-slate-50 border border-slate-200 rounded-[4px] outline-none focus:border-[#0D6D5F] text-slate-800 placeholder:text-slate-400"
                        autoFocus
                      />
                    </div>
                    <div className="space-y-0.5">
                      {filteredCategories.length > 0 ? (
                        filteredCategories.map((catName) => {
                          const isSelected = selectedCategories.includes(catName);
                          const isMaxReached = selectedCategories.length >= 5 && !isSelected;
                          return (
                            <button
                              key={catName}
                              type="button"
                              onClick={() => toggleCategory(catName)}
                              className={`w-full text-left px-2.5 py-2 rounded-[4px] text-xs flex items-center justify-between transition-colors cursor-pointer ${isSelected
                                ? "bg-[#0D6D5F]/10 text-[#0D6D5F] font-semibold"
                                : isMaxReached
                                  ? "text-slate-400 opacity-60 hover:bg-slate-50"
                                  : "text-slate-700 hover:bg-slate-50"
                                }`}
                            >
                              <span className="truncate pr-2">{catName}</span>
                              {isSelected && <FiCheck className="w-3.5 h-3.5 text-[#0D6D5F] shrink-0" />}
                            </button>
                          );
                        })
                      ) : (
                        <p className="text-xs text-slate-400 py-2 text-center">No categories found</p>
                      )}
                    </div>
                  </div>
                )}

                {/* Selected Category Tags Display */}
                {selectedCategories.length > 0 && (
                  <div className="flex flex-wrap items-center gap-1.5 mt-2">
                    {selectedCategories.map((cat) => (
                      <span
                        key={cat}
                        className="bg-[#F1F3F5] text-slate-700 text-xs font-medium px-3 py-1.5 rounded-[6px] border border-slate-200/60 inline-flex items-center gap-1.5"
                      >
                        <span>{cat}</span>
                        <button
                          type="button"
                          onClick={() => removeCategory(cat)}
                          className="text-slate-400 hover:text-slate-700 w-3.5 h-3.5 inline-flex items-center justify-center cursor-pointer"
                          title={`Remove ${cat}`}
                        >
                          <FiX className="w-3 h-3" />
                        </button>
                      </span>
                    ))}
                  </div>
                )}
                <p className="text-[11px] text-slate-400 mt-1">
                  Select up to 5 categories that describe your professional services.
                </p>
              </div>
            )}
          </div>

          {/* Bio */}
          <div className="mb-6">
            <label className="text-xs sm:text-[13px] font-medium text-gray-700 block mb-1.5">
              Bio
            </label>
            <textarea
              rows={3}
              value={description}
              onChange={(e) => setDescription(e.target.value)}
              placeholder="Write here"
              className="w-full p-3.5 bg-[#F0F0F0] border border-[rgba(0,0,0,0.10)] focus:border-gray-300 focus:bg-white rounded-[6px] text-sm text-gray-900 placeholder:text-[#868686] placeholder:font-normal outline-none transition-colors resize-none"
            />
          </div>

          {/* Skills Section */}
          <div className="mb-6">
            <label className="text-xs sm:text-[13px] font-medium text-gray-700 block mb-2">
              Skills
            </label>
            <div className="flex flex-wrap items-center gap-2 mb-2.5">
              {skillsList.map((skill, idx) => (
                <span
                  key={idx}
                  className="bg-[#F1F3F5] text-slate-700 text-xs font-medium px-3 py-1.5 rounded-[6px] border border-slate-200/60 inline-flex items-center gap-1.5"
                >
                  <span>{skill}</span>
                  <Button
                    type="button"
                    variant="ghost"
                    size="icon"
                    radius="full"
                    onClick={() => handleRemoveSkill(skill)}
                    className="text-slate-400 hover:text-slate-700 w-4 h-4 p-0 min-h-0 hover:bg-transparent"
                  >
                    <FiX className="w-3 h-3" />
                  </Button>
                </span>
              ))}
            </div>
            {skillsList.length === 0 && !isAddingSkill && (
              <p className="text-xs text-slate-400 mb-2">There is no skill added</p>
            )}

            {/* Add Skill Inline Form */}
            {isAddingSkill ? (
              <div className="flex items-center gap-2 max-w-sm mt-2">
                <input
                  type="text"
                  value={newSkillInput}
                  onChange={(e) => setNewSkillInput(e.target.value)}
                  onKeyDown={(e) => {
                    if (e.key === "Enter") {
                      e.preventDefault();
                      handleAddSkill();
                    }
                  }}
                  placeholder="Enter skill name"
                  className="px-3 py-1.5 rounded-[6px] border border-slate-200 text-xs outline-none focus:border-teal-500 flex-1"
                  autoFocus
                />
                <Button
                  type="button"
                  variant="dark"
                  size="xs"
                  radius="fiverr"
                  onClick={handleAddSkill}
                  className="px-3 py-1.5 font-semibold"
                >
                  Add
                </Button>
                <Button
                  type="button"
                  variant="ghost"
                  size="xs"
                  radius="fiverr"
                  onClick={() => setIsAddingSkill(false)}
                  className="px-2 py-1.5 text-slate-500 hover:text-slate-700"
                >
                  Cancel
                </Button>
              </div>
            ) : (
              <Button
                type="button"
                variant="ghost"
                size="xs"
                radius="fiverr"
                onClick={() => setIsAddingSkill(true)}
                rightIcon={<FiPlus className="text-sm" />}
                className="text-xs font-bold text-[#0D9488] hover:text-[#0b7a70] p-0 hover:bg-transparent inline-flex items-center gap-1 mt-1"
              >
                <span>Add Skills</span>
              </Button>
            )}
          </div>

          {/* Languages Section */}
          <div>
            <label className="text-xs font-bold text-slate-700 block mb-1">
              Languages
            </label>
            {languages.length === 0 && !isAddingLanguage ? (
              <p className="text-xs text-slate-400 mb-2">There is no language added</p>
            ) : (
              <div className="flex flex-wrap gap-2 mb-2.5">
                {languages.map((lang, idx) => (
                  <span
                    key={idx}
                    className="bg-[#F1F3F5] text-slate-700 text-xs font-medium px-3 py-1.5 rounded-[6px] border border-slate-200/60 inline-flex items-center gap-2"
                  >
                    <span>
                      {lang.language || lang.name}{" "}
                      <span className="text-slate-400 text-[11px]">({lang.level || "Fluent"})</span>
                    </span>
                    <Button
                      type="button"
                      variant="ghost"
                      size="icon"
                      radius="full"
                      onClick={() => handleRemoveLanguage(idx)}
                      className="text-slate-400 hover:text-slate-700 w-4 h-4 p-0 min-h-0 hover:bg-transparent"
                    >
                      <FiX className="w-3 h-3" />
                    </Button>
                  </span>
                ))}
              </div>
            )}

            {/* Add Language Inline Form */}
            {isAddingLanguage ? (
              <div className="flex flex-wrap items-center gap-2 max-w-md mt-2">
                <input
                  type="text"
                  value={newLangName}
                  onChange={(e) => setNewLangName(e.target.value)}
                  placeholder="Language (e.g. English)"
                  className="px-3 py-1.5 rounded-[6px] border border-slate-200 text-xs outline-none focus:border-teal-500 flex-1 min-w-[120px]"
                />
                <div className="w-[145px] shrink-0">
                  <CustomSelect
                    size="sm"
                    options={LANGUAGE_LEVEL_OPTIONS}
                    value={newLangLevel}
                    onChange={(val) => setNewLangLevel(String(val))}
                    placeholder="Level"
                    ariaLabel="Language level"
                  />
                </div>
                <Button
                  type="button"
                  variant="dark"
                  size="xs"
                  radius="fiverr"
                  onClick={handleAddLanguageItem}
                  className="px-3 py-1.5 font-semibold"
                >
                  Add
                </Button>
                <Button
                  type="button"
                  variant="ghost"
                  size="xs"
                  radius="fiverr"
                  onClick={() => setIsAddingLanguage(false)}
                  className="px-2 py-1.5 text-slate-500 hover:text-slate-700"
                >
                  Cancel
                </Button>
              </div>
            ) : (
              <Button
                type="button"
                variant="ghost"
                size="xs"
                radius="fiverr"
                onClick={() => setIsAddingLanguage(true)}
                rightIcon={<FiPlus className="text-sm" />}
                className="text-xs font-bold text-[#0D9488] hover:text-[#0b7a70] p-0 hover:bg-transparent inline-flex items-center gap-1"
              >
                <span>Add Languages</span>
              </Button>
            )}
          </div>
        </div>

        {/* SECTION 3: EXPERIENCE & EDUCATION */}
        <div
          id="section-experience"
          className="bg-white rounded-[6px] border border-slate-200/90 shadow-[0_1px_3px_rgba(0,0,0,0.02)] p-6 sm:p-7 mb-7 scroll-mt-32 sm:scroll-mt-36"
        >
          <div className="flex items-center justify-between pb-5 border-b border-slate-100 mb-6">
            <h2 className="text-base sm:text-lg font-bold text-slate-900">
              Experience &amp; Education
            </h2>
            <Button
              type="button"
              variant="ghost"
              size="icon"
              radius="fiverr"
              onClick={() => scrollToSection("section-experience")}
              className="text-slate-400 hover:text-slate-700 w-7 h-7 p-1 hover:bg-slate-100"
            >
              <FiEdit2 className="text-sm" />
            </Button>
          </div>

          {/* Work Experiences */}
          <div className="mb-8">
            <h3 className="text-xs font-bold text-slate-700 block mb-1">
              Work Experiences
            </h3>
            {experience.length === 0 ? (
              <p className="text-xs text-slate-400 mb-3">There is no experience added yet</p>
            ) : (
              <div className="space-y-3 mb-3">
                {experience.map((exp, idx) => (
                  <div
                    key={idx}
                    className="p-3.5 bg-slate-50 rounded-[6px] border border-slate-200/80 flex items-start justify-between gap-3"
                  >
                    <div>
                      <h4 className="font-bold text-xs sm:text-sm text-slate-900">{exp.title}</h4>
                      <p className="text-xs text-slate-500 mt-0.5">
                        {exp.company} • {exp.startDate || "2022"} - {exp.endDate || "Present"}
                      </p>
                      {exp.description && (
                        <p className="text-xs text-slate-600 mt-1 leading-relaxed">{exp.description}</p>
                      )}
                    </div>
                    <Button
                      type="button"
                      variant="ghost"
                      size="icon"
                      radius="fiverr"
                      onClick={() => handleRemoveExperience(idx)}
                      className="text-slate-400 hover:text-rose-500 w-7 h-7 p-1 hover:bg-rose-50"
                    >
                      <FiTrash2 className="text-xs" />
                    </Button>
                  </div>
                ))}
              </div>
            )}

            {/* Add Experience Dashed Box / Inline Form */}
            {isAddingExperience ? (
              <div className="p-4 rounded-[6px] border border-slate-200 bg-slate-50/50 space-y-3">
                <div className="grid grid-cols-1 sm:grid-cols-2 gap-3">
                  <input
                    type="text"
                    value={newExp.title}
                    onChange={(e) => setNewExp({ ...newExp, title: e.target.value })}
                    placeholder="Job Title (e.g. Lead Designer)"
                    className="h-10 px-3.5 bg-[#F0F0F0] border border-[rgba(0,0,0,0.10)] focus:border-gray-300 focus:bg-white rounded-[6px] text-sm text-gray-900 placeholder:text-[#868686] placeholder:font-normal outline-none transition-colors"
                  />
                  <input
                    type="text"
                    value={newExp.company}
                    onChange={(e) => setNewExp({ ...newExp, company: e.target.value })}
                    placeholder="Company Name"
                    className="h-10 px-3.5 bg-[#F0F0F0] border border-[rgba(0,0,0,0.10)] focus:border-gray-300 focus:bg-white rounded-[6px] text-sm text-gray-900 placeholder:text-[#868686] placeholder:font-normal outline-none transition-colors"
                  />
                  <input
                    type="text"
                    value={newExp.startDate}
                    onChange={(e) => setNewExp({ ...newExp, startDate: e.target.value })}
                    placeholder="Start Year (e.g. 2021)"
                    className="h-10 px-3.5 bg-[#F0F0F0] border border-[rgba(0,0,0,0.10)] focus:border-gray-300 focus:bg-white rounded-[6px] text-sm text-gray-900 placeholder:text-[#868686] placeholder:font-normal outline-none transition-colors"
                  />
                  <input
                    type="text"
                    value={newExp.endDate}
                    onChange={(e) => setNewExp({ ...newExp, endDate: e.target.value })}
                    placeholder="End Year or Present"
                    className="h-10 px-3.5 bg-[#F0F0F0] border border-[rgba(0,0,0,0.10)] focus:border-gray-300 focus:bg-white rounded-[6px] text-sm text-gray-900 placeholder:text-[#868686] placeholder:font-normal outline-none transition-colors"
                  />
                </div>
                <textarea
                  rows={2}
                  value={newExp.description}
                  onChange={(e) => setNewExp({ ...newExp, description: e.target.value })}
                  placeholder="Key responsibilities or summary..."
                  className="w-full p-3 bg-[#F0F0F0] border border-[rgba(0,0,0,0.10)] focus:border-gray-300 focus:bg-white rounded-[6px] text-sm text-gray-900 placeholder:text-[#868686] placeholder:font-normal outline-none transition-colors resize-none"
                />
                <div className="flex items-center gap-2">
                  <Button
                    type="button"
                    variant="dark"
                    size="sm"
                    radius="fiverr"
                    onClick={handleAddExperienceItem}
                    className="px-4 py-1.5 font-semibold"
                  >
                    Save Experience
                  </Button>
                  <Button
                    type="button"
                    variant="ghost"
                    size="sm"
                    radius="fiverr"
                    onClick={() => setIsAddingExperience(false)}
                    className="px-3 py-1.5 text-slate-500 hover:text-slate-700"
                  >
                    Cancel
                  </Button>
                </div>
              </div>
            ) : (
              <div
                onClick={() => setIsAddingExperience(true)}
                className="border border-dashed border-slate-200 rounded-[6px] p-5 text-center hover:bg-slate-50/70 hover:border-slate-300 transition-colors cursor-pointer"
              >
                <span className="text-xs font-bold text-[#0D9488] inline-flex items-center gap-1.5">
                  <span>Add Experiences</span>
                  <FiPlus className="text-sm" />
                </span>
              </div>
            )}
          </div>

          {/* Education */}
          <div>
            <h3 className="text-xs font-bold text-slate-700 block mb-1">
              Education
            </h3>
            {education.length === 0 ? (
              <p className="text-xs text-slate-400 mb-3">There is no education added yet</p>
            ) : (
              <div className="space-y-3 mb-3">
                {education.map((ed, idx) => (
                  <div
                    key={idx}
                    className="p-3.5 bg-slate-50 rounded-[6px] border border-slate-200/80 flex items-start justify-between gap-3"
                  >
                    <div>
                      <h4 className="font-bold text-xs sm:text-sm text-slate-900">
                        {ed.degree || ed.title}
                      </h4>
                      <p className="text-xs text-slate-500 mt-0.5">
                        {ed.university} • {ed.year || "Graduated"}
                      </p>
                    </div>
                    <Button
                      type="button"
                      variant="ghost"
                      size="icon"
                      radius="fiverr"
                      onClick={() => handleRemoveEducation(idx)}
                      className="text-slate-400 hover:text-rose-500 w-7 h-7 p-1 hover:bg-rose-50"
                    >
                      <FiTrash2 className="text-xs" />
                    </Button>
                  </div>
                ))}
              </div>
            )}

            {/* Add Education Dashed Box / Inline Form */}
            {isAddingEducation ? (
              <div className="p-4 rounded-[6px] border border-slate-200 bg-slate-50/50 space-y-3">
                <div className="grid grid-cols-1 sm:grid-cols-2 gap-3">
                  <input
                    type="text"
                    value={newEd.degree}
                    onChange={(e) => setNewEd({ ...newEd, degree: e.target.value })}
                    placeholder="Degree / Certificate (e.g. B.Sc in Computer Science)"
                    className="h-10 px-3.5 bg-[#F0F0F0] border border-[rgba(0,0,0,0.10)] focus:border-gray-300 focus:bg-white rounded-[6px] text-sm text-gray-900 placeholder:text-[#868686] placeholder:font-normal outline-none transition-colors"
                  />
                  <input
                    type="text"
                    value={newEd.university}
                    onChange={(e) => setNewEd({ ...newEd, university: e.target.value })}
                    placeholder="University / College"
                    className="h-10 px-3.5 bg-[#F0F0F0] border border-[rgba(0,0,0,0.10)] focus:border-gray-300 focus:bg-white rounded-[6px] text-sm text-gray-900 placeholder:text-[#868686] placeholder:font-normal outline-none transition-colors"
                  />
                  <input
                    type="text"
                    value={newEd.year}
                    onChange={(e) => setNewEd({ ...newEd, year: e.target.value })}
                    placeholder="Graduation Year (e.g. 2020)"
                    className="h-10 px-3.5 bg-[#F0F0F0] border border-[rgba(0,0,0,0.10)] focus:border-gray-300 focus:bg-white rounded-[6px] text-sm text-gray-900 placeholder:text-[#868686] placeholder:font-normal outline-none transition-colors"
                  />
                  <input
                    type="text"
                    value={newEd.country}
                    onChange={(e) => setNewEd({ ...newEd, country: e.target.value })}
                    placeholder="Country"
                    className="h-10 px-3.5 bg-[#F0F0F0] border border-[rgba(0,0,0,0.10)] focus:border-gray-300 focus:bg-white rounded-[6px] text-sm text-gray-900 placeholder:text-[#868686] placeholder:font-normal outline-none transition-colors"
                  />
                </div>
                <div className="flex items-center gap-2">
                  <Button
                    type="button"
                    variant="dark"
                    size="sm"
                    radius="fiverr"
                    onClick={handleAddEducationItem}
                    className="px-4 py-1.5 font-semibold"
                  >
                    Save Education
                  </Button>
                  <Button
                    type="button"
                    variant="ghost"
                    size="sm"
                    radius="fiverr"
                    onClick={() => setIsAddingEducation(false)}
                    className="px-3 py-1.5 text-slate-500 hover:text-slate-700"
                  >
                    Cancel
                  </Button>
                </div>
              </div>
            ) : (
              <div
                onClick={() => setIsAddingEducation(true)}
                className="border border-dashed border-slate-200 rounded-[6px] p-5 text-center hover:bg-slate-50/70 hover:border-slate-300 transition-colors cursor-pointer"
              >
                <span className="text-xs font-bold text-[#0D9488] inline-flex items-center gap-1.5">
                  <span>Add Education</span>
                  <FiPlus className="text-sm" />
                </span>
              </div>
            )}
          </div>
        </div>

        {/* OPTIONAL SELLER-ONLY SECTIONS (Preserving complete seller capabilities) */}
        {isSeller && (
          <>
            {/* SECTION: PORTFOLIO */}
            <div
              id="section-portfolio"
              className="bg-white rounded-[6px] border border-slate-200/90 shadow-[0_1px_3px_rgba(0,0,0,0.02)] p-6 sm:p-7 mb-7 scroll-mt-32 sm:scroll-mt-36"
            >
              <div className="flex items-center justify-between pb-5 border-b border-slate-100 mb-6">
                <div>
                  <h2 className="text-base sm:text-lg font-bold text-slate-900">Portfolio Projects</h2>
                  <p className="text-xs text-slate-500 mt-0.5">Showcase your completed works, case studies, and live links to clients.</p>
                </div>
                {editingProjectIdx === null && (
                  <Button
                    type="button"
                    variant="dark"
                    size="sm"
                    radius="fiverr"
                    onClick={handleAddPortfolio}
                    leftIcon={<FiPlus />}
                    className="font-bold shadow-xs px-3.5 py-1.5"
                  >
                    Add Project
                  </Button>
                )}
              </div>

              {editingProjectIdx !== null ? (
                /* Interactive Project Form Editor */
                <div className="bg-slate-50/70 border border-slate-200/90 rounded-[6px] p-5 sm:p-6 space-y-5">
                  <div className="flex justify-between items-center pb-3 border-b border-slate-200/70">
                    <h3 className="text-sm font-bold text-slate-900">
                      {portfolio[editingProjectIdx]?.title
                        ? `Edit Project: ${portfolio[editingProjectIdx].title}`
                        : "New Portfolio Project"}
                    </h3>
                    <Button
                      type="button"
                      variant="outline"
                      size="sm"
                      radius="fiverr"
                      onClick={() => handleCancelEditProject(editingProjectIdx)}
                      leftIcon={<ArrowLeft size={13} />}
                      className="font-semibold text-slate-600 bg-white hover:bg-slate-100 border border-slate-200 px-3 py-1.5"
                    >
                      Back to Projects
                    </Button>
                  </div>

                  <div className="space-y-4">
                    {/* Project Title */}
                    <div className="flex flex-col gap-1.5">
                      <label className="text-xs sm:text-[13px] font-medium text-gray-700">
                        Project Title <span className="text-red-500">*</span>
                      </label>
                      <input
                        type="text"
                        placeholder="e.g. E-Commerce Web & Mobile App Redesign"
                        value={portfolio[editingProjectIdx]?.title || ""}
                        onChange={(e) => handleUpdatePortfolio(editingProjectIdx, "title", e.target.value)}
                        className="w-full h-10 px-3.5 bg-[#F0F0F0] border border-[rgba(0,0,0,0.10)] focus:border-gray-300 focus:bg-white rounded-[6px] text-sm text-gray-900 placeholder:text-[#868686] placeholder:font-normal outline-none transition-colors"
                      />
                    </div>

                    {/* Description */}
                    <div className="flex flex-col gap-1.5">
                      <label className="text-xs sm:text-[13px] font-medium text-gray-700">Description</label>
                      <textarea
                        placeholder="Describe your role, technologies used, deliverables, and impact..."
                        rows={3}
                        value={portfolio[editingProjectIdx]?.description || ""}
                        onChange={(e) => handleUpdatePortfolio(editingProjectIdx, "description", e.target.value)}
                        className="w-full p-3.5 bg-[#F0F0F0] border border-[rgba(0,0,0,0.10)] focus:border-gray-300 focus:bg-white rounded-[6px] text-sm text-gray-900 placeholder:text-[#868686] placeholder:font-normal outline-none transition-colors resize-none"
                      />
                    </div>

                    {/* Project Cover Image */}
                    <div className="flex flex-col gap-1.5">
                      <label className="text-xs sm:text-[13px] font-medium text-gray-700">
                        Project Cover Image <span className="text-red-500">*</span>
                      </label>
                      <div className="flex flex-col sm:flex-row gap-3 items-start sm:items-center">
                        {portfolio[editingProjectIdx]?.image ? (
                          <div className="relative w-32 h-20 rounded-[6px] overflow-hidden border border-slate-200 group shrink-0 bg-slate-100 shadow-xs">
                            <img
                              src={portfolio[editingProjectIdx].image}
                              alt="Preview"
                              className="w-full h-full object-cover"
                            />
                            <Button
                              type="button"
                              variant="dark"
                              size="xs"
                              radius="none"
                              onClick={() => handleUpdatePortfolio(editingProjectIdx, "image", "")}
                              className="absolute inset-0 w-full h-full bg-black/60 text-white opacity-0 group-hover:opacity-100 flex items-center justify-center font-bold text-xs transition-opacity rounded-none p-0"
                            >
                              Remove
                            </Button>
                          </div>
                        ) : null}

                        <div className="flex-1 w-full">
                          <label className="flex-1 cursor-pointer">
                            <input
                              type="file"
                              accept="image/*"
                              className="hidden"
                              onChange={(e) => handlePortfolioImageUpload(editingProjectIdx, e)}
                              disabled={uploadingPortfolioIdx === editingProjectIdx}
                            />
                            <div className="flex items-center justify-center gap-2 px-4 py-3 bg-white hover:bg-teal-50/60 text-teal-800 border border-teal-200 rounded-[6px] text-xs font-bold transition-colors shadow-2xs">
                              {uploadingPortfolioIdx === editingProjectIdx ? (
                                <>
                                  <Loader size={16} />
                                  <span>Uploading Image...</span>
                                </>
                              ) : (
                                <>
                                  <UploadCloud size={16} />
                                  <span>
                                    {portfolio[editingProjectIdx]?.image
                                      ? "Change Image File"
                                      : "Upload Project Image"}
                                  </span>
                                </>
                              )}
                            </div>
                          </label>
                        </div>
                      </div>
                    </div>

                    {/* Project Live Link */}
                    <div className="flex flex-col gap-1.5">
                      <label className="text-xs sm:text-[13px] font-medium text-gray-700">Project Link (Optional)</label>
                      <input
                        type="url"
                        placeholder="e.g. https://myproject-demo.com or Behance/Dribbble URL"
                        value={portfolio[editingProjectIdx]?.link || ""}
                        onChange={(e) => handleUpdatePortfolio(editingProjectIdx, "link", e.target.value)}
                        className="w-full h-10 px-3.5 bg-[#F0F0F0] border border-[rgba(0,0,0,0.10)] focus:border-gray-300 focus:bg-white rounded-[6px] text-sm text-gray-900 placeholder:text-[#868686] placeholder:font-normal outline-none transition-colors"
                      />
                    </div>

                    {/* Editor Action Buttons */}
                    <div className="pt-2 flex justify-end items-center gap-2.5">
                      <Button
                        type="button"
                        variant="ghost"
                        size="sm"
                        radius="fiverr"
                        onClick={() => handleCancelEditProject(editingProjectIdx)}
                        className="text-slate-600 hover:bg-slate-200/70 font-semibold px-4 py-2"
                      >
                        Cancel
                      </Button>

                      {(() => {
                        const currentProject = editingProjectIdx !== null ? portfolio[editingProjectIdx] : null;
                        const isProjectFormValid = Boolean(
                          currentProject?.title?.trim() && currentProject?.image?.trim()
                        );
                        return (
                          <Button
                            type="button"
                            variant="dark"
                            size="sm"
                            radius="fiverr"
                            disabled={!isProjectFormValid}
                            onClick={() => handleSaveProject(editingProjectIdx)}
                            className="font-bold px-5 py-2 shadow-xs"
                          >
                            Save Project
                          </Button>
                        );
                      })()}
                    </div>
                  </div>
                </div>
              ) : (
                /* Portfolio Projects Cards Grid or Empty State */
                <div>
                  {portfolio.length === 0 ? (
                    <div className="text-center py-12 px-4 border-2 border-dashed border-slate-200 rounded-[6px] bg-slate-50/50 space-y-3">
                      <Folder className="w-10 h-10 text-teal-700/70 mx-auto" />
                      <h4 className="text-sm font-bold text-slate-800">No Portfolio Projects Added Yet</h4>
                      <p className="text-xs text-slate-500 max-w-sm mx-auto">
                        Showcase your best work, case studies, and live project links to attract more clients.
                      </p>
                      <Button
                        type="button"
                        variant="dark"
                        size="sm"
                        radius="fiverr"
                        onClick={handleAddPortfolio}
                        leftIcon={<FiPlus className="text-sm" />}
                        className="font-bold px-4 py-2 shadow-xs"
                      >
                        Add First Project
                      </Button>
                    </div>
                  ) : (
                    <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 gap-5">
                      {portfolio.map((item, idx) => (
                        <div
                          key={idx}
                          className="group relative bg-white border border-slate-200/90 rounded-[6px] overflow-hidden shadow-2xs hover:shadow-md hover:border-teal-500/40 transition-all flex flex-col"
                        >
                          {/* Card Cover Image */}
                          <div className="relative h-44 w-full bg-slate-100 overflow-hidden border-b border-slate-100">
                            {item.image ? (
                              <img
                                src={item.image}
                                alt={item.title || "Project"}
                                className="w-full h-full object-cover group-hover:scale-105 transition-transform duration-300"
                              />
                            ) : (
                              <div className="w-full h-full flex flex-col items-center justify-center bg-teal-50/40 text-teal-700 font-bold text-xs gap-1">
                                <ImageIcon className="w-7 h-7 text-teal-700 mb-0.5" />
                                <span>No Image Uploaded</span>
                              </div>
                            )}

                            {/* Quick Action Badges */}
                            <div className="absolute top-3 right-3 flex items-center gap-1.5">
                              <Button
                                type="button"
                                variant="ghost"
                                size="icon"
                                radius="fiverr"
                                onClick={() => setEditingProjectIdx(idx)}
                                className="w-8 h-8 p-1.5 bg-white/95 hover:bg-white text-slate-700 hover:text-teal-700 shadow-xs backdrop-blur-xs"
                                title="Edit Project"
                              >
                                <FiEdit2 className="text-xs" />
                              </Button>
                              <Button
                                type="button"
                                variant="ghost"
                                size="icon"
                                radius="fiverr"
                                onClick={() => handleRemovePortfolio(idx)}
                                className="w-8 h-8 p-1.5 bg-white/95 hover:bg-white text-slate-700 hover:text-rose-600 shadow-xs backdrop-blur-xs"
                                title="Delete Project"
                              >
                                <FiTrash2 className="text-xs" />
                              </Button>
                            </div>
                          </div>

                          {/* Card Body */}
                          <div className="p-4 flex-1 flex flex-col justify-between">
                            <div>
                              <h4 className="font-bold text-slate-900 text-sm line-clamp-1 mb-1">
                                {item.title || "Untitled Project"}
                              </h4>
                              <p className="text-xs text-slate-500 line-clamp-2 leading-relaxed mb-3">
                                {item.description || "No description provided."}
                              </p>
                            </div>

                            <div className="flex items-center justify-between pt-2.5 border-t border-slate-100 text-xs">
                              {item.link ? (
                                <a
                                  href={item.link}
                                  target="_blank"
                                  rel="noopener noreferrer"
                                  className="inline-flex items-center gap-1 text-teal-700 hover:text-teal-800 font-semibold text-xs"
                                >
                                  <FiExternalLink className="text-xs" />
                                  <span>View Live</span>
                                </a>
                              ) : (
                                <span className="text-slate-400 text-[11px]">No link attached</span>
                              )}

                              <Button
                                type="button"
                                variant="ghost"
                                size="xs"
                                radius="fiverr"
                                onClick={() => setEditingProjectIdx(idx)}
                                className="text-xs font-bold text-slate-600 hover:text-teal-700 p-0 hover:bg-transparent"
                              >
                                Edit Project
                              </Button>
                            </div>
                          </div>
                        </div>
                      ))}
                    </div>
                  )}
                </div>
              )}
            </div>

            {/* SECTION: ID VERIFICATION */}
            <div
              id="section-verification"
              className="bg-white rounded-[6px] border border-slate-200/90 shadow-[0_1px_3px_rgba(0,0,0,0.02)] p-6 sm:p-7 mb-7 scroll-mt-32 sm:scroll-mt-36"
            >
              <div className="pb-5 border-b border-slate-100 mb-6">
                <h2 className="text-base sm:text-lg font-bold text-slate-900">ID Verification</h2>
                <p className="text-xs text-slate-500 mt-0.5">Verify your government identity to earn a verified trust badge.</p>
              </div>
              <KycVerificationForm />
            </div>
          </>
        )}

        {/* BOTTOM ACTION BAR */}
        <div className="flex items-center justify-end gap-3 pt-2">
          <Button
            type="button"
            variant="ghost"
            size="md"
            radius="fiverr"
            onClick={() => router.back()}
            className="text-slate-600 hover:bg-slate-200/60 font-semibold px-5 py-2.5"
          >
            Cancel
          </Button>
          <Button
            type="button"
            variant="dark"
            size="md"
            radius="fiverr"
            disabled={isUpdating}
            isLoading={isUpdating}
            loadingText="Saving..."
            onClick={() => handleSubmit()}
            className="px-6 py-2.5 font-semibold shadow-xs"
          >
            Save Changes
          </Button>
        </div>
      </div>
    </div>
  );
}

