import React, { useState, useEffect } from "react";
import Image from "next/image";
import { Breadcrumb } from "@/components/ui/Breadcrumb/Breadcrumb";

interface CategoryHeroBannerProps {
  title: string;
  categoryName?: string;
  subtitle?: string;
  bannerImage?: string;
  banner?: string;
  onExploreGigs?: () => void;
  gigCount?: number;
  homeHref?: string;
