// Common aliases mapping backend icon identifiers to Lucide icon component names
const ICON_ALIASES: Record<string, string> = {
  bullhorn: 'Megaphone',
  marketing: 'Megaphone',
  advertising: 'Megaphone',
  seo: 'Megaphone',
  'file-text': 'FileText',
  filetext: 'FileText',
