"use client";

import React, { useState } from 'react';
import { axiosFetch } from '@/utils';
import { toast } from '@/utils/toast';
import { Button } from '@/components/ui';
import { Loader } from '@/components';

export interface AIPolishButtonProps {
  text: string;
  onSuccess: (polishedText: string) => void;
  onStateChange?: (isPolishing: boolean) => void;
  tone?: "professional" | "friendly" | "concise" | "formal";
  className?: string;
  tooltip?: string;
}

const PolishIcon = ({ className = "w-5 h-5" }) => (
  <svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 24 24" fill="none" className={className}>
    <path d="M19.5 3.9375V5.5M19.5 5.5V7.0625M19.5 5.5H18.25M19.5 5.5H20.75M22 5.5L20.9156 5.13852C20.4179 4.97263 20.0274 4.58211 19.8615 4.08443L19.5 3L19.1385 4.08443C18.9726 4.58211 18.5821 4.97263 18.0844 5.13852L17 5.5L18.0844 5.86148C18.5821 6.02737 18.9726 6.41789 19.1385 6.91557L19.5 8L19.8615 6.91557C20.0274 6.41789 20.4179 6.02737 20.9156 5.86148L22 5.5Z" stroke="currentColor" strokeWidth="1.5" strokeLinecap="round" strokeLinejoin="round" />
    <path d="M2 12.8598C4.81875 10.0939 11.44 4.44198 13.275 6.40609C15.5938 8.888 3.40937 15.1646 5.28854 17.93C7.2734 20.851 14.2146 10.5543 16.5635 12.3982C18.9125 14.2422 10.926 18.391 12.8052 20.696C13.5569 21.6179 15.6239 20.235 16.5635 19.313" stroke="currentColor" strokeWidth="1.5" strokeLinecap="round" strokeLinejoin="round" />
  </svg>
);

const AIPolishButton = ({
  text,
  onSuccess,
  onStateChange,
  tone = "professional",
  className = "",
  tooltip = "Polish message with AI",
}: AIPolishButtonProps) => {
  const [isPolishing, setIsPolishing] = useState(false);

  const handlePolish = async (e: React.MouseEvent) => {
    e.preventDefault();
    e.stopPropagation();

    if (!text || !text.trim()) {
      toast.error("Please enter some text to polish.");
      return;
    }

    setIsPolishing(true);
    if (onStateChange) onStateChange(true);

    try {
      const res = await axiosFetch.post('/ai/polish', { text, tone });
      if (res.data && !res.data.error) {
        onSuccess(res.data.polishedText);
      }
    } catch (error: any) {
      if (error.response?.status === 429) {
        toast.error("Too many polish requests. Please wait a moment.");
      } else if (error.response?.status === 401) {
        toast.error("Please sign in to use AI Polish.");
      } else {
        toast.error("Couldn't polish message. Your original text has been kept.");
      }
    } finally {
      setIsPolishing(false);
      if (onStateChange) onStateChange(false);
    }
  };

  const isDisabled = !text.trim() || isPolishing;

  return (
    <Button
      type="button"
      variant="ghost"
      size="icon"
      radius="xl"
      className={`p-2 flex-shrink-0 transition-colors ${isDisabled
        ? "text-[var(--Foundation-Grey-grey-900,#1F1F1F)] cursor-not-allowed"
        : "text-brand-green hover:text-brand-green hover:bg-[#FAFAFA]"
        } ${className}`}
      onClick={handlePolish}
      disabled={isDisabled}
      title={tooltip}
      aria-label={tooltip}
      icon={
        isPolishing ? (
          <Loader size={18} />
        ) : (
          <PolishIcon className="w-5 h-5" />
        )
      }
    />
  );
};

export default AIPolishButton;

