                }`}
            >

              <div className={`flex items-center gap-1 text-[13px] font-semibold shrink-0 ml-1.5 ${isSeeMoreSelected ? 'text-emerald-100' : 'text-[#0D6D5F]'}`}>
                <span>See more</span>
                <FiArrowRight className="text-xs" />
              </div>
