"use client";

import React, { forwardRef, ReactNode, HTMLAttributes } from "react";

export type TagVariant =
  | "in_progress"
  | "In_progress"
  | "inprogress"
  | "Inprogress"
  | "in-progress"
  | "in_revision"
  | "In_revision"
  | "in_Revision"
  | "revision"
  | "Revision"
  | "in-revision"
  | "completed"
  | "Completed"
  | "delivered"
  | "Delivered"
  | "cancelled"
  | "Cancelled"
  | "failed"
  | "Failed"
  | "pending"
  | "Pending"
  | "draft"
  | "Draft"
  | "late"
  | "Late"
  | "danger"
  | "Danger"
  | "delivered_late"
  | "Delivered_late"
  | "delivered-late"
  | "disputed"
  | "Disputed"
  | "neutral"
  | "Neutral"
  | string;

export type TagSize = "sm" | "md" | "lg";

export interface TagProps extends HTMLAttributes<HTMLElement> {
  variant?: TagVariant;
  size?: TagSize;
  dot?: boolean;
  leftIcon?: ReactNode;
  rightIcon?: ReactNode;
  children?: ReactNode;
  as?: "span" | "div" | "button";
}

interface VariantDefinition {
  color: string;
  background: string;
  defaultLabel: string;
  dotColor: string;
}

const VARIANT_CONFIGS: Record<string, VariantDefinition> = {
  in_revision: {
    color: "var(--purple-700, #4600A9)",
    background: "var(--purple-50, #EFE6FD)",
    defaultLabel: "Revision",
    dotColor: "#4600A9",
  },
  revision: {
    color: "var(--purple-700, #4600A9)",
    background: "var(--purple-50, #EFE6FD)",
    defaultLabel: "Revision",
    dotColor: "#4600A9",
  },
  in_progress: {
    color: "var(--blue-600, #021B75)",
    background: "var(--blue-50, #E6E9F2)",
    defaultLabel: "Inprogress",
    dotColor: "#021B75",
  },
  inprogress: {
    color: "var(--blue-600, #021B75)",
    background: "var(--blue-50, #E6E9F2)",
    defaultLabel: "Inprogress",
    dotColor: "#021B75",
  },
  delivered: {
    color: "var(--teal-900, #265F58)",
    background: "var(--teal-100, #CCF6F1)",
    defaultLabel: "Delivered",
    dotColor: "#265F58",
  },
  pending: {
    color: "var(--alert-900, #674C00)",
    background: "#FFFFFF",
    defaultLabel: "Pending",
    dotColor: "#674C00",
  },
  completed: {
    color: "var(--teal-900, #265F58)",
    background: "var(--teal-100, #CCF6F1)",
    defaultLabel: "Completed",
    dotColor: "#265F58",
  },
  cancelled: {
    color: "#991B1B",
    background: "#FEF2F2",
    defaultLabel: "Cancelled",
    dotColor: "#991B1B",
  },
  failed: {
    color: "#991B1B",
    background: "#FEF2F2",
    defaultLabel: "Failed",
    dotColor: "#991B1B",
  },
  late: {
    color: "#DC2626",
    background: "#FEE2E2",
    defaultLabel: "Late",
    dotColor: "#DC2626",
  },
  danger: {
    color: "#DC2626",
    background: "#FEE2E2",
    defaultLabel: "Late",
    dotColor: "#DC2626",
  },
  delivered_late: {
    color: "#D97706",
    background: "#FEF3C7",
    defaultLabel: "Delivered late",
    dotColor: "#D97706",
  },
  draft: {
    color: "#475569",
    background: "#F1F5F9",
    defaultLabel: "Draft",
    dotColor: "#475569",
  },
  neutral: {
    color: "#475569",
    background: "#F1F5F9",
    defaultLabel: "Neutral",
    dotColor: "#475569",
  },
  disputed: {
    color: "#B45309",
    background: "#FEF3C7",
    defaultLabel: "Disputed",
    dotColor: "#B45309",
  },
};

const SIZE_STYLES: Record<TagSize, { className: string; fontSize?: string }> = {
  sm: {
    className: "text-[12px] px-3 py-1 gap-1.5",
    fontSize: "12px",
  },
  md: {
    className: "text-[13px] px-4 py-1.5 gap-2",
    fontSize: "16px",
  },
  lg: {
    className: "text-[14px] px-5 py-2 gap-2.5",
    fontSize: "18px",
  },
};

export const Tag = forwardRef<HTMLElement, TagProps>(
  (
    {
      variant = "inprogress",
      size = "md",
      dot = false,
      leftIcon,
      rightIcon,
      children,
      as = "span",
      className = "",
      style,
      ...props
    },
    ref
  ) => {
    // Normalize variant key (case-insensitive, convert dashes and spaces to underscores)
    const normalizedKey = String(variant || "")
      .trim()
      .toLowerCase()
      .replace(/[-\s]/g, "_");

    const config =
      VARIANT_CONFIGS[normalizedKey] ||
      VARIANT_CONFIGS[normalizedKey.replace(/^in_/, "")] ||
      VARIANT_CONFIGS[`in_${normalizedKey}`] ||
      VARIANT_CONFIGS[normalizedKey.replace(/_/g, "")] ||
      VARIANT_CONFIGS.in_progress;

    const sizeConfig = SIZE_STYLES[size] || SIZE_STYLES.md;
    const Component = as as any;

    const baseStyle: React.CSSProperties = {
      fontFamily: '"SF Pro", var(--font-sf-pro), -apple-system, BlinkMacSystemFont, sans-serif',
      fontStyle: "normal",
      fontWeight: 510,
      lineHeight: "normal",
      borderRadius: "60px",
      border: "1px solid rgba(0, 0, 0, 0.10)",
      color: config.color,
      background: config.background,
      fontSize: sizeConfig.fontSize,
      ...style,
    };

    const content = children !== undefined ? children : config.defaultLabel;

    return (
      <Component
        ref={ref}
        style={baseStyle}
        className={`inline-flex items-center justify-center whitespace-nowrap select-none transition-colors ${sizeConfig.className} ${className}`}
        {...props}
      >
        {dot && (
          <span
            className="w-1.5 h-1.5 rounded-full shrink-0"
            style={{ backgroundColor: config.dotColor }}
            aria-hidden="true"
          />
        )}
        {leftIcon && <span className="inline-flex shrink-0">{leftIcon}</span>}
        <span>{content}</span>
        {rightIcon && <span className="inline-flex shrink-0">{rightIcon}</span>}
      </Component>
    );
  }
);

Tag.displayName = "Tag";

export default Tag;

export interface SubcategoryItem {
  id: string;
  title: string;
  banner: string;
  subtitle?: string;
  resultCount?: string;
  items: string[];
}

export interface CategoryTaxonomy {
  slug: string;
  name: string;
  heroTitle: string;
  heroSubtitle: string;
  defaultBanner?: string;
  subcategories: SubcategoryItem[];
}

// Empty dictionary - all category taxonomy data is dynamically derived from backend API
export const CATEGORY_TAXONOMIES: Record<string, CategoryTaxonomy> = {};

const isValidUrl = (url: unknown): boolean => {
  if (typeof url !== "string") return false;
  const t = url.trim();
  return t.startsWith("http://") || t.startsWith("https://") || t.startsWith("/");
};

export const getFallbackSubcategoryBanner = (slugOrName: string = ""): string => {
  const s = slugOrName.toLowerCase();
  if (s.includes("artist") || s.includes("design") || s.includes("art") || s.includes("image")) {
    return "https://images.unsplash.com/photo-1509198397868-475647b2a1e5?auto=format&fit=crop&w=800&q=85";
  }
  if (s.includes("bot") || s.includes("chat") || s.includes("agent")) {
    return "https://images.unsplash.com/photo-1618005182384-a83a8bd57fbe?auto=format&fit=crop&w=800&q=85";
  }
  if (s.includes("workflow") || s.includes("automation") || s.includes("n8n") || s.includes("zapier")) {
    return "https://images.unsplash.com/photo-1634017839464-5c339ebe3cb4?auto=format&fit=crop&w=800&q=85";
  }
  if (s.includes("data") || s.includes("learning") || s.includes("science") || s.includes("analytics")) {
    return "https://images.unsplash.com/photo-1579783900882-c0d3dad7b119?auto=format&fit=crop&w=800&q=85";
  }
  if (s.includes("consult") || s.includes("business") || s.includes("strategy")) {
    return "https://images.unsplash.com/photo-1518770660439-4636190af475?auto=format&fit=crop&w=800&q=85";
  }
  if (s.includes("code") || s.includes("tech") || s.includes("dev") || s.includes("software")) {
    return "https://images.unsplash.com/photo-1555066931-4365d14bab8c?auto=format&fit=crop&w=800&q=85";
  }
  return "https://images.unsplash.com/photo-1550684848-fac1c5b4e853?auto=format&fit=crop&w=800&q=85";
};

/**
 * Dynamically constructs CategoryTaxonomy strictly from live API category data.
 */
export const getCategoryTaxonomy = (slug: string, apiCategories?: any[]): CategoryTaxonomy | null => {
  if (!slug) return null;

  const normalizedSlug = slug.toLowerCase().trim().replace(/&/g, "and").replace(/\s+/g, "-").replace(/[^a-z0-9-]/g, "");

  // Find matching live API category
  const apiCategory = apiCategories?.find((cat: any) => {
    const catSlug = (cat?.slug || cat?.name || "")
      .toLowerCase()
      .trim()
      .replace(/&/g, "and")
      .replace(/\s+/g, "-")
      .replace(/[^a-z0-9-]/g, "");
    const rawCatSlug = (cat?.slug || "").toLowerCase().trim();
    return (
      catSlug === normalizedSlug ||
      rawCatSlug === normalizedSlug ||
      cat?.id === slug ||
      cat?._id === slug
    );
  });

  const categoryName =
    apiCategory?.name ||
    apiCategory?.title ||
    slug
      .split("-")
      .map((s) => s.charAt(0).toUpperCase() + s.slice(1))
      .join(" ");

  // Extract 1st-level children (subcategories) directly from live backend category
  const rawApiChildren =
    Array.isArray(apiCategory?.children) && apiCategory.children.length > 0
      ? apiCategory.children
      : Array.isArray(apiCategory?.subcategories) && apiCategory.subcategories.length > 0
      ? apiCategory.subcategories
      : Array.isArray(apiCategories)
      ? apiCategories.filter(
          (c: any) =>
            c.parentId &&
            (c.parentId === apiCategory?.id ||
              c.parentId === apiCategory?._id ||
              c.parentName?.toLowerCase() === apiCategory?.name?.toLowerCase())
        )
      : [];

  // Map 1st-level children to subcategory cards and 2nd-level children strictly to items
  const subcategories: SubcategoryItem[] = rawApiChildren.map((child: any) => {
    const childTitle = child.name || child.title || String(child);
    const childSlug =
      child.slug ||
      childTitle
        .toLowerCase()
        .trim()
        .replace(/&/g, "and")
        .replace(/\s+/g, "-")
        .replace(/[^a-z0-9-]/g, "");

    // 2nd children of each 1st child directly from backend
    let secondChildren: any[] = [];
    if (Array.isArray(child.children) && child.children.length > 0) {
      secondChildren = child.children;
    } else if (Array.isArray(child.subcategories) && child.subcategories.length > 0) {
      secondChildren = child.subcategories;
    } else if (Array.isArray(apiCategories)) {
      secondChildren = apiCategories.filter(
        (c: any) => c.parentId && (c.parentId === child.id || c.parentId === child._id)
      );
    }

    const items: string[] = secondChildren.map((c: any) => c.name || c.title || String(c));

    const banner = isValidUrl(child.banner)
      ? child.banner
      : getFallbackSubcategoryBanner(childSlug || childTitle);

    return {
      id: childSlug,
      title: childTitle,
      subtitle: child.description || undefined,
      resultCount: child.gigCount ? `${child.gigCount}+ Results` : undefined,
      banner,
      items,
    };
  });

  return {
    slug: normalizedSlug,
    name: categoryName,
    heroTitle: categoryName,
    heroSubtitle:
      apiCategory?.description || `Discover top quality ${categoryName} services from verified experts`,
    defaultBanner: isValidUrl(apiCategory?.banner) ? apiCategory.banner : undefined,
    subcategories,
  };
};

