"use client";

import { useState, useEffect } from "react";
import { axiosFetch } from "@/utils";
import { toast } from "@/utils/toast";
import { Button } from "@/components/ui";
import { useAuthModalStore } from "@/store/authModalStore";

interface FavoriteButtonProps {
  gigId: string;
  initialIsFavorited?: boolean;
  initialFavoriteCount?: number;
  currentUser: any;
  className?: string;
  iconClassName?: string;
  showCount?: boolean;
  onToggle?: (isFavorited: boolean) => void;
}

const FavoriteButton = ({
  gigId,
  initialIsFavorited = false,
  initialFavoriteCount = 0,
  currentUser,
  className = "",
  iconClassName = "",
  showCount = false,
  onToggle
}: FavoriteButtonProps) => {
  const [isFavorited, setIsFavorited] = useState(initialIsFavorited);
  const [favoriteCount, setFavoriteCount] = useState(initialFavoriteCount);
  const [loading, setLoading] = useState(false);
  const openAuthModal = useAuthModalStore((state) => state.openAuthModal);

  // Sync state if prop changes from outside (e.g. fresh API data)
  useEffect(() => {
    setIsFavorited(initialIsFavorited);
  }, [initialIsFavorited]);

  const handleToggleFavorite = async (e: React.MouseEvent) => {
    e.preventDefault();
    e.stopPropagation();

    if (!currentUser?._id) {
      openAuthModal({
        mode: "login",
      });
      return;
    }

    // Optimistic UI update
    const previousState = isFavorited;
    const previousCount = favoriteCount;

    setIsFavorited(!previousState);
    if (onToggle) onToggle(!previousState);
    setFavoriteCount((prev) => (previousState ? Math.max(0, prev - 1) : prev + 1));
    setLoading(true);

    try {
      const res = await axiosFetch.post(`/gigs/${gigId}/favorite`);
      if (!res.data.error) {
        setIsFavorited(res.data.isFavorited);
        if (onToggle) onToggle(res.data.isFavorited);
        setFavoriteCount(res.data.favoriteCount);
        if (res.data.message) {
          toast.success(res.data.message);
        }
      }
    } catch (err: any) {
      // Revert optimistic update on failure
      setIsFavorited(previousState);
      if (onToggle) onToggle(previousState);
      setFavoriteCount(previousCount);
      toast.error(err.response?.data?.message || "Failed to update favorite status.");
    } finally {
      setLoading(false);
    }
  };

  return (
    <Button
      type="button"
      variant="ghost"
      size="sm"
      radius="full"
      onClick={handleToggleFavorite}
      disabled={loading}
      className={`!p-0 !min-h-0 !h-auto flex items-center justify-center transition-colors outline-none cursor-pointer ${className} ${isFavorited ? "text-red-500" : "text-gray-500 hover:text-red-500"
        }`}
      title={isFavorited ? "Remove from Favorites" : "Add to Favorites"}
    >
      <svg
        xmlns="http://www.w3.org/2000/svg"
        viewBox="0 0 24 24"
        fill={isFavorited ? "currentColor" : "none"}
        stroke="currentColor"
        strokeWidth="2"
        strokeLinecap="round"
        strokeLinejoin="round"
        className={`transition-colors ${iconClassName || 'w-full h-full'}`}
      >
        <path d="M20.84 4.61a5.5 5.5 0 0 0-7.78 0L12 5.67l-1.06-1.06a5.5 5.5 0 0 0-7.78 7.78l1.06 1.06L12 21.23l7.78-7.78 1.06-1.06a5.5 5.5 0 0 0 0-7.78z" />
      </svg>
      {showCount && favoriteCount !== undefined && (
        <span className="text-[13.5px] font-semibold text-gray-700 ml-1.5 whitespace-nowrap">{favoriteCount}</span>
      )}
    </Button>
  );
};

export default FavoriteButton;

"use client";

import React, { useState, useEffect } from "react";
import { useUserStore } from "@/store/userStore";
import { axiosFetch } from "@/utils";
import { toast } from "@/utils/toast";
import { Button } from "@/components/ui";

interface FavoriteSellerButtonProps {
  sellerId: string;
  className?: string;
  showText?: boolean;
}

export const FavoriteSellerButton: React.FC<FavoriteSellerButtonProps> = ({
  sellerId,
  className = "",
  showText = false,
}) => {
  const { user } = useUserStore((state: any) => state);
  const [isFavorited, setIsFavorited] = useState(false);
  const [loading, setLoading] = useState(false);

  useEffect(() => {
    if (!user || user.isSeller || !sellerId) return;

    let isMounted = true;
    axiosFetch
      .get(`/users/favorite-seller/${sellerId}/status`)
      .then(({ data }) => {
        if (isMounted && !data.error) {
          setIsFavorited(!!data.isFavorited);
        }
      })
      .catch(() => {});

    return () => {
      isMounted = false;
    };
  }, [user, sellerId]);

  // Only display to authenticated buyers
  if (!user || user.isSeller || !sellerId) {
    return null;
  }

  // Prevent buyers from favoriting themselves if sellerId matches
  const currentUid = String(user._id || user.id || "");
  if (currentUid === String(sellerId)) {
    return null;
  }

  const handleToggleFavorite = async (e: React.MouseEvent) => {
    e.stopPropagation();
    e.preventDefault();

    if (loading) return;

    const previousState = isFavorited;
    setIsFavorited(!previousState);
    setLoading(true);

    try {
      const { data } = await axiosFetch.post(`/users/favorite-seller/${sellerId}`);
      if (data.error) {
        setIsFavorited(previousState);
        toast.error(data.message || "Failed to update favorite status");
      } else {
        const nextState = !!data.isFavorited;
        setIsFavorited(nextState);
        toast.success(
          nextState ? "Added to Favorite Sellers!" : "Removed from Favorite Sellers."
        );
      }
    } catch (err: any) {
      setIsFavorited(previousState);
      toast.error(err?.response?.data?.message || "Failed to update favorite seller");
    } finally {
      setLoading(false);
    }
  };

  return (
    <Button
      type="button"
      variant={isFavorited ? "danger-soft" : "outline"}
      size={showText ? "sm" : "icon"}
      radius="full"
      onClick={handleToggleFavorite}
      disabled={loading}
      className={`transition-all duration-200 cursor-pointer shadow-xs ${
        isFavorited
          ? "!bg-red-50 !text-red-500 hover:!bg-red-100 !border-red-200"
          : "!bg-white/90 hover:!bg-gray-100 !text-gray-400 hover:!text-red-500 !border-gray-200"
      } ${className}`}
      title={isFavorited ? "Remove from Favorite Sellers" : "Add to Favorite Sellers"}
      aria-label="Favorite Seller"
    >
      <svg
        className={`w-5 h-5 transition-transform duration-200 ${
          isFavorited ? "fill-red-500 stroke-red-500 scale-110" : "fill-none stroke-current"
        }`}
        viewBox="0 0 24 24"
        strokeWidth="2"
        strokeLinecap="round"
        strokeLinejoin="round"
      >
        <path d="M20.84 4.61a5.5 5.5 0 0 0-7.78 0L12 5.67l-1.06-1.06a5.5 5.5 0 0 0-7.78 7.78l1.06 1.06L12 21.23l7.78-7.78 1.06-1.06a5.5 5.5 0 0 0 0-7.78z" />
