                  onClick={() => {
                    setIsMsgSearchActive(false);
                    setMsgSearchQuery("");
                  }}
                  aria-label="Close search"
                  icon={<span>&times;</span>}
                />
              </div>
            ) : (
              <Button
                type="button"
                variant="ghost"
                size="icon"
                radius="lg"
                className="w-8 h-8 sm:w-9 sm:h-9 rounded-[6px] sm:rounded-[6px] hover:bg-slate-100 text-slate-600 shrink-0"
