  activeConversation,
  conversationID,
  isRecipientOnline,
  contactOrders,
  isOrdersExpanded,
  setIsOrdersExpanded,
  onOpenOfferModal,
  onOpenMeetingModal,
  onCloseRightSide,
  onNavigateToProfile,
