"use client";

import React, { useState, useMemo } from "react";
import { toast } from "@/utils/toast";
import { RiCloseLine } from "react-icons/ri";
import { Button, Skeleton } from "@/components";
import { formatFileSize } from "@/lib";
import { formatFileNameWithExtension, isImageFile } from "../../utils/chatMediaHelpers";
import { MediaFileItem } from "../../types";
import { ContactProfileTab } from "./ContactProfileTab";
import { ContactMediaTab } from "./ContactMediaTab";

interface ContactSidebarProps {
  isValidId: boolean;
  isRightSideOpen: boolean;
  onCloseRightSide: () => void;
  finalRecipientUser: any;
  isFetchingTargetUser: boolean;
  activeConversation: any;
  conversationID: string;
  isRecipientOnline: boolean;
  contactOrders: any[];
  messages: any[];
  user: any;
  onOpenOfferModal: () => void;
  onOpenMeetingModal: () => void;
  onNavigateToProfile: (id: string) => void;
  onNavigateToOrder: (id?: string) => void;
  onNavigateToAllOrders: () => void;
  onImagePreview: (url: string) => void;
}

export const ContactSidebar: React.FC<ContactSidebarProps> = ({
  isValidId,
  isRightSideOpen,
  onCloseRightSide,
  finalRecipientUser,
  isFetchingTargetUser,
  activeConversation,
  conversationID,
  isRecipientOnline,
  contactOrders,
  messages,
  user,
  onOpenOfferModal,
  onOpenMeetingModal,
  onNavigateToProfile,
  onNavigateToOrder,
  onNavigateToAllOrders,
  onImagePreview,
}) => {
  const [contactSidebarTab, setContactSidebarTab] = useState<"profile" | "media">("profile");
  const [isOrdersExpanded, setIsOrdersExpanded] = useState(true);

  const conversationMediaFiles = useMemo<MediaFileItem[]>(() => {
    const seenUrls = new Set<string>();
    return (messages || []).flatMap((m: any) => {
      const items: MediaFileItem[] = [];
      const parseItem = (item: any) => {
        if (!item) return;
        if (typeof item === "string" && item.trim().length > 0) {
          if (seenUrls.has(item)) return;
          seenUrls.add(item);

          const rawName =
            m.attachment?.name ||
            m.fileName ||
            m.name ||
            m.originalName ||
            item.split("/").pop()?.split("?")[0] ||
            "Attachment";
          const fileName = formatFileNameWithExtension(rawName, item, null, m);
          const rawSize = m.fileSize || m.size || m.bytes || m.attachment?.size;
          items.push({
            name: fileName,
            sizeText: formatFileSize(rawSize),
            url: item,
          });
        } else if (typeof item === "object" && (item.url || item.file || item.secure_url)) {
          const url = item.url || item.file || item.secure_url;
          if (typeof url === "string" && url.trim().length > 0) {
            if (seenUrls.has(url)) return;
            seenUrls.add(url);

            const rawName =
              item.name ||
              item.fileName ||
              item.original_filename ||
              m.attachment?.name ||
              m.fileName ||
              m.name ||
              url.split("/").pop()?.split("?")[0] ||
              "Attachment";
            const fileName = formatFileNameWithExtension(rawName, url, item, m);
            const rawSize =
              item.sizeText || item.size || item.bytes || m.fileSize || m.size || m.attachment?.size;
            items.push({
              name: fileName,
              sizeText: formatFileSize(rawSize),
              url,
            });
          }
        }
      };
      if (m.file) parseItem(m.file);
      if (m.attachment && m.attachment.url && m.attachment.url !== m.file) parseItem(m.attachment);
      if (Array.isArray(m.attachments)) m.attachments.forEach(parseItem);
      return items;
    });
  }, [messages]);

  const handlePreviewMedia = (file: MediaFileItem) => {
    if (!file.url || file.url === "#") {
      toast.error("File URL is not available");
      return;
    }
    if (isImageFile(file)) {
      onImagePreview(file.url);
    } else {
      window.open(file.url, "_blank", "noopener,noreferrer");
    }
  };

  const handleDownloadMedia = async (file: MediaFileItem) => {
    if (file.url && file.url !== "#") {
      try {
        const res = await fetch(file.url);
        if (res.ok) {
          const blob = await res.blob();
          const blobUrl = window.URL.createObjectURL(blob);
          const link = document.createElement("a");
          link.href = blobUrl;
          link.download = file.name;
          document.body.appendChild(link);
          link.click();
          document.body.removeChild(link);
          window.URL.revokeObjectURL(blobUrl);
          return;
        }
      } catch {
        // Fallback to direct anchor if fetch blocked by CORS
      }
      const link = document.createElement("a");
      link.href = file.url;
      link.download = file.name;
      link.target = "_blank";
      link.rel = "noopener noreferrer";
      document.body.appendChild(link);
      link.click();
      document.body.removeChild(link);
    } else {
      toast.success(`Downloading ${file.name}`);
    }
  };

  if (!isValidId) return null;

  if (!finalRecipientUser && isFetchingTargetUser) {
    return (
      <aside
        className={`w-[320px] min-w-[280px] xl:w-[340px] xl:min-w-[320px] h-full max-h-full min-h-0 border-l border-[rgba(0, 0, 0, 0.10)] bg-[#F8F8F8] overflow-y-auto overflow-x-hidden p-4 xl:p-5 flex flex-col shrink-0 box-border max-xl:fixed max-xl:top-0 max-xl:bottom-0 max-xl:right-0 max-xl:z-50 max-xl:shadow-2xl max-xl:h-full max-xl:flex max-xl:transform max-xl:transition-transform max-xl:duration-300 max-xl:ease-in-out max-sm:w-[85vw] max-sm:max-w-[340px] ${
          isRightSideOpen ? "max-xl:translate-x-0" : "max-xl:translate-x-full"
        }`}
      >
        <div className="flex flex-col gap-4">
          <Skeleton className="w-full h-44 rounded-[6px]" />
          <Skeleton className="w-full h-36 rounded-[6px]" />
        </div>
      </aside>
    );
  }

  if (!finalRecipientUser) return null;

  return (
    <>
      <div
        className={`xl:hidden fixed inset-0 bg-slate-900/40 backdrop-blur-xs z-40 transition-opacity duration-300 ease-in-out ${
          isRightSideOpen ? "opacity-100 pointer-events-auto" : "opacity-0 pointer-events-none"
        }`}
        onClick={onCloseRightSide}
      />

      <aside
        className={`w-[320px] min-w-[280px] xl:w-[340px] xl:min-w-[320px] h-full max-h-full min-h-0 border-l border-[rgba(0, 0, 0, 0.10)] bg-[#F8F8F8] overflow-y-auto overflow-x-hidden p-4 xl:p-5 flex flex-col shrink-0 box-border [&::-webkit-scrollbar]:w-1.5 [&::-webkit-scrollbar-thumb]:bg-slate-300 [&::-webkit-scrollbar-thumb]:rounded-full max-xl:fixed max-xl:top-0 max-xl:bottom-0 max-xl:right-0 max-xl:z-50 max-xl:shadow-2xl max-xl:h-full max-xl:flex max-xl:transform max-xl:transition-transform max-xl:duration-300 max-xl:ease-in-out max-sm:w-[85vw] max-sm:max-w-[340px] ${
          isRightSideOpen ? "max-xl:translate-x-0" : "max-xl:translate-x-full"
        }`}
      >
        <div className="w-full flex flex-col gap-4 pb-20">
          {/* Mobile Drawer Top Bar */}
          <div className="xl:hidden flex items-center justify-between pb-3 border-b border-slate-200/80 -mt-1">
            <span className="font-bold text-slate-900 text-base">Contact Details</span>
            <Button
              type="button"
              variant="ghost"
              size="icon"
              radius="full"
              className="w-8 h-8 rounded-full text-slate-500 hover:text-slate-800 hover:bg-slate-200/60"
              onClick={onCloseRightSide}
              aria-label="Close sidebar"
              icon={<RiCloseLine className="w-5 h-5" />}
            />
          </div>

          {/* Top Segmented Controls: Profile | Media (Sticky header shield) */}
          <div className="sticky -top-4 xl:-top-5 -mt-4 xl:-mt-5 pt-4 xl:pt-5 pb-2 bg-[#F8F8F8] z-10">
            <div className="bg-[#f0f2f5] p-1 rounded-[6px] flex items-center border border-slate-200/70 shadow-xs">
              <Button
                type="button"
                variant={contactSidebarTab === "profile" ? "dark" : "ghost"}
                size="sm"
                radius="xl"
                onClick={() => setContactSidebarTab("profile")}
                className={`flex-1 py-2 text-sm font-semibold text-center ${
                  contactSidebarTab === "profile"
                    ? "!bg-[#0e3834] !text-white shadow-xs"
                    : "text-slate-600 hover:text-slate-900"
                }`}
              >
                Profile
              </Button>
              <Button
                type="button"
                variant={contactSidebarTab === "media" ? "dark" : "ghost"}
                size="sm"
                radius="xl"
                onClick={() => setContactSidebarTab("media")}
                className={`flex-1 py-2 text-sm font-semibold text-center ${
                  contactSidebarTab === "media"
                    ? "!bg-[#0e3834] !text-white shadow-xs"
                    : "text-slate-600 hover:text-slate-900"
                }`}
              >
                Media
              </Button>
            </div>
          </div>

          {contactSidebarTab === "profile" ? (
            <ContactProfileTab
              user={user}
              finalRecipientUser={finalRecipientUser}
              activeConversation={activeConversation}
              conversationID={conversationID}
              isRecipientOnline={isRecipientOnline}
              contactOrders={contactOrders}
              isOrdersExpanded={isOrdersExpanded}
              setIsOrdersExpanded={setIsOrdersExpanded}
              onOpenOfferModal={onOpenOfferModal}
              onOpenMeetingModal={onOpenMeetingModal}
              onCloseRightSide={onCloseRightSide}
              onNavigateToProfile={onNavigateToProfile}
              onNavigateToOrder={onNavigateToOrder}
              onNavigateToAllOrders={onNavigateToAllOrders}
            />
          ) : (
            <ContactMediaTab
              conversationMediaFiles={conversationMediaFiles}
              onPreviewMedia={handlePreviewMedia}
              onDownloadMedia={handleDownloadMedia}
            />
          )}
        </div>
      </aside>
    </>
  );
};

"use client";

import React from "react";
import moment from "moment";
import { getOtherUser, isConversationUnread, isTargetConversation } from "@/utils/chatHelpers";
import { getAvatarUrl } from "@/utils";
import { ConversationTagBadge } from "@/features/chat/ConversationTags";

interface ConversationItemProps {
  conv: any;
  user: any;
  activeConversationID: string;
  onSelect: (canonicalId: string) => void;
}

export const ConversationItem: React.FC<ConversationItemProps> = ({
  conv,
  user,
  activeConversationID,
  onSelect,
}) => {
  const isUnread = isConversationUnread(conv, user);
  const contact = getOtherUser(conv, user);
  const contactName =
    contact?.username ||
    contact?.name ||
    (user?.isSeller ? conv.buyer_username : conv.seller_username) ||
    "User";
  const avatarSrc = getAvatarUrl(
    contact?.image || contact?.img || contact?.avatar || "/media/noavatar.png"
  );
  const lastMsg = conv.lastMessage?.startsWith("[CUSTOM_OFFER]")
    ? "📋 Custom Offer"
    : conv.lastMessage?.startsWith("[MEETING_INVITE]")
    ? "📹 Video Meeting Invitation"
    : conv.lastMessage || "No messages yet";
  const canonicalId = conv.uuid || conv.conversationID || conv._id || conv.id;
  const isActive = isTargetConversation(conv, activeConversationID);
  const timeText = conv.updatedAt ? moment(conv.updatedAt).format("h:mm A") : "";
  const unreadCountBadge = conv.unreadCount || (isUnread ? 1 : 0);

  return (
    <div
      className={`flex items-center gap-3 p-2.5 sm:p-3 rounded-[6px] cursor-pointer transition-all duration-150 ${
        isActive ? "bg-white" : "hover:bg-slate-50"
      }`}
      onClick={() => onSelect(canonicalId)}
    >
      <img
        src={avatarSrc}
        alt={contactName}
        className="w-11 h-11 rounded-full object-cover shrink-0 border border-slate-100 shadow-2xs"
      />
      <div className="flex-1 min-w-0">
        <div className="flex items-center justify-between gap-1 mb-0.5">
          <div className="flex items-center gap-1.5 min-w-0">
            <span className="font-semibold text-slate-900 text-sm truncate leading-tight">
              {contactName}
            </span>
            {unreadCountBadge > 0 && (
              <span className="w-4 h-4 bg-red-600 text-white text-[10px] font-bold rounded-full flex items-center justify-center shrink-0 leading-none">
                {unreadCountBadge}
              </span>
            )}
          </div>
          <span className="text-[11px] text-slate-400 font-normal shrink-0">
            {timeText}
          </span>
        </div>
        <p className="text-xs text-slate-500 truncate leading-snug">{lastMsg}</p>
        {/* Private Tags Badges on Conversation Card */}
        {Array.isArray(conv.tags) && conv.tags.length > 0 && (
          <div className="flex items-center gap-1 mt-1 overflow-hidden flex-wrap">
            {conv.tags.slice(0, 2).map((t: string) => (
              <ConversationTagBadge key={t} tag={t} size="xs" />
            ))}
            {conv.tags.length > 2 && (
              <span className="text-[10px] text-slate-400 font-medium leading-none">
                +{conv.tags.length - 2}
              </span>
            )}
          </div>
        )}
      </div>
    </div>
  );
};

"use client";

import React from "react";
import { Home } from "lucide-react";
import { Button, Loader } from "@/components";
import { ConversationFilters } from "./ConversationFilters";
import { ConversationItem } from "./ConversationItem";

interface ConversationListProps {
  isLeftSideOpen: boolean;
  onCloseLeftSide: () => void;
  user: any;
  onNavigateDashboard: () => void;
  convSearchQuery: string;
  setConvSearchQuery: (query: string) => void;
  convFilterTab: "all" | "read" | "unread";
  setConvFilterTab: (tab: "all" | "read" | "unread") => void;
  selectedTagFilter: string | null;
  setSelectedTagFilter: (tag: string | null) => void;
  allAvailableTags: string[];
  isTagFilterMenuOpen: boolean;
  setIsTagFilterMenuOpen: (open: boolean) => void;
  convsLoading: boolean;
  displayedConversations: any[];
  conversationID: string;
  onSelectConversation: (id: string) => void;
}

export const ConversationList: React.FC<ConversationListProps> = ({
  isLeftSideOpen,
  onCloseLeftSide,
  user,
  onNavigateDashboard,
  convSearchQuery,
  setConvSearchQuery,
  convFilterTab,
  setConvFilterTab,
  selectedTagFilter,
  setSelectedTagFilter,
  allAvailableTags,
  isTagFilterMenuOpen,
  setIsTagFilterMenuOpen,
  convsLoading,
  displayedConversations,
  conversationID,
  onSelectConversation,
}) => {
  return (
    <>
      <div
        className={`md:hidden fixed inset-0 bg-black/20 z-30 transition-opacity duration-300 ease-in-out ${
          isLeftSideOpen ? "opacity-100 pointer-events-auto" : "opacity-0 pointer-events-none"
        }`}
        onClick={onCloseLeftSide}
      />

      <aside
        className={`w-[300px] min-w-[280px] md:w-[320px] lg:w-[340px] xl:w-[350px] border-r border-[rgba(0,0,0,0.10)] flex flex-col bg-[var(--Foundation-White-white-200,#F8F8F8)] overflow-hidden box-border transform transition-transform duration-300 ease-in-out max-md:absolute max-md:z-40 max-md:w-[320px] max-md:h-full max-md:shadow-xl max-md:flex ${
          isLeftSideOpen ? "max-md:translate-x-0" : "max-md:-translate-x-full"
        }`}
      >
        {/* Header: Back Button + Messages Heading */}
        <div className="p-4 sm:p-5 pb-3 flex flex-col gap-3.5 border-b border-slate-100">
          <div className="flex items-center gap-3 justify-between">
            <h2 className="text-[24px] sm:text-[26px] md:text-[28px] lg:text-[30px] macbook:text-[32px] 2xl:text-[36px] font-normal leading-tight tracking-tight text-[#292929] font-sf-pro">
              Messages
            </h2>
            <Button
              type="button"
              variant="outline"
              size="icon"
              radius="full"
              onClick={onNavigateDashboard}
              className="w-9 h-9 min-h-[36px] !p-0 border !border-[rgba(0,0,0,0.10)] text-[#126D6B] bg-white hover:bg-slate-50 shrink-0"
              aria-label="Back to Dashboard"
              title="Back to Dashboard"
              icon={<Home className="w-4 h-4 text-brand-green" />}
            />
          </div>

          <ConversationFilters
            convSearchQuery={convSearchQuery}
            setConvSearchQuery={setConvSearchQuery}
            convFilterTab={convFilterTab}
            setConvFilterTab={setConvFilterTab}
            selectedTagFilter={selectedTagFilter}
            setSelectedTagFilter={setSelectedTagFilter}
            allAvailableTags={allAvailableTags}
            isTagFilterMenuOpen={isTagFilterMenuOpen}
            setIsTagFilterMenuOpen={setIsTagFilterMenuOpen}
          />
        </div>

        {/* Conversation Items List */}
        <div className="flex-1 overflow-y-auto px-2 py-2 flex flex-col gap-0.5">
          {convsLoading ? (
            <div className="list-loader py-10 flex justify-center">
              <Loader size={28} />
            </div>
          ) : displayedConversations.length === 0 ? (
            <div className="py-12 text-center text-xs text-slate-400">
              {convSearchQuery ? "No conversations found" : "No conversations yet"}
            </div>
          ) : (
            displayedConversations.map((conv: any) => (
              <ConversationItem
                key={conv._id || conv.uuid || conv.conversationID || conv.id}
                conv={conv}
                user={user}
                activeConversationID={conversationID}
                onSelect={(id) => {
                  onSelectConversation(id);
                  onCloseLeftSide();
                }}
              />
            ))
          )}
        </div>
      </aside>
    </>
  );
};

