// Helper to reliably extract file extension from URL, item metadata, or MIME type
export const extractFileExtension = (url: string, itemObj?: any, msgObj?: any): string => {
  if (!url && !itemObj && !msgObj) return '';

  // 1. Check if format or extension is explicitly specified in itemObj or msgObj
  const explicitFormat =
    itemObj?.format ||
    itemObj?.ext ||
    itemObj?.extension ||
    msgObj?.format ||
    msgObj?.fileFormat ||
    msgObj?.attachment?.format;
  if (explicitFormat && typeof explicitFormat === 'string') {
    return explicitFormat.replace(/^\./, '').toLowerCase();
  }

  const rawUrl = String(url || itemObj?.url || itemObj?.secure_url || itemObj?.file || '');

  // 2. Check query params or Cloudinary URL transformations for format (e.g. format=pdf, format=png, f_pdf, f_png)
  const formatQueryMatch = rawUrl.match(/[?&]format=([a-zA-Z0-9]+)/i);
  if (formatQueryMatch) {
    return formatQueryMatch[1].toLowerCase();
  }

  const cldFormatMatch = rawUrl.match(/\/f_([a-zA-Z0-9]+)[\/,]/i);
  if (cldFormatMatch && cldFormatMatch[1].toLowerCase() !== 'auto') {
    return cldFormatMatch[1].toLowerCase();
  }

  // 3. Check if PDF is indicated anywhere in the URL (path, filename, or query)
  if (
    /\.pdf($|[?#])/i.test(rawUrl) ||
    /format=pdf/i.test(rawUrl) ||
    rawUrl.toLowerCase().includes('.pdf') ||
    rawUrl.toLowerCase().includes('format=pdf')
  ) {
    return 'pdf';
  }

  // 4. Check url path for standard file extension (before query string)
  const cleanUrl = rawUrl.split('?')[0].split('#')[0];
  const urlExtMatch = cleanUrl.match(/\.([a-zA-Z0-9]{2,6})$/);
  if (urlExtMatch) {
    return urlExtMatch[1].toLowerCase();
  }

  // 5. Check MIME types
  const mime = (
    itemObj?.type ||
    itemObj?.mimeType ||
    msgObj?.fileType ||
    msgObj?.attachment?.type ||
    ''
  ).toLowerCase();
  if (mime.includes('pdf')) return 'pdf';
  if (mime.includes('image/png')) return 'png';
  if (mime.includes('image/jpeg') || mime.includes('image/jpg')) return 'jpg';
  if (mime.includes('image/webp')) return 'webp';
  if (mime.includes('image/gif')) return 'gif';
  if (mime.includes('image/svg')) return 'svg';
  if (mime.includes('application/zip') || mime.includes('zip')) return 'zip';
  if (mime.includes('text/csv') || mime.includes('csv')) return 'csv';
  if (mime.includes('text/plain')) return 'txt';
  if (mime.includes('word') || mime.includes('docx')) return 'docx';
  if (mime.includes('sheet') || mime.includes('xlsx')) return 'xlsx';

  // 6. Check common video extensions
  if (/\.(mp4|webm|ogg|mov|mkv|avi|m4v)($|[?#])/i.test(rawUrl) || rawUrl.includes('/video/')) {
    return 'mp4';
  }

  // 7. Check if Cloudinary raw file
  if (cleanUrl.includes('cloudinary.com') && cleanUrl.includes('/raw/')) {
    return '';
  }

  // 8. If Cloudinary image upload and not pdf/doc/video, fallback to image format (jpg/png)
  if (
    cleanUrl.includes('cloudinary.com') &&
    cleanUrl.includes('/image/') &&
    !rawUrl.toLowerCase().includes('pdf') &&
    !rawUrl.toLowerCase().includes('format=')
  ) {
    return 'png';
  }

  return '';
};

// Formats file name to ensure it ALWAYS has its proper extension
export const formatFileNameWithExtension = (name: string, url: string, itemObj?: any, msgObj?: any): string => {
  let trimmed = (name || '').trim();

  // Try extracting filename from URL query params (e.g. ?filename=my_doc.pdf or ?name=photo.jpg)
  if (!trimmed || trimmed === 'Attachment' || trimmed === 'download' || trimmed === 'download.png') {
    const rawUrl = String(url || itemObj?.url || '');
    const qNameMatch = rawUrl.match(/[?&](?:filename|original_filename|name|file|title)=([^&#]+)/i);
    if (qNameMatch) {
      try {
        const decoded = decodeURIComponent(qNameMatch[1]).trim();
        if (decoded) trimmed = decoded;
      } catch {
        // ignore decoding error
      }
    }
  }

  if (!trimmed) {
    trimmed = 'Attachment';
  }

  const ext = extractFileExtension(url, itemObj, msgObj);

  // If the name already ends with the correct extension (case insensitive)
  if (ext && new RegExp(`\\.${ext}$`, 'i').test(trimmed)) {
    return trimmed;
  }

  // If name has a different extension (e.g. name was "download.png", but format is "pdf"!)
  if (ext && /\.[a-zA-Z0-9]{2,6}$/.test(trimmed)) {
    const currentExtMatch = trimmed.match(/\.([a-zA-Z0-9]{2,6})$/);
    const currentExt = currentExtMatch ? currentExtMatch[1].toLowerCase() : '';
    if (currentExt !== ext) {
      return trimmed.replace(/\.[a-zA-Z0-9]{2,6}$/, `.${ext}`);
    }
    return trimmed;
  }

  if (/\.[a-zA-Z0-9]{2,6}$/.test(trimmed)) {
    return trimmed;
  }

  return ext ? `${trimmed}.${ext}` : trimmed;
};

// Parse JSON payload from custom offer string or object
export const parseOffer = (desc?: any) => {
  if (!desc) return null;
  if (typeof desc === 'object' && (desc.price !== undefined || desc.packageID || desc.delivery)) {
    return desc;
  }
  if (typeof desc !== 'string') return null;
  const str = desc.trim();
  if (str.includes('[CUSTOM_OFFER]')) {
    try {
      const jsonPart = str.substring(str.indexOf('[CUSTOM_OFFER]') + '[CUSTOM_OFFER]'.length).trim();
      return JSON.parse(jsonPart);
    } catch (err) {
      console.error("Failed to parse custom offer json:", err);
      return null;
    }
  }
  return null;
};

// Parse JSON payload from video meeting invite string or object
export const parseMeeting = (desc?: any) => {
  if (!desc) return null;
  if (typeof desc === 'object' && (desc.roomUrl || desc.meetingId || desc.joinUrl)) {
    return desc;
  }
  if (typeof desc !== 'string') return null;
  const str = desc.trim();
  if (str.includes('[MEETING_INVITE]')) {
    try {
      const jsonPart = str.substring(str.indexOf('[MEETING_INVITE]') + '[MEETING_INVITE]'.length).trim();
      return JSON.parse(jsonPart);
    } catch (err) {
      console.error("Failed to parse meeting invite json:", err);
      return null;
    }
  }
  return null;
};

// Check if a file is an image
export const isImageFile = (file: { name: string; url: string }): boolean => {
  const url = (file.url || '').toLowerCase();
  const name = (file.name || '').toLowerCase();

  // Check if PDF (never treat as image!)
  const isPdf =
    url.includes('format=pdf') ||
    url.includes('.pdf') ||
    name.endsWith('.pdf') ||
    /\.pdf($|[?#])/i.test(url);
  if (isPdf) return false;

  const isDoc =
    /\.(docx?|xlsx?|pptx?|txt|csv|zip|rar|tar|gz)($|[?#])/i.test(url) ||
    /\.(docx?|xlsx?|pptx?|txt|csv|zip|rar|tar|gz)$/i.test(name) ||
    /[?&]format=(docx?|xlsx?|pptx?|zip|rar|tar|gz|txt|csv)/i.test(url);
  if (isDoc) return false;

  const isVideo =
    /\.(mp4|webm|ogg|mov|mkv|avi|m4v|3gp)($|[?#])/i.test(url) ||
    /\.(mp4|webm|ogg|mov|mkv|avi|m4v|3gp)$/i.test(name) ||
    /[?&]format=(mp4|webm|ogg|mov)/i.test(url);
  if (isVideo) return false;

  return Boolean(
    /\.(png|jpe?g|gif|webp|svg|bmp|avif)($|[?#])/i.test(url) ||
    /\.(png|jpe?g|gif|webp|svg|bmp|avif)$/i.test(name) ||
    /[?&]format=(png|jpe?g|gif|webp|svg|bmp|avif)/i.test(url) ||
    (url.includes('cloudinary.com') && url.includes('/image/upload/') && !url.includes('pdf'))
  );
};

// Check if a file is a PDF
export const isPdfFile = (file: { name?: string; url?: string }): boolean => {
  const url = (file?.url || '').toLowerCase();
  const name = (file?.name || '').toLowerCase();
  return (
    url.includes('format=pdf') ||
    url.includes('.pdf') ||
    name.endsWith('.pdf') ||
    /\.pdf($|[?#])/i.test(url)
  );
};

"use client";

import React, { useState, useRef, useEffect } from "react";
import { FiTag, FiPlus, FiX, FiLock, FiCheck } from "react-icons/fi";
import { toast } from "@/utils/toast";
import { useQueryClient } from "@tanstack/react-query";
import { PRESET_TAGS, sanitizeTags, updateConversationTagsApi } from "@/utils/chatHelpers";
import { ConversationTagBadge } from "./ConversationTagBadge";
import { Button } from "@/components/ui";

interface ConversationTagsManagerProps {
  conversationId: string;
  tags?: string[];
  mode?: "popover" | "card";
  isOpen?: boolean;
  onClose?: () => void;
  onTagsUpdated?: (tags: string[]) => void;
}

export const ConversationTagsManager: React.FC<ConversationTagsManagerProps> = ({
  conversationId,
  tags = [],
  mode = "card",
  isOpen = false,
  onClose,
  onTagsUpdated,
}) => {
  const queryClient = useQueryClient();
  const [currentTags, setCurrentTags] = useState<string[]>(tags || []);
  const [inputValue, setInputValue] = useState("");
  const [isSaving, setIsSaving] = useState(false);
  const desktopContainerRef = useRef<HTMLDivElement>(null);
  const mobileContainerRef = useRef<HTMLDivElement>(null);
  const inputRef = useRef<HTMLInputElement>(null);

  // Sync internal state with external tags prop
  useEffect(() => {
    setCurrentTags(tags || []);
  }, [tags]);

  // Click outside to close if mode is popover
  useEffect(() => {
    if (mode !== "popover" || !isOpen) return;

    const handleOutsideClick = (e: MouseEvent) => {
      const target = e.target as Node;
      const clickedInsideDesktop = desktopContainerRef.current?.contains(target);
      const clickedInsideMobile = mobileContainerRef.current?.contains(target);
      if (!clickedInsideDesktop && !clickedInsideMobile) {
        onClose?.();
      }
    };

    document.addEventListener("mousedown", handleOutsideClick);
    return () => document.removeEventListener("mousedown", handleOutsideClick);
  }, [mode, isOpen, onClose]);

  // Focus input when opened as popover (desktop only to prevent mobile viewport zoom)
  useEffect(() => {
    if (mode === "popover" && isOpen) {
      if (typeof window !== "undefined" && window.innerWidth >= 640) {
        setTimeout(() => inputRef.current?.focus(), 50);
      }
    }
  }, [mode, isOpen]);

  const saveTags = async (nextTags: string[]) => {
    const sanitized = sanitizeTags(nextTags);
    const prevTags = currentTags;
    setCurrentTags(sanitized);

    // Optimistically update conversation cache in React Query
    queryClient.setQueryData(["conversations"], (oldData: any) => {
      if (!Array.isArray(oldData)) return oldData;
      return oldData.map((c: any) => {
        const cId = String(c.uuid || c.conversationID || c._id || c.id || "");
        if (cId === String(conversationId) || c._id === String(conversationId)) {
          return { ...c, tags: sanitized };
        }
        return c;
      });
    });

    queryClient.setQueryData(["conversation-detail", conversationId], (oldData: any) => {
      if (!oldData || typeof oldData !== "object") return oldData;
      return { ...oldData, tags: sanitized };
    });

    onTagsUpdated?.(sanitized);

    setIsSaving(true);
    try {
      await updateConversationTagsApi(conversationId, sanitized);
      queryClient.invalidateQueries({ queryKey: ["conversations"] });
    } catch (err: any) {
      setCurrentTags(prevTags);
      onTagsUpdated?.(prevTags);
      toast.error(err?.response?.data?.message || "Failed to update tags");
    } finally {
      setIsSaving(false);
    }
  };

  const handleAddTag = (tagToAdd: string) => {
    const trimmed = tagToAdd.trim();
    if (!trimmed) return;

    if (trimmed.length > 50) {
      toast.error("Tag must not exceed 50 characters");
      return;
    }

    const lowerKey = trimmed.toLowerCase();
    if (currentTags.some((t) => t.toLowerCase() === lowerKey)) {
      toast.error("This tag has already been added");
      setInputValue("");
      return;
    }

    if (currentTags.length >= 20) {
      toast.error("Maximum 20 tags per conversation");
      return;
    }

    const nextTags = [...currentTags, trimmed];
    setInputValue("");
    saveTags(nextTags);
  };

  const handleRemoveTag = (tagToRemove: string) => {
    const nextTags = currentTags.filter((t) => t.toLowerCase() !== tagToRemove.toLowerCase());
    saveTags(nextTags);
  };

  const handleKeyDown = (e: React.KeyboardEvent<HTMLInputElement>) => {
    if (e.key === "Enter") {
      e.preventDefault();
      handleAddTag(inputValue);
    } else if (e.key === "Escape" && mode === "popover") {
      onClose?.();
    }
  };

  const content = (
    <div className="flex flex-col gap-3">
      {/* Header & Lock notice */}
      <div className="flex items-center justify-between gap-2">
        <div className="flex items-center gap-1.5 text-xs font-semibold text-slate-800">
          <FiTag className="w-3.5 h-3.5 text-slate-600" />
          <span>Private Tags</span>
          <span className="text-[10px] text-slate-400 font-normal">
            ({currentTags.length}/20)
          </span>
        </div>
        <div
          className="flex items-center gap-1 text-[11px] text-slate-500 bg-slate-100 px-2 py-0.5 rounded-full"
          title="Only you can see these tags. The other party cannot see or edit them."
        >
          <FiLock className="w-2.5 h-2.5 text-slate-400" />
          <span className="font-normal text-[10px]">Private to you</span>
        </div>
      </div>

      {/* Existing tags list */}
      <div className="flex flex-wrap items-center gap-1.5 min-h-[26px]">
        {currentTags.length === 0 ? (
          <span className="text-xs text-slate-400 italic">No tags assigned yet</span>
        ) : (
          currentTags.map((t) => (
            <ConversationTagBadge
              key={t}
              tag={t}
              size={mode === "popover" ? "xs" : "sm"}
              onRemove={isSaving ? undefined : handleRemoveTag}
            />
          ))
        )}
      </div>

      {/* Input row */}
      <div className="flex items-center gap-1.5">
        <input
          ref={inputRef}
          type="text"
          value={inputValue}
          maxLength={50}
          placeholder="New tag label..."
          onChange={(e) => setInputValue(e.target.value)}
          onKeyDown={handleKeyDown}
          disabled={isSaving || currentTags.length >= 20}
          className="flex-1 h-[32px] min-h-[32px] max-h-[32px] box-border bg-white border border-slate-200 focus:border-slate-400 focus:ring-1 focus:ring-slate-400 rounded-[6px] px-2.5 text-xs text-slate-800 placeholder:text-slate-400 outline-none transition-colors"
        />
        <Button
          type="button"
          variant="dark"
          size="xs"
          radius="md"
          onClick={() => handleAddTag(inputValue)}
          disabled={!inputValue.trim() || isSaving || currentTags.length >= 20}
          isLoading={isSaving}
          className="!h-[32px] !min-h-[32px] !max-h-[32px] box-border px-3 !text-xs font-semibold shrink-0 !py-0 flex items-center justify-center leading-none"
        >
          Add
        </Button>
      </div>

      {/* Quick Preset Tags */}
      <div className="flex flex-col gap-1.5 pt-1 border-t border-slate-100">
        <span className="text-[11px] text-slate-500 font-medium">Quick suggestions:</span>
        <div className="flex flex-wrap gap-1">
          {PRESET_TAGS.map((preset) => {
            const isAssigned = currentTags.some((t) => t.toLowerCase() === preset.toLowerCase());
            return (
              <button
                key={preset}
                type="button"
                onClick={() => {
                  if (isAssigned) {
                    handleRemoveTag(preset);
                  } else {
                    handleAddTag(preset);
                  }
                }}
                disabled={isSaving}
                className={`text-[11px] px-2 py-0.5 rounded-full border border-[rgba(0,0,0,0.10)] bg-white transition-all flex items-center gap-1 ${isAssigned
                    ? "!border-[rgba(0,0,0,0.25)] text-slate-900 font-semibold shadow-2xs"
                    : "text-slate-600 hover:text-slate-900 hover:border-slate-300"
                  }`}
              >
                {isAssigned && <FiCheck className="w-2.5 h-2.5 text-slate-800" />}
                <span>{preset}</span>
              </button>
            );
          })}
        </div>
      </div>
    </div>
  );

  if (mode === "popover") {
    return (
      <>
        {/* Mobile Backdrop (<640px) */}
        <div
          className={`sm:hidden fixed inset-0 bg-black/40 z-50 transition-opacity duration-300 ease-in-out ${
            isOpen ? "opacity-100 pointer-events-auto" : "opacity-0 pointer-events-none"
          }`}
          onClick={onClose}
        />

        {/* Mobile Right-Side Drawer (<640px) */}
        <div
          ref={mobileContainerRef}
          onClick={(e) => e.stopPropagation()}
          className={`sm:hidden fixed top-0 bottom-0 right-0 z-50 w-[85vw] max-w-[340px] h-full bg-white shadow-2xl p-5 overflow-y-auto flex flex-col gap-3 transform transition-transform duration-300 ease-in-out ${
            isOpen ? "translate-x-0" : "translate-x-full pointer-events-none"
          }`}
        >
          <div className="flex items-center justify-between pb-2 border-b border-slate-100">
            <span className="text-sm font-bold text-slate-800">Organize Conversation</span>
            <button
              type="button"
              onClick={onClose}
              className="text-slate-400 hover:text-slate-600 p-1 rounded-full"
              aria-label="Close"
            >
              <FiX className="w-5 h-5" />
            </button>
          </div>
          {content}
        </div>

        {/* Desktop Anchored Popover (>=640px) */}
        {isOpen && (
          <div
            ref={desktopContainerRef}
            className="hidden sm:block absolute top-full right-0 mt-2 w-[320px] bg-white border border-slate-200 rounded-[8px] p-4 shadow-xl z-50 animate-in fade-in zoom-in-95 duration-150"
          >
            <div className="flex items-center justify-between pb-2 mb-2 border-b border-slate-100">
              <span className="text-xs font-bold text-slate-800">Organize Conversation</span>
              <button
                type="button"
                onClick={onClose}
                className="text-slate-400 hover:text-slate-600 p-0.5 rounded-full"
                aria-label="Close"
              >
                <FiX className="w-3.5 h-3.5" />
              </button>
            </div>
            {content}
          </div>
        )}
      </>
    );
  }

  // Card mode (for right sidebar)
  return (
    <div
      ref={desktopContainerRef}
      className="bg-white rounded-[6px] p-4 border border-slate-200/80 shadow-xs flex flex-col gap-2"
    >
      {content}
    </div>
  );
};

