            href="/manage-orders"
            className="text-xs sm:text-sm font-semibold text-[#113E37] hover:underline flex items-center gap-1.5 whitespace-nowrap cursor-pointer"
          >
            Manage all orders <FiArrowRight className="text-xs" />
