"use client";

import Link from "next/link";
import Image from "next/image";
import { useRouter } from "next/navigation";
import React from "react";
import { useUserStore } from "@/store/userStore";
import { FavoriteButton } from "@/components";

const FALLBACK_COVER =
  "https://images.unsplash.com/photo-1498050108023-c5249f4df085?auto=format&fit=crop&w=1000&q=85";

const isValidUrl = (url?: unknown): boolean => {
  if (!url || typeof url !== "string") return false;
  const trimmed = url.trim();
  if (!trimmed || trimmed === '""' || trimmed === "''" || trimmed === "null" || trimmed === "undefined") {
    return false;
  }
  return trimmed.startsWith("http://") || trimmed.startsWith("https://") || trimmed.startsWith("/");
};

const resolveCoverImage = (data: any): string => {
  const candidate =
    data?.cover ||
    data?.img ||
    data?.image ||
    (Array.isArray(data?.images) && data?.images[0]);

  if (isValidUrl(candidate)) {
    return (candidate as string).trim();
  }
  return FALLBACK_COVER;
};

const PackageCard = ({ data, priority = false }: { data: any; priority?: boolean }) => {
  const router = useRouter();
  const { user } = useUserStore((state: any) => state);

  const [imgSrc, setImgSrc] = React.useState<string>(() => resolveCoverImage(data));
  const [isFavorited, setIsFavorited] = React.useState<boolean>(!!data?.isFavorited);

  React.useEffect(() => {
    setImgSrc(resolveCoverImage(data));
  }, [data?.cover, data?.img, data?.image, data?.images]);

  React.useEffect(() => {
    setIsFavorited(!!data?.isFavorited);
  }, [data?.isFavorited]);

  if (!data) return null;

  const userObj = data.user || data.userId || data.userID || {};
  const userImg = userObj.image || data.pp || "/media/noavatar.png";
  const username = userObj.username || data.username || "Seller";

  const handleImageError = () => {
    if (imgSrc !== FALLBACK_COVER) {
      setImgSrc(FALLBACK_COVER);
    }
  };

  // Rating calculation: prioritize gigRating directly from backend
  const rawRating =
    typeof data.gigRating === "number"
      ? data.gigRating
      : typeof data.starRating === "number"
      ? data.starRating
      : data.starNumber > 0 && typeof data.totalStars === "number"
      ? data.totalStars / data.starNumber
      : data.star || data.rating || 0;

  const rating = Number(rawRating || 0).toFixed(1);
  const sales = data.sales || 0;
  const reviewCount = data.starNumber || data.reviews || (data.sales ? data.sales : 0);
  const hasMetricsReset = Boolean(userObj.metricsResetAt || data.user?.metricsResetAt || data.metricsResetAt);
  const level = hasMetricsReset
    ? "Level 1"
    : userObj.sellerLevel || data.user?.sellerLevel || userObj.level || "Level 1";

  // Price formatting
  const formattedPrice =
    typeof data.price === "number"
      ? `$${data.price}`
      : data.price
        ? String(data.price).startsWith("$")
          ? data.price
          : `$${data.price}`
        : "$150";

  // Slug or fallback ID for details URL
  const packageUrl = `/package/${data.slug || data._id || data.id}`;

  const handleProfileClick = (e: React.MouseEvent) => {
    e.preventDefault();
    e.stopPropagation();
    router.push(`/seller/${username}`);
  };

  return (
    <Link
      href={packageUrl}
      className="group flex flex-col w-full h-full bg-white rounded-[6px] border border-[#DADADA] p-[10px] shadow-none hover:shadow-[0_8px_24px_rgba(0,0,0,0.08)] transition-shadow duration-300"
    >
      {/* Top Image + Overlapping Avatar */}
      <div className="relative w-full aspect-[405/220] shrink-0">
        {/* Thumbnail */}
        <div className="absolute inset-0 rounded-[6px] overflow-hidden bg-gray-100">
          <Image
            src={imgSrc}
            alt={data.title || data.desc || "Package Cover"}
            fill
            sizes="(max-width: 640px) 100vw, (max-width: 1024px) 50vw, (max-width: 1280px) 33vw, 405px"
            priority={priority}
            unoptimized
            className="w-full h-full object-cover group-hover:scale-[1.03] transition-transform duration-500 ease-out"
            onError={handleImageError}
          />

          {/* Favorite Button */}
          <div
            className={`absolute top-2.5 right-2.5 z-10 transition-opacity duration-200 ${isFavorited
              ? "opacity-100"
              : "opacity-0 group-hover:opacity-100"
              }`}
            onClick={(e) => {
              e.preventDefault();
              e.stopPropagation();
            }}
          >
            <div className="w-7 h-7 sm:w-8 sm:h-8 rounded-full bg-white/90 backdrop-blur-sm shadow-sm flex items-center justify-center hover:bg-white transition-all cursor-pointer">
              <FavoriteButton
                gigId={data._id || data.id}
                initialIsFavorited={isFavorited}
                initialFavoriteCount={data.favoriteCount}
                currentUser={user}
                className="w-full h-full flex items-center justify-center"
                iconClassName="w-3.5 h-3.5 sm:w-4 sm:h-4"
                onToggle={(newVal) => setIsFavorited(newVal)}
              />
            </div>
          </div>
        </div>

        {/* Circular Avatar Overlapping Bottom Edge */}
        <div
          onClick={handleProfileClick}
          className="absolute -bottom-6 left-3 z-10 cursor-pointer"
          title={username}
        >
          <div className="relative w-[48px] h-[48px] aspect-square rounded-full overflow-hidden border-2 border-white shadow-sm bg-gray-100 hover:opacity-95 transition-opacity">
            <Image
              src={userImg}
              alt={username}
              fill
              className="object-cover"
              unoptimized
            />
          </div>
        </div>
      </div>

      {/* Card Content Body */}
      <div className="flex flex-col flex-1 justify-between pt-7 px-1">
        <div>
          {/* Row 1: Seller Name + Rating */}
          <div className="flex items-center justify-between gap-2">
            <span
              onClick={handleProfileClick}
              className="font-sf-pro font-[590] text-black text-[13px] not-italic hover:underline cursor-pointer truncate max-w-[65%]"
            >
              {username}
            </span>

            <div className="flex items-center gap-1 text-[13.5px] shrink-0">
              <span className="text-gray-500 font-normal">
                ({sales})
              </span>

              <span className="text-gray-900 font-bold ml-0.5">
                {rating}
              </span>

              <svg
                className="w-3.5 h-3.5 text-[#F4AA1C] fill-[#F4AA1C] ml-0.5 -mt-0.5"
                viewBox="0 0 20 20"
                xmlns="http://www.w3.org/2000/svg"
              >
                <path d="M9.049 2.927c.3-.921 1.603-.921 1.902 0l1.07 3.292a1 1 0 00.95.69h3.462c.969 0 1.371 1.24.588 1.81l-2.8 2.034a1 1 0 00-.364 1.118l1.07 3.292c.3.921-.755 1.688-1.54 1.118l-2.8-2.034a1 1 0 00-1.175 0l-2.8 2.034c-.784.57-1.838-.197-1.539-1.118l1.07-3.292a1 1 0 00-.364-1.118L2.98 8.72c-.783-.57-.38-1.81.588-1.81h3.461a1 1 0 00.951-.69l1.07-3.292z" />
              </svg>
            </div>
          </div>

          {/* Row 2: Title / Description */}
          <h3 className="mt-3 text-[14px] leading-[22px] text-[rgba(24,24,27,1)] font-[500] font-inter not-italic line-clamp-2 h-[44px] max-h-[44px] overflow-hidden group-hover:text-gray-900 transition-colors">
            {data.title}
          </h3>
        </div>

        {/* Row 3: Starting from Price */}
        <div className="flex items-baseline gap-2 mt-auto pt-3 pb-0.5">
          <span className="text-[14px] text-[#222325] font-normal font-inter leading-[20px] sm:leading-[22px] not-italic">
            Starting from
          </span>

          <span className="text-[18px] font-semibold font-inter text-[#222325] leading-[22px] not-italic">
            {formattedPrice}
          </span>
        </div>
      </div>
    </Link>
  );
};

export default PackageCard;

