                    >
                      Select Basic
                    </Button>
                  )}
                </div>
                <div className="p-3 sm:p-4 xl:p-5 border-r border-gray-200">
                  {standardPkg && (
                    <Button
                      type="button"
                      onClick={() => {
                        onSelectTier('standard');
                        window.scrollTo({ top: 0, behavior: 'smooth' });
                      }}
                      variant="brand"
                      size="md"
                      radius="fiverr"
                      fullWidth
                    >
                      Select Standard
                    </Button>
                  )}
                </div>
                <div className="p-3 sm:p-4 xl:p-5">
                  {premiumPkg && (
                    <Button
                      type="button"
                      onClick={() => {
                        onSelectTier('premium');
                        window.scrollTo({ top: 0, behavior: 'smooth' });
                      }}
                      variant="dark"
                      size="md"
                      radius="fiverr"
                      fullWidth
                    >
                      Select Premium
                    </Button>
                  )}
                </div>
              </div>
            </div>
          </div>
        )}
      </div>
    </div>
  );
};

