"use client";

import React, { useState, useRef, useEffect } from "react";
import { FiMaximize2, FiX } from "react-icons/fi";
import { Button } from "@/components/ui";

interface PackageGalleryProps {
  mainBanner?: string;
  thumbnails?: string[];
  title: string;
}

export const PackageGallery: React.FC<PackageGalleryProps> = ({
  mainBanner,
  thumbnails = [],
  title,
}) => {
  // Collect all real unique images
  const allImages = Array.from(
    new Set([mainBanner, ...thumbnails].filter((img): img is string => Boolean(img && img.trim())))
  );

  const heroImage = allImages[0] || "";
  const [activeImage, setActiveImage] = useState(heroImage);
  const [activeThumbIndex, setActiveThumbIndex] = useState<number>(0);
  const [isLightboxOpen, setIsLightboxOpen] = useState(false);
  const containerRef = useRef<HTMLDivElement>(null);
  const [itemHeight, setItemHeight] = useState<number | null>(null);

  useEffect(() => {
    if (heroImage && (!activeImage || !allImages.includes(activeImage))) {
      setActiveImage(heroImage);
      setActiveThumbIndex(0);
    }
  }, [heroImage]);

  const hasThumbnails = allImages.length > 1;
  const hasMoreThan5 = allImages.length > 5;

  useEffect(() => {
    if (!hasMoreThan5) {
      setItemHeight(null);
      return;
    }

    const calcHeight = () => {
      if (containerRef.current) {
        const ch = containerRef.current.clientHeight;
        if (ch > 0) {
          const h = (ch - 32) / 4.5;
          setItemHeight(h);
        }
      }
    };

    calcHeight();
    window.addEventListener("resize", calcHeight);
    return () => window.removeEventListener("resize", calcHeight);
  }, [hasMoreThan5, allImages.length]);

  const handleSelectThumb = (img: string, idx: number, e?: React.MouseEvent<HTMLButtonElement>) => {
    setActiveImage(img);
    setActiveThumbIndex(idx);
    if (e?.currentTarget) {
      e.currentTarget.scrollIntoView({ behavior: "smooth", block: "nearest" });
    }
  };

  if (allImages.length === 0) {
    return (
      <div className="w-full h-[280px] sm:h-[340px] rounded-[6px] bg-gray-100 border border-gray-200 flex flex-col items-center justify-center text-gray-400 mb-8 p-6 text-center">
        <span className="text-sm font-semibold">{title}</span>
        <span className="text-xs text-gray-400 mt-1">No cover image uploaded</span>
      </div>
    );
  }

  return (
    <div className="w-full mb-8">
      {/* Side-by-side Gallery when multiple images, or full-width hero when 1 image */}
      <div className="flex gap-2.5 sm:gap-3 h-[320px] sm:h-[380px] md:h-[420px]">
        {/* Main Hero Image */}
        <div
          onClick={() => setIsLightboxOpen(true)}
          className="flex-1 h-full rounded-[6px] overflow-hidden bg-gray-950 border border-gray-100 relative group cursor-pointer shadow-xs"
        >
          <img
            src={activeImage || heroImage}
            alt={title}
            className="w-full h-full object-cover transition-transform duration-500 group-hover:scale-[1.01]"
          />

          {/* Expand Icon on Hover */}
          <div className="absolute top-3.5 right-3.5 w-8 h-8 rounded-full bg-black/60 hover:bg-black/80 text-white flex items-center justify-center opacity-0 group-hover:opacity-100 transition-opacity backdrop-blur-xs shadow-sm">
            <FiMaximize2 className="w-4 h-4" />
          </div>
        </div>

        {/* Stacked Thumbnails (only shown if seller uploaded multiple images) */}
        {hasThumbnails && (
          <div
            ref={containerRef}
            className={`w-[80px] sm:w-[95px] md:w-[105px] flex flex-col gap-2 h-full shrink-0 ${hasMoreThan5
              ? "overflow-y-auto scroll-smooth scrollbar-none [scrollbar-width:none] [-ms-overflow-style:none] [&::-webkit-scrollbar]:hidden overscroll-y-contain"
              : "justify-start"
              }`}
          >
            {allImages.map((img, idx) => {
              const isSelected = activeImage === img;

              return (
                <Button
                  key={idx}
                  type="button"
                  variant="ghost"
                  size="xs"
                  radius="lg"
                  onClick={(e) => handleSelectThumb(img, idx, e)}
                  style={
                    hasMoreThan5
                      ? {
                        height: itemHeight ? `${itemHeight}px` : "calc((100% - 32px) / 4.5)",
                        minHeight: itemHeight ? `${itemHeight}px` : "calc((100% - 32px) / 4.5)",
                        flexBasis: itemHeight ? `${itemHeight}px` : "calc((100% - 32px) / 4.5)",
                      }
                      : { height: "76px", minHeight: "76px" }
                  }
                  className={`relative w-full !p-0 !min-h-0 overflow-hidden border-2 transition-all cursor-pointer bg-gray-100 shadow-2xs shrink-0 ${isSelected
                    ? "border-brand-green ring-1 ring-brand-green scale-[0.98]"
                    : "border-transparent opacity-80 hover:opacity-100 hover:border-gray-300"
                    }`}
                >
                  <img
                    src={img}
                    alt={`${title} thumbnail ${idx + 1}`}
                    className="w-full h-full object-cover"
                  />
                </Button>
              );
            })}
          </div>
        )}
      </div>

      {/* Fullscreen Lightbox Modal */}
      {isLightboxOpen && (
        <div
          className="fixed inset-0 z-50 bg-black/95 backdrop-blur-md flex flex-col items-center justify-between p-4 md:p-6 select-none animate-fadeIn"
          onClick={() => setIsLightboxOpen(false)}
        >
          {/* Top Bar */}
          <div className="w-full flex items-center justify-between text-white z-10" onClick={(e) => e.stopPropagation()}>
            <span className="text-sm font-semibold bg-white/10 px-3.5 py-1 rounded-full">
              {title}
            </span>
            <Button
              type="button"
              variant="ghost"
              size="icon"
              radius="full"
              onClick={() => setIsLightboxOpen(false)}
              className="w-10 h-10 rounded-full bg-white/10 hover:bg-white/20 text-white cursor-pointer transition-colors p-0"
              icon={<FiX className="w-5 h-5" />}
            />
          </div>

          {/* Main Large Image */}
          <div className="relative flex-1 w-full max-w-5xl flex items-center justify-center my-4" onClick={(e) => e.stopPropagation()}>
            <img
              src={activeImage || heroImage}
              alt="Fullscreen Preview"
              className="max-w-full max-h-[80vh] object-contain rounded-[6px] shadow-2xl"
            />
          </div>

          {/* Bottom Thumbnails Strip */}
          {hasThumbnails && (
            <div className="flex items-center gap-2.5 max-w-full overflow-x-auto p-2 no-scrollbar z-10" onClick={(e) => e.stopPropagation()}>
              {allImages.map((img, idx) => (
                <Button
                  key={idx}
                  type="button"
                  variant="ghost"
                  size="xs"
                  radius="lg"
                  onClick={() => setActiveImage(img)}
                  className={`w-14 h-14 !p-0 !min-h-0 overflow-hidden border-2 transition-all shrink-0 cursor-pointer ${activeImage === img ? "border-white scale-105" : "border-transparent opacity-50 hover:opacity-100"
                    }`}
                >
                  <img src={img} alt="" className="w-full h-full object-cover" />
                </Button>
              ))}
            </div>
          )}
        </div>
      )}
    </div>
  );
};

"use client";

import React from "react";
import Link from "next/link";
import { FiHome, FiHeart, FiShare2, FiMoreVertical, FiShield, FiClock, FiAward, FiRepeat } from "react-icons/fi";
import { FaAward } from "react-icons/fa";
import { SellerDetails } from "../utils/packageDetailsNormalizer";
import { BadgeCheck } from "lucide-react";
import { Button, Breadcrumb } from "@/components/ui";
import { getOnlineStatus } from "@/utils/userStatus";
import { useUserStore } from "@/store/userStore";
import { useAuthModalStore } from "@/store/authModalStore";

interface PackageHeaderStatsProps {
  title: string;
  categoryName: string;
  subcategoryName?: string;
  seller: SellerDetails;
  isFavorited?: boolean;
  favoriteCount?: number;
  onToggleFavorite?: () => void;
  onShare?: () => void;
}

export const PackageHeaderStats: React.FC<PackageHeaderStatsProps> = ({
  title,
  categoryName,
  subcategoryName,
  seller,
  isFavorited = false,
  favoriteCount = 0,
  onToggleFavorite,
  onShare,
}) => {
  const defaultAvatar = `https://ui-avatars.com/api/?name=${encodeURIComponent(
    seller.name || "Seller"
  )}&background=0D9488&color=fff&bold=true`;

  const user = useUserStore((state: any) => state.user);
  const openAuthModal = useAuthModalStore((state) => state.openAuthModal);
  const sellerStatus = getOnlineStatus(seller.lastActiveAt || seller.lastSeen, seller.isOnline, 10);

  const handleFavoriteClick = (e: React.MouseEvent) => {
    e.preventDefault();
    e.stopPropagation();

    if (!user) {
      openAuthModal({
        mode: "login",
        onSuccess: () => {
          onToggleFavorite?.();
        },
      });
      return;
    }

    onToggleFavorite?.();
  };

  return (
    <div className="w-full mb-6">
      {/* 1. Breadcrumbs */}
      <Breadcrumb
        items={[
          {
            name: categoryName,
            href: categoryName === "Services" ? "/packages" : `/packages?category=${encodeURIComponent(categoryName)}`,
          },
          ...(subcategoryName
            ? [
              {
                name: subcategoryName,
                href: `/packages?category=${encodeURIComponent(subcategoryName)}`,
              },
            ]
            : []),
          { name: title, isLast: true },
        ]}
      />

      {/* 2. Main Title */}
      <h1
        className="
    text-[24px]
    min-[400px]:text-[26px]
    sm:text-[28px]
    md:text-[26px]
    lg:text-[28px]
    xl:text-[32px]
    2xl:text-[32px]
    font-[590]
    font-sf-pro
    leading-[1.2]
    text-[var(--Foundation-Grey-grey-800,#292929)]
    not-italic
    mb-4
  "
      >
        {title}
      </h1>

      {/* 3. Seller Meta Bar + Actions */}
      <div className="flex flex-wrap items-center justify-between gap-4 pb-4 mb-4 border-b border-gray-100">
        <div className="flex items-center gap-3 sm:gap-4">
          <Link
            href={`/seller/${seller.username || seller.name}`}
            className="shrink-0 group block"
            title={`View ${seller.name}'s profile`}
          >
            <img
              src={seller.avatar || defaultAvatar}
              alt={seller.name}
              className="w-12 h-12 sm:w-14 sm:h-14 md:w-[64px] md:h-[64px] aspect-square rounded-full object-cover border border-gray-200 shadow-xs group-hover:opacity-90 transition-opacity"
              onError={(e) => {
                (e.target as HTMLImageElement).src = defaultAvatar;
              }}
            />
          </Link>
          <div className="flex items-start gap-1 flex-col">
            <div className="flex items-center gap-2">
              <Link
                href={`/seller/${seller.username || seller.name}`}
                className="font-[510] text-[#000] font-sf-pro text-lg not-italic leading-normal hover:text-brand-green transition-colors"
                title={`View ${seller.name}'s profile`}
              >
                {seller.name}
              </Link>
              {seller.isPro && (
                <span className="inline-flex items-center justify-center px-[10px] py-[2px] gap-[10px] rounded-[4px] bg-[var(--purple-800,#360083)] text-white text-[10px] sm:text-xs font-bold uppercase tracking-wide">
                  Pro
                </span>
              )}
            </div>

            <div className="flex items-center gap-2 flex-wrap">
              <span className="text-[#000] text-sm sm:text-[16px] font-sf-pro font-[510] not-italic leading-normal">{seller.role}</span>
              <span className="text-gray-400 text-sm"> | </span>
              <div className="flex items-center gap-1.5 text-sm font-semibold text-gray-900">
                <span className="text-base font-sf-pro font-bold text-[#000] not-italic leading-normal">
                  {seller.rating > 0 ? seller.rating.toFixed(1) : "New"}
                </span>
                <svg xmlns="http://www.w3.org/2000/svg" width="20" height="20" viewBox="0 0 24 24" fill="none" className="w-4 h-4 shrink-0">
                  <path d="M13.7276 3.44418L15.4874 6.99288C15.7274 7.48687 16.3673 7.9607 16.9073 8.05143L20.0969 8.58575C22.1367 8.92853 22.6167 10.4206 21.1468 11.8925L18.6671 14.3927C18.2471 14.8161 18.0172 15.6327 18.1471 16.2175L18.8571 19.3125C19.417 21.7623 18.1271 22.71 15.9774 21.4296L12.9877 19.6452C12.4478 19.3226 11.5579 19.3226 11.0079 19.6452L8.01827 21.4296C5.8785 22.71 4.57865 21.7522 5.13859 19.3125L5.84851 16.2175C5.97849 15.6327 5.74852 14.8161 5.32856 14.3927L2.84884 11.8925C1.389 10.4206 1.85895 8.92853 3.89872 8.58575L7.08837 8.05143C7.61831 7.9607 8.25824 7.48687 8.49821 6.99288L10.258 3.44418C11.2179 1.51861 12.7777 1.51861 13.7276 3.44418Z" fill="#F5B400" />
                </svg>
                <span className="text-[var(--Foundation-Grey-grey-300,#868686)] text-base font-sf-pro font-normal not-italic leading-normal">
                  ({seller.reviewCount})
                </span>
              </div>
            </div>

          </div>
        </div>

        {/* Right Actions */}
        <div className="flex items-center gap-3 sm:gap-4 text-sm text-gray-600 flex-wrap justify-between sm:justify-end w-full sm:w-auto">
          <div className="flex items-center gap-2 flex-wrap">
            {seller.ordersInQueue > 0 && (
              <span className="text-[var(--Foundation-Grey-grey-500,#4A4A4A)] font-normal font-sf-pro text-base not-italic leading-normal">
                <strong className="text-[#222222] font-bold">{seller.ordersInQueue} </strong> orders in queue
                <span className="mx-2 text-gray-300">|</span>
              </span>
            )}

            <span className="inline-flex items-center gap-1.5 font-sf-pro text-base not-italic leading-normal">
              <span
                className={`w-2 h-2 rounded-full shrink-0 ${sellerStatus.isOnline ? "bg-[#10B981]" : "bg-gray-300"
                  }`}
              />
              <span
                className={
                  sellerStatus.isOnline
                    ? "text-emerald-700 font-medium"
                    : "text-[var(--Foundation-Grey-grey-500,#4A4A4A)] font-normal"
                }
              >
                {sellerStatus.isOnline
                  ? "Online"
                  : sellerStatus.lastSeenText
                    ? sellerStatus.lastSeenText
                    : "Offline"}
              </span>
            </span>
          </div>

          <div className="flex items-center gap-2 sm:gap-2.5">
            <Button
              type="button"
              variant={isFavorited ? "danger-soft" : "outline"}
              size="icon"
              radius="full"
              onClick={handleFavoriteClick}
              className={`w-9 h-9 sm:w-10 sm:h-10 !min-h-0 !p-0 aspect-square rounded-[60px] flex items-center justify-center transition-colors cursor-pointer hover:bg-gray-50 shrink-0 ${isFavorited ? '!text-red-500 !bg-red-50/50 !border-red-200' : 'text-gray-500 !bg-white border-gray-200'
                }`}
              title={isFavorited ? "Remove from favorites" : "Save to favorites"}
              aria-label={isFavorited ? "Remove from favorites" : "Save to favorites"}
              icon={<FiHeart className={`w-4 h-4 sm:w-5 sm:h-5 ${isFavorited ? 'fill-red-500 text-red-500' : ''}`} />}
            />

            <Button
              type="button"
              variant="outline"
              size="icon"
              radius="full"
              onClick={onShare}
              className="w-9 h-9 sm:w-10 sm:h-10 !min-h-0 !p-0 aspect-square rounded-[60px] !bg-white border border-gray-200 flex items-center justify-center text-gray-500 hover:bg-gray-50 transition-colors cursor-pointer shrink-0"
              title="Share"
              icon={<FiShare2 className="w-4 h-4 sm:w-5 sm:h-5" />}
            />
          </div>
        </div>
      </div>

      {/* 4. Seller Stats */}
      <div className="w-full mb-6 overflow-hidden rounded-[6px] border border-[#DADADA] bg-[#F5F5F5] grid grid-cols-1 md:grid-cols-2 macbook:grid-cols-4 ">

        {/* Card 1: Profile Status */}
        <div className="min-h-[72px] sm:min-h-[80px] xl:h-[84px] px-3 min-[480px]:px-3.5 sm:px-4 lg:px-4 xl:px-3.5 macbook:px-4 2xl:px-5 py-3 sm:py-3.5 xl:py-0 flex items-center gap-2 sm:gap-2.5 lg:gap-2.5 xl:gap-2.5 macbook:gap-3 2xl:gap-4 border-b border-r 2xl:border-b-0 border-black/10">
          <div className="w-8 h-8 sm:w-9 sm:h-9 lg:w-8 lg:h-8 xl:w-9 xl:h-9 2xl:w-10 2xl:h-10 rounded-[6px] border border-[#0000001A] bg-[#FAFAFA] text-[#5568AB] flex items-center justify-center shrink-0">
            <BadgeCheck className="w-4 h-4 sm:w-[17px] sm:h-[17px] lg:w-4 lg:h-4 xl:w-[17px] xl:h-[17px] 2xl:w-[18px] 2xl:h-[18px]" />
          </div>

          <div className="min-w-0 flex-1">
            <span className="text-xs macbook:text-[13px] 2xl:text-[13px] font-inter font-normal leading-tight text-[#6E6E6E] block truncate">
              Profile Status
            </span>

            <span className="text-[14px] font-inter font-bold text-black block truncate">
              {seller.verified ? "Verified" : "Active"}
            </span>
          </div>
        </div>

        {/* Card 2: Response Time */}
        <div className="min-h-[72px] sm:min-h-[80px] xl:h-[84px] px-3 min-[480px]:px-3.5 sm:px-4 lg:px-4 xl:px-3.5 macbook:px-4 2xl:px-5 py-3 sm:py-3.5 xl:py-0 flex items-center gap-2 sm:gap-2.5 lg:gap-2.5 xl:gap-2.5 macbook:gap-3 2xl:gap-4 border-b 2xl:border-b-0 xl:border-r border-black/10">
          <div className="w-8 h-8 sm:w-9 sm:h-9 lg:w-8 lg:h-8 xl:w-9 xl:h-9 2xl:w-10 2xl:h-10 rounded-[6px] border border-[#0000001A] bg-[#FAFAFA] text-[#F57727] flex items-center justify-center shrink-0">
            <FiClock className="w-4 h-4 sm:w-[17px] sm:h-[17px] lg:w-4 lg:h-4 xl:w-[17px] xl:h-[17px] 2xl:w-[18px] 2xl:h-[18px]" />
          </div>

          <div className="min-w-0 flex-1">
            <span className="text-[11px] min-[480px]:text-xs sm:text-xs md:text-xs lg:text-[11px] xl:text-xs macbook:text-[13px] 2xl:text-sm font-inter text-[#6E6E6E] block font-normal leading-tight truncate">
              Response Time
            </span>

            <span className="text-[14px] font-inter font-bold text-black block truncate">
              {seller.responseTime}
            </span>
          </div>
        </div>

        {/* Card 3: Category */}
        <div className="min-h-[72px] sm:min-h-[80px] xl:h-[84px] px-3 min-[480px]:px-3.5 sm:px-4 lg:px-4 xl:px-3.5 macbook:px-4 2xl:px-5 py-3 sm:py-3.5 xl:py-0 flex items-center gap-2 sm:gap-2.5 lg:gap-2.5 xl:gap-2.5 macbook:gap-3 2xl:gap-4 border-b md:border-b-0 border-r border-black/10">
          <div className="w-8 h-8 sm:w-9 sm:h-9 lg:w-8 lg:h-8 xl:w-9 xl:h-9 2xl:w-10 2xl:h-10 rounded-[6px] border border-[#0000001A] bg-[#FAFAFA] text-[#54AA54] flex items-center justify-center shrink-0">
            <FaAward className="w-4 h-4 sm:w-[17px] sm:h-[17px] lg:w-4 lg:h-4 xl:w-[17px] xl:h-[17px] 2xl:w-[18px] 2xl:h-[18px]" />
          </div>

          <div className="min-w-0 flex-1">
            <span className="text-[11px] min-[480px]:text-xs sm:text-xs md:text-xs lg:text-[11px] xl:text-xs macbook:text-[13px] 2xl:text-sm font-inter text-[#6E6E6E] block font-normal leading-tight truncate">
              Category
            </span>
            <span className="text-[14px] font-inter font-bold text-black block truncate"
              title={seller.topRatedIn}
            >
              {seller.topRatedIn}
            </span>
          </div>
        </div>

        {/* Card 4: Completion */}
        <div className="min-h-[72px] sm:min-h-[80px] xl:h-[84px] px-3 min-[480px]:px-3.5 sm:px-4 lg:px-4 xl:px-3.5 macbook:px-4 2xl:px-5 py-3 sm:py-3.5 xl:py-0 flex items-center gap-2 sm:gap-2.5 lg:gap-2.5 xl:gap-2.5 macbook:gap-3 2xl:gap-4">
          <div className="w-8 h-8 sm:w-9 sm:h-9 lg:w-8 lg:h-8 xl:w-9 xl:h-9 2xl:w-10 2xl:h-10 rounded-[6px] border border-[#0000001A] bg-[#FAFAFA] text-[#9654F4] flex items-center justify-center shrink-0">
