"use client";

import React, { useState, useRef, useEffect } from "react";
import Link from "next/link";
import { FiArrowLeft, FiArrowRight } from "react-icons/fi";
import { Button } from "@/components/ui";

interface PackagePortfolioShowcaseProps {
  sellerPackages?: any[];
  sellerName?: string;
}

export const PackagePortfolioShowcase: React.FC<PackagePortfolioShowcaseProps> = ({
  sellerPackages = [],
  sellerName = "Seller",
}) => {
  const [activeIndex, setActiveIndex] = useState(0);
  const scrollContainerRef = useRef<HTMLDivElement>(null);

  // Mouse Drag-to-Scroll state
  const [isDragging, setIsDragging] = useState(false);
  const [startX, setStartX] = useState(0);
  const [scrollLeft, setScrollLeft] = useState(0);
  const [hasMoved, setHasMoved] = useState(false);

  const handleMouseDown = (e: React.MouseEvent) => {
    if (!scrollContainerRef.current) return;
    setIsDragging(true);
    setHasMoved(false);
    setStartX(e.pageX - scrollContainerRef.current.offsetLeft);
    setScrollLeft(scrollContainerRef.current.scrollLeft);
  };

  const handleMouseMove = (e: React.MouseEvent) => {
    if (!isDragging || !scrollContainerRef.current) return;
    e.preventDefault();
    const x = e.pageX - scrollContainerRef.current.offsetLeft;
    const walk = (x - startX) * 1.5;
    if (Math.abs(walk) > 4) {
      setHasMoved(true);
    }
    scrollContainerRef.current.scrollLeft = scrollLeft - walk;
  };

  const handleMouseUpOrLeave = () => {
    setIsDragging(false);
  };

  // Keep the active thumbnail scrolled horizontally into view without scrolling the entire window
  const isInitialMount = useRef(true);
  useEffect(() => {
    if (isInitialMount.current) {
      isInitialMount.current = false;
      return;
    }
    const container = scrollContainerRef.current;
    if (container && container.children[activeIndex]) {
      const activeEl = container.children[activeIndex] as HTMLElement;
      const scrollTarget =
        activeEl.offsetLeft - container.offsetWidth / 2 + activeEl.offsetWidth / 2;
      container.scrollTo({ left: scrollTarget, behavior: "smooth" });
    }
  }, [activeIndex]);

  if (!Array.isArray(sellerPackages) || sellerPackages.length === 0) {
    return null;
  }

  const currentPkg = sellerPackages[activeIndex] || sellerPackages[0];

  const handlePrev = () => {
    setActiveIndex((prev) => (prev > 0 ? prev - 1 : sellerPackages.length - 1));
  };

  const handleNext = () => {
    setActiveIndex((prev) => (prev < sellerPackages.length - 1 ? prev + 1 : 0));
  };

  const coverImage = currentPkg.cover || (Array.isArray(currentPkg.images) && currentPkg.images[0]) || "";
  const pkgUrl = `/package/${currentPkg.slug || currentPkg._id || currentPkg.id}`;

  return (
    <div id="section-seller-packages" className="scroll-mt-36 bg-[#F5F5F5] border border-gray-100 rounded-[6px] p-4 sm:p-6 lg:p-8 mb-10 shadow-2xs">
      {/* Header */}
      <div className="flex flex-wrap items-center justify-between gap-3 sm:gap-4 mb-4 sm:mb-6">
        <div className="flex items-center gap-2.5 sm:gap-3 flex-wrap min-w-0">
          <h2 className="text-[20px] font-bold font-sf-pro text-[var(--Foundation-Grey-grey-800,#292929)] not-italic leading-tight tracking-tight">
            Packages
          </h2>
          <span className="inline-flex items-center gap-1 rounded-[4px] border border-[var(--Foundation-Grey-grey-100,#C7C7C7)] bg-[var(--Foundation-Grey-grey-50,#EDEDED)] px-2 sm:px-[10px] py-0.5 sm:py-[4px] text-xs sm:text-sm md:text-[16px] font-[510] font-sf-pro text-[var(--Foundation-Grey-grey-400,#6E6E6E)] not-italic leading-normal shrink-0">
            <span className="font-bold text-[var(--Foundation-Grey-grey-700,#353535)] font-sf-pro not-italic leading-normal">
              {sellerPackages.length}
            </span>
            <span>
              {sellerPackages.length === 1 ? 'Package' : 'Packages'}
            </span>
          </span>
        </div>

        {/* Carousel Arrow Controls */}
        {sellerPackages.length > 1 && (
          <div className="flex items-center gap-2">
            <Button
              type="button"
              variant="outline"
              size="icon"
              radius="full"
              onClick={handlePrev}
              aria-label="Previous package"
              className="w-8 h-8 rounded-full border-gray-200 hover:border-gray-900 text-gray-700 hover:text-black shrink-0 p-0 min-h-[32px]"
              icon={<FiArrowLeft className="w-3.5 h-3.5" />}
            />
            <Button
              type="button"
              variant="outline"
              size="icon"
              radius="full"
              onClick={handleNext}
              aria-label="Next package"
              className="w-8 h-8 rounded-full border-gray-200 hover:border-gray-900 text-gray-700 hover:text-black shrink-0 p-0 min-h-[32px]"
              icon={<FiArrowRight className="w-3.5 h-3.5" />}
            />
          </div>
        )}
      </div>

      {/* Main Active Package Showcase Card */}
      <Link href={pkgUrl} className="block group">
        <div className="relative aspect-[16/9] sm:aspect-[2.1/1] w-full rounded-[6px] overflow-hidden mb-4 shadow-sm bg-gray-950">
          {coverImage && (
            <img
              src={coverImage}
              alt={currentPkg.title || "Package Cover"}
              className="w-full h-full object-cover group-hover:scale-105 transition-transform duration-700"
            />
          )}

          {/* Frosted Glass Gradient Overlay */}
          <div className="absolute inset-x-0 bottom-0 h-[65%] bg-gradient-to-t from-black/95 via-black/60 to-transparent pointer-events-none" />

          {/* Text Content */}
          <div className="absolute inset-0 flex flex-col justify-end p-5 sm:p-7 text-white">
            <h3 className="text-lg sm:text-xl font-bold mb-1.5 drop-shadow-sm group-hover:text-fuchsia-400 transition-colors">
              {currentPkg.title}
            </h3>


            <div className="flex flex-wrap items-center justify-between gap-4 pt-2 border-t border-white/15">
              <div className="flex items-center gap-6 text-xs sm:text-sm">
                <div>
                  <span className="text-[11px] text-gray-400 block font-medium">Starting At</span>
                  <span className="font-bold text-white">${currentPkg.price}</span>
                </div>
                {currentPkg.deliveryTime && (
                  <div>
                    <span className="text-[11px] text-gray-400 block font-medium">Delivery</span>
                    <span className="font-bold text-white">{currentPkg.deliveryTime}</span>
                  </div>
                )}
              </div>

              {/* Tags */}
              {Array.isArray(currentPkg.tags) && currentPkg.tags.length > 0 && (
                <div className="flex items-center gap-1.5 flex-wrap">
                  {currentPkg.tags.slice(0, 3).map((tag: string, idx: number) => (
                    <span
                      key={idx}
                      className="bg-white/15 backdrop-blur-md text-white text-xs px-2.5 py-0.5 rounded-[6px] font-medium"
                    >
                      {tag}
                    </span>
                  ))}
                </div>
              )}
            </div>
          </div>
        </div>
      </Link>

      {/* Thumbnails of other packages in single scrollable row with drag-to-scroll */}
      {sellerPackages.length > 1 && (
        <div
          ref={scrollContainerRef}
          onMouseDown={handleMouseDown}
          onMouseMove={handleMouseMove}
          onMouseUp={handleMouseUpOrLeave}
          onMouseLeave={handleMouseUpOrLeave}
          className={`flex items-center gap-2.5 sm:gap-3 overflow-x-auto no-scrollbar scroll-smooth flex-nowrap py-1 select-none ${isDragging ? "cursor-grabbing" : "cursor-grab"
            }`}
        >
          {sellerPackages.map((pkg, idx) => {
            const isSelected = activeIndex === idx;
            const thumbImg = pkg.cover || (Array.isArray(pkg.images) && pkg.images[0]) || "";
            return (
              <Button
                key={idx}
                type="button"
                variant="ghost"
                size="xs"
                radius="xl"
                onClick={() => {
                  if (!hasMoved) setActiveIndex(idx);
                }}
                className={`relative w-[130px] sm:w-[160px] md:w-[180px] !p-0 !min-h-0 shrink-0 aspect-[16/10] overflow-hidden border-2 transition-all cursor-pointer bg-gray-100 active:scale-95 ${isSelected
                  ? "border-brand-green ring-1 ring-brand-green shadow-xs scale-98"
                  : "border-transparent opacity-75 hover:opacity-100 hover:border-gray-300"
                  }`}
              >
                {thumbImg && (
                  <img
                    src={thumbImg}
                    alt={pkg.title || ""}
                    className="w-full h-full object-cover pointer-events-none select-none"
                    draggable={false}
                  />
                )}
              </Button>
            );
          })}
        </div>
      )}
    </div>
  );
};

"use client";

import React from "react";
import { FiClock, FiRepeat, FiArrowRight, FiMessageSquare } from "react-icons/fi";
import { PackageTierDetails, SellerDetails } from "../utils/packageDetailsNormalizer";
import { Button } from "@/components/ui";
import { getOnlineStatus } from "@/utils";

interface PackagePricingSidebarProps {
  packages: {
    basic: PackageTierDetails;
    standard: PackageTierDetails;
    premium: PackageTierDetails;
  };
  seller: SellerDetails;
  selectedTier: 'basic' | 'standard' | 'premium';
  onSelectTier: (tier: 'basic' | 'standard' | 'premium') => void;
  onContact: () => void;
  onCheckout?: (tier?: 'basic' | 'standard' | 'premium') => void;
  onViewSellerProfile?: () => void;
  className?: string;
}

export const PackagePricingSidebar: React.FC<PackagePricingSidebarProps> = ({
  packages,
  seller,
  selectedTier,
  onSelectTier,
  onContact,
  onCheckout,
  onViewSellerProfile: _onViewSellerProfile,
  className = "",
}) => {

  const availableTiers = (['basic', 'standard', 'premium'] as const).filter(
    (key) => packages[key] && packages[key].hasTier !== false && packages[key].price > 0
  );

  const activePkg = packages[selectedTier] || packages.basic;

  const checklistItems =
    Array.isArray(activePkg.featureList) && activePkg.featureList.length > 0
      ? activePkg.featureList.filter(Boolean)
      : [];

  const defaultAvatar = `https://ui-avatars.com/api/?name=${encodeURIComponent(
    seller.name || "Seller"
  )}&background=0D9488&color=fff&bold=true`;

  const sellerStatus = getOnlineStatus(seller.lastActiveAt || seller.lastSeen, seller.isOnline, 10);

  return (
    <div className={`w-full max-w-[400px] space-y-6 ${className}`.trim()}>
      {/* 1. Top Card: Packages Pricing Tier Card */}
      <div className="bg-[#FFF] border border-[rgba(0,0,0,0.10)] rounded-[6px] p-[20px] shadow-2xs">
        {/* Tier Segmented Tabs (only if multiple tiers exist) */}
        {availableTiers.length > 1 && (
          <div
            className="grid gap-1 bg-[#F4F4F6] p-[4px] rounded-[6px] border border-gray-200/50 text-center mb-5  items-center"
            style={{
              gridTemplateColumns: `repeat(${availableTiers.length}, minmax(0, 1fr))`,
            }}
          >
            {availableTiers.map((tierKey) => {
              const pkg = packages[tierKey];
              const isSelected = selectedTier === tierKey;

              return (
                <Button
                  key={tierKey}
                  type="button"
                  variant={isSelected ? "brand" : "ghost"}
                  size="sm"
                  radius="fiverr"
                  onClick={() => onSelectTier(tierKey)}
                  className={`flex-1 h-full font-inter font-medium text-[14px] sm:text-[15px] transition-all cursor-pointer ${isSelected
                    ? "bg-[#0B403F] hover:bg-[#0B403F] text-white shadow-sm"
                    : "bg-transparent hover:bg-transparent text-[#6E6E6E] hover:text-[#222427]"
                    }`}
                >
                  {pkg.name}
                </Button>
              );
            })}
          </div>
        )}

        {/* Custom Tier Title / Tagline */}
        {(activePkg.tagline || activePkg.title) && (
          <h4 className="font-inter font-[510] not-italic text-[12px] text-[var(--Foundation-Grey-grey-400,#6E6E6E)] leading-normal mb-1">
            {activePkg.tagline || activePkg.title}
          </h4>
        )}

        {/* Price Display */}
        <div className="flex items-baseline mb-4 pb-4 border-b border-gray-100 font-inter font-semibold text-[26px] min-[400px]:text-[28px] sm:text-[20px] md:text-[22px] lg:text-[24px] xl:text-[26px]  not-italic">
          <span className="text-[000]">$</span>
          <span className="text-[#000]">{activePkg.price}</span>
        </div>

        {/* Short Description */}
        {activePkg.shortDesc && (
          <p className="
            font-inter
            not-italic
            text-[14px]
            leading-[1.3]
            text-[var(--Foundation-Grey-grey-500,#4A4A4A)]
            mb-5
            pb-5
            border-b
            border-gray-100
          ">
            {activePkg.shortDesc}
          </p>
        )}

        {/* Revisions & Delivery Meta Row */}
        {(Boolean(activePkg.revisions) || activePkg.deliveryTime > 0) && (
          <div className="flex items-center gap-4 sm:gap-5 2xl:gap-6 font-sf-pro font-normal not-italic text-[13px]  text-[var(--Foundation-Grey-grey-500,#4A4A4A)] leading-normal mb-5 flex-wrap">
            {activePkg.revisions ? (
              <div className="flex items-center gap-1.5 sm:gap-2">
                <FiRepeat className="w-[15px] h-[15px]  text-[var(--Foundation-Grey-grey-500,#4A4A4A)] shrink-0" />
                <span>{activePkg.revisions}</span>
              </div>
            ) : null}
            {activePkg.deliveryTime > 0 ? (
              <div className="flex items-center gap-1.5 sm:gap-2">
                <FiClock className="w-[15px] h-[15px] text-[var(--Foundation-Grey-grey-500,#4A4A4A)] shrink-0" />
                <span>{activePkg.deliveryTime} Day{activePkg.deliveryTime > 1 ? 's' : ''} Delivery</span>
              </div>
            ) : null}
          </div>
        )}

        {/* Feature Checklist with rounded pill rows (only if features exist) */}
        {checklistItems.length > 0 && (
          <div className="mb-6 bg-[#F5F5F5] rounded-[6px] border border-[rgba(0,0,0,0.10)] overflow-hidden divide-y divide-[rgba(0,0,0,0.10)]">
            {checklistItems.map((item, idx) => (
              <div
                key={idx}
                className="px-3.5 sm:px-4 lg:px-[18px] 2xl:px-[20px] py-2.5 sm:py-3 lg:py-3.5 2xl:py-[20px] flex items-center gap-2.5 sm:gap-3"
              >
                <svg
                  className="w-4 h-4 min-[400px]:w-5 min-[400px]:h-5 sm:w-[22px] sm:h-[22px] 2xl:w-6 2xl:h-6 shrink-0"
                  viewBox="0 0 24 24"
                  fill="none"
                  xmlns="http://www.w3.org/2000/svg"
                >
                  <path
                    d="M2.5 12C2.5 7.52166 2.5 5.28249 3.89124 3.89124C5.28249 2.5 7.52166 2.5 12 2.5C16.4783 2.5 18.7175 2.5 20.1088 3.89124C21.5 5.28249 21.5 7.52166 21.5 12C21.5 16.4783 21.5 18.7175 20.1088 20.1088C18.7175 21.5 16.4783 21.5 12 21.5C7.52166 21.5 5.28249 21.5 3.89124 20.1088C2.5 18.7175 2.5 16.4783 2.5 12Z"
                    stroke="#656565"
                    strokeWidth="1.5"
                  />
                  <path
                    d="M8 12.5L10.5 15L16 9"
                    stroke="#656565"
                    strokeWidth="1.5"
                    strokeLinecap="round"
                    strokeLinejoin="round"
                  />
                </svg>
                <span className="not-italic text-[13px] font-inter text-[#6E6E6E] leading-normal">
                  {item}
                </span>
              </div>
            ))}
          </div>
        )}

        {/* Primary Action Button: Continue / Checkout */}
        {onCheckout && (
          <Button
            variant="brand"
            size="md"
            radius="fiverr"
            fullWidth
            onClick={() => onCheckout(activePkg.key)}
            rightIcon={<FiArrowRight className="w-4 h-4" />}
            className="mb-2.5 font-bold"
          >
            Continue (${activePkg.price})
          </Button>
        )}

        {/* Secondary Action Button: Contact Me */}
        <Button
          variant="soft"
          size="md"
          radius="fiverr"
          fullWidth
          onClick={onContact}
          leftIcon={<FiMessageSquare className="w-3.5 h-3.5 text-gray-600" />}
          className="font-semibold"
        >
          Contact Seller
        </Button>
      </div>

      {/* Floating Message Seller Pill (matches Fiverr/marketplace floating widget) */}
      <div
        role="button"
        tabIndex={0}
        onClick={onContact}
        onKeyDown={(e) => {
          if (e.key === "Enter" || e.key === " ") {
            e.preventDefault();
            onContact();
          }
        }}
        className="fixed bottom-6 right-6 z-40 inline-flex items-center gap-2.5 sm:gap-3 bg-white hover:bg-[#FAFAFA] border border-gray-200/90 shadow-[0_4px_20px_rgba(0,0,0,0.10)] hover:shadow-[0_8px_30px_rgba(0,0,0,0.16)] px-4 py-2 sm:px-4.5 sm:py-2.5 rounded-[6px] cursor-pointer transition-all duration-200 hover:-translate-y-0.5 active:scale-95 select-none animate-fadeIn"
        title={`Message ${seller.name || seller.username || "Seller"}`}
      >
        {/* Emerald Lightning Bolt */}
        <svg
          xmlns="http://www.w3.org/2000/svg"
          viewBox="0 0 24 24"
          fill="#10B981"
          className="w-3.5 h-4 sm:w-4 sm:h-4 text-[#10B981] fill-[#10B981] shrink-0"
          aria-hidden="true"
        >
          <path d="M13 2L3 14h9l-1 8 10-12h-9l1-8z" />
        </svg>

        {/* Circular Avatar with Online/Offline Status Dot */}
        <div className="relative shrink-0">
          <img
            src={seller.avatar || defaultAvatar}
            alt={seller.name || "Seller"}
            className="w-9 h-9 sm:w-10 sm:h-10 rounded-full object-cover border border-gray-200/80 shadow-2xs"
            onError={(e) => {
              (e.target as HTMLImageElement).src = defaultAvatar;
            }}
          />
          <span
            className={`absolute -bottom-0.5 -right-0.5 w-3 h-3 sm:w-3.5 sm:h-3.5 rounded-full border-2 border-white ${sellerStatus.isOnline ? "bg-[#10B981]" : "bg-slate-300"
              }`}
          />
        </div>

        {/* Text Stack */}
        <div className="flex flex-col text-left justify-center pr-1 sm:pr-2">
          <div className="flex items-center gap-1.5 font-bold text-gray-900 text-xs sm:text-[13.5px] leading-tight">
            {/* Speech Bubble Icon */}
            <svg
              xmlns="http://www.w3.org/2000/svg"
              width="16"
              height="16"
              viewBox="0 0 24 24"
              fill="none"
              stroke="currentColor"
              strokeWidth="2"
              strokeLinecap="round"
              strokeLinejoin="round"
              className="w-3.5 h-3.5 sm:w-4 sm:h-4 text-gray-700 shrink-0"
              aria-hidden="true"
            >
              <path d="M14 9a2 2 0 0 1-2 2H6l-4 4V4c0-1.1.9-2 2-2h8a2 2 0 0 1 2 2v5Z" />
              <path d="M18 9h2a2 2 0 0 1 2 2v11l-4-4h-6a2 2 0 0 1-2-2v-1" />
            </svg>
            <span>Message {seller.name || seller.username || "Seller"}</span>
          </div>
          <div className="text-[10px] sm:text-[11.5px] text-gray-500 font-normal leading-tight mt-0.5">
            {sellerStatus.isOnline ? (
              <span className="text-emerald-600 font-medium flex items-center gap-1">
                Online
              </span>
            ) : sellerStatus.lastSeenText ? (
              `Offline · Last seen ${sellerStatus.lastSeenText}`
            ) : (
              "Offline"
            )}
          </div>
        </div>
      </div>
    </div>
  );
};

"use client";

import React, { useState } from "react";
import { FaStar } from "react-icons/fa";
import { FiChevronDown } from "react-icons/fi";
import { Button } from "@/components/ui";
import { useUserStore } from "@/store/userStore";
import { SellerReviewReply } from "@/features/reviews";
import { ClientReviewItem } from "../utils/packageDetailsNormalizer";

interface PackageReviewsSectionProps {
  averageRating?: number;
  totalReviews?: number;
  starDistribution?: { [star: number]: number };
  categoryScores?: {
    communication: number;
    quality: number;
    value: number;
  };
  reviews?: ClientReviewItem[];
  sellerName?: string;
  sellerAvatar?: string;
  sellerId?: string;
  sellerUsername?: string;
}

export const PackageReviewsSection: React.FC<PackageReviewsSectionProps> = ({
  averageRating = 0,
  totalReviews = 0,
  starDistribution = { 5: 0, 4: 0, 3: 0, 2: 0, 1: 0 },
  categoryScores = { communication: 0, quality: 0, value: 0 },
  reviews = [],
  sellerName,
  sellerAvatar,
  sellerId,
  sellerUsername,
}) => {
  const currentUser = useUserStore((state) => state.user);
  const [visibleCount, setVisibleCount] = useState(3);

  const isSellerOwner = Boolean(
    currentUser && (
      (currentUser.username && sellerUsername && currentUser.username.toLowerCase() === sellerUsername.toLowerCase()) ||
      (currentUser._id && sellerId && currentUser._id === sellerId) ||
      (currentUser.id && sellerId && currentUser.id === sellerId)
    )
  );

  const handleShowMore = () => {
    setVisibleCount((prev) => prev + 3);
  };

  if (reviews.length === 0) {
    return (
      <div id="section-reviews" className="scroll-mt-36 bg-white border border-gray-100 rounded-[6px] p-6 sm:p-8 mb-10 shadow-2xs">
        <div className="flex flex-wrap items-center justify-between gap-4 mb-6">
          <h2 className="text-xl sm:text-2xl font-bold text-gray-900 tracking-tight">
            Reviews from Clients
          </h2>
          <span className="text-xs font-semibold text-gray-500 bg-gray-50 border border-gray-200 px-3 py-1 rounded-[6px]">
            0 Reviews
          </span>
        </div>
        <div className="p-10 text-center bg-gray-50/60 rounded-[6px] border border-dashed border-gray-200">
          <FaStar className="w-8 h-8 text-amber-300 fill-amber-300 mx-auto mb-2 opacity-60" />
          <h3 className="text-sm font-bold text-gray-800 mb-1">No reviews yet for this package</h3>
          <p className="text-xs text-gray-500 max-w-sm mx-auto leading-relaxed">
            Be the first client to order this service package and share your experience with the community.
          </p>
        </div>
      </div>
    );
  }

  return (
    <div id="section-reviews" className="scroll-mt-36 bg-white border border-gray-100 rounded-[6px] p-6 sm:p-8 mb-10 shadow-2xs">
      {/* Header */}
      <div className="flex flex-wrap items-center justify-between gap-4 mb-6">
        <h2 className="text-[20px] font-bold font-sf-pro text-gray-900">
          Reviews from Clients
        </h2>
        <div className="flex items-center gap-1.5 font-semibold text-gray-900 text-sm">
          <span className="text-base font-bold">{averageRating.toFixed(1)}</span>
          <FaStar className="w-4 h-4 text-amber-400 fill-amber-400" />
          <span className="text-gray-400 font-normal">({totalReviews} reviews for this package)</span>
        </div>
      </div>

      {/* Ratings Breakdown Grid */}
      <div className="grid grid-cols-1 md:grid-cols-12 gap-6 mb-8 pb-8 border-b border-gray-100">
        {/* Left: 5 to 1 Star Bars */}
        <div className="md:col-span-6 space-y-2">
          {[5, 4, 3, 2, 1].map((star) => {
            const pct = starDistribution[star] || 0;
            return (
              <div key={star} className="flex items-center gap-3 text-xs font-semibold text-gray-700">
                <span className="w-2">{star}</span>
                <div className="flex-1 h-2.5 bg-gray-100 rounded-full overflow-hidden">
                  <div
                    className="h-full bg-amber-400 rounded-full transition-all duration-500"
                    style={{ width: `${pct}%` }}
                  />
                </div>
                <span className="w-8 text-right text-[11px] text-gray-400">{pct}%</span>
              </div>
            );
          })}
        </div>

        {/* Right: Specific Category Ratings */}
        <div className="md:col-span-6 space-y-3 sm:pl-4">
          <h4 className="text-xs font-bold text-gray-900 uppercase tracking-wider mb-3">
            Rating Breakdown
          </h4>
          <div className="space-y-2.5 text-xs sm:text-[13px] text-gray-700 font-medium">
            <div className="flex items-center justify-between">
              <span>Seller communication level</span>
              <div className="flex items-center gap-1 font-bold text-gray-900">
                <span>{categoryScores.communication}/5</span>
                <FaStar className="w-3.5 h-3.5 text-amber-400 fill-amber-400" />
              </div>
            </div>
            <div className="flex items-center justify-between">
              <span>Quality of delivery</span>
              <div className="flex items-center gap-1 font-bold text-gray-900">
                <span>{categoryScores.quality}/5</span>
                <FaStar className="w-3.5 h-3.5 text-amber-400 fill-amber-400" />
              </div>
            </div>
            <div className="flex items-center justify-between">
              <span>Value of delivery</span>
              <div className="flex items-center gap-1 font-bold text-gray-900">
                <span>{categoryScores.value}/5</span>
                <FaStar className="w-3.5 h-3.5 text-amber-400 fill-amber-400" />
              </div>
            </div>
          </div>
        </div>
      </div>

      {/* Reviews Cards List */}
      <div className="space-y-4 mb-6">
        {reviews.slice(0, visibleCount).map((review) => {
          const defaultAvatar = `https://ui-avatars.com/api/?name=${encodeURIComponent(
            review.buyerName || "Buyer"
          )}&background=0D9488&color=fff&bold=true`;

          return (
            <div
              key={review.id}
              className="p-5 sm:p-6 rounded-[6px] bg-gray-50/70 border border-gray-100 transition-all hover:bg-gray-50"
            >
              {/* Review Card Header */}
              <div className="flex items-start justify-between gap-4 mb-3">
                <div className="flex items-center gap-3">
                  <img
                    src={review.buyerAvatar || defaultAvatar}
                    alt={review.buyerName}
                    className="w-10 h-10 rounded-full object-cover border border-gray-200 shadow-2xs shrink-0"
                    onError={(e) => {
                      (e.target as HTMLImageElement).src = defaultAvatar;
                    }}
                  />
                  <div>
                    <span className="font-bold text-gray-900 text-sm block">{review.buyerName}</span>
                    <div className="flex items-center gap-2 text-xs text-gray-500 mt-0.5">
                      {review.country && <span>{review.country}</span>}
                      {review.country && review.dateText && <span>·</span>}
                      {review.dateText && <span>{review.dateText}</span>}
                    </div>
                  </div>
                </div>

                {/* Rating */}
                <div className="flex items-center gap-1 bg-white px-2.5 py-1 rounded-[6px] border border-gray-100 shadow-2xs">
                  <FaStar className="w-3.5 h-3.5 text-amber-400 fill-amber-400" />
                  <span className="text-xs font-bold text-gray-900">{review.rating}</span>
                </div>
              </div>

              {/* Review Comment Text */}
              <p className="text-xs sm:text-[13px] text-gray-700 leading-relaxed whitespace-pre-line mb-3">
                {review.reviewText}
              </p>

              {/* Nested Seller Response & Reply Box */}
              <SellerReviewReply
                reviewId={review.id}
                orderId={review.orderId}
                sellerReply={review.sellerReply || review.sellerResponse}
                sellerReplyAt={review.sellerReplyAt}
                sellerName={sellerName || "Seller"}
                sellerAvatar={sellerAvatar}
                canReply={isSellerOwner}
              />
            </div>
          );
        })}
      </div>

      {/* Show More Reviews Button */}
      {reviews.length > visibleCount && (
        <Button
          type="button"
          variant="outline"
          size="sm"
          radius="xl"
          fullWidth
          onClick={handleShowMore}
          className="bg-gray-50 hover:bg-gray-100 text-gray-700 text-xs font-semibold"
        >
          Show More Reviews ({reviews.length - visibleCount} remaining)
        </Button>
      )}
    </div>
  );
};

"use client";

import React from "react";
