"use client";

import React from "react";
import Link from "next/link";
import { FiHome } from "react-icons/fi";
import { FaStar } from "react-icons/fa";
import { Breadcrumb } from "@/components/ui";
import { SELLER_FALLBACK_IMAGES } from "../utils/sellerProfileNormalizer";

interface SellerHeroBannerProps {
  name: string;
  avatar: string;
  banner?: string;
  isPro?: boolean;
  isSeller?: boolean;
  sellerLevel?: string;
  role: string;
  rating: number;
  reviewCount: number;
  categoryName?: string;
  subcategoryName?: string;
}

export const SellerHeroBanner: React.FC<SellerHeroBannerProps> = ({
  name,
  avatar,
  banner = SELLER_FALLBACK_IMAGES.banner,
  isPro = false,
  isSeller = true,
  sellerLevel = "Level 1 Seller",
  role,
  rating,
  reviewCount,
  categoryName = "Services",
  subcategoryName,
}) => {
  return (
    <div className="w-full mb-8">
