      <Breadcrumb
        items={[
          {
            name: categoryName,
            href: categoryName === "Services" ? "/packages" : `/packages?category=${encodeURIComponent(categoryName)}`,
          },
          ...(subcategoryName
            ? [
                {
                  name: subcategoryName,
                  href: `/packages?category=${encodeURIComponent(subcategoryName)}`,
                },
              ]
            : []),
          {
            name,
            isLast: true,
          },
        ]}
      />

      {/* 2. Panoramic Hero Banner */}
