            <h1 className="text-xl sm:text-2xl font-bold font-sf-pro text-gray-900 tracking-tight">
              {name}
            </h1>
            {isSeller && sellerLevel && (
              <span className="bg-[#360083] text-white text-[10px] font-bold px-2.5 py-0.5 rounded-[6px] tracking-wide">
