"use client";

import React, { useState } from "react";
import { FaStar } from "react-icons/fa";
import { FiTag, FiCalendar, FiArrowRight } from "react-icons/fi";
import { Button } from "@/components/ui";
import { useUserStore } from "@/store/userStore";
import { SellerReviewReply } from "@/features/reviews";
import { SellerReviewItem, SELLER_FALLBACK_IMAGES } from "../utils/sellerProfileNormalizer";

interface SellerReviewsSectionProps {
  averageRating: number;
  totalReviews: number;
  starDistribution: { [star: number]: number };
  categoryScores: {
    communication: string;
    quality: string;
    value: string;
  };
  reviews: SellerReviewItem[];
  sellerName?: string;
  sellerAvatar?: string;
  sellerUsername?: string;
  sellerId?: string;
}

export const SellerReviewsSection: React.FC<SellerReviewsSectionProps> = ({
  averageRating,
  totalReviews,
  starDistribution,
  categoryScores,
  reviews,
  sellerName,
  sellerAvatar,
  sellerUsername,
  sellerId,
}) => {
  const currentUser = useUserStore((state) => state.user);
  const [visibleCount, setVisibleCount] = useState(2);

  const isSellerOwner = Boolean(
    currentUser && (
      (currentUser.username && sellerUsername && currentUser.username.toLowerCase() === sellerUsername.toLowerCase()) ||
      (currentUser._id && sellerId && currentUser._id === sellerId) ||
      (currentUser.id && sellerId && currentUser.id === sellerId)
    )
  );

  if (!reviews || reviews.length === 0) {
    return null;
  }

  const displayedReviews = reviews.slice(0, visibleCount);
  const hasCategoryScores = Boolean(categoryScores?.communication || categoryScores?.quality || categoryScores?.value);

  return (
    <div id="section-reviews" className="scroll-mt-36 bg-white border border-gray-100 rounded-[6px] p-6 sm:p-8 mb-10 shadow-2xs">
      {/* 1. Section Header */}
      <div className="flex flex-wrap items-center justify-between gap-4 mb-8">
        <h2 className="text-xl sm:text-2xl font-bold font-sf-pro text-gray-900 tracking-tight">
          Review from the client
        </h2>
        <div className="flex items-center gap-1.5 text-sm font-sf-pro">
          <span className="font-bold text-gray-900 text-base">{averageRating.toFixed(1)}</span>
          <FaStar className="w-4 h-4 text-[#F5B400] fill-[#F5B400]" />
          <span className="text-gray-400 font-normal">({totalReviews} review{totalReviews === 1 ? '' : 's'})</span>
        </div>
      </div>

      {/* 2. Rating Breakdown Summary Grid */}
      <div className="grid grid-cols-1 md:grid-cols-12 gap-8 items-center mb-8 pb-8 border-b border-gray-100">
        {/* Left: Star Distribution Progress Bars */}
        <div className={`${hasCategoryScores ? 'md:col-span-7' : 'md:col-span-12'} space-y-2.5`}>
          {[5, 4, 3, 2, 1].map((star) => {
            const percentage = starDistribution[star] || 0;
            return (
              <div key={star} className="flex items-center gap-3 text-xs text-gray-500 font-sf-pro">
                <span className="w-3 text-right font-semibold text-gray-700">{star}</span>
                <div className="flex-1 h-2 rounded-full bg-gray-200 overflow-hidden">
                  <div
                    className="h-full rounded-full bg-[#F5B400] transition-all duration-700"
                    style={{ width: `${percentage}%` }}
                  />
                </div>
              </div>
            );
          })}
        </div>

        {/* Right: Sub-scores Breakdown */}
        {hasCategoryScores && (
          <div className="md:col-span-5 md:border-l md:border-gray-100 md:pl-8 space-y-3 font-sf-pro">
            <h3 className="text-sm font-bold text-gray-900 mb-3">
              Rating Breakdown
            </h3>

            {categoryScores.communication && (
              <div className="flex items-center justify-between text-xs text-gray-600">
                <span>Seller communication level</span>
                <div className="flex items-center gap-1 font-bold text-gray-900">
                  <span>{categoryScores.communication}</span>
                  <FaStar className="w-3 h-3 text-[#F5B400] fill-[#F5B400]" />
                </div>
              </div>
            )}

            {categoryScores.quality && (
              <div className="flex items-center justify-between text-xs text-gray-600">
                <span>Quality of delivery</span>
                <div className="flex items-center gap-1 font-bold text-gray-900">
                  <span>{categoryScores.quality}</span>
                  <FaStar className="w-3 h-3 text-[#F5B400] fill-[#F5B400]" />
                </div>
              </div>
            )}

            {categoryScores.value && (
              <div className="flex items-center justify-between text-xs text-gray-600">
                <span>Value of delivery</span>
                <div className="flex items-center gap-1 font-bold text-gray-900">
                  <span>{categoryScores.value}</span>
                  <FaStar className="w-3 h-3 text-[#F5B400] fill-[#F5B400]" />
                </div>
              </div>
            )}
          </div>
        )}
      </div>

      {/* 3. Client Reviews List */}
      <div className="space-y-4">
        {displayedReviews.map((rev) => {
          return (
            <div
              key={rev.id}
              className="bg-[#FBFBFB] border border-gray-100 rounded-[6px] p-5 sm:p-6 transition-all"
            >
              <div className="flex flex-col sm:flex-row sm:items-start justify-between gap-4">
                {/* Reviewer Details */}
                <div className="flex items-start gap-3.5 flex-1">
                  <img
                    src={rev.buyerAvatar || "/images/mock-package/avatar-seller.png"}
                    alt={rev.buyerName}
                    className="w-10 h-10 rounded-full object-cover border border-gray-200 shrink-0 bg-gray-100"
                    onError={(e) => {
                      (e.target as HTMLImageElement).src = "/images/mock-package/avatar-seller.png";
                    }}
                  />

                  <div className="space-y-1">
                    <div className="flex items-center gap-2 flex-wrap">
                      <span className="font-bold text-sm text-gray-900 font-sf-pro">
                        {rev.buyerName}
                      </span>
                      {rev.projectStatus && (
                        <span className="text-[11px] font-medium text-gray-600 bg-white border border-gray-200 px-2 py-0.5 rounded shadow-2xs">
                          {rev.projectStatus}
                        </span>
                      )}
                    </div>

                    {rev.country && (
                      <div className="flex items-center gap-1.5 text-xs text-gray-500 font-sf-pro">
                        {rev.countryFlag && (
                          rev.countryFlag.startsWith("http") || rev.countryFlag.startsWith("/") ? (
                            <img src={rev.countryFlag} alt="" className="w-4 h-2.5 object-contain inline-block" />
                          ) : (
                            <span>{rev.countryFlag}</span>
                          )
                        )}
                        <span>{rev.country}</span>
                      </div>
                    )}

                    <div className="flex items-center gap-1.5 text-xs text-gray-500 font-sf-pro">
                      <span className="font-bold text-gray-900">{rev.rating.toFixed(1)}</span>
                      <FaStar className="w-3 h-3 text-[#F5B400] fill-[#F5B400]" />
                      {rev.dateText && (
                        <>
                          <span className="text-gray-400">·</span>
                          <span className="text-gray-400">{rev.dateText}</span>
                        </>
                      )}
                    </div>
                  </div>
                </div>

                {/* Right Project Thumbnail */}
                {rev.projectImage && (
                  <div className="w-24 sm:w-28 aspect-[16/10] rounded-[6px] overflow-hidden border border-gray-200 shrink-0 bg-gray-950 shadow-2xs">
                    <img
                      src={rev.projectImage}
                      alt="Reviewed project"
                      className="w-full h-full object-cover"
                      onError={(e) => {
                        const parent = (e.target as HTMLElement).parentElement;
                        if (parent) parent.style.display = "none";
                      }}
                    />
                  </div>
                )}
              </div>

              {/* Review Text */}
              {rev.reviewText && (
                <p className="text-sm text-gray-700 leading-relaxed font-normal my-4 font-sf-pro">
                  {rev.reviewText}
                </p>
              )}

              {/* Price & Duration Chips */}
              {(rev.projectPrice || rev.projectDuration) && (
                <div className="flex items-center gap-3 mb-4">
                  {rev.projectPrice && (
                    <div className="bg-white border border-gray-200/80 rounded-[6px] px-3 py-1.5 flex items-center gap-2 text-xs shadow-2xs">
                      <FiTag className="w-3.5 h-3.5 text-teal-600" />
                      <span className="text-gray-400">Price</span>
                      <span className="font-bold text-gray-900">{rev.projectPrice}</span>
                    </div>
                  )}

                  {rev.projectDuration && (
                    <div className="bg-white border border-gray-200/80 rounded-[6px] px-3 py-1.5 flex items-center gap-2 text-xs shadow-2xs">
                      <FiCalendar className="w-3.5 h-3.5 text-purple-600" />
                      <span className="text-gray-400">Duration</span>
                      <span className="font-bold text-gray-900">{rev.projectDuration}</span>
                    </div>
                  )}
                </div>
              )}

              {/* Nested Seller Response & Reply Box */}
              <SellerReviewReply
                reviewId={rev.id}
                orderId={rev.orderId}
                sellerReply={rev.sellerReply || rev.sellerResponse}
                sellerReplyAt={rev.sellerReplyAt}
                sellerName={sellerName || "Seller"}
                sellerAvatar={sellerAvatar}
                canReply={isSellerOwner}
              />
            </div>
          );
        })}
      </div>

      {/* 4. Show More Reviews Button */}
      {reviews.length > visibleCount && (
        <div className="mt-6">
          <Button
            type="button"
            variant="dark"
            size="sm"
            radius="fiverr"
            onClick={() => setVisibleCount((prev) => prev + 2)}
            rightIcon={<FiArrowRight className="w-3.5 h-3.5" />}
            className="font-semibold shadow-xs px-5 py-3"
          >
            Show More Reviews
          </Button>
        </div>
      )}
    </div>
  );
};

export default SellerReviewsSection;

import moment from "moment";
import { getCountryFlag } from "@/utils";

export interface SellerGigItem {
  id: string;
  slug?: string;
  category: string;
  subcategory?: string;
  rating: number;
  reviewCount: number;
  title: string;
  image: string;
  startingPrice: number;
  [key: string]: any;
}

export interface SellerReviewItem {
  id: string;
  buyerName: string;
  buyerAvatar: string;
  country: string;
  countryFlag: string;
  projectStatus: string;
  rating: number;
  dateText: string;
  reviewText: string;
  projectImage: string;
  projectPrice: string;
  projectDuration: string;
  sellerResponse?: string;
  sellerReply?: string | null;
  sellerReplyAt?: string | null;
  orderId?: string;
}

export interface SellerFaqItem {
  question: string;
  answer: string;
}

export interface NormalizedSellerProfile {
  id: string;
  username: string;
  name: string;
  avatar: string;
  banner: string;
  isPro: boolean;
  isSeller?: boolean;
  sellerLevel?: string;
  role: string;
  rating: number;
  reviewCount: number;
  memberSince: string;
  bio: string;
  country: string;
  responseTime: string;
  onTimeDelivery: string;
  skills: string[];
  localTimeText: string;
  lastActiveAt?: string | Date | null;
  isOnline?: boolean;
  categoryName?: string;
  subcategoryName?: string;
  gigs: any[];
  reviewsData: {
    averageRating: number;
    totalReviews: number;
    starDistribution: { [star: number]: number };
    categoryScores: {
      communication: string;
      quality: string;
      value: string;
    };
    list: SellerReviewItem[];
  };
  faqs: SellerFaqItem[];
}

export const SELLER_FALLBACK_IMAGES = {
  banner: '/images/mock-seller/banner-hd.jpg',
  fallbackBanner: '/images/mock-seller/banner.png',
  avatar: '/images/mock-package/avatar-seller.png',
  reviewerAvatar: '/images/mock-package/avatar-reviewer.png',
  gigCover: '/images/mock-seller/gig-cover.png',
  reviewLunar: '/images/mock-package/review-lunar.png',
};

export const DEFAULT_SELLER_GIGS: SellerGigItem[] = [];

export const DEFAULT_SELLER_REVIEWS: SellerReviewItem[] = [];

export const DEFAULT_SELLER_FAQS: SellerFaqItem[] = [];

export function normalizeSellerProfile(
  rawUser: any,
  rawGigs: any[] = [],
  rawReviews: any = [],
  usernameParam?: string
): NormalizedSellerProfile {
  // Handle backwards compatibility if 3rd argument is username string
  if (typeof rawReviews === "string") {
    usernameParam = rawReviews;
    rawReviews = [];
  }

  const sellerObj =
    rawUser?.data?.user ||
    rawUser?.user ||
    rawUser?.data ||
    rawUser ||
    {};

  const id =
    sellerObj._id ||
    sellerObj.id ||
    (Array.isArray(rawGigs) && (rawGigs[0]?.userID?._id || rawGigs[0]?.userID || rawGigs[0]?.sellerID?._id || rawGigs[0]?.sellerID)) ||
    '';
  const username = sellerObj.username || usernameParam || '';
  const name = sellerObj.name || (sellerObj.username ? `${sellerObj.username.replace(/[_-]/g, ' ')}` : '');
  const avatar = sellerObj.image || sellerObj.avatar || SELLER_FALLBACK_IMAGES.avatar;
  const banner = sellerObj.cover || sellerObj.banner || SELLER_FALLBACK_IMAGES.banner;
  const hasMetricsReset = Boolean(sellerObj.metricsResetAt);
  const isPro = !hasMetricsReset && Boolean(sellerObj.isPro ?? false);
  const isSeller = Boolean(
    sellerObj.isSeller ??
    (sellerObj.role === 'seller' || (Array.isArray(rawGigs) && rawGigs.length > 0) || true)
  );
  const sellerLevel = hasMetricsReset
    ? 'Level 1 Seller'
    : (sellerObj.sellerLevel || (isSeller ? 'Level 1 Seller' : ''));
  const role = sellerObj.role || sellerObj.headline || sellerObj.shortTitle || '';

  const memberSince = sellerObj.createdAt
    ? String(new Date(sellerObj.createdAt).getFullYear())
    : '';

  const bio = sellerObj.description || sellerObj.bio || '';

  const country = sellerObj.country || '';
  const responseTime = sellerObj.responseTimeHours
    ? `${sellerObj.responseTimeHours} Hour${sellerObj.responseTimeHours > 1 ? 's' : ''}`
    : (sellerObj.responseTime || '1 Hour');
  const onTimeDelivery = sellerObj.onTimeDeliveryRate
    ? `${sellerObj.onTimeDeliveryRate}%`
    : (sellerObj.metrics?.overall?.onTimeDeliveryRate ? `${sellerObj.metrics.overall.onTimeDeliveryRate}%` : '100%');

  const skills = Array.isArray(sellerObj.skills) && sellerObj.skills.length > 0
    ? sellerObj.skills
    : [];

  const lastActiveAt = sellerObj.lastActiveAt || sellerObj.lastSeen || sellerObj.updatedAt || null;
  const isOnline = Boolean(sellerObj.isOnline);

  // Map gigs with seller details attached so PackageCard renders properly
  let gigs: any[] = [];
  if (Array.isArray(rawGigs) && rawGigs.length > 0) {
    gigs = rawGigs.map((g: any, idx: number) => {
      const gId = g._id || g.id || `gig-${idx}`;
      const resolvedCover = g.cover || (Array.isArray(g.images) && g.images[0]) || g.img || g.image || '';
      return {
        ...g,
        _id: gId,
        id: gId,
        slug: g.slug || g._id || g.id,
        category: g.category || g.cat || 'Services',
        subcategory: g.subcategory || (Array.isArray(g.tags) && g.tags[0]) || '',
        rating: Number(g.starNumber ? (g.totalStars / g.starNumber) : (g.rating || g.star || 0)),
        reviewCount: Number(g.starNumber || g.reviews || g.reviewCount || 0),
        title: g.title || '',
        cover: resolvedCover,
        img: resolvedCover,
        image: resolvedCover,
        price: Number(g.price || g.startingPrice || 0),
        startingPrice: Number(g.price || g.startingPrice || 0),
        sales: Number(g.sales || 0),
        user: {
          name,
          username,
          image: avatar,
          sellerLevel: hasMetricsReset ? 'Level 1' : (sellerObj.sellerLevel || 'Level 1'),
        },
      };
    });
  }

  // Derive primary categories for breadcrumbs
  const categoryName = gigs[0]?.category || sellerObj.category || 'Services';
  const subcategoryName = gigs[0]?.subcategory || '';

  // Process dynamic reviews
  const reviewsList: SellerReviewItem[] = [];
  const starCounts: { [star: number]: number } = { 5: 0, 4: 0, 3: 0, 2: 0, 1: 0 };
  let validReviewCount = 0;
  let totalScore = 0;
  let commTotal = 0;
  let commCount = 0;
  let qualTotal = 0;
  let qualCount = 0;
  let valTotal = 0;
  let valCount = 0;

  const reviewsInput = Array.isArray(rawReviews)
    ? rawReviews
    : (Array.isArray(rawReviews?.reviews) ? rawReviews.reviews : (Array.isArray(rawReviews?.data) ? rawReviews.data : []));

  if (reviewsInput.length > 0) {
    reviewsInput.forEach((r: any, idx: number) => {
      const buyerObj = r.userID || r.user || {};
      const star = typeof r.star === 'number' && r.star > 0 && r.star <= 5 ? r.star : 5;
      const roundedStar = Math.min(5, Math.max(1, Math.round(star)));
      starCounts[roundedStar] = (starCounts[roundedStar] || 0) + 1;
      validReviewCount++;
      totalScore += star;

      const comm = Number(r.communicationRating || r.communication || 0);
      if (comm > 0) {
        commTotal += comm;
        commCount++;
      }
      const qual = Number(r.qualityRating || r.quality || 0);
      if (qual > 0) {
        qualTotal += qual;
        qualCount++;
      }
      const val = Number(r.valueRating || r.service || r.value || 0);
      if (val > 0) {
        valTotal += val;
        valCount++;
      }

      const buyerCountry = buyerObj.country || '';
      const flagObj = buyerCountry ? getCountryFlag(buyerCountry) : null;
      const flag = flagObj?.normal || flagObj?.mini || '';

      const priceVal = r.price || r.gigID?.price || r.orderID?.price;
      const formattedPrice = priceVal ? (String(priceVal).startsWith('$') ? String(priceVal) : `$${priceVal}`) : '';

      reviewsList.push({
        id: r._id || r.id || `rev-${idx}`,
        orderId: r.orderID?._id || r.orderID || r.orderId || undefined,
        buyerName: buyerObj.name || buyerObj.username || 'Verified Client',
        buyerAvatar: buyerObj.image || buyerObj.avatar || buyerObj.img || '',
        country: buyerCountry,
        countryFlag: flag,
        projectStatus: r.orderStatus || '',
        rating: star,
        dateText: r.createdAt ? moment(r.createdAt).fromNow() : '',
        reviewText: r.desc || r.description || '',
        projectImage: r.gigID?.cover || (Array.isArray(r.gigID?.images) && r.gigID?.images[0]) || '',
        projectPrice: formattedPrice,
        projectDuration: r.duration ? `${r.duration} Days` : '',
        sellerResponse: r.sellerReply || r.sellerResponse || undefined,
        sellerReply: r.sellerReply || r.sellerResponse || null,
        sellerReplyAt: r.sellerReplyAt || null,
      });
    });
  }

  // Calculate review metrics
  const finalReviews: SellerReviewItem[] = reviewsList;
  const finalTotalReviews = validReviewCount > 0 ? validReviewCount : Number(sellerObj.reviewCount || sellerObj.totalReviews || 0);
  const finalAverageRating = validReviewCount > 0
    ? (totalScore / validReviewCount)
    : (finalTotalReviews > 0 ? Number(sellerObj.rating || sellerObj.starRating || 0) : 0);

  const starDistribution: { [star: number]: number } = { 5: 0, 4: 0, 3: 0, 2: 0, 1: 0 };
  if (validReviewCount > 0) {
    for (let s = 1; s <= 5; s++) {
      starDistribution[s] = Math.round(((starCounts[s] || 0) / validReviewCount) * 100);
    }
  }

  const categoryScores = {
    communication: commCount > 0 ? `${(commTotal / commCount).toFixed(1)}/5` : '',
    quality: qualCount > 0 ? `${(qualTotal / qualCount).toFixed(1)}/5` : '',
    value: valCount > 0 ? `${(valTotal / valCount).toFixed(1)}/5` : '',
  };

  // Format local time
  const now = new Date();
  const timeStr = now.toLocaleTimeString([], { hour: '2-digit', minute: '2-digit', hour12: true });
  const localTimeText = `${timeStr} local time`;

  // Extract real FAQs from user object and from seller packages
  const realFaqs: SellerFaqItem[] = [];
  const seenFaqQuestions = new Set<string>();

  // 1. Direct seller FAQs from user model if present
  if (Array.isArray(sellerObj.faqs)) {
    sellerObj.faqs.forEach((f: any) => {
      const q = (f.question || f.q || '').trim();
      const a = (f.answer || f.a || '').trim();
      if (q && a && !seenFaqQuestions.has(q.toLowerCase())) {
        seenFaqQuestions.add(q.toLowerCase());
        realFaqs.push({ question: q, answer: a });
      }
    });
  }

  // 2. Aggregate FAQs from seller packages/gigs
  if (Array.isArray(rawGigs)) {
    rawGigs.forEach((gig: any) => {
      if (Array.isArray(gig.faqs)) {
        gig.faqs.forEach((f: any) => {
          const q = (f.question || f.q || '').trim();
          const a = (f.answer || f.a || '').trim();
          if (q && a && !seenFaqQuestions.has(q.toLowerCase())) {
            seenFaqQuestions.add(q.toLowerCase());
            realFaqs.push({ question: q, answer: a });
          }
        });
      }
    });
  }

  return {
    id,
    username,
    name,
    avatar,
    banner,
    isPro,
    isSeller,
    sellerLevel,
    role,
    rating: finalAverageRating,
    reviewCount: finalTotalReviews,
    memberSince,
    bio,
    country,
    responseTime,
    onTimeDelivery,
    skills,
    localTimeText,
    lastActiveAt,
    isOnline,
    categoryName,
    subcategoryName,
    gigs,
    reviewsData: {
      averageRating: finalAverageRating,
      totalReviews: finalTotalReviews,
      starDistribution,
      categoryScores,
      list: finalReviews,
    },
    faqs: realFaqs,
  };
}

