import { useState, useEffect, useRef, useCallback } from 'react';
import { axiosFetch } from '@/utils';
import axios from 'axios';

export interface SuggestionItem {
  text: string;
  type: 'category' | 'gig';
  slug?: string;
  id?: string;
  [key: string]: any;
}

export interface SuggestionsResponse {
  suggestions?: string[];
  items?: SuggestionItem[];
}

interface UseSearchSuggestionsOptions {
  limit?: number;
  debounceMs?: number;
}

export function useSearchSuggestions(
  query: string,
  options: UseSearchSuggestionsOptions = {}
) {
  const { limit = 8, debounceMs = 180 } = options;

  const [suggestions, setSuggestions] = useState<string[]>([]);
  const [items, setItems] = useState<SuggestionItem[]>([]);
  const [isLoading, setIsLoading] = useState(false);
  const [isOpen, setIsOpen] = useState(false);

  // Monotonic request ID counter for race-condition protection on fast typing
  const requestIdRef = useRef(0);
  const debounceTimerRef = useRef<NodeJS.Timeout | null>(null);
  const skipNextQueryRef = useRef(false);
  const isFirstMountRef = useRef(true);

  const clear = useCallback(() => {
    requestIdRef.current++;
    if (debounceTimerRef.current) {
      clearTimeout(debounceTimerRef.current);
      debounceTimerRef.current = null;
    }
    setSuggestions([]);
    setItems([]);
    setIsLoading(false);
    setIsOpen(false);
  }, []);

  const close = useCallback(() => {
    requestIdRef.current++;
    if (debounceTimerRef.current) {
      clearTimeout(debounceTimerRef.current);
      debounceTimerRef.current = null;
    }
    skipNextQueryRef.current = true;
    setSuggestions([]);
    setItems([]);
    setIsLoading(false);
    setIsOpen(false);
  }, []);

  useEffect(() => {
    // Prevent dropdown from auto-opening on initial component mount (e.g. when navigating to search page with initial query from URL)
    if (isFirstMountRef.current) {
      isFirstMountRef.current = false;
      return;
    }

    // If query change was triggered programmatically (e.g. user selected a suggestion or searched),
    // skip reopening and querying for suggestions
    if (skipNextQueryRef.current) {
      skipNextQueryRef.current = false;
      return;
    }

    const trimmed = query.trim();

    // Step 2 - Empty input check:
    // If the user erases everything or leaves the search input blank,
    // do not make an API call; just clear and hide the dropdown.
    if (!trimmed) {
      clear();
      return;
    }

    // Immediately show dropdown with "Search for {query}" while debouncing
    setIsOpen(true);

    // Fast typing protection: invalidate prior requests
    const currentRequestId = ++requestIdRef.current;

    if (debounceTimerRef.current) {
      clearTimeout(debounceTimerRef.current);
    }

    setIsLoading(true);

    // Step 2 - Debounce:
    // Wait 150ms to 200ms (180ms) after the user stops typing before making the request.
    debounceTimerRef.current = setTimeout(async () => {
      try {
        // Step 1 - Where to Call:
        // Endpoint: GET /api/gigs/suggestions?q={userInput}&limit={limit}
        const response = await fetch(`/api/gigs/suggestions?q=${encodeURIComponent(trimmed)}&limit=${limit}`, {
          headers: {
            'Accept': 'application/json',
          },
        });

        // If a newer character was typed or request was closed while this request was in flight, discard response
        if (currentRequestId !== requestIdRef.current) {
          return;
        }

        if (!response.ok) {
          throw new Error(`Failed to fetch suggestions: ${response.status}`);
        }

        const data: SuggestionsResponse = await response.json();

        if (currentRequestId !== requestIdRef.current) {
          return;
        }

        const rawSuggestions = Array.isArray(data?.suggestions) ? data.suggestions : [];
        const rawItems = Array.isArray(data?.items) ? data.items : [];

        const normalizedItems: SuggestionItem[] = rawItems.length > 0
          ? rawItems
          : rawSuggestions.map((text) => ({ text, type: 'gig' }));

        setSuggestions(rawSuggestions);
        setItems(normalizedItems);
        setIsOpen(true);
      } catch (err: any) {
        if (currentRequestId !== requestIdRef.current) {
          return;
        }
        console.warn('Search suggestions error:', err?.message || err);
        setSuggestions([]);
        setItems([]);
      } finally {
        if (currentRequestId === requestIdRef.current) {
          setIsLoading(false);
        }
      }
    }, debounceMs);

    return () => {
      if (debounceTimerRef.current) {
        clearTimeout(debounceTimerRef.current);
      }
    };
  }, [query, limit, debounceMs, clear]);

  return {
    suggestions,
    items,
    isLoading,
    isOpen,
    setIsOpen,
    clear,
    close,
  };
}

export default useSearchSuggestions;

"use client";

import { useState, useCallback, useEffect } from "react";
import { useRouter } from "next/navigation";
import { toast } from "@/utils/toast";
import { useUserStore } from "@/store/userStore";
import { User } from "@/types";
import {
  loadGoogleSDK,
  loadAppleSDK,
  exchangeGoogleToken,
  signInWithApple,
  SocialAuthResponse,
  GOOGLE_CLIENT_ID,
} from "@/services/socialAuth";

export interface SocialAuthOptions {
  onSuccess?: (user: User) => void;
  redirectUrl?: string;
  isSeller?: boolean;
}

export function useSocialAuth() {
  const [loadingProvider, setLoadingProvider] = useState<"google" | "apple" | null>(null);
  const [error, setError] = useState<string | null>(null);
  const setUser = useUserStore((state) => state.setUser);
  const router = useRouter();

  // Pre-load SDKs in background on mount
  useEffect(() => {
    loadGoogleSDK().catch(() => {});
    loadAppleSDK().catch(() => {});
  }, []);

  const handleError = useCallback((err: any) => {
    const errorMsg =
      err.response?.data?.message ||
      err.message ||
      "Social login failed. Please try again.";

    // Skip harsh toast if user merely closed popup
    const isCancelled =
      errorMsg.includes("user_cancelled") ||
      errorMsg.includes("popup_closed_by_user") ||
      errorMsg.includes("closed") ||
      errorMsg.includes("dismissed");

    if (!isCancelled) {
      setError(errorMsg);
      toast.error(errorMsg);
    }
  }, []);

  const handleSuccess = useCallback(
    (data: SocialAuthResponse, options?: SocialAuthOptions) => {
      const user = data.user;
      if (!user) {
        toast.error("Authentication succeeded but no user data returned.");
        return;
      }

      // Clear temporary KYC dismissal state
      const userKey = user.id || user._id || user.username || "default";
      sessionStorage.removeItem(`kyc_prompt_dismissed_${userKey}`);
      sessionStorage.removeItem("kyc_prompt_dismissed_session");

      const token = data.accessToken || (user as any).accessToken || (user as any).token;
      const refreshToken = data.refreshToken || (user as any).refreshToken;
      const combinedUser: User = {
        ...user,
        ...(token ? { accessToken: token, token } : {}),
        ...(refreshToken ? { refreshToken } : {}),
      };

      setUser(combinedUser);

      toast.success(`Welcome, ${user.name || user.username || "user"}!`);

      if (options?.onSuccess) {
        options.onSuccess(combinedUser);
        return;
      }

      // Safe redirect navigation
      let redirectFromQuery = "";
      if (typeof window !== "undefined") {
        try {
          redirectFromQuery = new URLSearchParams(window.location.search).get("redirect") || "";
        } catch {}
      }
      const rawRedirect = options?.redirectUrl || redirectFromQuery;
      let target = rawRedirect;
      if (target) {
        try {
          target = decodeURIComponent(target);
        } catch {}
        if (target.includes("%")) {
          try {
            target = decodeURIComponent(target);
          } catch {}
        }
      }

      let safeTarget =
        target &&
        target.startsWith("/") &&
        !target.startsWith("/login") &&
        !target.startsWith("/register")
          ? target
          : user.isSeller
          ? "/dashboard/seller"
          : "/dashboard/buyer";

      if (user.isSeller && !user.onboardingCompleted) {
        safeTarget = "/seller/onboarding";
      }

      window.location.href = safeTarget;
    },
    [setUser]
  );

  const renderGoogleButton = useCallback(
    (container: HTMLElement | null, options?: SocialAuthOptions) => {
      if (!container || typeof window === "undefined") return;

      loadGoogleSDK().then(() => {
        if (!window.google?.accounts?.id) return;

        window.google.accounts.id.initialize({
          client_id: GOOGLE_CLIENT_ID,
          callback: async (response: { credential?: string }) => {
            if (!response?.credential) {
              toast.error("Google authentication failed. No token received.");
              return;
            }
            try {
              setLoadingProvider("google");
              const data = await exchangeGoogleToken(response.credential, options?.isSeller);
              handleSuccess(data, options);
            } catch (err) {
              handleError(err);
            } finally {
              setLoadingProvider(null);
            }
          },
          cancel_on_tap_outside: true,
        });

        // Clear existing children to avoid duplicate buttons
        container.innerHTML = "";
        window.google.accounts.id.renderButton(container, {
          type: "standard",
          theme: "outline",
          size: "large",
          width: 320,
        });
      });
    },
    [handleSuccess, handleError]
  );

  const handleGoogleLogin = useCallback(
    async (options?: SocialAuthOptions) => {
      if (loadingProvider) return;
      setError(null);
      setLoadingProvider("google");

      try {
        await loadGoogleSDK();

        if (!window.google?.accounts?.id) {
          throw new Error("Google Identity Services failed to load.");
        }

        let isCompleted = false;

        window.google.accounts.id.initialize({
          client_id: GOOGLE_CLIENT_ID,
          callback: async (response: { credential?: string }) => {
            if (isCompleted) return;
            isCompleted = true;

            if (!response?.credential) {
              setLoadingProvider(null);
              toast.error("Google authentication failed. No token received.");
              return;
            }

            try {
              const data = await exchangeGoogleToken(response.credential, options?.isSeller);
              handleSuccess(data, options);
            } catch (err) {
              handleError(err);
            } finally {
              setLoadingProvider(null);
            }
          },
          cancel_on_tap_outside: true,
        });

        // Trigger Google One-Tap / Accounts Prompt
        window.google.accounts.id.prompt((notification: any) => {
          if (notification.isNotDisplayed() || notification.isSkippedMoment()) {
            // If One Tap was skipped or suppressed, search for hidden GSI trigger if rendered
            const hiddenButton = document.getElementById("g_id_signin_hidden")?.querySelector("div[role=button]") as HTMLElement;
            if (hiddenButton) {
              hiddenButton.click();
            } else {
              setLoadingProvider(null);
            }
          }
        });
      } catch (err) {
        handleError(err);
        setLoadingProvider(null);
      }
    },
    [loadingProvider, handleSuccess, handleError]
  );

  const handleAppleLogin = useCallback(
    async (options?: SocialAuthOptions) => {
      if (loadingProvider) return;
      setError(null);
      setLoadingProvider("apple");

      try {
        const data = await signInWithApple(options?.isSeller);
        handleSuccess(data, options);
      } catch (err: any) {
        handleError(err);
      } finally {
        setLoadingProvider(null);
      }
    },
    [loadingProvider, handleSuccess, handleError]
  );

  return {
    loadingProvider,
    error,
    handleGoogleLogin,
    handleAppleLogin,
    renderGoogleButton,
  };
}

