import { useEffect, useCallback, useRef, useState } from 'react';
import { io, Socket } from 'socket.io-client';
import { socket as mainSocket } from '@/utils/socket';

export interface SocketSupportMessage {
  id: string;
  ticketId: string;
  thread?: string;
  sender: string;
  senderID?: string;
  role: string;
  message: string;
  attachments?: any[];
  createdAt: string;
}

interface UseSupportSocketProps {
  ticketId: string;
  thread?: string;
  userDisplayName?: string;
  onMessageReceived?: (msg: SocketSupportMessage) => void;
}

const getAdminSocketURL = () => {
  if (process.env.NEXT_PUBLIC_ADMIN_BACKEND_URL) {
    return process.env.NEXT_PUBLIC_ADMIN_BACKEND_URL;
  }
  if (process.env.NEXT_PUBLIC_ADMIN_API_URL) {
    return process.env.NEXT_PUBLIC_ADMIN_API_URL.replace(/\/api\/?$/, '');
  }
  if (typeof window !== 'undefined') {
    if (window.location.hostname !== 'localhost' && window.location.hostname !== '127.0.0.1') {
      return window.location.origin;
    }
    return `${window.location.protocol}//${window.location.hostname}:8082`;
  }
  return 'http://localhost:8082';
};

let adminSocketInstance: Socket | null = null;

const getAdminSocket = () => {
  if (!adminSocketInstance && typeof window !== 'undefined') {
    adminSocketInstance = io(getAdminSocketURL(), {
      withCredentials: true,
      autoConnect: false,
      reconnection: true,
      reconnectionAttempts: Infinity,
      reconnectionDelay: 1000,
      reconnectionDelayMax: 5000,
      transports: ['websocket', 'polling'],
      path: '/socket.io/',
    });
  }
  return adminSocketInstance;
};

export function useSupportSocket({
  ticketId,
  thread = 'group',
  userDisplayName = 'User',
  onMessageReceived,
}: UseSupportSocketProps) {
  const [isConnected, setIsConnected] = useState(false);
  const [isUnauthorized, setIsUnauthorized] = useState(false);
  const [typingUser, setTypingUser] = useState<string | null>(null);

  const threadRef = useRef(thread);
  useEffect(() => {
    threadRef.current = thread;
  }, [thread]);

  const onMessageRef = useRef(onMessageReceived);
  useEffect(() => {
    onMessageRef.current = onMessageReceived;
  }, [onMessageReceived]);

  useEffect(() => {
    if (!ticketId) return;

    setIsUnauthorized(false);
    const adminSocket = getAdminSocket();

    if (adminSocket && !adminSocket.connected) {
      adminSocket.connect();
    }
    if (!mainSocket.connected) {
      mainSocket.connect();
    }
    setIsConnected(Boolean(adminSocket?.connected || mainSocket.connected));

    const joinTicketRooms = () => {
      setIsConnected(true);
      const payload = { ticketId };

      if (adminSocket) {
        adminSocket.emit('join_ticket', payload);
        adminSocket.emit('join_ticket_room', payload);
        adminSocket.emit('join_room', `ticket_${ticketId}`);
        adminSocket.emit('join_room', `ticket:${ticketId}`);
        adminSocket.emit('join_room', `ticket:${ticketId}:group`);
        adminSocket.emit('join_room', `ticket:${ticketId}:buyer`);
        adminSocket.emit('join_room', `ticket:${ticketId}:seller`);
        adminSocket.emit('join_room', `ticket_${ticketId}_buyer`);
        adminSocket.emit('join_room', `ticket_${ticketId}_seller`);
        adminSocket.emit('join_room', `room:support:ticket:${ticketId}:buyer`);
        adminSocket.emit('join_room', `room:support:ticket:${ticketId}:seller`);
      }

      mainSocket.emit('join_ticket', payload);
      mainSocket.emit('join_ticket_room', payload);
      mainSocket.emit('join_room', `ticket_${ticketId}`);
      mainSocket.emit('join_room', `ticket:${ticketId}`);
      mainSocket.emit('join_room', `ticket:${ticketId}:group`);
      mainSocket.emit('join_room', `ticket:${ticketId}:buyer`);
      mainSocket.emit('join_room', `ticket:${ticketId}:seller`);
      mainSocket.emit('join_room', `ticket_${ticketId}_buyer`);
      mainSocket.emit('join_room', `ticket_${ticketId}_seller`);
      mainSocket.emit('join_room', `room:support:ticket:${ticketId}:buyer`);
      mainSocket.emit('join_room', `room:support:ticket:${ticketId}:seller`);
    };

    joinTicketRooms();

    const handleConnect = () => joinTicketRooms();
    const handleDisconnect = () => {
      setIsConnected(Boolean(adminSocket?.connected || mainSocket.connected));
    };

    const handleReceiveMessage = (payload: any) => {
      const incomingTicketId = String(payload?.ticketId || payload?.ticketID || payload?.id || '');
      if (incomingTicketId && incomingTicketId === String(ticketId)) {
        const senderName = payload.senderName || payload.sender || 'Support Agent';
        const formatted: SocketSupportMessage = {
          id: payload.id || payload._id || payload.createdAt || `msg-${Date.now()}`,
          ticketId: String(ticketId),
          thread: payload.thread || 'group',
          sender: senderName,
          senderID: String(payload.senderID || payload.senderId || ''),
          role: payload.role || payload.senderRole || 'admin',
          message: payload.message || payload.text || payload.content || '',
          attachments: payload.attachments || [],
          createdAt: payload.createdAt || new Date().toISOString(),
        };

        if (onMessageRef.current) {
          onMessageRef.current(formatted);
        }
      }
    };

    const handleError = (err: any) => {
      const msg = String(err?.message || err || '');
      if (/unauthorized/i.test(msg)) {
        setIsUnauthorized(true);
      }
    };

    const handleRateLimited = (data: any) => {
      if (data?.event === 'join_ticket' || data?.event === 'join_ticket_room') {
        setTimeout(joinTicketRooms, 2000);
      }
    };

    const handleUserTyping = (data: { ticketId: string; username: string }) => {
      if (data && String(data.ticketId) === String(ticketId)) {
        setTypingUser(data.username);
      }
    };

    const handleUserStoppedTyping = (data: { ticketId: string }) => {
      if (data && String(data.ticketId) === String(ticketId)) {
        setTypingUser(null);
      }
    };

    if (adminSocket) {
      adminSocket.on('connect', handleConnect);
      adminSocket.on('disconnect', handleDisconnect);
      adminSocket.on('receive_support_message', handleReceiveMessage);
      adminSocket.on('error', handleError);
      adminSocket.on('rate_limited', handleRateLimited);
      adminSocket.on('user_typing', handleUserTyping);
      adminSocket.on('user_stopped_typing', handleUserStoppedTyping);
    }

    mainSocket.on('connect', handleConnect);
    mainSocket.on('disconnect', handleDisconnect);
    mainSocket.on('receive_support_message', handleReceiveMessage);
    mainSocket.on('error', handleError);
    mainSocket.on('rate_limited', handleRateLimited);
    mainSocket.on('user_typing', handleUserTyping);
    mainSocket.on('user_stopped_typing', handleUserStoppedTyping);

    return () => {
      const payload = { ticketId };

      if (adminSocket) {
        adminSocket.emit('leave_ticket', payload);
        adminSocket.emit('leave_ticket_room', payload);
        adminSocket.emit('leave_room', `ticket_${ticketId}`);
        adminSocket.emit('leave_room', `ticket:${ticketId}`);
        if (thread && thread !== 'group') {
          adminSocket.emit('leave_room', `ticket:${ticketId}:${thread}`);
          adminSocket.emit('leave_room', `ticket_${ticketId}_${thread}`);
          adminSocket.emit('leave_room', `room:support:ticket:${ticketId}:${thread}`);
        }
        adminSocket.off('connect', handleConnect);
        adminSocket.off('disconnect', handleDisconnect);
        adminSocket.off('receive_support_message', handleReceiveMessage);
        adminSocket.off('error', handleError);
        adminSocket.off('rate_limited', handleRateLimited);
        adminSocket.off('user_typing', handleUserTyping);
        adminSocket.off('user_stopped_typing', handleUserStoppedTyping);
      }

      mainSocket.emit('leave_ticket', payload);
      mainSocket.emit('leave_ticket_room', payload);
      mainSocket.emit('leave_room', `ticket_${ticketId}`);
      mainSocket.emit('leave_room', `ticket:${ticketId}`);
      mainSocket.off('connect', handleConnect);
      mainSocket.off('disconnect', handleDisconnect);
      mainSocket.off('receive_support_message', handleReceiveMessage);
      mainSocket.off('error', handleError);
      mainSocket.off('rate_limited', handleRateLimited);
      mainSocket.off('user_typing', handleUserTyping);
      mainSocket.off('user_stopped_typing', handleUserStoppedTyping);
    };
  }, [ticketId]);

  const sendSupportMessage = useCallback(
    (message: string, attachments: any[] = []) => {
      if (!ticketId || (!message.trim() && attachments.length === 0)) return;

      const payload = {
        ticketId,
        thread: threadRef.current || 'group',
        message: message.trim(),
        attachments,
        senderName: userDisplayName,
      };

      const adminSocket = getAdminSocket();
      if (adminSocket && adminSocket.connected) {
        adminSocket.emit('send_support_message', payload);
      }
      if (mainSocket.connected) {
        mainSocket.emit('send_support_message', payload);
      }
    },
    [ticketId, userDisplayName]
  );

  const startTyping = useCallback(() => {
    if (!ticketId) return;
    const payload = { ticketId, username: userDisplayName };
    const adminSocket = getAdminSocket();
    if (adminSocket && adminSocket.connected) adminSocket.emit('typing_start', payload);
    if (mainSocket.connected) mainSocket.emit('typing_start', payload);
  }, [ticketId, userDisplayName]);

  const stopTyping = useCallback(() => {
    if (!ticketId) return;
    const payload = { ticketId, username: userDisplayName };
    const adminSocket = getAdminSocket();
    if (adminSocket && adminSocket.connected) adminSocket.emit('typing_stop', payload);
    if (mainSocket.connected) mainSocket.emit('typing_stop', payload);
  }, [ticketId, userDisplayName]);

  return {
    isConnected,
    isUnauthorized,
    typingUser,
    sendSupportMessage,
    startTyping,
    stopTyping,
  };
}

export default useSupportSocket;

/**
 * Formats bytes or raw size strings into clean, human-readable file sizes (e.g. "file size 200mb", "file size 50kb").
 * Returns null if no valid size data is available so false or guessed data is never shown.
 */
export const formatFileSize = (bytesOrStr: any): string | null => {
  if (!bytesOrStr) return null;
  if (typeof bytesOrStr === 'string') {
    if (/(kb|mb|gb|bytes)/i.test(bytesOrStr)) {
      return `file size ${bytesOrStr.trim().toLowerCase()}`;
    }
    const num = parseFloat(bytesOrStr);
    if (!isNaN(num) && num > 0) {
      bytesOrStr = num;
    } else {
      return null;
    }
  }
  if (typeof bytesOrStr === 'number' && bytesOrStr > 0) {
    if (bytesOrStr >= 1024 * 1024) {
      return `file size ${(bytesOrStr / (1024 * 1024)).toFixed(bytesOrStr >= 10 * 1024 * 1024 ? 0 : 1)}mb`;
    }
    if (bytesOrStr >= 1024) {
      return `file size ${(bytesOrStr / 1024).toFixed(0)}kb`;
    }
    return `file size ${bytesOrStr}b`;
  }
  return null;
};

import { PackageTiers, PricingTierDetails } from "@/types";

export interface PackageFormFaq {
  question: string;
  answer: string;
}

export interface PackageFormState {
  // userID?: string;
  title: string;
  category: string;
  categoryId?: string;
  subcategory?: string;
  subcategoryId?: string;
  niche?: string;
  nicheId?: string;
  cover: string;
  images: string[];
  description: string;
  shortTitle: string;
  shortDesc: string;
  deliveryTime: string | number;
  revisionNumber: string | number;
  features: string[];
  faqs: PackageFormFaq[];
  price: number;
  packages: {
    basic: PricingTierDetails;
    standard: PricingTierDetails | null;
    premium: PricingTierDetails | null;
    [key: string]: PricingTierDetails | null | undefined;
  };
}

export const initialState: PackageFormState = {
  // userID: '',
  title: '',
  category: '',
  categoryId: '',
  subcategory: '',
  subcategoryId: '',
  niche: '',
  nicheId: '',
  cover: '',
  images: [],
  description: '',
  shortTitle: '',
  shortDesc: '',
  deliveryTime: '',
  revisionNumber: '',
  features: [],
  faqs: [],
  price: 0,
  packages: {
    basic: {
      title: '',
      shortDesc: '',
      price: 0,
      deliveryTime: '',
      revisionNumber: '',
      features: []
    },
    standard: null,
    premium: null
  }
};

export type PackageAction =
  | { type: 'CHANGE_INPUT'; payload: { name: string; value: any } }
  | { type: 'ADD_IMAGES'; payload: { cover: string; images: string[] } }
  | { type: 'ADD_FEATURE'; payload: string }
  | { type: 'REMOVE_FEATURE'; payload: string }
  | { type: 'ADD_FAQ'; payload: PackageFormFaq }
  | { type: 'REMOVE_FAQ'; payload: number }
  | { type: 'CHANGE_PACKAGE_INPUT'; payload: { tier: 'basic' | 'standard' | 'premium' | string; name: string; value: any } }
  | { type: 'ADD_PACKAGE_FEATURE'; payload: { tier: 'basic' | 'standard' | 'premium' | string; feature: string } }
  | { type: 'REMOVE_PACKAGE_FEATURE'; payload: { tier: 'basic' | 'standard' | 'premium' | string; feature: string } }
  | { type: 'TOGGLE_PACKAGE_TIER'; payload: { tier: 'standard' | 'premium' | string } }
  | { type: 'INITIALIZE_STATE'; payload: PackageFormState };

export const packageReducer = (state: PackageFormState, action: PackageAction): PackageFormState => {
  switch (action.type) {
    case 'CHANGE_INPUT':
      return {
        ...state,
        [action.payload.name]: action.payload.value
      };

    case 'ADD_IMAGES':
      return {
        ...state,
        cover: action.payload.cover,
        images: action.payload.images
      };

    case 'ADD_FEATURE':
      return {
        ...state,
        features: [...state.features, action.payload]
      };

    case 'REMOVE_FEATURE':
      return {
        ...state,
        features: state.features.filter((feature) => feature !== action.payload)
      };

    case 'ADD_FAQ':
      return {
        ...state,
        faqs: [...(state.faqs || []), action.payload]
      };

    case 'REMOVE_FAQ':
      return {
        ...state,
        faqs: (state.faqs || []).filter((_, index) => index !== action.payload)
      };

    case 'CHANGE_PACKAGE_INPUT': {
      const currentTier = state.packages[action.payload.tier];
      if (!currentTier) return state;
      return {
        ...state,
        packages: {
          ...state.packages,
          [action.payload.tier]: {
            ...currentTier,
            [action.payload.name]: action.payload.value
          }
        }
      };
    }

    case 'ADD_PACKAGE_FEATURE': {
      const currentTier = state.packages[action.payload.tier];
      if (!currentTier) return state;
      return {
        ...state,
        packages: {
          ...state.packages,
          [action.payload.tier]: {
            ...currentTier,
            features: [...currentTier.features, action.payload.feature]
          }
        }
      };
    }

    case 'REMOVE_PACKAGE_FEATURE': {
      const currentTier = state.packages[action.payload.tier];
      if (!currentTier) return state;
      return {
        ...state,
        packages: {
          ...state.packages,
          [action.payload.tier]: {
            ...currentTier,
            features: currentTier.features.filter((feature) => feature !== action.payload.feature)
          }
        }
      };
    }

    case 'TOGGLE_PACKAGE_TIER': {
      const isEnabled = state.packages[action.payload.tier] !== null;
      return {
        ...state,
        packages: {
          ...state.packages,
          [action.payload.tier]: isEnabled ? null : {
            title: '',
            shortDesc: '',
            price: 0,
            deliveryTime: '',
            revisionNumber: '',
            features: []
          }
        }
      };
    }

    case 'INITIALIZE_STATE':
      return action.payload;

    default:
      return state;
  }
};

const getBackendBaseUrl = (): string => {
  const envUrl = process.env.NEXT_PUBLIC_SERVER_API_URL || process.env.NEXT_PUBLIC_API_URL;
  if (envUrl) {
    const cleaned = envUrl.trim().replace(/\/$/, '');
    return cleaned.endsWith('/api') ? cleaned : `${cleaned}/api`;
  }
  return "https://devadmin.workvence.com/api";
};

export async function getInitialPackages(params?: Record<string, string | string[] | undefined>) {
  try {
    const baseUrl = getBackendBaseUrl();
    const query = new URLSearchParams();

    const getParam = (key: string): string => {
      const val = params?.[key];
      if (Array.isArray(val)) return val[0] || '';
      return typeof val === 'string' ? val : '';
    };

    const search = getParam('search');
    const category = getParam('category') || getParam('cat');
    const min = getParam('min');
    const max = getParam('max');
    const sort = getParam('sort');
    const page = getParam('page');

    if (search.trim()) query.set('search', search.trim());
    if (category.trim() && category !== 'All services' && category !== 'Results') {
      query.set('category', category.trim());
    }
    if (min.trim()) query.set('min', min.trim());
    if (max.trim()) query.set('max', max.trim());
    if (sort.trim()) query.set('sort', sort.trim());
    query.set('limit', '20');
    query.set('page', page.trim() || '1');

    const controller = new AbortController();
    const timeoutId = setTimeout(() => controller.abort(), 6000);

    const res = await fetch(`${baseUrl}/gigs?${query.toString()}`, {
      signal: controller.signal,
      next: { revalidate: 60 }
    });

    clearTimeout(timeoutId);

    if (!res.ok) {
      console.warn(`[getInitialPackages] Backend returned HTTP ${res.status}`);
      return [];
    }

    const data = await res.json();
    return data || [];
  } catch (error: any) {
    console.warn(`[getInitialPackages] Non-fatal fetch error:`, error?.message || error);
    return [];
  }
}

export async function getSingleGig(id: string) {
  if (!id) return null;
  try {
    const baseUrl = getBackendBaseUrl();
    const controller = new AbortController();
    const timeoutId = setTimeout(() => controller.abort(), 6000);

    const res = await fetch(`${baseUrl}/gigs/single/${encodeURIComponent(id)}`, {
      signal: controller.signal,
      next: { revalidate: 60 }
    });

    clearTimeout(timeoutId);

    if (!res.ok) {
      if (res.status === 404) return null;
      console.warn(`[getSingleGig] Backend returned HTTP ${res.status} for ID: ${id}`);
      return null;
    }

    const data = await res.json();
    if (data) {
      const rawImgs = Array.isArray(data.images) ? data.images : [];
      data.images = Array.from(new Set([data.cover, ...rawImgs].filter(Boolean)));
    }
    return data || null;
  } catch (error: any) {
    console.warn(`[getSingleGig] Non-fatal fetch error for ID ${id}:`, error?.message || error);
    return null;
  }
}

import { axiosFetch } from "@/utils";

export interface SubmitSellerReplyParams {
  reviewId?: string;
  orderId?: string;
  reply: string;
}

export interface ReviewReplyResponse {
  success: boolean;
  data?: any;
  error?: string;
}

/**
 * Submit or update a seller's public reply to a buyer's review.
 * Supports both /reviews/:reviewId/reply and /reviews/order/:orderId/reply.
 */
export async function submitSellerReviewReply(
  params: SubmitSellerReplyParams
): Promise<ReviewReplyResponse> {
  const { reviewId, orderId, reply } = params;
  const trimmedReply = reply.trim();

  if (!trimmedReply) {
    return { success: false, error: "Reply text cannot be empty." };
  }

  if (trimmedReply.length > 1000) {
    return { success: false, error: "Reply text cannot exceed 1,000 characters." };
  }

  const payload = { reply: trimmedReply };

  // 1. Try reviewId endpoint if reviewId is present
  if (reviewId) {
    try {
      const res = await axiosFetch.post(`/reviews/${reviewId}/reply`, payload);
      return { success: true, data: res.data?.review || res.data?.data || res.data };
    } catch (err: any) {
      // If error is 404 and orderId is available, fallback to orderId route
      if ((err?.response?.status === 404 || err?.response?.status === 400) && orderId) {
        try {
          const res = await axiosFetch.post(`/reviews/order/${orderId}/reply`, payload);
          return { success: true, data: res.data?.review || res.data?.data || res.data };
        } catch (orderErr: any) {
          const msg = orderErr?.response?.data?.message || orderErr?.message || "Failed to post reply.";
          return { success: false, error: Array.isArray(msg) ? msg.join(", ") : msg };
        }
      }
      const msg = err?.response?.data?.message || err?.message || "Failed to post reply.";
      return { success: false, error: Array.isArray(msg) ? msg.join(", ") : msg };
    }
  }

  // 2. Otherwise try orderId endpoint
  if (orderId) {
    try {
      const res = await axiosFetch.post(`/reviews/order/${orderId}/reply`, payload);
      return { success: true, data: res.data?.review || res.data?.data || res.data };
    } catch (err: any) {
      const msg = err?.response?.data?.message || err?.message || "Failed to post reply.";
      return { success: false, error: Array.isArray(msg) ? msg.join(", ") : msg };
    }
  }

  return { success: false, error: "Neither review ID nor order ID was provided." };
}

