export const PRESET_TAGS = ['Urgent', 'Lead', 'VIP', 'Follow Up', 'In Review'];

export const sanitizeTags = (rawTags: string[]): string[] => {
  if (!Array.isArray(rawTags)) return [];
  const seen = new Set<string>();
  const sanitized: string[] = [];

  for (const raw of rawTags) {
    if (typeof raw !== 'string') continue;
    const trimmed = raw.trim();
    if (!trimmed) continue;
    const truncated = trimmed.slice(0, 50);
    const lowerKey = truncated.toLowerCase();
    if (!seen.has(lowerKey)) {
      seen.add(lowerKey);
      sanitized.push(truncated);
      if (sanitized.length >= 20) break;
    }
  }

  return sanitized;
};

export const getTagColor = (tagName: string) => {
  const lower = (tagName || '').toLowerCase();
  if (lower.includes('urgent') || lower.includes('priority')) {
    return 'bg-white text-rose-700 border-[rgba(0,0,0,0.10)]';
  }
  if (lower.includes('vip') || lower.includes('star')) {
    return 'bg-white text-purple-700 border-[rgba(0,0,0,0.10)]';
  }
  if (lower.includes('lead') || lower.includes('client') || lower.includes('deal')) {
    return 'bg-white text-emerald-800 border-[rgba(0,0,0,0.10)]';
  }
  if (lower.includes('follow') || lower.includes('pending')) {
    return 'bg-white text-sky-800 border-[rgba(0,0,0,0.10)]';
  }
  if (lower.includes('review') || lower.includes('wait') || lower.includes('hold')) {
    return 'bg-white text-amber-800 border-[rgba(0,0,0,0.10)]';
  }
  return 'bg-white text-slate-700 border-[rgba(0,0,0,0.10)]';
};

export const updateConversationTagsApi = async (conversationId: string, tags: string[]) => {
  if (!conversationId) throw new Error('Missing conversation ID');
  const sanitized = sanitizeTags(tags);

  try {
    const res = await axiosFetch.patch(`/chat/conversations/${conversationId}/tags`, { tags: sanitized });
    return res.data;
  } catch (err: any) {
    // Fallback to /conversations/:id/tags if /chat/ prefix rewrite differs
    const res = await axiosFetch.patch(`/conversations/${conversationId}/tags`, { tags: sanitized });
    return res.data;
  }
};

/**
 * Utility function to sanitize and parse revision counts into non-negative integers.
 */
export const parseRevisionNumber = (val: any, fallback = 0): number => {
  if (val === undefined || val === null || val === "") return fallback;
  const parsed = parseInt(String(val), 10);
  return isNaN(parsed) || parsed < 0 ? fallback : parsed;
};

import { io, Socket } from 'socket.io-client';

const getSocketURL = (): string => {
  if (process.env.NEXT_PUBLIC_SOCKET_URL) {
    return process.env.NEXT_PUBLIC_SOCKET_URL.replace(/\/api\/?$/, '');
  }
  const envUrl = process.env.NEXT_PUBLIC_SERVER_API_URL || process.env.NEXT_PUBLIC_API_URL;
  if (envUrl) {
    return envUrl.replace(/\/api\/?$/, '');
  }
  const hostname = typeof window !== 'undefined' && window.location.hostname
    ? window.location.hostname
    : 'localhost';
  return `http://${hostname}:8080`;
};

const options = {
  withCredentials: true,
  autoConnect: false,
  reconnection: true,
  reconnectionAttempts: Infinity,
  reconnectionDelay: 1000,
  reconnectionDelayMax: 5000,
  transports: ['websocket', 'polling'],
  path: '/socket.io/'
};

const getAuthToken = (): string | null => {
  if (typeof window === 'undefined') return null;
  const match = document.cookie.match(/(?:^|;\s*)accessToken=([^;]*)/);
  if (match && match[1]) return decodeURIComponent(match[1]);
  return localStorage.getItem('token') || localStorage.getItem('accessToken') || null;
};

let realSocket: Socket | null = null;

const getSocket = (): Socket | null => {
  if (!realSocket && typeof window !== 'undefined') {
    const token = getAuthToken();
    realSocket = io(getSocketURL(), {
      ...options,
      auth: token ? { token } : undefined,
      query: token ? { token } : undefined,
    });
  }
  return realSocket;
};

export interface SocketClient {
  connect: () => void;
  disconnect: () => void;
  emit: (event: string, ...args: any[]) => void;
  on: (event: string, cb: (...args: any[]) => void) => void;
  once: (event: string, cb: (...args: any[]) => void) => void;
  off: (event: string, cb?: (...args: any[]) => void) => void;
  readonly connected: boolean;
}

export const socket: SocketClient = {
  connect() {
    const s = getSocket();
    if (s && !s.connected) {
      s.connect();
    }
  },
  disconnect() {
    if (realSocket) {
      if (realSocket.connected) {
        realSocket.emit('leave_conversation');
      }
      realSocket.disconnect();
      realSocket = null;
    }
  },
  emit(event: string, ...args: any[]) {
    const s = getSocket();
    s?.emit(event, ...args);
  },
  on(event: string, cb: (...args: any[]) => void) {
    const s = getSocket();
    s?.on(event, cb);
  },
  once(event: string, cb: (...args: any[]) => void) {
    const s = getSocket();
    s?.once(event, cb);
  },
  off(event: string, cb?: (...args: any[]) => void) {
    if (realSocket) {
      realSocket.off(event, cb);
    }
  },
  get connected(): boolean {
    return !!(realSocket && realSocket.connected);
  }
};

export default socket;

let globalAudioCtx: AudioContext | null = null;
let userHasInteracted = false;

const initAudioContextOnGesture = () => {
  if (typeof window === 'undefined') return;
  userHasInteracted = true;
  if (!globalAudioCtx) {
    const AudioCtxClass = window.AudioContext || (window as any).webkitAudioContext;
    if (AudioCtxClass) {
      try {
        globalAudioCtx = new AudioCtxClass();
      } catch (e) {
        // Silently ignore audio context creation error
      }
    }
  }
  if (globalAudioCtx && globalAudioCtx.state === 'suspended') {
    globalAudioCtx.resume().catch(() => {});
  }
};

// Register gesture listeners immediately on client load
if (typeof window !== 'undefined') {
  const events = ['click', 'pointerdown', 'keydown', 'touchstart', 'scroll'];
  const handleGesture = () => {
    initAudioContextOnGesture();
    events.forEach(evt => window.removeEventListener(evt, handleGesture));
  };
  events.forEach(evt => window.addEventListener(evt, handleGesture, { passive: true }));
}

const getAudioContext = (): AudioContext | null => {
  if (typeof window === 'undefined' || !userHasInteracted) return null;
  if (!globalAudioCtx) {
    initAudioContextOnGesture();
  }
  if (globalAudioCtx && globalAudioCtx.state === 'suspended') {
    globalAudioCtx.resume().catch(() => {});
    return null; // Return null while suspended to eliminate Chrome console warnings
  }
  return globalAudioCtx;
};

/**
 * Play a notification chime sound cleanly after user interaction.
 * @param type 'message' | 'notification' | 'general'
 */
export const playNotificationSound = (type: 'message' | 'notification' | 'general' = 'notification') => {
  try {
    const ctx = getAudioContext();
    if (!ctx || ctx.state !== 'running') return;

    if (type === 'message') {
      // Pleasant double-chime for incoming message (D5 -> A5)
      const now = ctx.currentTime;

      const osc1 = ctx.createOscillator();
      const gain1 = ctx.createGain();
      osc1.type = 'sine';
      osc1.frequency.setValueAtTime(587.33, now); // D5
      gain1.gain.setValueAtTime(0.15, now);
      gain1.gain.exponentialRampToValueAtTime(0.001, now + 0.15);
      osc1.connect(gain1);
      gain1.connect(ctx.destination);
      osc1.start(now);
      osc1.stop(now + 0.15);

      const osc2 = ctx.createOscillator();
      const gain2 = ctx.createGain();
      osc2.type = 'sine';
      osc2.frequency.setValueAtTime(880, now + 0.08); // A5
      gain2.gain.setValueAtTime(0.2, now + 0.08);
      gain2.gain.exponentialRampToValueAtTime(0.001, now + 0.3);
      osc2.connect(gain2);
      gain2.connect(ctx.destination);
      osc2.start(now + 0.08);
      osc2.stop(now + 0.3);
    } else {
      // Arpeggio chime for general & order notifications (C5 -> E5 -> G5)
      const now = ctx.currentTime;

      const osc = ctx.createOscillator();
      const gain = ctx.createGain();
      osc.type = 'triangle';
      osc.frequency.setValueAtTime(523.25, now); // C5
      osc.frequency.setValueAtTime(659.25, now + 0.08); // E5
      osc.frequency.setValueAtTime(783.99, now + 0.16); // G5
      gain.gain.setValueAtTime(0.2, now);
      gain.gain.exponentialRampToValueAtTime(0.001, now + 0.4);

      osc.connect(gain);
      gain.connect(ctx.destination);
      osc.start(now);
      osc.stop(now + 0.4);
    }
  } catch (e) {
    // Silently ignore playback errors
  }
};

import axios from 'axios';
import axiosFetch from './axiosFetch';

const getAdminApiUrl = () => {
  if (typeof window !== "undefined") {
    return "/api";
