import axios from "axios";
import { JwtPayload } from "@/types";
import { useUserStore } from "@/store/userStore";
import socket from "@/utils/socket";

// Track in-flight refresh to prevent duplicate concurrent calls
let isRefreshing = false;
let refreshSubscribers: Array<(token: string | null) => void> = [];

function subscribeTokenRefresh(cb: (token: string | null) => void) {
  refreshSubscribers.push(cb);
}

function onRefreshed(token: string | null) {
  refreshSubscribers.forEach((cb) => cb(token));
  refreshSubscribers = [];
}

/**
 * Get cookie value by name from document.cookie (browser-only)
 */
export function getCookie(name: string): string | null {
  if (typeof document === "undefined") return null;
  const match = document.cookie.match(new RegExp(`(?:^|; )\\s*${name}\\s*=\\s*([^;]+)`));
  return match ? decodeURIComponent(match[1]) : null;
}

/**
 * Set a cookie (browser-only)
 */
export function setCookie(name: string, value: string, maxAgeSec: number = 3600): void {
  if (typeof document === "undefined") return;
  document.cookie = `${name}=${encodeURIComponent(value)}; path=/; max-age=${maxAgeSec}; SameSite=Lax`;
}

/**
 * Decode JWT payload safely in both browser and Node environments
 */
export function decodeJwtPayload(token?: string): JwtPayload | null {
  if (!token || typeof token !== "string") return null;
  const trimmed = token.trim();
  if (!trimmed || trimmed === "undefined" || trimmed === "null") return null;
  try {
    const parts = trimmed.split(".");
    if (parts.length < 2) return null;
    const base64Url = parts[1];
    const base64 = base64Url.replace(/-/g, "+").replace(/_/g, "/");
    if (typeof window !== "undefined" && typeof window.atob === "function") {
      const jsonPayload = decodeURIComponent(
        window
          .atob(base64)
          .split("")
          .map((c) => "%" + ("00" + c.charCodeAt(0).toString(16)).slice(-2))
          .join("")
      );
      return JSON.parse(jsonPayload) as JwtPayload;
    } else if (typeof Buffer !== "undefined") {
      const jsonPayload = Buffer.from(base64, "base64").toString("utf-8");
      return JSON.parse(jsonPayload) as JwtPayload;
    }
    return null;
  } catch {
    return null;
  }
}

/**
 * Check if the current access token is expired or expiring within bufferSeconds (default: 5 mins)
 * Returns false if no session tokens exist (guest state).
 */
export function isAccessTokenExpiringSoon(bufferSeconds: number = 300): boolean {
  const token =
    getCookie("accessToken") ||
    (typeof window !== "undefined" ? localStorage.getItem("accessToken") || localStorage.getItem("token") : null);

  const hasSession = Boolean(
    token ||
    getCookie("user") ||
    getCookie("refreshToken") ||
    (typeof window !== "undefined" && (localStorage.getItem("user") || localStorage.getItem("refreshToken")))
  );

  // If user has neither session nor token, there is no active session to refresh
  if (!hasSession) return false;
  // If access token is missing but a session exists, renew immediately
  if (!token) return true;

  const payload = decodeJwtPayload(token);
  if (!payload || !payload.exp) return true;
  // payload.exp is in seconds
  const remainingMs = payload.exp * 1000 - Date.now();
  return remainingMs <= bufferSeconds * 1000;
}

/**
 * Handle authentication expiration:
 * Clears cookies, local/session storage, userStore, disconnects socket,
 * and redirects to /login on 401 errors ONLY if on a protected route or explicitly requested.
 */
export function handleAuthExpired(redirectPath?: string): void {
  if (typeof window === "undefined") return;

  // 1. Purge auth cookies
  const cookiesToClear = ["accessToken", "refreshToken", "user", "isSeller", "role"];
  cookiesToClear.forEach((name) => {
    document.cookie = `${name}=; path=/; max-age=0; SameSite=Lax`;
  });

  // 2. Clear storage
  localStorage.removeItem("user");
  sessionStorage.removeItem("kyc_prompt_dismissed_session");

  // 3. Reset Zustand store
  try {
    useUserStore.getState().setUser(null);
  } catch {
    // Ignore store access failure
  }

  // 4. Disconnect realtime socket
  try {
    socket.disconnect();
  } catch {
    // Ignore socket error
  }

  // 5. Redirect to /login only if currently on a protected route or explicitly provided redirectPath
  const currentPath = redirectPath || window.location.pathname;
  const currentTarget = redirectPath || (window.location.pathname + window.location.search);

  const isGuestAuthRoute =
    currentPath.startsWith("/login") ||
    currentPath.startsWith("/register") ||
    currentPath.startsWith("/forgot-password") ||
    currentPath.startsWith("/reset-password");

  const PROTECTED_PREFIXES = [
    "/dashboard",
    "/profile",
    "/orders",
    "/messages",
    "/message",
    "/favorites",
    "/pay",
    "/organize",
    "/briefs/create",
    "/briefs/my-briefs",
    "/briefs/my-proposals",
    "/earnings",
    "/my-packages",
    "/kyc",
    "/settings",
    "/seller/suspended",
    "/suspended-seller",
    "/admin",
  ];

  const isProtectedRoute = PROTECTED_PREFIXES.some(
    (prefix) => currentPath === prefix || currentPath.startsWith(`${prefix}/`)
  );

  // Never redirect if browsing public/marketing pages (e.g. homepage "/", "/packages", "/help-center", etc.)
  if (!isGuestAuthRoute && (Boolean(redirectPath) || isProtectedRoute)) {
    const loginUrl = `/login?redirect=${encodeURIComponent(currentTarget)}`;
    window.location.href = loginUrl;
  }
}

/**
 * Base URL resolver for auth endpoints
 */
const getAuthBaseURL = (): string => {
  if (typeof window !== "undefined") {
    return "/api";
  }
  const envUrl = process.env.NEXT_PUBLIC_SERVER_API_URL || process.env.NEXT_PUBLIC_API_URL;
  if (envUrl) {
    const cleaned = envUrl.trim().replace(/\/$/, "");
    return cleaned.endsWith("/api") ? cleaned : `${cleaned}/api`;
  }
  return "https://devadmin.workvence.com/api";
};

/**
 * Refresh access token using POST /api/auth/refresh-token
 * Sends credentials (Cookie: refreshToken HttpOnly) + header fallback + body fallback
 * Concurrency-safe: Queues simultaneous callers to a single in-flight request.
 */
export async function refreshAccessToken(): Promise<string> {
  // If already refreshing, wait for existing promise
  if (isRefreshing) {
    return new Promise((resolve, reject) => {
      subscribeTokenRefresh((token) => {
        if (token) {
          resolve(token);
        } else {
          reject(new Error("Refresh token expired or invalid"));
        }
      });
    });
  }

  isRefreshing = true;

  try {
    const headers: Record<string, string> = {
      "Content-Type": "application/json",
    };

    // Header method: x-refresh-token fallback (if readable from cookie or localStorage)
    const refreshToken =
      getCookie("refreshToken") ||
      (typeof window !== "undefined" ? localStorage.getItem("refreshToken") : null);

    if (refreshToken) {
      headers["x-refresh-token"] = refreshToken;
    }

    // Call /api/auth/refresh-token with withCredentials: true (so browser sends HttpOnly cookie automatically)
    // and also provide body payload in case backend DTO validates @Body() { refreshToken }
    const body = refreshToken ? { refreshToken } : {};

    const response = await axios.post(
      `${getAuthBaseURL()}/auth/refresh-token`,
      body,
      {
        withCredentials: true,
        headers,
      }
    );

    const newAccessToken =
      response.data?.accessToken ||
      response.data?.token ||
      response.data?.data?.accessToken ||
      response.data?.data?.token;

    if (newAccessToken) {
      // Access token lifetime: 1 hour (3600 seconds)
      setCookie("accessToken", newAccessToken, 3600);
      if (typeof window !== "undefined") {
        try { localStorage.setItem("accessToken", newAccessToken); } catch {}
        try { localStorage.setItem("token", newAccessToken); } catch {}
      }
      isRefreshing = false;
      onRefreshed(newAccessToken);
      return newAccessToken;
    }

    throw new Error("No accessToken returned by refresh endpoint");
  } catch (error: any) {
    isRefreshing = false;
    onRefreshed(null);

    // Error 401 — Invalid or expired token: Redirect user to login page
    if (error.response?.status === 401) {
      handleAuthExpired();
    }

    throw error;
  }
}
